def construct(input, left, right): 
    if right >= left: 
        mid = (left + right) // 2
        node = Node(input[mid]) 
        node.left = construct(input, left, mid-1) 
        node.right = construct(input, mid+1, right) 
    else: 
        node = None
    return node

