        if string1[i] < string2[i]:
            result = -1
            break
        # if the character in string1 is larger than the corresponding character in string2
        elif string1[i] > string2[i]:
            result = 1
            break
    # if the two strings are equal in length
    if result == 0 and len(string1) != len(string2):
        # if string1 is shorter than string2
