    stack = []
    for ch in exp:
        if ch == "(":
            stack.append("(")
        elif ch == ")":
            if stack[-1] == "!":
                op = stack.pop()
                stack.pop()  # Pop the (
                stack.append(not stack.pop())
            elif stack[-1] == "&":
                stack.pop()  # Pop the &
                right = stack.pop()
                left = stack.pop()
                stack.pop()  # Pop the (
                stack.append(left and right)
            elif stack[-1] == "|":
                stack.pop()  # Pop the |
                right = stack.pop()
                left = stack.pop()
                stack.pop()  # Pop the (
                stack.append(left or right)
        else:
            stack.append(ch == "T")
    return stack.pop()

