# Function to flatten a nested dictionary
def flatten_dictionary(dictionary, flattened = None): 

    # Initialize an empty dictionary
    if flattened == None: 
        flattened = {} 

    for key, value in dictionary.items(): 

        # If the value is not a dictionary, add it
        # to the result
        if not isinstance(value, dict): 
            flattened[key] = value 

        # If the value is a dictionary, recursively call the 
        # function with the sub-dictionary
        else: 
            temp = flatten_dictionary(value) 
            for key_ in temp: 
                flattened[key + "." + key_] = temp[key_] 

    return flattened

class PriorityQueueWithBST:

    def __init__(self):
        self.bst1 = {} 
        self.bst2 = {}

    def enqueue(self, value, priority):
        if priority in self.bst1:
            self.bst1[priority].append(value)
        else:
            self.bst1[priority] = [value]

        if len(self.bst2) == 0 or priority > list(self.bst2.keys())[0]: 
            if len(self.bst2) != 0:
                prev_priority = list(self.bst2.keys())[0]
                self.bst2[priority] = self.bst2[prev_priority]
                del self.bst2[prev_priority]
            else:
                self.bst2[priority] = len(self.bst1[priority])

    def dequeue(self):
        if len(self.bst2) != 0:
            priority = list(self.bst2.keys())[0]
            value = self.bst1[priority].pop(0)
            self.bst2[priority] -= 1
            if self.bst2[priority] == 0:
                del self.bst2[priority]
                if len(self.bst1) != 0:
                    next_priority = max(self.bst1.keys())
                    self.bst2[next_priority] = len(self.bst1[next_priority])
            return value
        else:
            return None

    def peek(self):
        if len(self.bst2) != 0:
            priority = list(self.bst2.keys())[0]
            return self.bst1[priority][0]
        else:
            return None

def maximum_sum_non_adjacent_elements(arr):
    if len(arr) <= 2:
        return max(arr)

    even_sum = arr[0]
    odd_sum = max(arr[0], arr[1])

    for i in range(2, len(arr)):
        if i % 2 == 0:
            even_sum = max(odd_sum, even_sum + arr[i])
        else:
            odd_sum = max(even_sum, odd_sum + arr[i])

    return max(even_sum, odd_sum)

