def compute_modulus(num1, num2):
    try:
        modulus = num1 % num2
        return modulus
    except ZeroDivisionError:
        return 'Error: Division by zero is undefined.'
    except TypeError:
        return 'Error: Both inputs must be integers or floating point numbers.'

