def majorityElement(arr):
    length = len(arr)
    count = {}

    for i in arr:
        if i not in count: 
            count[i] = 1
        else:
            count[i] += 1

    max_count = max(count.values()) 

    if max_count > length//2: 
        majority_element = [key for key in count.keys() if count[key] == max_count]
        return majority_element[0] 
    else: 
        return -1

