def get_frequent_numbers(arr):
    if not arr:
        return None

    count_dict = {}
    for num in arr:
        count_dict[num] = count_dict.get(num, 0) + 1

    max_value = max(count_dict.values())
    frequent = [key for key, value in count_dict.items() if value == max_value]

    return frequent

