def optimize_schedule(store_clerks): 
  # Initialize an empty list for the final schedule
  schedule = [[] for _ in range(24)]

  # Iterate through the clerks
  for clerk in store_clerks:
    # Find the start and end hours
    if clerk['shift'] == 'morning':
      start_hour = 0
      end_hour = clerk['hour']
    elif clerk['shift'] == 'evening':
      start_hour = clerk['hour']
      end_hour = 24
    # Assign the clerk to every hour between the start and end hours
    for hour in range(start_hour, end_hour):
      schedule[hour].append(clerk['name'])

  return schedule

import numpy as np

class Perceptron():

    def __init__(self, num_features):
        self.weights = np.zeros(num_features + 1) # weights vector
        self.lr = 0.01 # learning rate

    def predict(self, x):
        z = np.dot(x, self.weights[1:]) + self.weights[0] # dot product between features and weights
        a = np.where(z >= 0, 1, -1) # activation function

        return a

    def fit(self, X, y):
        for _ in range(10000):
            for x, target in zip(X, y):
                prediction = self.predict(x) # prediction of a training example

                error = target - prediction # potential error

                # weight update
                self.weights[1:] += self.lr * x * error
                self.weights[0] += self.lr * error

def BFS(arr):
    queue = []
    visited = [[False for _ in range(len(arr[0]))] for _ in range(len(arr))]
    queue.append((0, 0))
    visited[0][0] = True
    step = 0
    while len(queue) > 0:
        row, col = queue.pop(0)
        if row == len(arr)-1 and col == len(arr[0])-1:
            break
        for X in range(-1, 2):
            for Y in range(-1, 2):
                if X == 0 and Y == 0:
                    continue
                new_row = row + X
                new_column = col + Y
                if new_row < 0 or new_row >= len(arr) or new_column < 0 or new_column >= len(arr[0]):
                    continue
                if not visited[new_row][new_column] and arr[new_row][new_column] == 0:
                    queue.append((new_row, new_column))
                    visited[new_row][new_column] = True
                    step += 1
    return step

