import math

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def prime_divisors(n):
    divisors_list = []
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0 and is_prime(i):
            divisors_list.append(i)
    if n > 1:
        divisors_list.append(n)
    return divisors_list

