def caesar_cipher_encode(string, shift): 
    cipher = "" 
    for char in string: 
        if char.isalpha(): 
            code = ord(char) + shift
            if char.isupper():
                if code > ord('Z'):
                    code -= 26
                elif code < ord('A'):
                    code += 26
            elif char.islower():
                if code > ord('z'):
                    code -= 26
                elif code < ord('a'):
                    code += 26
            cipher += chr(code)
        else: 
            cipher += char
    return cipher

def caesar_cipher(message, shift):
    encrypted_message = ""
    for char in message:
        charIndex = ord(char)
        encryptedIndex = charIndex + shift
        if encryptedIndex <= 255:
            encrypted_message += chr(encryptedIndex)
        else:
            encrypted_message += chr(encryptedIndex - 255)
    return encrypted_message

