def largest_palindrome_number():
    biggerPalin = 0
    a = 999
    b = 999
    while a >= 100:
        while b >= a:
            if a * a < biggerPalin:  # Optimization: Break the inner loop if the product of a and a is smaller than the current largest palindrome
