def bin_packing(weights, bin_size):
    bins = []
    while len(weights) > 0:
        bin = []
        while sum(bin) + weights[0] <= bin_size:
            bin.append(weights[0])
            weights.pop(0)
            if len(weights) == 0:
                break
        bins.append(bin)
    return bins

