        elements = []
        curr = self.head
        while curr:
            elements.append(curr.data)
            curr = curr.next
        return elements

    def insert_middle(self, data):
        if self.head is None:
            self.head = Node(data)
            return

        slow = self.head
        fast = self.head

        while fast is not None and fast.next is not None:
            fast = fast.next.next
            slow = slow.next

        new_node = Node(data)
        new_node.next = slow.next
        slow.next = new_node

