class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None


class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def is_empty(self):
        return self.head is None

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.is_empty():
            self.head = new_node
        else:
            new_node.next = self.head
            self.head.prev = new_node
            self.head = new_node

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.is_empty():
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = new_node
            new_node.prev = current

    def delete_at_beginning(self):
        if self.is_empty():
            return None
        else:
            temp = self.head
            self.head = self.head.next
            self.head.prev = None
            temp.next = None
            return temp.data

    def delete_at_end(self):
        if self.is_empty():
            return None
        else:
            current = self.head
            while current.next:
                current = current.next
            temp = current
            current.prev.next = None
            temp.prev = None
            return temp.data

    def display(self):
        if self.is_empty():
            print("Doubly linked list is empty")
        else:
            current = self.head
            while current:
                print(current.data, end=" ")
                current = current.next
            print()


