def hasCycle(head):
    if head is None:
        return False

    slow = head
    fast = head.next

    while slow != fast:
        if fast is None or fast.next is None:
            return False
        slow = slow.next
        fast = fast.next.next

    return True

def find_path_recursive(maze, start, end):
    if start == end:
        return [start]
    if start not in maze or end not in maze:
        return []
    if maze[start] == 0:
        return []

    paths = []
    for direction in [[1, 0], [-1, 0], [0, 1], [0, -1]]:
        new_position = (start[0]+direction[0], start[1]+direction[1])
        rec_paths = find_path_recursive(maze, new_position, end)
        if rec_paths:
            path = [start] + rec_paths
            paths.append(path)
    return paths

