def advanced_binary_search(lst, target):
    if len(lst) == 0:
        return None

    low = 0
    high = len(lst) - 1

    while low <= high:
        mid = (low + high) // 2
        if lst[mid] == target:
            return lst[mid]
        elif lst[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    if low >= len(lst):
        return lst[high]
    elif high < 0:
        return lst[low]
    else:
        return lst[low] if abs(lst[low] - target) < abs(lst[high] - target) else lst[high]

