def construct_expression_tree(postfix_expression):
    stack = []
    operators = set(['+', '-', '*', '/'])

    for char in postfix_expression:
        if char not in operators:
            node = Node(char)
            stack.append(node)
        else:
            right_node = stack.pop()
            left_node = stack.pop()
            operator_node = Node(char)
