def generateMaze():
    grid = []
    for row in range(8):
        grid.append([0]*8)
    stack = []
    done = False
    row = 0
    col = 0
    grid[row][col] = 1
    while not done:
        neigh = getNeighbors(grid, row, col)
        if len(neigh) > 0:
            neighr = random.choice(neigh)
            stack.append((row, col))
            row = neighr[0]
            col = neighr[1]
            grid[row][col] = 1
        else:
            if len(stack) > 0:
                row, col = stack.pop()
            else:
                done = True
    return grid

# Helper function to get neighboring cells
def getNeighbors(grid, row, col):
    neighbors = []
    if row > 0:
        neighbors.append((row-1, col))
    if row < len(grid) - 1:
        neighbors.append((row+1, col))
    if col > 0:
        neighbors.append((row, col-1))
    if col < len(grid[0]) - 1:
        neighbors.append((row, col+1))
    return neighbors

