def evaluateTree(root): 
    if root is None: 
        return 0
    if root.left is None and root.right is None: 
        return int(root.val) 
    left_sum = evaluateTree(root.left) 
    right_sum = evaluateTree(root.right) 
    if (root.val == '+'): 
        return left_sum + right_sum 
    elif (root.val == '-'): 
        return left_sum - right_sum 
    elif (root.val == '*'): 
        return left_sum * right_sum 
    else: 
        return left_sum / right_sum

