def quick_sort(unsorted_list):
    if len(unsorted_list) <= 1:
        return unsorted_list
    pivot = unsorted_list[-1]
    less = []
    great = []
    equal = []

    for i in unsorted_list:
        if i < pivot:
            less.append(i)
        elif i > pivot:
            great.append(i)
        else:
            equal.append(i)

    return quick_sort(less) + equal + quick_sort(great)

