def LongestIncreasingSublist(arr):
    n = len(arr)
    lis = [1] * n
    sublist = [[] for _ in range(n + 1)]

    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    max_length = 0

    for i in range(n):
        if max_length < lis[i]:
            max_length = lis[i]

    start_index = lis.index(max_length)

    j = max_length - 1
    for i in range(start_index, -1, -1):
        if lis[i] == j:
            sublist[j].append(arr[i])
            j -= 1

    return sublist[max_length]

def is_anagram(string1, string2):
  # Removing spaces from both strings
    string1 = string1.replace(' ', '')
    string2 = string2.replace(' ', '')

    # Calculating lengths of both strings
    n1 = len(string1)
    n2 = len(string2)

    # Comparing lengths of both strings
    if n1 != n2:
        return False

    # Sorting strings
    string1 = sorted(string1)
    string2 = sorted(string2)

    # Comparing both strings
    for i in range(0, n1):
        if string1[i] != string2[i]:
            return False

    return True

