def generate(parentheses_list, current, left, right): 
    if(left == 0 and right == 0): 
        parentheses_list.append(current) 

    if(left > 0): 
        generate(parentheses_list, current + "(", left - 1, right) 

    if(right > left): 
        generate(parentheses_list, current + ")", left, right - 1) 

