def findMax(root):
    if root is None:
        return float('-inf')

    res = root.val
    leftMax = findMax(root.left)
    rightMax = findMax(root.right)

    if leftMax > res:
        res = leftMax
    if rightMax > res:
        res = rightMax

    return res

