def subset(arr, k): 
    result = []
    for i in range(1 << len(arr)):
        if len(result) == k:
            break 
        subset = []
        for j in range(len(arr)):
            if i & (1 << j): 
                subset.append(arr[j])
        result.append(subset)
    return result

