def find_most_frequent_word(sentence):
    # Split the sentence into individual words
    words = sentence.split()

    # Initialize an empty dictionary to store the word frequencies
    word_freq = {}

    # Iterate through each word in the sentence
    for word in words:
        # Increment the count for each word in the dictionary
        if word in word_freq:
            word_freq[word] += 1
        else:
            word_freq[word] = 1

    # Find the word with the maximum frequency
    most_frequent_word = max(word_freq, key=word_freq.get)
    count = word_freq[most_frequent_word]

    return most_frequent_word, count

