def encrypt(plain_text, shift): 
    cipher_text = "" 
    for char in plain_text: 
        if char.isalpha(): 
            char_code = ord(char) 
            char_code += shift 
            if char.isupper():
                if char_code > ord('Z'): 
                    char_code -= 26 
                elif char_code < ord('A'): 
                    char_code += 26 
            elif char.islower(): 
                if char_code > ord('z'): 
                    char_code -= 26 
                elif char_code < ord('a'): 
                    char_code += 26 
            cipher_text += chr(char_code) 
        else: 
            cipher_text += char
    return cipher_text

