def solve_n_rooks(n):
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        return True

    def solve_n_rooks_util(board, col):
        # base case: If all rooks are placed
        if col >= n:
            return True

        # Consider this column and try placing
        # this rook in all rows one by one
        for i in range(n):
            if is_safe(board, i, col):
                # Place this rook in board[i][col]
                board[i][col] = 1

                # recur to place rest of the rooks
                if solve_n_rooks_util(board, col + 1) == True:
                    return True

                # If placing rook in board[i][col
                # doesn't lead to a solution, then
                # remove rook from board[i][col]
                board[i][col] = 0

        # If the rook can not be placed in any row in
        # this column col then return false
        return False

    board = [[0]*n for _ in range(n)]

    # If solution exists, print it
    if not solve_n_rooks_util(board, 0):
        print ("Solution does not exist")
        return False

    print("Solution exists and the possible configurations are:")
    for i in range(n):
        for j in range(n):
            print (board[i][j], end = " ")
        print()
    return True

