def findMax(root): 
    if root is None: 
        return float('-inf') 

    res = root.val 
    lres = findMax(root.left) 
    rres = findMax(root.right) 

    if (lres > res): 
        res = lres 
    if (rres > res): 
        res = rres 
    return res

