def two_sum(arr, target):
    left = 0
    right = len(arr) - 1

    while left < right:
        sum = arr[left] + arr[right] 
        if sum == target: 
            return (arr[left], arr[right])
        elif sum > target: 
            right -= 1
        else: 
            left += 1

    return None

