class LinkedList: 
    def __init__(self, nodes): 
        self.head = None
        for node in nodes[::-1]:
            self.head = Node(node[0], self.head)

    def rotate(self, k): 
        if k >= 0: 
            head = self.head
            tail = self.head 
            while tail.next_node: 
                tail = tail.next_node
            tail.next_node = head 
            while k > 0: 
                head = head.next_node 
                tail = tail.next_node 
                k -= 1
            tail.next_node = None 
            return head 
        else: 
            return self.head

