    letter_count = {}
    for letter in string:
        if letter.isalpha():
            if letter.lower() in letter_count:
                letter_count[letter.lower()] += 1
            else:
                letter_count[letter.lower()] = 1

    most_common_letter = max(letter_count, key=lambda k: letter_count[k])
    return most_common_letter

