    for c in range(BOARD_COLS-3):
        for r in range(BOARD_ROWS):
            if board[r][c] == piece and board[r][c+1] == piece and board[r][c+2] == piece and board[r][c+3] == piece:
                return True

    for r in range(BOARD_ROWS-3):
        for c in range(BOARD_COLS):
