def findSmallestPositive(arr, n): 
    small = None

    # Store all positive elements in array 
    for i in range(n): 
        if (arr[i] > 0 and (small is None or arr[i] < small)): 
            small = arr[i] 

    # Smallest number must be greater than 1 
    if (small is None or small > 1): 
        return 1

    # Traverse the array and check for missing element 
    for i in range(n): 
        if (small == arr[i]): 
            small += 1

    return small

