from collections import deque

def BFS(tree, root):
    visited = []
    queue = deque([root])

    while queue:
        node = queue.popleft()
        visited.append(node)

        for neighbour in tree[node]:
            if neighbour not in visited:
                queue.append(neighbour)

    return visited

