def partition(n):
    answer = []
    # base case, no elements
    if n == 0:
        answer.append([])
        return answer

    if n == 1:
        answer.append([1])
        return answer

    # Recursive case
    for i in range(n, 0, -1):
        partition_list = partition(n - i)
        for result in partition_list:
            new_result = result + [i]
            answer.append(new_result)

    return answer

def merge_sort(array):
    if len(array) <= 1:
        return array

    midpoint = len(array) // 2
    left_half = array[:midpoint]
    right_half = array[midpoint:]

    left_half = merge_sort(left_half)
    right_half = merge_sort(right_half)

    return merge(left_half, right_half)

def merge(left_half, right_half):
    sorted_list = []
    left_index = 0
    right_index = 0

    while left_index < len(left_half) and right_index < len(right_half):
        if left_half[left_index] < right_half[right_index]:
            sorted_list.append(left_half[left_index])
            left_index += 1
        else:
            sorted_list.append(right_half[right_index])
            right_index += 1

    if left_index < len(left_half):  
        sorted_list.extend(left_half[left_index:])
    if right_index < len(right_half):
        sorted_list.extend(right_half[right_index:])

    return sorted_list

