import random

def create_maze(m, n):
    maze = [[0 for j in range(n)] for i in range(m)]
    walls = []

    # Create the empty maze
    for i in range(m):
        for j in range(n):
            walls.append([i, j])

    # Choose a random wall and "knock it down"
    while walls:
        wall = random.choice(walls)
        walls.remove(wall)

        x, y = wall
        if x == 0:
            maze[x][y] = 1
        elif y == 0:
            maze[x][y] = 2
        elif maze[x - 1][y] == 0:
            maze[x][y] = 1
        elif maze[x][y - 1] == 0:
            maze[x][y] = 2
        else:
            walls.append(wall)

    return maze

