def calculator(stack, expression):
    for token in expression:
        if isinstance(token, int):
            stack.push(token)
        else:
            a = stack.pop()
            b = stack.pop()
            if token == '+':
                stack.push(b+a)
            elif token == '-':
                stack.push(b-a)
            elif token == '*':
                stack.push(b*a)
            elif token == '/':
                stack.push(b/a)
    return stack.pop()

