    max_ele = -float('inf') 
    if n > 0: 
        max_ele = heap[0] 
        i = 0 
        while (i < n): 
            l = 2 * i + 1
            r = 2 * i + 2
            if (l < n and heap[l] > max_ele): 
                max_ele = heap[l] 
            if (r < n and heap[r] > max_ele): 
                max_ele = heap[r] 
            i = i + 1
