def get_max_depth(tree):
    if tree is None:
        return 0

    max_depth = 0
    queue = []
    queue.append((tree, 1))

    while queue:
        node, level = queue.pop(0)

        if node is not None:
            max_depth = max(max_depth, level)

            if node.left:
                queue.append((node.left, level + 1))

            if node.right:
                queue.append((node.right, level + 1))

    return max_depth

