        self.data = data
        self.next = None


class Stack:
    def __init__(self):
        self.top = None

    def is_empty(self):
        return self.top is None

    def push(self, data):
        new_node = Node(data)

        if self.is_empty():
            self.top = new_node
            new_node.next = self.top
        else:
            new_node.next = self.top.next
            self.top.next = new_node
            self.top = new_node

    def pop(self):
        if self.is_empty():
            print("Stack is empty. Cannot perform pop operation.")
            return

        popped_data = self.top.data

        if self.top.next == self.top:
            self.top = None
        else:
            temp = self.top.next
            while temp.next != self.top:
                temp = temp.next
            temp.next = self.top.next
            self.top = temp

        return popped_data

    def display(self):
        if self.is_empty():
            print("Stack is empty.")
            return

        temp = self.top.next
        while temp != self.top:
            print(temp.data, end=" ")
            temp = temp.next
        print(temp.data)


