        if (temp.data == data):
            self.head = temp.next
            temp = None
            return  
        while (temp != None):
            if temp.data == data:  
                break  
            prev = temp
            temp = temp.next
        if (temp == None):
            return  
        prev.next = temp.next
        temp = None


