def binary_search_sqrt(number):
    left = 0
    right = number
    epsilon = 0.00001   # Precision of the result

    while right - left > epsilon:
        mid = (left + right) / 2
        if mid * mid < number:
            left = mid
        else:
            right = mid

    return left

