import heapq

def huffman_encoding(data):
    frequencies = {}
    for char in data:
        if char not in frequencies:
            frequencies[char] = 0
        frequencies[char] += 1

    heap = [[freq, [char, '']] for char, freq in frequencies.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        left = heapq.heappop(heap)
        right = heapq.heappop(heap)

        for pair in left[1:]:
            pair[1] = '0' + pair[1]
        for pair in right[1:]:
            pair[1] = '1' + pair[1]
        heapq.heappush(heap, [left[0] + right[0]] + left[1:] + right[1:])

    codes = {}
    for freq, code in heapq.heappop(heap)[1:]:
        codes[code] = freq

    return codes

def caesar_encode(string, shift):
    encoded_string = ""
    for char in string:
        # only encode letters
        if char.isalpha():
            # if uppercase, base = 65 (ASCII for A)
            if char.isupper():
                base = ord('A')
            # if lowercase, base = 97 (ASCII for a)
            else:
                base = ord('a')
            # perform caesar shift
            encoded_char = chr(base + (ord(char) - base + shift) % 26)
            encoded_string += encoded_char
        else:
            encoded_string += char
    return encoded_string

