def create_trie(dictionary):
    root = Node('')
    for word in dictionary:
        current = root
        for ch in word:
            found = False
            for node in current.children:
                if node.label == ch:
                    found = True
                    current = node
                    break
            if not found:
                node = Node(ch)
                current.children.add(node)
                current = node
    return root

