    box_row = pos[0] // 3
    box_col = pos[1] // 3

    for row in range(box_row * 3, box_row * 3 + 3):
        for col in range(box_col * 3, box_col * 3 + 3):
            if board[row][col] == num and (row, col) != pos:
                return False

    return True


