def merge_sorted_lists(head1, head2): 

    # start with the smallest value in either list 
    if head1.data < head2.data : 
        start_node = head1 
        previous = head1 
        head1 = head1.next
    else: 
        start_node = head2 
        previous = head2 
        head2 = head2.next

    # Traverse the list and insert smaller values in the combined sorted list
    while head1 is not None and head2 is not None: 
        if head1.data < head2.data : 
            previous.next = head1 
            previous = head1 
            head1 = head1.next
        else: 
            previous.next = head2 
            previous = head2 
            head2 = head2.next

    # Append the remaining nodes at the tail of the combined list
    if head1 is not None : 
        previous.next = head1 
    if head2 is not None : 
        previous.next = head2 

    return start_node

