def array_to_tree(arr):
    if len(arr) == 0:
        return None

    root = TreeNode(arr.pop(0))
    queue = [root]
    while len(arr):
        node = queue.pop(0)
        leftVal = arr.pop(0)
        if leftVal is not None:
            node.left = TreeNode(leftVal)
            queue.append(node.left)
        if len(arr):
            rightVal = arr.pop(0)
            if rightVal is not None:
                node.right = TreeNode(rightVal)
                queue.append(node.right)
    return root

def evaluate_prefix(prefix_expr):
    stack = []
    operators = set(['+', '-', '*', '/'])

    # Reverse the prefix expression
    prefix_expr = prefix_expr[::-1]

    # Traverse the expression
    for char in prefix_expr:
        # Push operand to stack
        if not char in operators: 
            stack.append(int(char))
        else:
            # Pop two operands from stack
            a = stack.pop()
            b = stack.pop()

            # Perform arithmetic operation and push result back to stack
            if char=='+': stack.append(a+b)
            elif char=='-': stack.append(a-b)
            elif char=='*': stack.append(a*b)
            elif char=='/': stack.append(a/b)

    return stack.pop()

