def findPeak(arr, n): 
    # Corner Case 
    if (n == 1): 
        return arr[0] 

    # If arr[0] is peak element 
    if (arr[0] >= arr[1]): 
        return arr[0] 

    # If arr[n-1] is peak element 
    if (arr[n - 1] >= arr[n - 2]): 
        return arr[n - 1] 

    # If there is no peak element 
    for i in range(1, n - 1): 
        if (arr[i] >= arr[i - 1] and arr[i] >= arr[i + 1]): 
            return arr[i] 

