    for k in range(len(board)):
        if board[i][k] == number:
            return False

    # Check column
    for k in range(len(board)):
        if board[k][j] == number:
            return False

    # Check soduku
    row_start = int(i - (i % 3))
    col_start = int(j - (j % 3))

    for k in range(3):
        for l in range(3):
            if board[row_start + k][col_start + l] == number:
                return False

    return True

