def compress_list(original_list):
    compressed_list = []
    count = 1

    for index in range(1, len(original_list)):
        if original_list[index] == original_list[index-1]:
            count += 1
        else:
            compressed_list.append(str(original_list[index-1]) + 'x' + str(count))
            count = 1
    compressed_list.append(str(original_list[index]) + 'x' + str(count))

    return compressed_list

