def same_chars(string1, string2):
    if len(string1) != len(string2):
        return False

    char_map = {}
    for char in string1:
        if char in char_map:
            char_map[char] += 1
        else:
            char_map[char] = 1

    for char in string2:
        if char not in char_map or char_map[char] == 0:
            return False
        else:
            char_map[char] -= 1

    return True

