def findSmallest(array):
    smallest = array[0]
    smallest_2 = array[1]

    for i in range(2, len(array)):
        if array[i] <= smallest:
            smallest_2 = smallest
            smallest = array[i]
        elif array[i] < smallest_2:
            smallest_2 = array[i]

    return (smallest, smallest_2)

