    swapped = True

    # Run the loop until no more swaps are needed
    while swapped:
        swapped = False
        for i in range(n-1):
            if arr[i] > arr[i+1]:
                # Swap elements if they are in the wrong order
                arr[i], arr[i+1] = arr[i+1], arr[i]
                swapped = True

