def reduce_time_complexity(arr):
    n = len(arr)
    result = 0

    for i in range(n):
        for j in range(i+1, n):
            if arr[i]+arr[j] == 0:
                result += 1

    # Get the sum of all pairs using a hashmap
    # This reduces the time complexity to O(n)
    s = set()
    for num in arr:
        if -num in s:
            result += 1
        else:
            s.add(num)

    return result

