class PriorityQueue: 

    def __init__(self): 
        self.elements = [] 

    def top(self): 
        if len(self.elements) > 0:
            return self.elements[0]
        else: 
            return None

    def is_empty(self): 
        return len(self.elements) == 0 

    def push(self, item): 
        self.elements.append(item) 
        self._heapify() 

    def pop(self): 
        length = len(self.elements) 
        if length == 0:
            return None 
        elif length == 1: 
            return self.elements.pop() 
        else: 
            top_element = self.elements[0] 
            self.elements[0] = self.elements.pop() 
            self._heapify() 
            return top_element 

    def _heapify(self): 
        length = len(self.elements) 
        for i in range((length - 1) // 2, -1, -1): 
            self._max_heapify(i) 

    def _max_heapify(self, index): 
        left = 2 * index + 1 
        right = 2 * index + 2 

        largest = index
        if left < len(self.elements) and self.elements[left] > self.elements[largest]: 
            largest = left 
        if right < len(self.elements) and self.elements[right] > self.elements[largest]: 
            largest = right 
        if largest != index: 
            self.elements[largest], self.elements[index] = self.elements[index], self.elements[largest] 
            self._max_heapify(largest)

def check_sudoku(puzzle):
    N = len(puzzle)
    if N != 9:
        return False

    # Check rows and columns
    for i in range(0, N):
        row = [puzzle[i][j] for j in range(0,N)]
        col = [puzzle[j][i] for j in range(0,N)]

        # Check if 1-9 occur exactly once in each row
        row_count = [0]*9
        col_count = [0]*9
        for x in row:
            if x == 0: 
                continue
            row_count[x-1] += 1
            if row_count[x-1] > 1:
                return False
        for y in col:
            if y == 0: 
                continue
            col_count[y-1] += 1
            if col_count[y-1] > 1:
                return False

    # Check the 3x3 sub sections of the puzzle
    for x in range(0,N,3):
        for y in range(0, N, 3):
            sub = [puzzle[i][j] for i in range(x,x+3) for j in range(y,y+3)]

            # Check if 1-9 occur exactly once in each sub section
            sub_count = [0]*9
            for z in sub:
                if z == 0:
                    continue
                sub_count[z-1] += 1
                if sub_count[z-1] > 1:
                    return False
    return True

