def assignCourses(courses, students):
    # Initialize assignments
    assignments = {student: [] for student in students}

    # Randomly assign courses to each student
    for course in courses:
        # Get an array of all the students that are eligible for the course
        availableStudents = [student for student in students if course not in assignments[student]]

