def generate_pprime_pyramid(levels):
    pyramid = []  # Initialize an empty pyramid list
    curr = 2  # Start with the first prime number, which is 2
    for row in range(levels):
        level_prime = []  # Initialize an empty list for prime numbers in each level
        # Generate the prime numbers for an individual level
        for col in range(row + 1):
            prime = True  # Assume the current number is prime
            # Check if the number is divisible by any numbers less than half of itself
            for i in range(2, curr // 2 + 1):
                if (curr % i) == 0:
                    prime = False  # If divisible, it is not prime
            # If the number is prime, add it to the current level
            if prime:
                level_prime.append(curr)
            curr += 1  # Move to the next number
        # Add the prime numbers for the current level to the pyramid
        pyramid.append(level_prime)
    return pyramid

