        for char in expression:
            if char.isdigit():
                self.stack.append(int(char))
            else:
                op1 = self.stack.pop()
                op2 = self.stack.pop()
                result = 0

                if char == '+':
                    result = op2 + op1
                elif char == '-':
                    result = op2 - op1
                elif char == '*':
