def hill_climbing(start_state, evaluate_fn):
  current = start_state
  best_state = current
  best_score = evaluate_fn(current)

  while True:
    neighbors = find_neighbors(current)
    for n in neighbors:
      score = evaluate_fn(n)
      if score > best_score:
        best_score = score
        best_state = n

    if best_score <= evaluate_fn(current):    
      break
    current = best_state

  return current

