def xy_coordinates(x, y):
    x_coordinates = []
    y_coordinates = []

    for i in x:
        x_coordinates.append(i * 2)
    for i in y:
        y_coordinates.append(i * 2)

    # Support for fractions
    for i in x:
        x_coordinates.append(i + 1/2)
    for i in y:
        y_coordinates.append(i + 1/2)

