def sum_of_primes(n):
    prime_sum = 0
    prime_count = 0
    num = 2 
    while prime_count < n: 
        if is_prime(num): 
            prime_count += 1
            prime_sum += num
        num += 1 
    return prime_sum

def is_prime(num):
    # Edge case 
    if num <= 1:
        return False

    # Check from 2 to n-1 
    for i in range(2, num):
        if num % i == 0:
            return False

    return True

