def binary_search(arr, x):
    """Perform a binary search on the given sorted list and
    return the index at which x is located, or -1 if not found.
    """
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            return mid
        elif x < arr[mid]:
            right = mid - 1
        else:
            left = mid + 1

    return -1

