def evaluate_expr(expr):
    '''Evaluate a given expression using a stack'''
    stack = []
    result = 0

    for char in expr: 
        if char.isdigit():
            stack.append(int(char))
        else: # if current character is an operator
            if char == '-':
                first = 0 - stack.pop()
            else:
                first = stack.pop()
            second = stack.pop()
            stack.append(first + second)

    return stack.pop()

