def rotate(arr, d): 
    n = len(arr) 
    d %= n
    g_c_d = __gcd(d, n)
    for i in range(g_c_d): 
        temp = arr[i] 
        j = i 
        while (1): 
            k = j + d 
            if k >= n: 
                k = k - n 
            if k == i: 
                break
            arr[j] = arr[k] 
            j = k

        arr[j] = temp

