def insertion_sort(data):
    for i in range(1, len(data)):
        current_value = data[i]
        position = i

        while position > 0 and data[position-1] > current_value:
            data[position] = data[position-1]
            position = position - 1

        data[position] = current_value

def create_anagrams(word):
    if len(word) <= 1:  
        return [word] 
    else: 
        anagrams = [] 
        for i, letter in enumerate(word): 
            for j in create_anagrams(word[:i]+word[i+1:]): 
                anagrams.append(letter + j) 

    return anagrams

def find_anagrams(words):
    """This function finds all the anagrams in a list of words."""
    anagrams = []
    seen = set()
    for word in words:
        sorted_word = ''.join(sorted(word))  # sort characters in word
        if sorted_word not in seen:
            seen.add(sorted_word)
            anagrams.append([word])  # append itself as first anagram
        else:
            for i in range(len(anagrams)):
                if ''.join(sorted(anagrams[i][0])) == sorted_word:
