    Sorts a 3x2 2D matrix in ascending order
    """
    sorted_matrix = [[None] * 2 for _ in range(6)]
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            smallest_element = float('inf')
            smallest_row = None
            smallest_col = None
            for x in range(len(matrix)):
                for y in range(len(matrix[0])):
                    if matrix[x][y] < smallest_element:
                        smallest_element = matrix[x][y]
                        smallest_row = x
                        smallest_col = y
            sorted_matrix[i * 2 + j][0] = smallest_row
            sorted_matrix[i * 2 + j][1] = smallest_col
            matrix[smallest_row][smallest_col] = float('inf')
