def solve_equation(n):
    solutions = []

    for x in range(1, n+1):
        for y in range(1, n+1):
            z = (x**4 + y**4) ** 0.25  # Calculate z using the fourth root
            if z.is_integer() and z <= n:  # Check if z is an integer and within the given range
                solutions.append((x, y, int(z)))

    return solutions

class BinaryTree:
    def __init__(self, root):
        self.root = root
        self.left = None
        self.right = None

    def insert_left(self, node):
        if self.left is None:
            self.left = BinaryTree(node)
        else:
            t = BinaryTree(node)
            t.left = self.left
            self.left = t

    def insert_right(self, node):
        if self.right is None:
            self.right = BinaryTree(node)
        else:
            t = BinaryTree(node)
            t.right = self.right
            self.right = t

import sys

def min_cost_path(cost, m, n): 
    if (m < 0 or n < 0): 
        return sys.maxsize 
    elif (m == 0 and n == 0): 
        return cost[m][n] 
    else: 
        return cost[m][n] + min(min_cost_path(cost, m-1, n-1), 
                               min_cost_path(cost, m-1, n), 
                               min_cost_path(cost, m, n-1))

def median(arr):
    arr.sort()
    n = len(arr)

    if n % 2 != 0:
        return arr[n // 2]
    else:
        return (arr[(n - 1) // 2] + arr[n // 2]) / 2

