def minimax(game, is_player1):
    if game.is_finished():
        return game.get_score()

    best_score = None
    for move in game.get_moves():
        game.make_move(move)
        score = minimax(game, not is_player1)
        game.undo_move()

        if is_player1:
            if score > best_score or best_score is None:
                best_score = score
        else:
            if score < best_score or best_score is None:
                best_score = score

    return best_score

