def evaluate_infix(expr):
    stack = []

    prec = {
        '^': 4,
        '*': 3,
        '/': 3,
        '+': 2,
        '-': 2,
        '(': 1
    }

    for el in expr:
        if el.isnumeric():
            stack.append(el)
        elif el == '(':
            stack.append(el)
        elif el == ')':
            temp = stack.pop()
            while temp != '(':
                op2 = int(stack.pop())
                op1 = int(stack.pop())
                result = eval(str(op1) + temp + str(op2))
                stack.append(str(result))
                temp = stack.pop()
        else:
            while stack and prec[stack[-1]] >= prec[el]:
                op2 = int(stack.pop())
                op1 = int(stack.pop())
                result = eval(str(op1) + stack.pop() + str(op2))
                stack.append(str(result))
            stack.append(el)

    while len(stack) != 1:
        op2 = int(stack.pop())
        op1 = int(stack.pop())
        result = eval(str(op1) + stack.pop() + str(op2))
        stack.append(str(result))

    return int(stack.pop())

