        self.children = {}
        self.isEndOfWord = False

class Trie(object):
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        current = self.root
        for letter in word:
            if letter not in current.children:
                current.children[letter] = TrieNode()
            current = current.children[letter]
        current.isEndOfWord = True

    def buildTrie(self, words):
        for word in words:
            self.insert(word)

