def generate_password():
    password = ""
    special_characters = [
        "!", "@", "#", "$", "%", "^", "&", "*", "(", ")", "[", "]"
    ]

    for i in range(10):
        random_digit = random.randint(0, 11)

        if random_digit <= 5:
            random_num = random.randint(0, 9)
            password += str(random_num)
        elif random_digit == 7:
            random_char = random.choice(special_characters)
            password += random_char
        else:
            random_char = random.choice(string.ascii_lowercase + string.ascii_uppercase)
            password += random_char

    return password

