def find_max(root):
    if root is None:
        return

    max_val = root.data

    left_max = find_max(root.left)
    right_max = find_max(root.right)

    if left_max > max_val:
        max_val = left_max

    if right_max > max_val:
        max_val = right_max

    return max_val

def sort(arr):
    for i in range(len(arr)-1):
        min_index = i
        for j in range(i+1, len(arr)):
            if arr[j] < arr[min_index]:
                min_index = j
        arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr

