class Interpreter:

    def __init__(self):
        self.operators = {
            '+':   self.add,
            '-':   self.sub,
            '/':   self.div,
            '*':   self.mul,
        }

    def parse(self, text):
        expressions = text.split(' ')
        return expressions

    def evaluate(self, expressions):
        operator = self.operators.get(expressions[1])
        if not operator:
            raise Exception('Invalid operator')
        return operator(expressions[0], expressions[2])

    def add(self, a, b):
        return int(a) + int(b)

    def sub(self, a, b):
        return int(a) - int(b)

    def div(self, a, b):
        return int(a) / int(b)

    def mul(self, a, b):
        return int(a) * int(b)

def find_permutations(string): 
    if len(string) == 0: 
        return [''] 
    prev_list = find_permutations(string[1:len(string)]) 
    next_list = [] 
    for i in range(0,len(prev_list)): 
        for j in range(0,len(string)): 
            new_string = prev_list[i][0:j]+string[0]+prev_list[i][j:len(string)-1] 
            if new_string not in next_list: 
                next_list.append(new_string) 
    return next_list

