def calculate_mode(arr):
    # Create a frequency table
    frequency_table = {}
    for num in arr:
        if num not in frequency_table:
            frequency_table[num] = 1
        else:
            frequency_table[num] += 1

    # Sort the frequency table
    sorted_frequency_table = sorted(frequency_table, key=frequency_table.__getitem__, reverse=True)

