def convert_str_to_int(s):
  if s is None or len(s) == 0:
    return 0
  i = 0
  num = 0
  while i < len(s):
    if s[i] >= '0' and s[i] <= '9':
      num *= 10
      num += int(s[i])
    i += 1
  return num

