def find_smallest(array):
    smallest_number = array[0]
    smallest_indices = []

    for i in range(len(array)):
        if array[i] < smallest_number:
            smallest_number = array[i]
            smallest_indices = [i]
        elif array[i] == smallest_number:
            smallest_indices.append(i)

    return smallest_indices

