import math

def is_prime(n):
    if n == 1 or(n % 2 == 0 and n > 2):
        return False
    else:
        sqrtn = math.isqrt(n)
        for divisor in range(3, sqrtn + 1, 2):
            if n % divisor == 0:
                return False
        return True

def is_mersenne_prime(n):
    if n < 2:
        return False

    p = math.log2(n + 1)
    if p.is_integer():

        # Check if p is prime
        if is_prime(int(p)):
            return True
    return False

