def is_anagram(str1, str2):
    if len(str1) != len(str2):
        return False

    hashmap = {}

    for letter in str1:
        if letter in hashmap:
            hashmap[letter] += 1
        else:
            hashmap[letter] = 1

    for letter in str2:
        if letter not in hashmap or hashmap[letter] == 0:
            return False
        else:
            hashmap[letter] -= 1

    for key in hashmap:
        if hashmap[key] != 0:
            return False

    return True

