def getNPrimes(n): 
    prime_list = []
    num = 2
    while len(prime_list) < n:
        is_prime = True
        for prime in prime_list:
            if num % prime == 0:
                is_prime = False
                break
        if is_prime:
            prime_list.append(num)
        num += 1 
    return prime_list[:n]

