def scrutinize_dict(d):
    # checking if input variable d is a dictionary
    if not isinstance(d, dict):
        print('Input variable d is not a Python dictionary.')
        return None

    data_report = {"total_keys": 0, "data_types_count": {}, "empty_values": 0}
    for key, value in d.items():
        data_report["total_keys"] += 1

        # tracking the data types
        value_type = type(value).__name__
        if value_type in data_report["data_types_count"]:
            data_report["data_types_count"][value_type] += 1
        else:
            data_report["data_types_count"][value_type] = 1

        # checking if the value is empty of any useful data 
        if value == "" or value == [] or value is None:
            data_report["empty_values"] += 1

    return data_report


