import collections

def solve_rubiks_cube(cube):
    queue = collections.deque()
    visited = set()
    queue.append(cube)

    while queue:
        c = queue.popleft()
        if c in visited:
            continue
        visited.add(c)

        if c.is_solved():
            return c

        for move in c.possible_moves():
            child_cube = c.apply_move(move)
            queue.append(child_cube)

    return None

