def sort_by_frequency(items):
    ''' Sorts a list of items by frequency in descending order. '''
    # Create the counts of each item in the list
    counts = dict()
    for i in items:
        if i in counts:
            counts[i] += 1
        else:
            counts[i] = 1

    # Sort the counts in descending order
    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)

    # Return the list of items sorted by frequency
    return [item[0] for item in sorted_counts]

