def generate_binary_tree(num_elements):
    if num_elements <= 0:
        return None

    root = Node(1)
    num_elements -= 1

    queue = []
    queue.append(root)

    while num_elements > 0:
        current_node = queue.pop(0)

        if num_elements > 0:
            current_node.left = Node(current_node.value * 2)
            queue.append(current_node.left)
            num_elements -= 1

        if num_elements > 0:
            current_node.right = Node(current_node.value * 2 + 1)
            queue.append(current_node.right)
            num_elements -= 1

    return root

