def islands(matrix):
    islands = 0

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):

            # Check if the cell is a 1
            if matrix[i][j] == 1:
                # If so, check if any of the neighbors is a 1
                if i > 0 and matrix[i-1][j] == 1:
                    continue
                if i < len(matrix)-1 and matrix[i+1][j] == 1:
                    continue
                if j > 0 and matrix[i][j-1] == 1:
                    continue
                if j < len(matrix[0])-1 and matrix[i][j+1] == 1:
                    continue
                # If no neighbors have a 1, then we have a new island
                islands += 1
    return islands

