def addTwoLists(l1, l2):
    head = ListNode()
    curr = head
    carry = 0

    while l1 or l2 or carry > 0:
        if l1:
            carry += l1.val
            l1 = l1.next
        if l2:
            carry += l2.val
            l2 = l2.next

        curr.next = ListNode(carry%10)
        curr = curr.next
        carry //= 10

    return head.next

