        '(xxx)xxx-xxxx',
        'xxx-xxx-xxxx',
        'xxxxxxxxx',
        'xxxxxxxxxx',
    ]

    normalized_number = ''.join(c for c in number if c.isdigit())

    for pattern in patterns:
        if len(normalized_number) == len(pattern.replace('x', '')):
            formatted_number = pattern.replace('x', '{}')
            if formatted_number.format(*normalized_number) == number:
                return True

    return False

