def get_subsets(nums, K):
    '''Returns all subsets of size K from the given set of numbers.'''
    subsets = []
    if K <= 0:
        return [[]]
    for idx in range(len(nums)):
        subset = [nums[idx]]
        subsets.append(subset)
    if K == 1:
        return subsets

    for k in range(2, K+1):
        for idx in range(len(nums)-k+1):
            subset = nums[idx:idx+k]
            subsets.append(subset)

    return subsets

