    prime_factors = [] 
    i = 2
    while i*i <= num: 
        if num % i: 
            i += 1 
        else: 
            num //= i 
            prime_factors.append(i) 
    if num > 1: 
        prime_factors.append(num) 
    if len(prime_factors) > 0: 
        return max(prime_factors) 
    else: 
        return None

