import random
import numpy as np

def generate_sudoku(mask_rate=0.5):
    while True:
        n = 9
        mat = np.zeros((n, n), dtype=int)

        try:
            fill_values(mat, 0, 0)
        except:
            continue

        mask = np.random.random((n,n))<mask_rate
        mat = np.ma.array(mat, mask=mask, fill_value=0)

        return mat.filled()

def fill_values(mat, i, j):
    n = 9
    values = list(range(1, n + 1))
    np.random.shuffle(values)
    for x in values:
        if valid_value(mat, i, j, x):
            mat[i][j] = x
            if i == n - 1:
                if j == n - 1:
                    return
                fill_values(mat, 0, j + 1)
            else:
                fill_values(mat, i + 1, j)

def valid_value(mat, i, j, x):
    n = 9
    for y in range(n):
        if mat[y][j] == x: return False
    for y in range(n):
        if mat[i][y] == x: return False
    for y in range(3 * (i // 3), 3 * (i // 3) + 3):
        for z in range(3 * (j // 3), 3 * (j // 3) + 3):
            if mat[y][z] == x: return False
    return True

