def is_prime(n):
    """Returns True if n is a prime number"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def perfect_cubes_primes(n):
    """List down all perfect cubes of prime numbers under n"""
    cubes = []
    for i in range(2, n):
        if is_prime(i):
            cube = i ** 3
            if cube < n:
                cubes.append(cube)
            else:
                break
    return cubes

