        return

    top = 0
    bottom = len(matrix)-1
    left = 0
    right = len(matrix[0])-1

    while True:
        if left > right: 
            break
        for i in range(left, right+1):
            print(matrix[top][i])
        top += 1

        if top > bottom: 
            break
        for i in range(top, bottom+1):
