def stable_marriage(men, women):
    proposals = {}
    engaged = {}

    while len(proposals.keys()) < len(men):
        for man in men:
            if man not in proposals:
                woman = men[man].pop(0)

                if woman not in engaged:
                    engaged[woman] = man
                    proposals[man] = woman
                else:
                    current_man = engaged[woman]
                    if women[woman].index(man) < women[woman].index(current_man):
                        engaged[woman] = man
                        proposals[man] = woman
                        del proposals[current_man]

    return engaged

