    while len(list1) and len(list2):
        if list1[0] < list2[0]:
            merged_list.append(list1.pop(0))
        else: 
            merged_list.append(list2.pop(0))

    if len(list1):
        merged_list += list1
    if len(list2):
        merged_list += list2

    return merged_list

