def string_compression(s):
    count = 1
    compressed_list = []

    for i in range(len(s)-1):
        if s[i] == s[i+1]:
            count += 1
        else:
            compressed_list.append(s[i] + str(count))
            count = 1

    compressed_list.append(s[-1] + str(count))
    return ''.join(compressed_list)

