def topologicalSort(adj): 
    indeg = [0] * V 
    top_order = [] 

    # calculate in-degrees of all vertices 
    for i in range(V): 
        for j in adj[i]:
            indeg[j] += 1

    # Create a queue and enqueue all vertices with indegree 0 
    queue = []
    for i in range(V): 
        if indeg[i] == 0: 
            queue.append(i) 

    # Perform topological sorting
    curr_count = 0
    while queue: 
        u = queue.pop(0) 
        top_order.append(u) 

        # decrease every vertex's indegree by 1 as long as all its edges are traversed 
        for v in adj[u]: 
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v) 
        curr_count += 1

    # Check if there was a cycle
    if curr_count != V: 
        print("There exists a cycle in the graph") 
        return
    else: 
        for i in top_order: 
            print(i)

        return top_order

def primes_in_range(start, end):
    prime_numbers = []
    for num in range(start, end + 1):
        if num > 1:  # primes are greater than 1
            for i in range(2, num):
                if (num % i) == 0:  # if num is divisible by any number between 2 and num, it's not prime
                    break
            else:
                prime_numbers.append(num)
    return prime_numbers

