def find_max_value(tree):
    max_val = 0  # initial maximum value
    def traverse(dictionary):
        nonlocal max_val
        for key, val in dictionary.items():
            if isinstance(val, int):  # check if the value is an integer
                if val > max_val:
                    max_val = val  # update the maximum value if a larger one is found
            else:
                traverse(val)  # recursively traverse inner dictionaries

    traverse(tree)
    print(max_val)  # print the maximum value

