def eliminate_duplicates(arr):
    '''Function to eliminate adjacent duplicates in an array.'''
    if not arr or len(arr) < 2:
        return arr
    prev = arr[0]
    result = []
    for i in range(1, len(arr)):
        if arr[i] != prev:
            result.append(prev)
            prev = arr[i]
    result.append(arr[-1])
    return result

