import numpy as np

class TicTacToeAgent:
    def __init__(self, turn='X'):
        self.turn = turn
        self.opponent = 'O' if turn == 'X' else 'X'

    def make_move(self, state):
        outcome, move = self.minimax(state, self.turn)
        return move

    def minimax(self, state, player):
        if self.game_over(state):
            winner = self.winner(state)
            if winner == self.turn:
                return 1, None
            elif winner == self.opponent:
                return -1, None
            else:
                return 0, None

        if player == self.turn:
            best_outcome = -float('inf')
            best_move = None
            for row in range(3):
                for col in range(3):
                    if state[row][col] == 0:
                        state[row][col] = self.turn
                        _, move = self.minimax(state, self.opponent)
                        state[row][col] = 0
                        if move is not None:
                            best_move = (row, col)
                        best_outcome = max(best_outcome, _)
            return best_outcome, best_move
        else:
            best_outcome = float('inf')
            best_move = None
            for row in range(3):
                for col in range(3):
                    if state[row][col] == 0:
                        state[row][col] = self.opponent
                        _, move = self.minimax(state, self.turn)
                        state[row][col] = 0
                        if move is not None:
                            best_move = (row, col)
                        best_outcome = min(best_outcome, _)
            return best_outcome, best_move

    def game_over(self, state):
        return tuple(np.sum(state, axis=1)) in (3, -3) or tuple(np.sum(state, axis=0)) in (3, -3) or np.sum(np.diagonal(state)) in (3, -3) or np.sum(np.fliplr(state).diagonal()) in (3, -3)

    def winner(self, state):
        for player in ('X', 'O'):
            if tuple(np.sum(state, axis=1)) == (3,) * 3:
                return player
            elif tuple(np.sum(state, axis=0)) == (3,) * 3:
                return player
            elif np.sum(np.diagonal(state)) == 3: 
                return player
            elif np.sum(np.fliplr(state).diagonal()) == 3: 
                return player
            elif tuple(np.sum(state, axis=1)) == (-3,) * 3:
                return player
            elif tuple(np.sum(state, axis=0)) == (-3,) * 3: 
                return player
            elif np.sum(np.diagonal(state)) == -3: 
                return player
            elif np.sum(np.fliplr(state).diagonal()) == -3:
                return player
        return None

def solve_knapsack(capacity, items):
    selected = []
    curr = capacity

    for item in items:
        ratio = item[1]/item[0]
        items.sort(key=lambda x: x[1]/x[0], reverse=True)

    for item in items:
        if item[0] <= curr:
            selected.append(item)
            curr -= item[0]

        if curr == 0:
            break

    return selected

