def ternary_search(arr, low, high, x):
    if (high >= low):
        mid1 = low + ((high - low) // 3)
        mid2 = high - ((high - low) // 3)

        if arr[mid1] == x:
            return mid1

        if arr[mid2] == x:
            return mid2

        if x < arr[mid1]:
            return ternary_search(arr, low, mid1 - 1, x)
        elif x > arr[mid2]:
            return ternary_search(arr, mid2 + 1, high, x)
        else:
            return ternary_search(arr, mid1 + 1, mid2 - 1, x)
    return -1

