def divide_ints(num1, num2):
    if num2 == 0:
        return 'Cannot divide by 0'
    else:
        num1_sign = num1 >= 0 
        num2_sign = num2 >= 0 
        ans = 0
        num1 = abs(num1)
        num2 = abs(num2)
        while (num1 - num2) >= 0:
