def caesar_cipher(message, shift):
    cipherText = ""
    for char in message:
        if char.isalpha():
            charCode = ord(char) + shift
            # Wrap around if character code gets too high or too low
            if charCode > ord("z"):
                charCode -= 26
            elif charCode < ord("a"):
                charCode += 26

            cipherText += chr(charCode)
        else:
            cipherText += char

    return cipherText

