    turns = iter(player1, player2) # Players rotate turns

    for pawn1, pawn2 in zip(player1, player2): # Iterate over each of the pawns
        current_turn = next(turns)

        while not pawn1.position == 5 or not pawn2.position == 5:
            if current_turn == player1:
                pawn1.move()
            else:
                pawn2.move()
            current_turn = next(turns) # Switches turns

    if player1.status == 3: # In order to win, the player must have three pawns in the finish line
        return "Player 1 wins!"
    else:
        return "Player 2 wins!"

