    """Adds the next prime number to a list of integers."""
    if not numbers:
        return [2]  # Special case when the list is empty
    last_number = numbers[-1]
    next_prime = last_number + 1
    while True:
        if is_prime(next_prime):
            numbers.append(next_prime)
            break
        next_prime += 1
    return numbers

