def traverse_spiral(array):
    result = []
    i, j, direction = 0, 0, 0

    for _ in range(len(array) * len(array[0])):
        result.append(array[i][j])
        array[i][j] = 0

        if direction == 0:
            j += 1
            if j >= len(array[0]) or array[i][j] == 0:
                j -= 1
                direction = 1
                i += 1
        elif direction == 1:
            i += 1
            if i >= len(array) or array[i][j] == 0:
                i -= 1
                direction = 2
                j -= 1
        elif direction == 2:
            j -= 1
            if j < 0 or array[i][j] == 0:
                j += 1
                direction = 3
                i -= 1
        elif direction == 3:
            i -= 1
            if i < 0 or array[i][j] == 0:
                i += 1
                direction = 0
                j += 1

    return result

