def search(dict, word):
  low = 0
  high = len(dict) - 1

  while low <= high:
    mid = (low + high) // 2
    if dict[mid] < word:
      low = mid + 1
    elif dict[mid] > word:
      high = mid - 1
    else:
      return mid

  return -1

