def bfs(maze):
    queue = []
    start_pos = (0, 0)
    queue.append([start_pos])

    while queue:
        path = queue.pop(0)
        pos = path[-1]

        if pos == (len(maze)-1, len(maze[0]) - 1):  
            return path 

        for x, y in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_pos = (pos[0] + x, pos[1] + y)
            if 0 <= new_pos[0] < len(maze) and 0 <= new_pos[1] < len(maze[0]) and maze[new_pos[0]][new_pos[1]] != 'X':
                new_path = list(path)
                new_path.append(new_pos)
                queue.append(new_path)

