def sort_01(arr):
    # Return empty array if it is empty
    if len(arr) == 0:
        return arr

    # Initializing variables
    left = 0
    right = len(arr) - 1

    # Traverse through array
    while left < right:
        # Swap when 0 appears after 1
        if arr[left] > arr[right]:
            arr[left], arr[right] = arr[right], arr[left]

        # Increment left pointer if 0 appears
        if arr[left] == 0:
            left += 1

        # Decrement right pointer if 1 appears
        if arr[right] == 1:
            right -= 1

    # Return sorted array
    return arr

