def search_word(boggle_board, row, col, visited, string, words, dictionary): 
    # Mark the current cell as visited 
    visited[row][col] = True

    # Add the current character to string 
    string += boggle_board[row][col] 

    # If string is present in dictionary, then add it 
    if string in dictionary: 
        words.append(string) 

    # Traverse the 8 adjacent cells of boggle_board[row][col] 
    for i in range(row - 1, row + 2): 
