def interpolationSearch(arr, low, high, x):
    if low > high:
        return -1

    mid = low + (high - low) * (x - arr[low]) // (arr[high] - arr[low])

    if mid < 0 or mid > high:
        return -1

    if arr[mid] == x:
        return mid

    if arr[mid] < x:
        return interpolationSearch(arr, mid + 1, high, x)
    else:
        return interpolationSearch(arr, low, mid - 1, x)

