def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True

    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i*i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def largest_prime_factor(n):

    max_prime = -1

    while n % 2 == 0:
        max_prime = 2
        n >>= 1

    for i in range(3, int(math.sqrt(n))+1, 2):
        while n % i == 0:
            max_prime = i
            n //= i
    if n > 2:
        max_prime = n

    return int(max_prime)

