def merge(left, right):
    merged_array = []

    while (len(left) > 0) and (len(right) > 0):
        if left[0] < right[0]:
            merged_array.append(left[0])
            left.pop(0)
        else:
            merged_array.append(right[0])
            right.pop(0)

    if len(left) > 0:
        merged_array.extend(left)
    if len(right) > 0:
        merged_array.extend(right)

    return merged_array

