def compress_string(s):
    if len(s) == 0:
        return ''

    compressed = ''
    count = 1
    for i, c in enumerate(s):
        if i < len(s) - 1:
            if s[i+1] == c:
                count += 1
            else:
                compressed += c + str(count)
                count = 1
        else:
            compressed += c + str(count)

