def find_deepest_node(root): 
    if root is None: 
        return None

    queue = []  
    queue.append(root) 

    deepest_node = root 
    while queue: 
        node = queue.pop(0) 

        if node.left: 
            queue.append(node.left) 
            deepest_node = node.left 
        if node.right: 
            queue.append(node.right) 
            deepest_node = node.right 

    return deepest_node

