def evaluate(expression):
    stack = []
    res = 0

    for char in expression:
        if char.isdigit():
            stack.append(int(char))
        else:
            val1 = stack.pop()
            val2 = stack.pop()
            if char == '+':
                res = val1 + val2
            elif char == '-':
                res = val2 - val1
            elif char == '*':
                res = val2 * val1
            else:
                res = int(val2 / val1)
            stack.append(res)

    return stack.pop()

