def case_swap(a, b):
    '''This function will take two strings and swap the cases of the characters if they are the same.'''
    a_chars = list(a)
    b_chars = list(b)
    for i in range(len(a)):
        a_char = a_chars[i]
        b_char = b_chars[i]
        if a_char.islower() == b_char.islower():
            a_chars[i] = a_char.swapcase()
            b_chars[i] = b_char.swapcase()
    return ''.join(a_chars), ''.join(b_chars)

