def binary_search(n, arr):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if arr[mid] > n:
            high = mid - 1
        elif arr[mid] < n:
            low = mid + 1
        else:
            return mid
    return -1

def mergeLinkedLists(head1, head2):
    # If the first linked list is empty
    if head1 is None:
        return head2

    # If the second linked list is empty
    if head2 is None:
        return head1

    # Pick the smaller value
    if head1.val < head2.val :
        head1.next = mergeLinkedLists(head1.next, head2)
        return head1
    else :
        head2.next = mergeLinkedLists(head1, head2.next)
        return head2

def binary_search(arr, low, high, target):
    if high >= low:
        mid = (high + low) // 2

        if arr[mid] == target:
            return mid

        elif arr[mid] > target:
            return binary_search(arr, low, mid - 1, target)

        else:
            return binary_search(arr, mid + 1, high, target)

    else:
        return -1

