    # check row
    for i in range(len(board[0])):
        if board[row][i] == k: 
            return False

    # check column 
    for i in range(len(board)):
        if board[i][col] == k:
            return False

    # check 3x3 grid
    boxRow = row - row % 3
    boxCol = col - col % 3

    for i in range(boxRow, boxRow + 3):
        for j in range(boxCol, boxCol + 3):
            if board[i][j] == k:
                return False
    return True

