# Neuron class
class Neuron:
    # Initialize inputs and weights
    def __init__(self, numInputs):
        self.weights = []
        for i in range(numInputs):
            self.weights.append(random.uniform(-1, 1))

    # Process inputs and produce output
    def process(self, inputs):
        # Multiply inputs by weights
        output = 0
        for i in range(len(self.weights)):
            output += self.weights[i] * inputs[i]

        # Use sigmoid function to normalize result
        return 1 / (1 + math.exp(-output))

def calculate_influence_coefficients(x, y, nx, ny, dl):
    # Calculate influence coefficients
    A = np.zeros((len(x), len(x)))
    for i in range(len(x)):
        for j in range(len(x)):
            if i != j:
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                r = np.sqrt(dx**2 + dy**2)
                cos_theta = dx / r
                sin_theta = dy / r
                A[i, j] = (nx[j]*cos_theta + ny[j]*sin_theta) * np.log(1 + dl[j]/r)
    return A

