def firstUniqChar(s):
    frequency = {}  # Step 1: Create dictionary

    # Step 2: Count the occurrence of each character
    for char in s:
        if char not in frequency:
            frequency[char] = 1
        else:
            frequency[char] += 1

    # Step 3: Check the corresponding count of each character
    for char in s:
        if frequency[char] == 1:
            return char

    return None  # Return None if there is no unique character in the string

