    for direction in directions:
        for i in range(4):
            # Calculate score for the current sequence
            sequence_score = 0
            for j in range(4):
                sequence_score += board[x + direction[0] * j][y + direction[1] * j]
            # Increase score if player has 3 pieces in the sequence
            if sequence_score == 3:
               score += 100
            # Increase score if opponent has 3 pieces in the sequence
