def sum_of_odd_numbers(n):
    if n == 1:  # base case
        return 1
    elif n % 2 == 0:  # if n is even, skip it
        return sum_of_odd_numbers(n-1)
    else:  # if n is odd, add it to the sum
        return n + sum_of_odd_numbers(n-2)

