def unique_element_positions(arr):
    # 建立一個空字典來存儲元素及其出現的次數
    count_dict = {}

    # 遍歷列表，更新每個元素的次數
    for num in arr:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # 建立一個空列表來存儲唯一元素的位置
    positions = []

    # 遍歷字典，找出出現次數為一的元素，並將其位置添加到列表中
    for key, value in count_dict.items():
        if value == 1:
            positions.append(arr.index(key))

    # 返回位置列表
    return positions


