def evaluate(node):
    if node.isLeaf():
        return node.value
    else:
        m1 = evaluate(node.left)
        m2 = evaluate(node.right)

    if node.value == '+':
        return m1 + m2
    elif node.value == '-':
        return m1 - m2
    elif node.value == '*':
        return m1 * m2
    elif node.value == '/':
        return m1 / m2
    else:
        return None

def partition(arr, low, high):
    i = (low - 1)
    pivot = arr[high]

    for j in range(low, high):
        if arr[j] <= pivot:
            i = i + 1
            arr[i], arr[j] = arr[j], arr[i]

    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return (i + 1)

def quickSort(arr, low, high):
    if low < high:
        pi = partition(arr, low, high)
        quickSort(arr, low, pi - 1)
        quickSort(arr, pi + 1, high)

