def sieveOfEratosthenes(n):
    prime = [True for i in range(n + 1)]
    p = 2
    prime_numbers = []
    while (p * p <= n):
        if (prime[p] == True):
            for i in range(p * 2, n + 1, p):
                prime[i] = False
        p += 1

    prime[0] = False
    prime[1] = False
    for p in range(n + 1):
        if prime[p]:
            prime_numbers.append(p)

    return prime_numbers

