def ordered_crossover(parent1, parent2, crossover_prob):
    # Create a copy of the parents to use as the offspring
    offspring = parent1.copy()
    # Check if crossover should be performed
    if random.random() < crossover_prob:
        # Select a random subset of cities from the first parent
        subset = random.sample(range(len(parent1)), len(parent1)//2)
        # Fill in the remaining cities in the offspring with the cities from the second parent
        for i in range(len(parent2)):
            if parent2[i] not in subset:
                for j in range(len(offspring)):
                    if offspring[j] == -1:
                        offspring[j] = parent2[i]
                        break
        # Fix any duplicate cities in the offspring
        for i in range(len(offspring)):
            if offspring.count(offspring[i]) > 1:
                for j in range(len(offspring)):
                    if offspring[j] not in offspring[:i]:
                        offspring[i] = offspring[j]
                        offspring[j] = offspring[i]
                        break
    return offspring

