def findFrequency(arr):
    # Creates an empty dictionary
    freq = {}
    max = arr[0]

    # Traverse all elements in the array
    for i in arr:
        if i in freq:
            freq[i] += 1
        else:
            freq[i] = 1

    # Traverse the dictionary to find the most frequent element
    for key, value in freq.items():
        if value > max:
            max = value
            max_element = key
        else:
            max = max
            max_element = max_element

    return max_element

