def generate_ip_mask(subnetMask):
    octets = []
    for i in range(4):
        if subnetMask >= 8:
            octets.append(255)
            subnetMask -= 8
        else:
            octets.append(256 - 2 ** (8 - subnetMask))
            subnetMask = 0
    return "%d.%d.%d.%d" % (octets[0], octets[1], octets[2], octets[3])

