def pascal_triangle(numRows):
   if numRows == 0:
      return []

   triangle = [[1]]

   for level in range(1, numRows):
       prev_level = triangle[level-1]
       cur_level = [1]

       for i in range(len(prev_level) - 1):
           cur_level.append(prev_level[i] + prev_level[i+1])
       cur_level.append(1)

       triangle.append(cur_level)

   return triangle

