def first_fit(process_sizes, memory_slot_sizes):
  result = []  # This list will store the allocated memory slots for each process
  for process_size in process_sizes:
    for slot_index, slot_size in enumerate(memory_slot_sizes):
      if slot_size >= process_size:
        result.append((slot_index, process_size))  # Add the allocated slot to the result list
        memory_slot_sizes[slot_index] -= process_size  # Update the remaining slot size
        break  # Stop searching for available slots for the current process
  return result

