import cmath

class QuadraticEquation:
    def __init__(self, a, b, c):
        self.a = a
        self.b = b
        self.c = c

    def get_roots(self):
        d = (self.b**2) - (4*self.a*self.c)

        # Find two solutions using quadratic formula
        sol1 = (-self.b-cmath.sqrt(d))/(2*self.a)
        sol2 = (-self.b+cmath.sqrt(d))/(2*self.a)

        return (sol1, sol2)

