def sort_array(A):
    for i in range(len(A) - 1):
        min = A[i]
        min_index = i
        for j in range(i + 1, len(A)):
            if A[j] < min:
                min = A[j]
                min_index = j
        if min_index != i:
            A[i], A[min_index] = A[min_index], A[i]
    return A

def merge_sorted_arrays(arr1, arr2):
    res_arr = []
    i = 0
    j = 0

    while(i < len(arr1) and j < len(arr2)):
        if(arr1[i] > arr2[j]):
            res_arr.append(arr2[j])
            j += 1
        else:
            res_arr.append(arr1[i])
            i += 1

    if(i < len(arr1)):
        res_arr = res_arr + arr1[i:]
    elif(j < len(arr2)):
        res_arr = res_arr + arr2[j:]

    return res_arr

