def detect_anagrams(dictionary):
    """
    Detect anagrams using a dictionary
    """
    result = {}
    for word in dictionary:
        key = ''.join(sorted(word))
        if key not in result:
            result[key] = [word]
        else:
            result[key].append(word)
    return result

