def search_index(array, value):
    low = 0 
    high = len(array)-1

    while low <= high:
        mid = (low + high) // 2
        mid_value = array[mid] 
        if mid_value == value:
            return mid
        elif mid_value < value:
            low = mid + 1
        else:
            high = mid - 1
    return None

