def get_min_coins(coins, total):
    num_coins = [0] * (total + 1)
    num_coins[0] = 0

    for i in range(1, total + 1):
        num_coins[i] = float("inf")
        for coin in coins:
            if i >= coin:
                num_coins[i] = min(num_coins[i], 1+num_coins[i - coin])

    return num_coins[total]

