    def one(num):
        switcher = {
            1: 'one',
            2: 'two',
            3: 'three',
            4: 'four',
            5: 'five',
            6: 'six',
            7: 'seven',
            8: 'eight',
            9: 'nine'
        }
        return switcher.get(num)

    def two_less_20(num):
        switcher = {
            10: 'ten',
            11: 'eleven',
            12: 'twelve',
            13: 'thirteen',
            14: 'fourteen',
            15: 'fifteen',
            16: 'sixteen',
            17: 'seventeen',
            18: 'eighteen',
            19: 'nineteen'
        }
        return switcher.get(num)

    def ten(num):
        switcher = {
            2: 'twenty',
            3: 'thirty',
            4: 'forty',
            5: 'fifty',
            6: 'sixty',
            7: 'seventy',
            8: 'eighty',
            9: 'ninety'
        }
        return switcher.get(num)

    def two(num):
        if not num:
            return ''
        elif num < 10:
            return one(num)
        elif num < 20:
            return two_less_20(num)
        else:
            tens, remainder = divmod(num, 10)
            return ten(tens) + '-' + one(remainder) if remainder else ten(tens)

    def three(num):
        hundred, remainder = divmod(num, 100)
        return one(hundred) + ' hundred' + ' and ' + two(remainder) if hundred and remainder else one(hundred) + ' hundred' if hundred else two(remainder)

    billion, remainder = divmod(n, 10**9)
    million, remainder = divmod(remainder, 10**6)
    thousand, remainder = divmod(remainder, 10**3)
    result = ''
    if billion:        
        result += three(billion) + ' billion'
    if million:
        result += ' ' if result else ''    
        result += three(million) + ' million'
    if thousand:
        result += ' ' if result else ''
        result += three(thousand) + ' thousand'
    if remainder:
        result += ' ' if result else ''
        result += three(remainder)
