def eval_postfix(expr):   
    stack = []  
    for val in expr:   
        if val == '+' or  val == '-' or val == '*' or val == '/':
            a = int(stack.pop())  
            b = int(stack.pop())  
            result = 0
            if val == '+':  
                result = a + b  
            elif val == '-':  
                result = b - a  
            elif val == '*':  
                result = a * b 
            elif val == '/':  
                result = b / a
            stack.append(result)
        else:
            stack.append(val)  
    print("Result is:", int(stack.pop()))

