    min_index = i

    # Find the position of the minimum value in the unsorted subarray
    for j in range(i+1, len(arr)):
      if arr[min_index] > arr[j]:
        min_index = j

    # Swap the minimum value with the current position
    arr[i], arr[min_index] = arr[min_index], arr[i]

  return arr

