def generate_parenthesis(n):
    result = []

    def generate_parens(left, right, n, curr_string):
        if left == n and right == n:
            result.append(curr_string)
            return

        # open a new parenthesis if one can still be opened
        if left < n:
            generate_parens(left + 1, right, n, curr_string + "(")

        # close a parenthesis if it's safe to do so
        if right < left:
            generate_parens(left, right + 1, n, curr_string + ")")

    generate_parens(0, 0, n, "")
    return result

def optimize_job_distribution(jobs, employees):
    total_workload = sum(jobs.values())
    workload_per_employee = total_workload // len(employees)

    for employee in employees:
        assigned_jobs = []
        for job, duration in jobs.items():
            if duration <= workload_per_employee and employee.has_skill(job):
                assigned_jobs.append(job)
                workload_per_employee -= duration

        employee.assign_jobs(assigned_jobs)

    return employees

