def rotate(array, k):
    """Rotate an array of n integers k steps to the right."""
    # assumption: k is not greater than array length

    if k == 0:
        return array
    else:
        temp = array[len(array) - k:]
        for i in range(len(array) - k):
            array[len(array) - 1 - i] = array[len(array) - k -1 - i]
        for i in range(k):
            array[i] = temp[i]
    return array

