class Fraction:  
    # Constructor for fraction class
    def __init__(self, numerator, denominator):
        self.numerator = numerator
        self.denominator = denominator

    # Function to add two fractions
    def addFraction(self, frac_c): 
        new_numerator = (self.numerator*frac_c.denominator)+(self.denominator*frac_c.numerator)
        new_denominator = (self.denominator*frac_c.denominator)
        common = self.gcd(new_numerator, new_denominator)
        return Fraction(new_numerator//common, new_denominator//common)

    # Function to multiply two fractions
    def mulFraction(self, frac_c):
        new_numerator = self.numerator * frac_c.numerator
        new_denominator = self.denominator * frac_c.denominator
        common = self.gcd(new_numerator, new_denominator)
        return Fraction(new_numerator//common, new_denominator//common)

    # Function to divide two fractions
    def divFraction(self, frac_c):
        new_numerator = self.numerator * frac_c.denominator
        new_denominator = self.denominator * frac_c.numerator
        common = self.gcd(new_numerator, new_denominator)
        return Fraction(new_numerator//common, new_denominator//common)

    # Utility function to return 
    # gcd of a and b
    def gcd(self, a, b): 
        if a == 0: 
            return b  
        return self.gcd(b%a, a)

