def minimize_sum(numbers):
    n = len(numbers)
    sum_matrix = [[0] * (n+1) for _ in range(n+1)]

    for i in range(1, n+1):
        sum_matrix[i][i] = numbers[i-1]

    for sub_len in range(2, n+1):
        for i in range(1, n-sub_len+2):
            j = i + sub_len - 1
            min_sum = float('inf')

            for k in range(i, j):
                current_sum = sum_matrix[i][k] + sum_matrix[k+1][j]
                if current_sum < min_sum:
                    min_sum = current_sum

            sum_matrix[i][j] = min_sum

    return sum_matrix[1][n]

