def knapsack(weight_limit, weights, values):
    # base cases 
    if weight_limit == 0 or len(weights) == 0:
        return 0 

    # if first item weights more than the weight_limit,
    # do not include it in the knapsack 
    if weights[0] > weight_limit:
        return knapsack(weight_limit, weights[1:], values[1:])

    # if the first item is included 
    include = values[0] + knapsack(weight_limit - weights[0], weights[1:], values[1:])
    # if the first item is excluded 
    exclude = knapsack(weight_limit, weights[1:], values[1:])
    return max(include, exclude)

