class LinkedList:
    # Constructor for empty Linked List
    def __init__(self):
        self.head = None

    def insert(self, data):
        if self.head == None:
            self.head = Node(data)
        else:
            current_node = self.head
            while current_node.next != None:
                current_node = current_node.next
            current_node.next = Node(data)

    def to_list(self):
        nodes = []
        current_node = self.head
        while current_node != None:
            nodes.append(current_node.data)
            current_node = current_node.next
        return nodes

# Function to merge two sorted linked lists
def merge_linked_lists(list_1, list_2):
    # Create linked lists from lists
    llist_1 = LinkedList()
    for i in list_1:
        llist_1.insert(i)
    llist_2 = LinkedList()
    for i in list_2:
        llist_2.insert(i)

    # Combine the linked lists
    llist_3 = LinkedList()
    current_1 = llist_1.head
    current_2 = llist_2.head
    while current_1 and current_2:
        if current_1.data < current_2.data:
            llist_3.insert(current_1.data)
            current_1 = current_1.next
        else:
            llist_3.insert(current_2.data)
            current_2 = current_2.next

    # Add the remaining elements of llist1
    while current_1:
        llist_3.insert(current_1.data)
        current_1 = current_1.next

    # Add the remaining elements of llist2
    while current_2:
        llist_3.insert(current_2.data)
        current_2 = current_2.next

    return llist_3.to_list()

