def can_partition_k_subsets(arr, k):
    total_sum = sum(arr)

    if k == 0 or total_sum % k != 0:
        return False

    target = total_sum // k
    arr.sort(reverse=True)

    subsets = [0] * k

    def backtrack(index):
        if index >= len(arr):
            return True

        for i in range(k):
            if subsets[i] + arr[index] > target:
                continue
            if i > 0 and subsets[i] == subsets[i - 1]:
                continue

            subsets[i] += arr[index]

            if backtrack(index + 1):
                return True

            subsets[i] -= arr[index]

            if subsets[i] == 0:
                break

        return False

    return backtrack(0)

