        return None  # If there are fewer than 2 numbers, return None or handle it as needed.

    # Initialize variables to hold the largest and smallest numbers
    largest1 = second_largest = -float('inf')
    smallest1 = second_smallest = float('inf')

    for number in numbers:
        if number > largest1:
            second_largest = largest1
            largest1 = number
        elif second_largest < number <= largest1:
            second_largest = number

        if number < smallest1:
            second_smallest = smallest1
            smallest1 = number
        elif second_smallest > number >= smallest1:
            second_smallest = number

    # Calculate the products
    product1 = largest1 * second_largest
    product2 = smallest1 * second_smallest

    # Return the maximum of the two products
    return max(product1, product2)

def find_target_count(nums, target):
    def binary_search_left(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def binary_search_right(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    left = binary_search_left(nums, target)
    if left == len(nums) or nums[left] != target:
        return 0
    right = binary_search_right(nums, target)
    return right - left + 1

