def sieve_of_eratosthenes(low, high):
    if low > high:
        return []

    if low < 2:
        low = 2

    is_prime = [True] * (high + 1)
    is_prime[0] = is_prime[1] = False

    p = 2
    while p * p <= high:
        if is_prime[p]:
            for i in range(p * p, high + 1, p):
                is_prime[i] = False
        p += 1

    primes = [num for num in range(low, high + 1) if is_prime[num]]
    return primes

