def find_bridges(graph):
    bridges = []
    discovery_time = {}
    lowest_time = {}
    time = 0

    def dfs(u, parent):
        nonlocal time
        discovery_time[u] = lowest_time[u] = time
        time += 1

        for neighbor in graph[u]:
            if neighbor not in discovery_time:
                dfs(neighbor, u)
                lowest_time[u] = min(lowest_time[u], lowest_time[neighbor])
                if lowest_time[neighbor] > discovery_time[u]:
                    bridges.append((u, neighbor))
            elif neighbor != parent:
                lowest_time[u] = min(lowest_time[u], discovery_time[neighbor])

    for vertex in graph:
        if vertex not in discovery_time:
            dfs(vertex, None)

    return bridges

