    n = len(nums)
    if n == 0:
        return []

    dp = [1] * n
    prev = [-1] * n

    max_length = 1
    max_length_end = 0

    for i in range(1, n):
        for j in range(0, i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                prev[i] = j
        if dp[i] > max_length:
            max_length = dp[i]
            max_length_end = i

    result = []
    current = max_length_end
    while current != -1:
        result.append(nums[current])
        current = prev[current]

    return result[::-1]

