def longest_palindrome(s):
    if not s:
        return ""

    max_length = 0
    result = ""

    def expand_around_center(left, right):
        nonlocal max_length, result
        while left >= 0 and right < len(s) and s[left] == s[right]:
            current_length = right - left + 1
            if current_length > max_length:
                max_length = current_length
                result = s[left:right + 1]
            left -= 1
            right += 1

    for i in range(len(s)):
        expand_around_center(i, i)
        expand_around_center(i, i + 1)

    return result

def find_longest_increasing_subsequence(lst):
    if not lst:
        return []

    n = len(lst)
    dp = [1] * n
    prev = [-1] * n

    for i in range(1, n):
        for j in range(0, i):
            if lst[i] > lst[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev[i] = j

    max_length = max(dp)
    index = dp.index(max_length)

    subsequence = []
    current = index
    while current != -1:
        subsequence.append(lst[current])
        current = prev[current]

    return subsequence[::-1]

def longest_common_substring(str1, str2):
    def dfs(i, j):
        if i >= len(str1) or j >= len(str2):
            return ""

        if str1[i] == str2[j]:
            result = str1[i] + dfs(i + 1, j + 1)
            return result
        else:
            option1 = dfs(i + 1, j)
            option2 = dfs(i, j + 1)
            return max(option1, option2, key=len)

    return dfs(0, 0)

