def find_count(nums, x):
    def binary_search_left(target):
        low, high = 0, len(nums) - 1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return low

    def binary_search_right(target):
        low, high = 0, len(nums) - 1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] <= target:
                low = mid + 1
            else:
                high = mid - 1
        return high

    left = binary_search_left(x)
    right = binary_search_right(x)

    if left <= right and right < len(nums) and nums[right] == x:
        return right - left + 1
    else:
        return 0

def combinationSum4(nums, target):
