    def backtrack(t):
        if t < 0:
            return 0
        if t == 0:
            return 1

        if t in memo:
            return memo[t]

        ways = 0
        for num in nums:
            ways += backtrack(t - num)

        memo[t] = ways
        return ways

    return backtrack(target)

