def minJumps(nums):
    if len(nums) <= 1:
        return 0

    jumps = 0
    current_end = 0
    farthest = 0
    can_jump = True

    i = 0

    while i <= current_end:
        if i == len(nums) - 1:
            return jumps

        farthest = max(farthest, i + nums[i])

        i += 1

        if i > current_end:
            jumps += 1
            current_end = farthest

            if current_end >= len(nums) - 1:
                return jumps

    return jumps

