def determinant(matrix):
    n = len(matrix)

    if n == 0:
        return 0

    if n == 1:
        return matrix[0][0]

    if n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]

    det = 0
    for j in range(n):
        cofactor = (-1) ** j * matrix[0][j]
        submatrix = [[matrix[i][k] for k in range(n) if k != j] for i in range(1, n)]
        det += cofactor * determinant(submatrix)

    return det

