def recursive_sqrt(number, current_value=1):
    if number < 0:
        return None  # Square root of a negative number is not defined in the real number system.

    new_value = 0.5 * (current_value + number / current_value)

    # If the difference between current_value and new_value is small enough, return new_value
    if abs(new_value - current_value) < 1e-7:
        return new_value
    else:
        return recursive_sqrt(number, new_value)

