def longest_palindromic_substring(s):
    if not s:
        return ""

    longest_palindrome = ""

    def expand_around_center(left, right):
        nonlocal longest_palindrome
        while left >= 0 and right < len(s) and s[left] == s[right]:
            current_palindrome = s[left:right + 1]
            if len(current_palindrome) > len(longest_palindrome):
                longest_palindrome = current_palindrome
            left -= 1
            right += 1

    for i in range(len(s)):
        # Consider each character as the center
        expand_around_center(i, i)
        # Consider each pair of consecutive characters as the center
        expand_around_center(i, i + 1)

    return longest_palindrome

