    # Iterate through each string in the list
    for string in lst:
        # If the string is already in the dictionary, increment its count
        if string in counts:
            counts[string] += 1
        # If the string is not in the dictionary, add it with a count of 1
        else:
            counts[string] = 1

    # Return the dictionary with the counts
    return counts

def insertion_sort(list_):
    if not list_:
        return []

    for i in range(1, len(list_)):
        key = list_[i]
        j = i - 1

        while j >= 0 and list_[j] > key:
            list_[j + 1] = list_[j]
            j -= 1

        list_[j + 1] = key

    return list_

