def find_pair_sum(arr, sum_value):
    frequency = {}
    count = 0

    for num in arr:
        complement = sum_value - num
        if complement in frequency:
            count += frequency[complement]

        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    return count

