def max_sum_memo(arr):
    if not arr:
        return 0

    n = len(arr)

    # Initialize memoization table
    memo = [0] * n

    # Base case
    memo[0] = arr[0]

    # Fill the memoization table
    for i in range(1, n):
        memo[i] = max(arr[i], memo[i-1] + arr[i])

    # The result is the maximum value in the memoization table
    return max(memo)

