def count_distinct_prime_factors(num):
    if num < 2:
        return 0

    prime_factors = set()

    factor = 2
    while factor * factor <= num:
        while num % factor == 0:
            prime_factors.add(factor)
            num //= factor
        factor += 1

    if num > 1:
        prime_factors.add(num)

    return len(prime_factors)

def is_forest(graph):
    visited = set()

    def dfs(u, parent):
        if u in current_path:
            return False
        if u in visited:
            return True

        current_path.add(u)
        visited.add(u)

        for neighbor in graph.get(u, []):
            if neighbor != parent:
                if not dfs(neighbor, u):
                    return False

        current_path.remove(u)
        return True

    current_path = set()
    for u in graph:
        if u not in visited and not dfs(u, None):
            return False

    return True

