def generate_all_strings(letters, number_of_letters):
    if number_of_letters == 0:
        return [""]

    result = []
    n = len(letters)

    def backtrack(index, current_string):
        if index == number_of_letters:
            result.append(current_string)
            return

        for i in range(n):
            backtrack(index + 1, current_string + letters[i])

    backtrack(0, "")
    return result

