def sum_of_primes_in_range(start, end):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    prime_sum = 0
    for number in range(start, end + 1):
        if is_prime(number):
            prime_sum += number

    return prime_sum

