def knapsack(weights, values, capacity):
    n = len(weights)
    # Create a 2D list to store the maximum value for each subproblem
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    # Iterate through each item
    for i in range(1, n + 1):
        # Iterate through each possible capacity
        for j in range(1, capacity + 1):
            # If the item's weight is greater than the current capacity, it cannot be included
            if weights[i-1] > j:
                dp[i][j] = dp[i-1][j]
            else:
                # Choose the maximum value between including the item or not including it
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-weights[i-1]] + values[i-1])

    # The result is the maximum value for the full capacity
    return dp[n][capacity]

