def longest_common_prefix(strs):
    if not strs:
        return ""

    # Start with the first string as the initial prefix
    prefix = strs[0]

    for string in strs[1:]:
        # Find the common prefix between the current prefix and the next string
        new_prefix = ""
        for i in range(min(len(prefix), len(string))):
            if prefix[i] == string[i]:
                new_prefix += prefix[i]
            else:
                break
        prefix = new_prefix

        # If at any point the prefix becomes empty, return it
        if not prefix:
            return ""

    return prefix

