def harmonic_mean(numbers_dict):
    if not numbers_dict:
        return 0  # If the dictionary is empty, return 0

    values = list(numbers_dict.values())
    n = len(values)

    if n == 0:
        return 0

    sum_of_reciprocals = 0
    for value in values:
        if value == 0:
            return 0  # Harmonic mean is undefined if any value is zero
        sum_of_reciprocals += 1 / value

    arithmetic_mean_of_reciprocals = sum_of_reciprocals / n
    harmonic_mean = 1 / arithmetic_mean_of_reciprocals

    return harmonic_mean

def find_least_common(dictionary):
    if not dictionary:
        return []

    # Create a dictionary to count the occurrences of each value
    value_counts = {}
    for value in dictionary.values():
        if value in value_counts:
            value_counts[value] += 1
        else:
            value_counts[value] = 1

    # Find the minimum frequency
    min_frequency = min(value_counts.values())

    # Collect values with the minimum frequency
    least_common_values = [value for value, count in value_counts.items() if count == min_frequency]

    return least_common_values

def convert_sec_to_hms(time_in_seconds):
    hours = time_in_seconds // 3600
    remaining_seconds = time_in_seconds % 3600
    minutes = remaining_seconds // 60
    seconds = remaining_seconds % 60
    return (int(hours), int(minutes), int(seconds))

