def knapsack_memoized(weights, values, capacity):
    memo = {}

    def dfs(i, w):
        if w <= 0 or i < 0:
            return 0
        if i == 0:
            if weights[0] <= w:
                return values[0]
            else:
                return 0

        state = (i, w)
        if state in memo:
            return memo[state]

        if weights[i] > w:
            result = dfs(i - 1, w)
        else:
            result = max(dfs(i - 1, w), dfs(i - 1, w - weights[i]) + values[i])

        memo[state] = result
        return result

    return dfs(len(weights) - 1, capacity)

