    adjacency_list = [[] for _ in range(num_vertices)]
    for u, v in edge_list:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    max_clique_size = 0

    # Iterate through all possible subsets of vertices
    for i in range(2 ** num_vertices):
        subset = [j for j in range(num_vertices) if (i & (1 << j)) != 0]
        if subset:
            is_clique = True
            for u in subset:
                for v in subset:
                    if u != v and v not in adjacency_list[u]:
                        is_clique = False
