def recursive_sort(arr, start=0):
    if len(arr) <= 1:
        return arr

    def find_max_index(arr, start):
        if start == len(arr):
            return -1
        max_index = start
        for i in range(start + 1, len(arr)):
            if arr[i] > arr[max_index]:
                max_index = i
        return max_index

    max_index = find_max_index(arr, start)
    if max_index != -1:
        arr[start], arr[max_index] = arr[max_index], arr[start]
        recursive_sort(arr, start + 1)

    return arr

