def longest_increasing_path(grid):
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    memo = {}

    def dfs(x, y):
        if (x, y) in memo:
            return memo[(x, y)]

        max_length = 1
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] > grid[x][y]:
                max_length = max(max_length, 1 + dfs(nx, ny))

        memo[(x, y)] = max_length
        return max_length

    result = 0
    for i in range(m):
        for j in range(n):
            result = max(result, dfs(i, j))

    return result

