def has_hamiltonian_cycle(graph):
    def dfs(v, path):
        if len(path) == len(graph):
            if v in graph and path[0] in graph[v]:
                return True
            return False

        for neighbor in graph.get(v, []):
            if neighbor not in path:
                path.append(neighbor)
                if dfs(neighbor, path):
                    return True
                path.pop()

        return False

    if not graph:
        return False

    vertices = list(graph.keys())
    if vertices:
        path = [vertices[0]]
        return dfs(vertices[0], path)

    return False

