def calculate_average_days(years):
    def is_leap_year(year):
        if year % 4 == 0:
            if year % 100 == 0:
                if year % 400 == 0:
                    return True
                else:
                    return False
            else:
                return True
        else:
            return False

    total_days = 0

    for year in years:
        if is_leap_year(year):
            total_days += 366
        else:
            total_days += 365

    if years:
        average_days = total_days / len(years)
        return average_days
    else:
        return 0

