def is_valid_parentheses(s: str) -> bool:
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if stack and stack[-1] == matching_bracket[char]:
                stack.pop()
            else:
                return False

    return not stack

