        elif number < min_value:
            min_value = number

    return max_value - min_value

def permutate(arr):
    if len(arr) == 1:
        return [arr]

    result = []

    for i in range(len(arr)):
        current = arr[i]
        remaining = arr[:i] + arr[i+1:]
        for p in permutate(remaining):
            result.append([current] + p)

    return result

