def is_valid_triangle(sides):
    if len(sides) != 3:
        return False

    a, b, c = sides

    # Check if all sides are positive
    if a <= 0 or b <= 0 or c <= 0:
        return False

    # Apply the triangle inequality theorem
    if a + b > c and a + c > b and b + c > a:
        return True
    else:
        return False

