def count_number_of_islands(matrix):
    if not matrix:
        return 0

    rows, cols = len(matrix), len(matrix[0])
    number_of_islands = 0

    def dfs(i, j):
        if i < 0 or j < 0 or i >= rows or j >= cols or matrix[i][j] != 1:
            return
        matrix[i][j] = 0
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 1:
                number_of_islands += 1
                dfs(i, j)

    return number_of_islands

