def find_minimum_value(dictionary):
    if not dictionary:
        return None  # If the dictionary is empty, return None

    # Initialize the minimum value with the first value of the dictionary
    minimum_value = next(iter(dictionary.values()))

    # Iterate through the dictionary values and update the minimum value if necessary
    for value in dictionary.values():
        if value < minimum_value:
            minimum_value = value

    return minimum_value

