def insertion_sort(unsorted_list):
    if not unsorted_list:
        return []

    for i in range(1, len(unsorted_list)):
        key = unsorted_list[i]
        j = i - 1

        while j >= 0 and unsorted_list[j] > key:
            unsorted_list[j + 1] = unsorted_list[j]
            j -= 1

        unsorted_list[j + 1] = key

    return unsorted_list

def edit_distance(str1, str2):
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + 1)

    return dp[m][n]

def longest_common_subsequence(X, Y):
    m, n = len(X), len(Y)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if X[i - 1] == Y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if X[i - 1] == Y[j - 1]:
            lcs.append(X[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lcs))

def find_common_prefix(str1, str2):
    if not str1 or not str2:
        return ""

    common_prefix = ""
    min_length = min(len(str1), len(str2))

    for i in range(min_length):
        if str1[i] == str2[i]:
            common_prefix += str1[i]
        else:
            break

    return common_prefix

def longest_palindrome(s):
    if not s:
        return ""

    longest_palindrome = ""

    def expand_around_center(left, right):
        nonlocal longest_palindrome
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        current_palindrome = s[left + 1:right]
        if len(current_palindrome) > len(longest_palindrome):
            longest_palindrome = current_palindrome

    for i in range(len(s)):
        expand_around_center(i, i)  # Odd length palindromes
        expand_around_center(i, i + 1)  # Even length palindromes

    return longest_palindrome

def findCommonElement(arr):
    if not arr:  # Check if the array is empty
        return None

    # Dictionary to count occurrences of each element
    count_dict = {}

    # Count the occurrences of each element in the array
    for element in arr:
        if element in count_dict:
            count_dict[element] += 1
        else:
            count_dict[element] = 1

    # Find the element with the highest count
    most_common_element = None
    highest_count = 0

    for element, count in count_dict.items():
        if count > highest_count:
            most_common_element = element
            highest_count = count

    return most_common_element

