def count_duplicates(nums):
    if not nums:
        return 0

    # Dictionary to count occurrences of each integer
    count_dict = {}

    # Populate the dictionary with counts
    for num in nums:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Count how many integers have at least one duplicate
    duplicates = sum(1 for count in count_dict.values() if count > 1)

    return duplicates

def longest_substring_without_repeating(s):
    if not s:
        return ""

    max_length = 0
    result = ""
    char_set = set()
    start = 0
    end = 0

    while end < len(s):
        if s[end] in char_set:
            char_set.remove(s[start])
            start += 1
        else:
            char_set.add(s[end])
            end += 1
            current_length = end - start
            if current_length > max_length:
                max_length = current_length
                result = s[start:end]

    return result

def levenshtein_distance(str1, str2):
    m, n = len(str1), len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # Min. operations = j
            elif j == 0:
                dp[i][j] = i  # Min. operations = i
            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + 1,  # Deletion
                               dp[i][j - 1] + 1,  # Insertion
                               dp[i - 1][j - 1] + 1)  # Substitution

    return dp[m][n]

def parentheses_validator(string):
    stack = []
    matching_bracket = {')': '(', ']': '[', '}': '{'}

    for char in string:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if stack and stack[-1] == matching_bracket[char]:
                stack.pop()
            else:
                return False

    return not stack

def prime_factors(num):
    if num < 2:
        return []

    factors = []
    factor = 2

    while factor * factor <= num:
        while num % factor == 0:
            factors.append(factor)
            num //= factor
        factor += 1

    if num > 1:
        factors.append(num)

    return factors

