def longest_unique_substring_length(s):
    if not s:
        return 0

    left = 0
    right = 0
    unique_chars = set()
    max_length = 0

    while right < len(s):
        if s[right] in unique_chars:
            while s[right] in unique_chars:
                unique_chars.remove(s[left])
                left += 1
        unique_chars.add(s[right])
        right += 1
        current_length = right - left
        if current_length > max_length:
            max_length = current_length

    return max_length

