def has_cycle(graph):
    visited = set()
    recursion_stack = set()

    def dfs(node):
        if node in recursion_stack:
            return True
        if node in visited:
            return False

        recursion_stack.add(node)
        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        recursion_stack.remove(node)
        visited.add(node)
        return False

    for node in graph:
        if dfs(node):
            return True

    return False

def maximum_units_on_truck(box_types, truck_size):
    # Sort box_types based on the number of units per box in descending order
    box_types.sort(key=lambda x: -x[1])

    total_units = 0
    remaining_capacity = truck_size

    for number_of_boxes, units_per_box in box_types:
        if remaining_capacity <= 0:
            break
        if number_of_boxes <= remaining_capacity:
            total_units += number_of_boxes * units_per_box
            remaining_capacity -= number_of_boxes
        else:
            total_units += remaining_capacity * units_per_box
            remaining_capacity = 0

    return total_units

