        self.size = 1000  # choose an appropriate size based on your expected dictionary size
        self.data = [None] * self.size

    def _hash(self, key):
        hash_sum = 0
        for char in key:
            hash_sum += ord(char)
        return hash_sum % self.size

    def add(self, key, value):
        index = self._hash(key)
        if self.data[index] is None:
            self.data[index] = []
        self.data[index].append((key, value))

    def get(self, key):
        index = self._hash(key)
        if self.data[index] is not None:
            for pair in self.data[index]:
