class HashTable:
    def __init__(self, size):
        self.size = size
        self.data = [None] * size

    def hash_func(self, key):
        hashed_key = 0
        for char in key:
            hashed_key += ord(char)
        return hashed_key % self.size

    def insert(self, key, value):
        index = self.hash_func(key)
        if not self.data[index]:
            self.data[index] = []
        self.data[index].append((key, value))

    def get(self, key):
        index = self.hash_func(key)
        if self.data[index]:
            for pair in self.data[index]:
                if pair[0] == key:
                    return pair[1]
        return None

