class CaesarCipher:
    def __init__(self, message):
        self.message = message
        # The number of letters to shift the message
        self.shift = 3

    def encode(self):
        encoded_message = ""
        for char in self.message:
            coded_char = chr(ord(char) + self.shift)
            encoded_message += coded_char
        return encoded_message

    def decode(self):
        decoded_message = ""
        for char in self.message:
            decoded_char = chr(ord(char) - self.shift)
            decoded_message += decoded_char
        return decoded_message

