    if len(string) == 0:
        return ['']

    prev_list = permutations(string[1:len(string)])

    next_list = []
    for i in range(0, len(prev_list)):
        for j in range(0, len(string)):
            new_combination = prev_list[i][0:j] + string[0] + prev_list[i][j:len(string)-1]
            if new_combination not in next_list:
                next_list.append(new_combination)

    return next_list

