def isValidBST(root):
    # An empty tree is considered a valid BST
    if root is None:
        return True

    # Checking for the constraint: left child should be smaller than parent
    if root.left is not None and root.left.data >= root.data:
        return False

    # Checking for the constraint: right child should be greater than parent
    if root.right is not None and root.right.data <= root.data:
        return False

    # Recursively checking for the constraint in the left and right subtrees
    if not isValidBST(root.left) or not isValidBST(root.right):
        return False

    # If all of the above checks passed successfully, then the given binary tree is a valid BST
    return True

