def minimax(board, isMaximizing):
    # Check if it is a winning board
    if checkWin(board):
        return reward

    # Play the game
    if isMaximizing:
        bestScore = -float("inf")
        for i in range(3):
            for j in range(3):
                if board[i][j] == 0:
                    board[i][j] = 1
                    score = minimax(board, False)
                    board[i][j] = 0
                    bestScore = max(score, bestScore)
        return bestScore

    # Minimizing
    else:
        bestScore = float("inf")
        for i in range(3):
            for j in range(3):
                if board[i][j] == 0:
                    board[i][j] = -1
                    score = minimax(board, True)
                    board[i][j] = 0
                    bestScore = min(score, bestScore)
        return bestScore

