def trim_whitespace(str):
    startindex = None
    endindex = None
    for i in range(len(str)):
        if str[i] != ' ':
            startindex = i
            break

    for i in range(len(str)-1, -1, -1):
        if str[i] != ' ':
            endindex = i
            break

    return str[startindex:endindex+1]

