def objective_function(points, k):
    # Initialize an empty dictionary with k clusters
    clusters = {i: [] for i in range(k)}

    # Iterate over data points
    for i, point in enumerate(points):
        # Assign a cluster to each point based on the lowest within-cluster total
        min_cluster, min_total = None, None
        for cluster in clusters:
            total = 0
            for other_point in clusters[cluster]:
                total += calculate_distance(point, other_point)
            if min_cluster is None or min_total > total:
                min_cluster, min_total = cluster, total
        clusters[min_cluster].append(i)

    return clusters

def selection_sort(array):
  n = len(array)

  for i in range(n):
    # Find the smallest element in the array
    min = i
    for j in range(i+1, n):
      if array[j] < array[min]:
        min = j

    # Swap the smallest with the current element
    array[i], array[min] = array[min], array[i]

  return array

