def permutations(word): 
    # Base case, if the word is empty 
    if len(word) == 0: 
        return [''] 
    prev_list = permutations(word[1:]) 
    next_list = [] 
     # Insert the anagrams using the first character of the word into the list 
    for perm in prev_list: 
        for i in range(len(word)): 
            next_list.append(perm[:i] + word[0:1] + perm[i:]) 
    return next_list

