def iterative_quick_sort(arr):
    stack = [(0, len(arr)-1)]
    while stack:
        start,end = stack.pop()
        if start >= end:
            continue
        pivot = arr[end]
        index = start
        for i in range(start,end):
            if arr[i] < pivot:
                arr[i],arr[index] = arr[index],arr[i]
                index+=1
        arr[index],arr[end] = arr[end],arr[index]
        stack.append((start,index-1))
        stack.append((index+1,end))
    return arr

