def fibonacci(n):
    """Find the nth Fibonacci number"""
    try:
        if n < 0:
            raise ValueError("Input must be greater than 0")
        elif n == 0:
            return 0
        elif n == 1:
            return 1
        else:
            return fibonacci(n - 1) + fibonacci(n - 2)
    except ValueError as error:
        print("Error:", error)

