class HashTable:
    def __init__(self, size):
        self.size = size
        self.table = [None for _ in range(size)]

    def put(self, key, value):
        hashCode = self.generateHashCode(key)
        self.table[hashCode] = value

    def get(self, key):
        hashCode = self.generateHashCode(key)
        return self.table[hashCode]

    def generateHashCode(self, key):
        return hash(key) % self.size

