def find_second_lowest(array):
    lowest = array[0]
    second_lowest = float('inf')
    for num in array:
        if num < lowest:
            second_lowest = lowest
            lowest = num
        elif num < second_lowest and num != lowest:
            second_lowest = num
    return second_lowest

