def delete_node(head, delete_num):

    if head is None:
        return

    curr = head
    prev = None

    while curr and curr.data != delete_num:
        prev = curr
        curr = curr.next

    if prev == None:
        return head.next

    prev.next = curr.next
    return head

class Stack:
    def __init__(self):
        self.stack = []

    def push(self, data):
        self.stack.append(data)

    def pop(self):
        if len(self.stack) <= 0:
            return None
        else:
            return self.stack.pop()

    def peek(self):
        if len(self.stack) <= 0:
            return None
        else:
            return self.stack[-1]

    def is_empty(self):
        return len(self.stack) == 0

