def mode_median(nums):
    # Mode
    frequency_dict = {}
    mode = 0
    mode_freq = 0
    for num in nums:
        if num not in frequency_dict:
            frequency_dict[num] = 0
        frequency_dict[num] += 1
        if frequency_dict[num] > mode_freq:
            mode = num
            mode_freq = frequency_dict[num]

    # Median
    nums.sort()
    med_index = int(len(nums)/2)
    if len(nums)%2 == 1:
        median = nums[med_index]
    else:
        median = (nums[med_index] + nums[med_index-1])/2
    return mode, median

