    self.head = None

  def push(self, data):
    node = Node(data)
    node.next = self.head
    self.head = node

  def search(self, key):
    current = self.head
    while current and current.data != key:
      current = current.next
    return current

  def insert_after(self, prev_node, data):
    if prev_node is None:
      print("Previous node cannot be null")
      return
    node = Node(data)
    node.next = prev_node.next
    prev_node.next = node

  def delete(self, key):
    current = self.head
    prev = None

    while current and current.data != key:
      prev = current
      current = current.next

    if prev is None:
      self.head = current.next
    else:
      prev.next = current.next

