class BST:
    def __init__(self):
        self.root = None

    def insert(self, value):
        node = Node(value)
        if self.root is None:
            self.root = node
            return
        cur = self.root
        while True:
            if value < cur.value:
                if cur.left is None:
                    cur.left = node
                    break
                cur = cur.left
            elif value > cur.value:
                if cur.right is None:
