def construct_directory_tree(directory):
    root = TreeNode(directory)
    stack = [root]

    while stack:
        current_node = stack.pop()

        # Retrieve the subdirectories within the current directory
        subdirectories = get_subdirectories(current_node.name)

        for subdirectory in subdirectories:
            child_node = TreeNode(subdirectory)
            current_node.children.append(child_node)
            stack.append(child_node)

    return root

