def split_array(array):
    length = len(array)
    left = 0
    right = length - 1
    array_sum = 0
    left_sum = 0
    right_sum = 0

    for i in range(length):
        array_sum = array_sum + array[i] 

    while left < right: 
        if left_sum < right_sum: 
            left_sum+= array[left] 
            left+= 1
        else: 
            right_sum+= array[right] 
            right-= 1

    if left_sum == right_sum and left == right and array_sum-left_sum == left_sum:
        return array[:left], array[left:]
    else:
