    """Find the most common words in the given text.

    :param text: A sentence or multiple sentences as a single string
    :returns: A list of the most common words in the given text
    """

    # Split the text into a list of words
    words = text.split()

    # Count the occurrences of each word
    word_count = {}
    for word in words:
        word = word.lower()
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    # Get the most common words
    most_common_words = []
    max_count = 0
    for word, count in word_count.items():
        if count > max_count:
            most_common_words = [word]
            max_count = count
        elif count == max_count:
            most_common_words.append(word)

