def kruskal(graph):
    sorted_edges = sorted(graph["edges"], key=lambda x: x[2])
    disjoint_sets = [[node] for node in graph["nodes"]]

    result = []
    for consider_edge in sorted_edges:
        from_node, to_node, _ = consider_edge

        from_set = None
        to_set = None
        for find_set in disjoint_sets:
            if from_node in find_set:
                from_set = find_set
            if to_node in find_set:
                to_set = find_set

        if from_set == to_set:
            continue

        result.append(consider_edge)
        disjoint_sets.remove(from_set)
        disjoint_sets.remove(to_set)
        disjoint_sets.append(from_set + to_set)

    return result

