def permute_letters(letters):
    if len(letters) == 0:
        return []

    if len(letters) == 1:
        return [letters]

    permuted_letters = []

    for letter in letters:
        remaining_letters = [letter2 for letter2 in letters if letter2 != letter]
        permutations = permute_letters(remaining_letters)

        for permutation in permutations:
            permuted_letters.append([letter] + permutation)

    return permuted_letters

def find_shortest_unique_substrings(string):
    visited = set()
    res = []
    for start in range(len(string)):
        for end in range(start+1, len(string)+1):
            if string[start:end] not in visited:
                visited.add(string[start:end])
                res.append(string[start:end])
    res.sort(key=len)
    return res[0]

