    weighted_tasks = []
    for t in tasks:
        weight = 0
        if t.is_important:
            weight += 3
        if t.has_deadline:
            weight += 2
        if t.is_time_sensitive:
            weight += 5
        weighted_tasks.append({"task": t, "weight": weight})
    return weighted_tasks

