def plan_route(start, goal): 
    graph = {
        'A': ['B', 'C'],
        'B': ['D'],
        'C': ['D', 'E'],
        'D': ['F'],
        'E': ['G'],
        'F': ['G']
    }

    fringe = []
    fringe.append([start]) 

    while len(fringe) > 0: 
        path = fringe.pop(0) 
        node = path[-1] 
        if node == goal: 
            return path 
        else: 
            for neighbour in graph[node]: 
                newPath = list(path) 
                newPath.append(neighbour)
                fringe.append(newPath)

    return None 

print(plan_route('A', 'G'))  # ['A', 'C', 'E', 'G']

def longest_palindrome(str): 
    n = len(str) 

    # List for storing results 
    result = "" 

    # Find longest palindrome 
    for i in range(n): 
        for j in range(i + 1, n): 
            # Getting the current substring 
            substr = str[i : j + 1] 

            # Checking if it's a palindrome 
            if all(substr[k] == substr[j-k] for k in range(j - i + 1)): 
                if len(substr) > len(result): 
                    result = substr 

    return result

