def permutations(nums):
    if len(nums) == 0:
        return []
    if len(nums) == 1:
        return [nums]
    permutations = []
    for i in range(len(nums)):
        element = nums[i]
        remaining_elements = [x for x in nums if x != element]
        z = permutations(remaining_elements)
        for t in z:
            permutations.append([element] + t)
    return permutations

def detect_cycle(head):
    slow = head
    fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next

        # cycle found
        if slow == fast:
            return True

    return False

