    sorted_scores = sorted(scores, reverse=True)

    ranks = []
    prev_score = -1
    rank = 1

    for score in sorted_scores:
        if score != prev_score:
            ranks.append(rank)
        else:
            ranks.append(ranks[-1])
        rank += 1
        prev_score = score

    rank_student = {}
    for student, rank in zip(scores, ranks):
