def shortest_path(G, start, goal):
    visited = []
    queue = [[start]]

    if start == goal:
        return "Start node is the same as the goal"

    while queue:
        path = queue.pop(0)
        node = path[-1]

        if node not in visited:
            visited.append(node)
            adjacent_nodes = list(G.neighbors(node))

            for adj_node in adjacent_nodes:
                new_path = list(path)
                new_path.append(adj_node)
                queue.append(new_path)

                if adj_node == goal:
                    return new_path

def find_shortest_path(maze): 
    # return None if no path is found 
    if not maze: 
        return None 

    # find start and destination 
    start, destination = None, None 
    for r in range(len(maze)): 
        for c in range(len(maze[r])): 
            if maze[r][c] == 1: 
                start = (r,c) 
            elif maze[r][c] == 2: 
                destination = (r,c) 

    if start == None or destination == None: 
        return None 

    # perform BFS 
    visited, path_length_so_far, queue = set(), 0, [start] 
    while queue: 
        r,c = queue.pop(0) 
        if (r,c) in visited: 
            continue 
        visited.add((r,c)) 
        if r > 0 and maze[r-1][c] != 0: # left 
            if (r-1,c) == destination: 
                path_length_so_far += 1 
                break 
            else: 
                queue.append((r-1,c)) 
        if r < len(maze)-1 and maze[r+1][c] != 0: # right 
            if (r+1,c) == destination: 
                path_length_so_far += 1
                break 
            else: 
                queue.append((r+1,c)) 
        if c > 0 and maze[r][c-1] != 0: # up 
            if (r,c-1) == destination: 
                path_length_so_far += 1
                break 
            else: 
                queue.append((r,c-1)) 
        if c < len(maze[0])-1 and maze[r][c+1] != 0: # down 
            if (r,c+1) == destination: 
                path_length_so_far += 1 
                break 
            else: 
                queue.append((r,c+1)) 
        path_length_so_far += 1 

    return path_length_so_far

