def median(numbers):
    numbers.sort()
    middle_index = int(len(numbers)/2)
    if len(numbers) % 2 == 0:
        return (numbers[middle_index] + numbers[middle_index-1])/2
    else:
        return numbers[middle_index]

def mode(numbers):
    max_freq = 0
    modes = []
    for num in set(numbers):
        count = numbers.count(num)
        if count > max_freq:
            modes.clear()
            modes.append(num)
            max_freq = count
        elif count == max_freq and num not in modes:
            modes.append(num)
    return modes

