def insert_item(root, item):
    if root is None:
        root = item
    else:
        if item.data < root.data:
            if root.left is None:
                root.left = item
            else:
                insert_item(root.left, item)
        else:
            if root.right is None:
                root.right = item
            else:
                insert_item(root.right, item)

