        self.name = name
        self.parent = parent
        self.children = []

    def add_child(self, child):
        child.parent = self
        self.children.append(child)

    def get_siblings(self):
        siblings = []
        if self.parent is not None:
            for child in self.parent.children:
                if not self.name == child.name:
                    siblings.append(child.name)
        return siblings

