def start_game():
  print('Welcome to Tic Tac Toe')
  display_board()

  if full_board_check():
    return

  turn = 0

  while not full_board_check():
    player = determine_player(turn)
    handle_player_turn(player)
    if win_check(player):
      print('Congratulations ' + player + ': You have won!')
      break
    turn+=1
  if not win_check(player):
    print('It\'s a tie')

