def contains_cycle(head):
    if (head == None):
        return False

    slow_pointer = head
    fast_pointer = head.next

    while (fast_pointer != None and fast_pointer.next != None):
        if (slow_pointer == fast_pointer):
            return True

        slow_pointer = slow_pointer.next
        fast_pointer = fast_pointer.next.next

    return False

