def longestIncreasingSubsequence(sequence):
    n = len(sequence)
    lis = [1]*n
    for i in range(1, n):
        for j in range(0, i):
            if sequence[i] > sequence[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
    maximum = 0
    for i in range(n):
        maximum = max(maximum, lis[i])
    return maximum

import random

def optimize_prob_space(space):
    best_solution = [float("inf")] * len(space)
    while True:
        new_solution = get_random_solution(space)
        if is_more_desirable(new_solution, best_solution):
            best_solution = new_solution
        if is_optimal(new_solution, space):
            break
    return best_solution

def get_random_solution(space):
    # This function generates a random solution within the given space
    solution = [random.uniform(space[i][0], space[i][1]) for i in range(len(space))] 
    return solution

def is_more_desirable(new_solution, best_solution):
    # This function checks if the new solution is more desirable than the current best solution
    for i in range(len(new_solution)): 
        if new_solution[i] > best_solution[i]: 
            return False
    return True

def is_optimal(new_solution, space):
    # This function checks if the new solution is an optimal solution within the given space
    for i in range(len(new_solution)): 
        if new_solution[i] > space[i][1]:
            return False
    return True

