def linear_sort(arr):
    max_val = max(arr)
    counting_array = [0] * (max_val + 1)

    for value in arr:
        counting_array[value] += 1

    i = 0
    for j in range(max_val + 1):
        for _ in range(counting_array[j]):
            arr[i] = j
            i += 1

    return arr

def calculate_stats(data):
    mean = sum(data) / len(data)
    sorted_data = sorted(data) 
    midpoint = len(sorted_data) // 2 
    if len(sorted_data) % 2 == 0:
        median = (sorted_data[midpoint - 1] + sorted_data[midpoint]) / 2
    else:
        median = sorted_data[midpoint]

    count_dict = {}
    for element in data: 
        if element in count_dict:
            count_dict[element] += 1
        else:
            count_dict[element] = 1

    mode = []
    max_count = 0
    for key, value in count_dict.items():
        if value > max_count:
            max_count = value
            mode = [key]
        elif value == max_count:
            mode.append(key)

    return mean, median, mode

def create_binary_tree(words):
    # Create a root node
    rootNode = Node(None, None, None)

    # Loop through all words
    for word in words:
        currNode = rootNode
        for ch in word:
            # Check if character already exists in the tree
            index = searchNode(currNode.children, ch)

            # If yes, continue from that node
            if index != -1:
                currNode = currNode.children[index]
            # If no, create a new node and continue
            else:
                newNode = Node(ch, None, None)
                currNode.children.append(newNode)
                currNode = newNode

    return rootNode

