def optimize_resource_allocation(resources, constraints):
    best_allocation = []
    best_score = float('-inf')
    for resource in resources:
        current_allocation = []
        for constraint in constraints:
            valid = True
            for key in constraint:
                if resource.get(key) != constraint[key]:
                    valid = False
                    break
            if valid:
                current_allocation.append(resource)

        current_score = calculate_score(current_allocation)

        if current_score > best_score:
            best_allocation = current_allocation
            best_score = current_score

