    prev = None

    while curr is not None:
        # If the data to be deleted is found in the node
        if curr.data == data:  
            # If it's the first node, set the 
            # head to be its next node
            if prev == None:
                head = curr.next
            else:
                prev.next = curr.next   # otherwise set the previous node 
                                        # to point to the current node's next
            # Delete the current node
