def fibonacci(num): 
    a = 0
    b = 1
    result = 0

    if num == 0: 
        return a 
    elif num == 1: 
        return b 
    else: 
        for i in range(2, num + 1): 
            result = a + b 
            a = b 
            b = result 
    return result 

def fibonacci_memoize(num, memo): 
    if memo[num] is not None: 
        return memo[num] 
    if num <= 1: 
        result = num 
    else: 
        result = fibonacci_memoize(num - 1, memo) + fibonacci_memoize(num - 2, memo) 
    memo[num] = result 
    return result 

