class Matrix:
    def __init__(self, data):
        self.data = data

    def __repr__(self):
        return str(self.data)

    def shape(self):
        """
        Returns the shape of the matrix
        """
        return (len(self.data), len(self.data[0]))

    def add_scalar(self, scalar):
        """
        Performs scalar addition on the matrix
        """
        return [[v + scalar for v in row] for row in self.data]

    def add_matrix(self, other):
        """
        Performs matrix addition with another matrix
        """
        return [[v1 + v2 for (v1, v2) in zip(row1, row2)] for (row1, row2) in zip(self.data, other.data)]

    def subtract_scalar(self, scalar):
        """
        Performs scalar subtraction on the matrix
        """
        return [[v - scalar for v in row] for row in self.data]

    def subtract_matrix(self, other):
        """
        Performs matrix subtraction with another matrix
        """
        return [[v1 - v2 for (v1, v2) in zip(row1, row2)] for (row1, row2) in zip(self.data, other.data)]

    def multiply_scalar(self, scalar):
        """
        Performs scalar multiplication on the matrix
        """
        return [[v*scalar for v in row] for row in self.data]

    def transpose(self):
        """
        Transposes the matrix
        """
        return [list(v) for v in list(zip(*self.data))]

