def isPalindrome(head):
    slow = head
    fast = head
    stack = []

    while fast and fast.next:
        stack.append(slow.val)
        slow = slow.next
        fast = fast.next.next

    if fast:
        slow = slow.next

    while slow:
        if stack.pop() != slow.val:
            return False
        slow = slow.next

    return True

