def sortDescending(arr):
    # Iterate through the array
    for i in range(len(arr) - 1):
        # Set largestNumIndex to the current index
        largestNumIndex = i
        # Iterate through remaining list to find the largest number
        for j in range(i + 1, len(arr)):
            if arr[j] > arr[largestNumIndex]:
                largestNumIndex = j
        # Swap the largest number with the current number
        temp = arr[i]
        arr[i] = arr[largestNumIndex]
        arr[largestNumIndex] = temp

