def has_multiple_cycles(graph):
    visited = set()
    for node in graph:
        if node not in visited:
            if has_cycle(graph, node, visited, set()):
                return True
    return False

def has_cycle(graph, node, visited, path):
    visited.add(node)
    path.add(node)
    for neighbor in graph[node]:
        if neighbor not in visited:
            if has_cycle(graph, neighbor, visited, path):
                return True
        elif neighbor in path:
            return True
    path.remove(node)
    return False

