def eval_expr(expr): 
    stack = [] 
    for char in expr: 
        if char in ['(', '{', '[']: 
            stack.append(char)
        elif char in [')', '}', ']']: 
            if not stack: 
                return False 

            current_char = stack.pop() 
            if current_char == '(': 
                if char != ')': 
                    return False 
            elif current_char == '{': 
                if char != '}': 
                    return False 
            elif current_char == '[': 
                if char != ']': 
                    return False 

    if stack: 
        return False
    else: 
        return True

