def reverse_vowels(word):
    vowels = "aeiou"
    word = list(word)
    start = 0
    end = len(word) - 1
    while start < end:
        if word[start] in vowels and word[end] in vowels:
            temp = word[start]
            word[start] = word[end]
            word[end] = temp
            start += 1
            end -= 1
        elif word[start] in vowels:
            end -= 1
        elif word[end] in vowels:
            start += 1
        else:
            start += 1
            end -= 1
    return "".join(word)

