def array_sort(array):
  # Iterate over the array
  for i in range(len(array)):
    # Find the minimum element
    min_position = i
    for j in range(i + 1, len(array)):
      if array[min_position] > array[j]:
        min_position = j

    # Swap minimum element to current position
    array[i], array[min_position] = array[min_position], array[i]

  return array

def lowest_sum(numbers):
    lowest_sum = numbers[0] + numbers[1]  # Initializing the lowest sum with the sum of first two numbers
    for i in range(len(numbers) - 1):
        for j in range(i + 1, len(numbers)):
            current_sum = numbers[i] + numbers[j]  # Calculating the sum of two numbers
            if current_sum < lowest_sum:  # If current sum is lower than lowest sum found so far
                lowest_sum = current_sum  # Update the lowest sum
    return lowest_sum

