def evaluate(exp):
    stack = []

    for char in exp:
        if char in ['+','-','*','/']:
            # perform the operation in the stack using the operator
            b = stack.pop()
            a = stack.pop()
            if char == '+':
                stack.append(a+b)
            elif char == '-':
                stack.append(a-b)
            elif char == '*':
                stack.append(a*b)
            elif char == '/':
                stack.append(a/b)
        else:
            # 'char' is a number, so convert to int and push to stack
            stack.append(int(char))
    return stack.pop()

