def longestCommonSubstring(str_1, str_2): 
    # Initialize the result 
    result = 0

    # Find the longest common suffix 
    for i in range(len(str_1)): 
        for j in range(len(str_2)):
            l = 0
            while (i+l < len(str_1) and j+l < len(str_2) and str_1[i+l] == str_2[j+l]):
                l += 1
            if result < l:
