def is_binary_search_tree(root): 
    # Base Case 
    if root is None: 
        return True

    # Determine if the left subtree is a binary search tree 
    if root.left is not None:
        if root.data < root.left.data or not is_binary_search_tree(root.left): 
            return False

    # Determine if the right subtree is a binary search tree 
    if root.right is not None:
        if root.data > root.right.data or not is_binary_search_tree(root.right): 
            return False

    # If all the above cases return false, then the root is a binary search tree 
