import random

def generate(length, num_special_chars, num_digits):
    chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!@#$%^&*'
    digits = '0123456789'
    password = ''

    # Generate random characters
    for i in range(length - num_special_chars - num_digits):
        password += random.choice(chars)

    # Add random special characters
    for i in range(num_special_chars):
        password += random.choice(chars[-num_special_chars:])

    # Add random digits
    for i in range(num_digits):
        password += random.choice(digits)

    # Shuffle the password
    return ''.join(random.sample(password, len(password)))

