def check_parentheses(lst):
    parentheses = {'(': ')', '{': '}', '[': ']'}
    stack = []

    for char in lst:
        if char in parentheses.keys():
            stack.append(char)
        elif char in parentheses.values():
            if len(stack) == 0 or parentheses[stack.pop()] != char:
                return False
    return len(stack) == 0

