class Node:
    def __init__(self, data):
        self.left = None
        self.right = None
        self.data = data

    def insert(self, data):
        # Compare the new value with the parent node
        if self.data:
            if data < self.data:
                if self.left is None:
                    self.left = Node(data)
                else:
                    self.left.insert(data)
            elif data > self.data:
                if self.right is None:
                    self.right = Node(data)
                else:
                    self.right.insert(data)
            else:
                self.data = data

    def find(self, data):
        # Compare the new value with the parent node
        if data < self.data:
            if self.left is None:
                return 'Not Found'
            else:
                return self.left.find(data)
        elif data > self.data:
            if self.right is None:
                return 'Not Found'
            else:
                return self.right.find(data)
        else:
            return 'Found'

