def shortest_path(graph, start, end):
    visited = set()
    queue = [[start]]
    while queue:
        path = queue.pop(0)
        vertex = path[-1]
        if vertex == end:
            return path
        for neighbour in graph[vertex]:
            if neighbour not in visited:
                visited.add(neighbour)
                new_path = list(path)
                new_path.append(neighbour)
                queue.append(new_path)
    return None

