def categorize_sentence(sentence):
    # Tokenize the sentence into words
    words = word_tokenize(sentence)

    # Extract important features from the sentence
    features = {
        'contains_question_mark': '?' in sentence,
        'starts_with_capital_letter': words[0].isupper(),
        'ends_with_period': sentence.endswith('.'),
        'contains_exclamation_mark': '!' in sentence,
        'contains_quotation_marks': '"' in sentence
    }

    # Define a set of rules to classify the sentence
    if features['contains_question_mark']:
        return 'Interrogative sentence.'
    elif features['ends_with_period']:
        return 'Statement sentence.'
    elif features['contains_exclamation_mark']:
        return 'Exclamatory sentence.'
    elif features['starts_with_capital_letter']:
        return 'Imperative sentence.'
    elif features['contains_quotation_marks']:
        return 'Quoted sentence.'
    else:
        return 'Unclassified sentence.'

