import urllib
import re
from collections import deque

def crawl(url):
    q = deque([url])
    visited = set()
    while q:
        url = q.popleft()
        visited.add(url)
        try:
            response = urllib.urlopen(url)
        except:
            continue 

        page_content = response.read()
        for x in re.findall('<a href="?\'?(https?:\/\/[^"\'>]*)', page_content):
            if x not in visited:
                q.append(x)
                visited.add(x)
        print(url)    

