def TSP_solution(graph):
    n = len(graph)
    V = [1]
    cost = 0

    while len(V) < n:
        min = float('inf')
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                if (i not in V) and (j in V):
                    if graph[i][j] < min:
                        min = graph[i][j]
                        a = i
                        b = j
        V.append(a)
        cost = cost + graph[a][b]
    cost = cost + graph[b][0]
    return [V, cost]

