def find_anagrams(lst): 
    word_indices = {} 
    for i, word in enumerate(lst): 
        sorted_word = ''.join(sorted(word)) 
        if sorted_word in word_indices: 
            word_indices[sorted_word].append(i) 
        else:
            word_indices[sorted_word] = [i] 

    anagram_indices = [indices for indices in word_indices.values() if len(indices) > 1] 

