def sortedList(head): 
    if(head == None or head.next == None): 
        return head 

    prev = None
    slow = head 
    fast = head 

    while(fast != None and fast.next != None): 
        fast = fast.next.next
        prev = slow
        slow = slow.next

    prev.next = None

    left = sortedList(head) 
    right = sortedList(slow)  
    sortedHead = merge(left, right) 

    return sortedHead 

def merge(left, right): 
    result = Node(None)
    temp   = result 

    while(left != None and right != None): 
        if left.data <= right.data: 
            temp.next = left
            left = left.next
        else: 
            temp.next = right
            right = right.next
        temp = temp.next

    if left != None: 
        temp.next = left  
    if right != None: 
        temp.next = right

    return result.next 

