def approximateMaxCut(G): 

    # Initializing the two subsets A and B 
    A = {'s'}
    B = []
    for vertex in G:
        if vertex != 's':
            B.append(vertex)

    while len(B) > 0: 
        # Selecting the edge with maximum weight 
        max_weight = 0
        v = None
        u = None

        for i in A: 
            for j in B: 
                if G[i][j] > max_weight: 
                    max_weight = G[i][j] 
                    u = i
                    v = j

        B.remove(v)
        A.add(v)

    # Calculating the cut weight
    cut_weight = 0
    for i in A: 
        for j in B: 
            cut_weight += G[i][j] 

    return cut_weight, A, B

