class BST:
    # define constructor
    def __init__(self):
        self.root = None

    # define the insert function
    def insert(self, node): 
        # create new node if root is empty
        if self.root is None: 
            self.root = node
        else:
            # start from the root and traverse down 
            curr = self.root 
            while curr is not None: 
                # if the element to be inserted is smaller than root, continue to left node
                if node.data < curr.data: 
                    if curr.left is None: 
                        curr.left = node 
                        break
                    else: 
                        curr = curr.left 
                # if the element to be inserted greater than root, continue to right node
                else:
                    if curr.right is None:
                        curr.right = node
                        break 
                    else: 
                        curr = curr.right

