def validParentheses(string):
    stack = []
    open_p = ["(", "[", "{"]
    close_p = [")", "]", "}"]
    for char in string:
        if char in open_p:
            stack.append(char)
        elif char in close_p:
            index = close_p.index(char)
            if len(stack) > 0 and open_p[index] == stack[-1]:
                stack.pop()
            else:
                return False
    return len(stack) == 0

