def bubble_sort(list):
    is_sorted = False
    while not is_sorted:
        is_sorted = True
        for i in range(len(list)-1):
            if (list[i] > list[i+1]):
                list[i], list[i+1] = list[i+1], list[i]
                is_sorted = False
    return list

def highest_common_factor(a, b):
    if a == 0 and b == 0:
        return 0
    if a > 0 and b > 0:
        while a != b:
            if a > b:
                a = a - b
            else:
                b = b - a
        return a

