def binary_search(lst, target):
    left = 0
    right  = len(lst) - 1

    while left <= right:
        mid = (right + left) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

