def find_armstrong_numbers():
    armstrong_nums = []
    for num in range (0, 1000):
        digits_sum = 0
        temp = num

        while temp > 0:
            digit = temp % 10
            digits_sum += digit ** 3
            temp //= 10

        if num == digits_sum:
            armstrong_nums.append(num)
    return armstrong_nums

