        return f"TreeNode(value={self.value}, timestamp={self.timestamp}, children={self.children})"

def construct_tree(triplets):
    root = TreeNode(None, 0)
    nodes = {root.value: root}

    for parent, child, timestamp in triplets:
        if child not in nodes:
            nodes[child] = TreeNode(child, timestamp)

        parent_node = nodes[parent]
        child_node = nodes[child]
        parent_node.children.append(child_node)

    return root

