def inverse_formula(formula: str) -> str:
    tokens = formula.split()
    inverse_tokens = []
    for token in tokens:
        if token == "+":
            inverse_tokens.append("-")
        elif token == "-":
            inverse_tokens.append("+")
        elif token == "*":
            inverse_tokens.append("/")
        elif token == "/":
            inverse_tokens.append("*")
        else:
            inverse_tokens.append(token)
    return " ".join(inverse_tokens)

import numpy as np

class Tensor:
    def __init__(self, data):
        self.data = np.array(data)

    def add(self, other):
        return Tensor(self.data + other.data)

    def multiply(self, other):
        return Tensor(self.data * other.data)

    def divide(self, other):
        return Tensor(self.data / other.data)

    def exponentiate(self, other):
        return Tensor(self.data ** other.data)

    def subtract(self, other):
        return Tensor(self.data - other.data)

def convert_number_to_human_readable(num: int) -> str:
    if num < 1000:
        return f'{num}'

    suffixes = ['', 'K', 'M', 'B', 'T']
    suffix_index = 0
    while num >= 1000:
        num /= 1000
        suffix_index += 1
    rounded_num = round(num, 1)
    return f'{rounded_num}{suffixes[suffix_index]}'

