def calculate_emission_rate(block_height, emission_mode):
    if emission_mode == 'fixed':
        return 100  # Fixed emission rate of 100 tokens per block

    elif emission_mode == 'variable':
        if block_height <= 100:
            return 100  # Emission rate is 100 tokens per block for the first 100 blocks

        elif block_height <= 10000:
            return 10  # Emission rate is 10 tokens per block for the next 9,000 blocks

        elif block_height <= 100000:
            return 1  # Emission rate is 1 token per block for the next 90,000 blocks

        else:
            return 0.1  # Emission rate is 0.1 tokens per block for the remaining blocks

    else:
        raise ValueError("Invalid emission mode.")

def singleton_decorator(name):
