import re

def modify_sentence(sentence, pattern):
    match = re.search(pattern, sentence)
    if not match:
        return sentence
    def uppercase_first_letter(match):
        return match.group(0).capitalize()
    modified_sentence = re.sub(pattern, uppercase_first_letter, sentence, count=1)
    return modified_sentence

