import base64

def validate_and_decode_base64(encoded_string: str) -> str:
    """
    Validates a base64-encoded string and decodes it.
    """
    if not encoded_string:
        raise ValueError("Invalid base64 string: the input string is empty.")

    try:
        decoded_bytes = base64.b64decode(encoded_string)
        decoded_string = decoded_bytes.decode()
    except TypeError as e:
        raise ValueError("Invalid base64 string: " + str(e))

    return decoded_string

def calculate_slope(a, b):
    x1, y1 = a
    x2, y2 = b
    dy = y2 - y1
    dx = x2 - x1
    if dx == 0:
        return (None, 1)
    elif dy == 0:
        return (1, None)
    m = dy / dx
    return (m, 1)

