def are_graphs_degree_equivalent(graph_one, graph_two):
    if len(graph_one) != len(graph_two):
        return False

    for node in graph_one:
        if node not in graph_two:
            return False
        degree_one = len(graph_one[node])
        degree_two = len(graph_two[node])
        if degree_one != degree_two:
