import re

def validate_hex_string(hex_string):
    if not hex_string:
        return False, None
    if not re.match(r'^[0-9a-fA-F]*$', hex_string):
        return False, None
    try:
        parsed_int = int(hex_string, base=16)
    except ValueError:
        return False, None
    if parsed_int > 2**256 - 1:
        return False, None
    return True, parsed_int

