def logbase2(x: int) -> int:
    if x <= 0:
        raise ValueError("Input must be a positive integer")

    if x > 1_000_000:
        raise ValueError("Input must be less than or equal to 1,000,000")

    msb_index = 0

    while x > 0:
        x >>= 1
        msb_index += 1

    return msb_index - 1

