def get_descendants(node):
    if not node:
        return []

    descendants = [node.value]
    for child in node.children:
        descendants.extend(get_descendants(child))

    return descendants

def detect_cycle(graph):
    for from_node, to_node in graph:
        if hasattr(to_node, 'visited') and to_node.visited:
            return True
        to_node.visited = True
        if detect_cycle([(to_node, neighbor) for neighbor in to_node.neighbors]):
            return True
    return False

