    for letter in word:
        if letter.isalpha():
            rotated_index = (alphabet.index(letter.lower()) + 13) % len(alphabet)
            rotated_letter = alphabet[rotated_index]
            if letter.isupper():
                rotated_letter = rotated_letter.upper()
            rotated_word += rotated_letter
        else:
            rotated_word += letter
    return rotated_word

