        raise ValueError("Invalid length: must be non-negative")
    if any(not isinstance(c, str) or len(c) != 1 for c in alphabet):
        raise ValueError("Invalid alphabet: must be a list of single-character strings")

    def backtrack(prefix, remaining_length):
        if remaining_length == 0:
