def execute_program_with_args(program, args=None, path=None):
    if path:
        program_path = os.path.join(path, program)
        if os.path.exists(program_path):
            program = program_path
    else:
        for directory in os.environ['PATH'].split(os.pathsep):
            program_path = os.path.join(directory, program)
            if os.path.exists(program_path):
                program = program_path
                break
        else:
            raise ProgramNotFoundError(f"Program '{program}' not found in PATH")
    try:
        with subprocess.Popen([program] + (args or []), stdout=subprocess.PIPE) as process:
            output, _ = process.communicate()
            return output.decode('utf-8')
    except subprocess.CalledProcessError as e:
        raise e

import math

def modular_inverse(a, n):
    t, newt = 0, 1
    r, newr = n, a
    while newr != 0:
        quotient = r // newr
        t, newt = newt, t - quotient * newt
        r, newr = newr, r - quotient * newr
    if r > 1:
        raise ValueError("a is not invertible modulo n")
    if t < 0:
        t += n
    return t

class RSA:
    def __init__(self, p, q):
        self.p = p
        self.q = q
        self.n = p * q
        self.phi = (p - 1) * (q - 1)
        self.e = self.calculate_e()
        self.d = self.calculate_d(self.e, self.phi)

    def encrypt(self, message):
        cipher = pow(message, self.e, self.n)
        return cipher

    def decrypt(self, cipher):
        message = pow(cipher, self.d, self.n)
        return message

    def get_public_key(self):
        return self.e

    def get_private_key(self):
        return self.d

    def calculate_e(self):
        e = 3
        while math.gcd(e, self.phi) != 1:
            e += 2
        return e

    def calculate_d(self, e, phi):
        return modular_inverse(e, phi)

