from typing import List

def deduplicate_lists(lists: List[List]) -> List[List]:
    """
    De-duplicates a list of lists, removing duplicates while maintaining their order.
    Time complexity: O(n), where n is the number of lists.
    """
    seen = {}
    unique_lists = []

    for lst in lists:
        if tuple(lst) not in seen:
            seen[tuple(lst)] = True
            unique_lists.append(lst)

    return unique_lists

