def split_data_into_chunks(data, chunk_size):
    if chunk_size <= 0:
        raise ValueError("Chunk size must be greater than zero.")
    num_full_chunks = len(data) // chunk_size
    num_remaining_elements = len(data) % chunk_size
    chunks = []
    for i in range(num_full_chunks):
        chunk = data[i*chunk_size:(i+1)*chunk_size]
        chunks.append(chunk)
    if num_remaining_elements > 0:
        chunk = data[num_full_chunks*chunk_size:] + [None] * (chunk_size - num_remaining_elements)
        chunks.append(chunk)

    return chunks

