def count_neighbours(grid, cell_position):
    if not is_grid_2d(grid):
        raise ValueError("Grid must be 2-dimensional")

    count = 0
    row, col = cell_position
    num_rows = len(grid)
    num_cols = len(grid[0])
    if row - 1 >= 0 and col - 1 >= 0 and grid[row - 1][col - 1] == 1:
        count += 1
    if row - 1 >= 0 and grid[row - 1][col] == 1:
        count += 1
    if row - 1 >= 0 and col + 1 < num_cols and grid[row - 1][col + 1] == 1:
        count += 1
    if col - 1 >= 0 and grid[row][col - 1] == 1:
        count += 1
    if col + 1 < num_cols and grid[row][col + 1] == 1:
        count += 1
    if row + 1 < num_rows and col - 1 >= 0 and grid[row + 1][col - 1] == 1:
        count += 1
    if row + 1 < num_rows and grid[row + 1][col] == 1:
        count += 1
    if row + 1 < num_rows and col + 1 < num_cols and grid[row + 1][col + 1] == 1:
        count += 1

    return count

def is_grid_2d(grid):
    if len(grid) == 0:
        return False

    num_cols = len(grid[0])

    for row in grid:
        if len(row) != num_cols:
            return False

    return True

