class ComplexSystem:
    def __init__(self, nodes, edges):
        self.nodes = nodes
        self.edges = edges

    def check_nodes_and_edges(self):
        for node in self.nodes:
            if node.position < 0:
                raise Exception("Node position must not be negative")
        for edge in self.edges:
            if edge.start_node not in self.nodes or edge.end_node not in self.nodes:
                raise Exception("Start or end node for edge not found in system")
            if edge.start_node == edge.end_node:
                raise Exception("Self-loops are not allowed")

