def seconds_to_formatted_string(seconds):
    hours = seconds // 3600
    minutes = (seconds % 3600) // 60
    seconds = (seconds % 3600) % 60

    formatted_string = f"{hours} hour" if hours == 1 else f"{hours} hours"
    if minutes > 0:
        formatted_string += f", {minutes} minute" if minutes == 1 else f", {minutes} minutes"
    if seconds > 0:
        formatted_string += f", and {seconds} second" if seconds == 1 else f", and {seconds} seconds"

    return formatted_string

