def mask_and_shift(file_object, mask_list):
    result = []

    try:
        bytes_to_read = 4
        data = file_object.read(bytes_to_read)
        for offset, mask in mask_list:
            masked_byte = data[offset] & mask
            shifted_byte = masked_byte >> offset
            result.append(shifted_byte)

        return result

    except Exception as e:
        print(f"An error occurred while reading or masking/shifting the bytes: {e}")
        return None

def calculate_filter_order(kernel_size, stride, input_shape):
    assert kernel_size > 0 and stride > 0 and all(x > 0 for x in input_shape), "Invalid input"

    output_width = (input_shape[0] - kernel_size) // stride + 1
    output_height = (input_shape[1] - kernel_size) // stride + 1

    return (output_width, output_height)

