def format_ordinal(number):
    if not 1 <= number <= 100:
        return ""

    last_digit = number % 10
    if last_digit in (1, 2, 3) and (number - last_digit) % 100 != 10:
        suffix = ["st", "nd", "rd"][last_digit - 1]
    else:
        suffix = "th"
    return str(number) + suffix

