        return f"Point(x={self.x}, y={self.y}, z={self.z})"

def euclidean_distance(a: Point, b: Point) -> float:
    x_diff_sq = (a.x - b.x) ** 2
    y_diff_sq = (a.y - b.y) ** 2
    z_diff_sq = (a.z - b.z) ** 2
    return (x_diff_sq + y_diff_sq + z_diff_sq) ** 0.5

