def call_methods(obj, method_names, method_args):
    results = []
    for name, args in zip(method_names, method_args):
        try:
            method = getattr(obj, name)
            result = method(*args)
            results.append(result)
        except AttributeError:
            print(f"Invalid method name: {name}")
        except TypeError:
            print(f"Invalid arguments for method: {name}")
            raise
    return results

