import re

def match_selector(tag, selector):
    star_re = re.compile(r'\*')
    plus_re = re.compile(r'\+')
    greater_re = re.compile(r'\>')
    if star_re.search(selector):
        return True

    if plus_re.search(selector):
        return False

    if greater_re.search(selector):
        return False
    if tag == selector:
        return True

    return False

def selector_matches_tags(selector, tags):
    for tag in tags:
        if match_selector(tag, selector):
            return True

    return False

