def longest_substring_without_duplicates(s: str) -> str:
    start = end = 0
    max_length = 0
    longest_substring = ""
    seen_characters = set()

    while end < len(s):
        if s[end] not in seen_characters:
            seen_characters.add(s[end])
            end += 1
            if end - start > max_length:
                max_length = end - start
                longest_substring = s[start:end]
        else:
            seen_characters.remove(s[start])
            start += 1

    return longest_substring

