def prime_factorization(number):
    factors = {}
    factor = 2
    while number > 1:
        if number % factor == 0:
            factors[factor] = factors.get(factor, 0) + 1
            number /= factor
        else:
            factor += 1
    return factors
def prime_factorization_of_product(number):
    factors = prime_factorization(number)
    product_factors = {}
    for factor, exponent in factors.items():
        product_factors[factor] = exponent + 1
    return product_factors

