def greatest_and_least_clamped(numbers):
    min_val = -50
    max_val = 100
    greatest_clamped = min_val
    least_clamped = max_val

    for num in numbers:
        clamped_num = min(max(num, min_val), max_val)
        if clamped_num > greatest_clamped:
            greatest_clamped = clamped_num
        if clamped_num < least_clamped:
            least_clamped = clamped_num

    return greatest_clamped, least_clamped

