import random

def generate_weighted_random_number(weighted_numbers):
    total_weight = sum(number[1] for number in weighted_numbers)
    random_number = random.randint(0, total_weight)
    current_sum = 0
    for number, weight in weighted_numbers:
        current_sum += weight
        if current_sum > random_number:
            return number
    return weighted_numbers[-1][0]

import torch

def recursive_tensor_conversion(data, device='cpu'):
    if isinstance(data, (int, float)):
        return torch.tensor(data, device=device)
    elif isinstance(data, (list, tuple)):
        return [recursive_tensor_conversion(item, device) for item in data]
    elif isinstance(data, dict):
        return {key: recursive_tensor_conversion(value, device) for key, value in data.items()}
    else:
        return data

