from typing import Dict, Any

def xml_to_dict(xml_string: str) -> Dict[str, Any]:
    """
    Convert an XML string to a dictionary.
    """
    tree = ET.fromstring(xml_string)
    def traverse_tree(element: ET.Element) -> Dict[str, Any]:
        element_dict = {}
        element_dict[element.tag] = element.text
        if len(element) > 0:
            children = []
            for child in element:
                child_dict = traverse_tree(child)
                children.append(child_dict)
            element_dict[element.tag] = children

        return element_dict
    return traverse_tree(tree)

def search_tree(tree, pattern):
    def search_tree_helper(tree, pattern, path):
        result = []
        for key, value in tree.items():
            new_path = path + '.' + key if path else key
            if new_path == pattern:
                result.append(value)
            elif isinstance(value, dict):
                result.extend(search_tree_helper(value, pattern, new_path))
        return result
    return search_tree_helper(tree, pattern, '')

