class MinHeap:
    def __init__(self):
        self.heap = []

    def heappush(self, item):
        self.heap.append(item)
        self._siftup(len(self.heap) - 1)

    def heappop(self):
        if not self.heap:
            raise IndexError("cannot pop from an empty heap")
        self._swap(0, len(self.heap) - 1)
        item = self.heap.pop()
        self._siftdown(0)
        return item

    def _siftup(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self.heap[parent] <= self.heap[i]:
                break
            self._swap(i, parent)
            i = parent

    def _siftdown(self, i):
        while True:
            left = 2 * i + 1
            right = 2 * i + 2
            smallest = i
            if left < len(self.heap) and self.heap[left] < self.heap[i]:
                smallest = left
            if right < len(self.heap) and self.heap[right] < self.heap[smallest]:
                smallest = right
            if smallest == i:
                break
            self._swap(i, smallest)
            i = smallest

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def __len__(self):
        return len(self.heap)

def find_global_minimum(a: float, b: float, c: float) -> float:
    """
    Finds the global minimum of a quadratic function.
    The function takes in the coefficients a, b, and c of the function and returns the value of x that minimizes the function.
    """
    if a > 0:
        x_min = -b / (2 * a)
        return x_min
    else:
        return None

