def polygon_orientation(polygon):
    signed_area = 0
    for i in range(len(polygon)):
        j = (i + 1) % len(polygon)
        x1, y1 = polygon[i]
        x2, y2 = polygon[j]
        signed_area += (x1 * y2 - x2 * y1)
    if signed_area > 0:
        return 1
    elif signed_area < 0:
        return -1
    else:
        return 0

