def fibonacci_dp(n: int) -> int:
    cache = {}

    def helper(k: int) -> int:
        if k <= 1:
            return k
        if k not in cache:
            cache[k] = helper(k - 1) + helper(k - 2)
        return cache[k]

    return helper(n)

