def is_cyclic(graph):
    visited = set()
    def dfs(node_id):
        if node_id in visited:
            return True

        visited.add(node_id)

        for connection_id in graph[node_id]:
            if dfs(connection_id):
                return True

        return False
    for node_id in graph:
        if dfs(node_id):
            return True

    return False

