def struct_to_dict(struct_ptr):
    """
    Converts a ctypes struct pointer into a dictionary.
    Args:
        struct_ptr (ctypes.Structure): A ctypes struct pointer.
    Returns:
        dict: A dictionary representing the contents of the struct.
    """
    struct_dict = {}
    for field_name, field_type in struct_ptr._type_.iter_fields():
        if isinstance(field_type, Structure):
            field_value = struct_to_dict(struct_ptr[field_name])
        else:
            field_value = struct_ptr[field_name]
        struct_dict[field_name] = field_value
    return struct_dict

def apply_f_to_inputs(f, inputs):
    if not inputs:
        return []
    input_type = type(inputs[0])
    for i in inputs[1:]:
        if not isinstance(i, input_type):
            return f"Error: not all inputs are of type {input_type}."
    outputs = []
    for i in inputs:
        try:
