unit_prefixes = {
    'k': 1000,
    'M': 1000000,
    'G': 1000000000,
    'T': 1000000000000
}

def convert_line_to_list_of_floats(line):
    values = line.split(',')
    converted_values = []
    for value in values:
        match = re.search(r'^(\d+(\.\d+)?)([kMG])$', value)
        if match:
            num_part = float(match.group(1))
            prefix = match.group(3)
            factor = unit_prefixes[prefix]
            converted_values.append(num_part * factor)
        else:
            converted_values.append(float(value))

    return converted_values

import re

def minutes_since_midnight(time_str):
    if not re.match(r'^([0-1]\d|2[0-3]):[0-5]\d$', time_str):
        return 0
    hour, minute = time_str.split(':')
    hour = int(hour)
    if hour < 0 or hour > 23:
        return 0

    minute = int(minute)
    if minute < 0 or minute > 59:
        return 0
    return hour * 60 + minute

