import xml.etree.ElementTree as ET

def xml_to_dict(xml_string: str) -> dict:
    root = ET.fromstring(xml_string)

    def traverse_xml_tree(element):
        if element.attrib:
            tag_attributes = {key: value for key, value in element.attrib.items()}
        else:
            tag_attributes = {}
        for child in element:
            tag_attributes[child.tag] = traverse_xml_tree(child)

        return tag_attributes

    return {root.tag: traverse_xml_tree(root)}

