import hashlib

def pow_mining(message, target_difficulty):
    nonce = 0
    while True:
        message_with_nonce = message + str(nonce)
        hash_value = hashlib.sha256(message_with_nonce.encode()).hexdigest()
        for _ in range(target_difficulty):
            hash_value = hashlib.sha256(hash_value.encode()).hexdigest()
        if hash_value[:target_difficulty] == '0' * target_difficulty:
            return nonce
        nonce += 1

def longest_substring_without_repeated_chars(s):
    if not s:
        return ""

    start, end = 0, 0
    longest_substring = ""

    while end < len(s):
        if s[end] not in s[start:end]:
            end += 1
        else:
            start = s.index(s[end], start) + 1
            end += 1

        if end - start > len(longest_substring):
            longest_substring = s[start:end]

    return longest_substring

