def dot_product(A, B):
    n, m = len(A), len(A[0])
    m, p = len(B), len(B[0])

    def dot(row, col):
        for i in range(m):
            yield A[row][i] * B[i][col]

    return [[sum(dot(i, j)) for j in range(p)] for i in range(n)]

