def count_ranges(ranges, num):
    ranges.sort(key=lambda x: x[0])
    new_ranges = []
    for range in ranges:
        if new_ranges and new_ranges[-1][1] >= range[0]:
            new_ranges[-1][1] = max(new_ranges[-1][1], range[1])
        else:
            new_ranges.append(range)
    count = 0
    for range in new_ranges:
        if num >= range[0] and num <= range[1]:
            count += 1

    return count

def spiral_traversal(arr):
    rows = len(arr)
    cols = len(arr[0])
    direction = 0  # 0 = right, 1 = down, 2 = left, 3 = up
    output = []

    row, col = 0, 0
    while len(output) < rows * cols:
        output.append((row, col))
        next_row, next_col = get_next_position(row, col, direction)
        if 0 <= next_row < rows and 0 <= next_col < cols and (next_row, next_col) not in output:
            row, col = next_row, next_col
        else:
            direction = (direction + 1) % 4
            row, col = get_next_position(row, col, direction)

    return output


def get_next_position(row, col, direction):
    if direction == 0:
        return row, col + 1
    elif direction == 1:
        return row + 1, col
    elif direction == 2:
        return row, col - 1
    else:
        return row - 1, col

