import bisect

def create_binary_search_function(list_of_integers):
    def binary_search_function(target, list_of_integers):
        index = bisect.bisect_left(list_of_integers, target)
        if index < len(list_of_integers) and list_of_integers[index] == target:
            return index
        return -1

    return binary_search_function

def calc_length(arr, idx):
