def insertion_sort_copy(items):
    if not isinstance(items, list):
        raise ValueError('Invalid input: must be a list')
    sorted_items = items[:]
    for i in range(1, len(sorted_items)):
        current_item = sorted_items[i]
        j = i - 1
        while j >= 0 and sorted_items[j] > current_item:
            sorted_items[j + 1] = sorted_items[j]
            j -= 1
        sorted_items[j + 1] = current_item

    return sorted_items

