import json

def convert_keys(data):
    if isinstance(data, dict):
        return {convert_keys(k): convert_keys(v) for k, v in data.items()}
    elif isinstance(data, (list, tuple)):
        return type(data)(convert_keys(v) for v in data)
    else:
        return data

def snake_case(data):
    if isinstance(data, dict):
        return {snake_case(k): snake_case(v) for k, v in data.items()}
    elif isinstance(data, str):
        return ''.join(('_' if c.isupper() else c) for c in data).lower()
    else:
        return data

def serialize(dictionary, filename):
    converted_dictionary = convert_keys(snake_case(dictionary))
    with open(filename, 'w') as file:
        json.dump(converted_dictionary, file)

