import hashlib
import os

def md5_hash_with_optimal_block_size(file_path):
    file_size = os.path.getsize(file_path)
    optimal_block_size = 1024  # Adjust this value based on your memory constraints and other factors

    with open(file_path, 'rb') as f:
        md5 = hashlib.md5()
        while True:
            data = f.read(optimal_block_size)
            if not data:
                break
            md5.update(data)

    return md5.hexdigest()

