import concurrent.futures
import urllib.request

def fetch_url(url):
    with urllib.request.urlopen(url) as response:
        return response.read()

def process_urls(urls, max_workers=10):
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = [executor.submit(fetch_url, url) for url in urls]
        results = []
        for future in concurrent.futures.as_completed(futures):
            if future.cancelled():
                results.append(None)
            elif future.exception():
                results.append(None)
            else:
                results.append(future.result())
    return results

import numpy as np

def generate_sparsely_connected_network(n_hidden, n_input, n_output, sparsity, reinit_seed):
    np.random.seed(reinit_seed)
    adjacency_matrix = np.zeros((n_input + n_hidden + n_output, n_input + n_hidden + n_output))
    adjacency_matrix[:n_input, :n_input] = 1
    adjacency_matrix[n_input:n_input+n_hidden, n_input:n_input+n_hidden] = 1
    adjacency_matrix[n_input+n_hidden:, n_input+n_hidden:] = 1
    for i in range(n_input):
        for j in range(n_input, n_input+n_hidden):
            if np.random.rand() < sparsity:
                adjacency_matrix[i, j] = 1
    for i in range(n_input+n_hidden, n_input+n_hidden+n_output):
        for j in range(n_input, n_input+n_hidden):
            if np.random.rand() < sparsity:
                adjacency_matrix[i, j] = 1

    return adjacency_matrix

def most_frequent_character(string):
