import math

def cyclical_learning_rates(max_lr, min_lr, num_iterations):
    learning_rates = []
    for i in range(num_iterations):
        learning_rates.append(min_lr + (max_lr - min_lr) * i / (num_iterations - 1))
    for i in range(num_iterations):
        learning_rates.append(max_lr - (max_lr - min_lr) * i / (num_iterations - 1))
    return learning_rates

def cosine_decay_learning_rates(max_lr, min_lr, num_iterations):
    learning_rates = []
    for i in range(num_iterations):
        learning_rates.append(min_lr + (max_lr - min_lr) * (1 + math.cos(math.pi * i / num_iterations)) / 2)
    return learning_rates

