def smallest_average_ascii_value(strings):
    def average_ascii(string):
        char_sum = 0
        for char in string:
            char_sum += ord(char)
        return char_sum / len(string)

    min_value = float("inf")
    min_string = ""
    for string in strings:
        avg_ascii = average_ascii(string)
        if avg_ascii < min_value or (avg_ascii == min_value and string < min_string):
            min_value = avg_ascii
            min_string = string

    return min_string

