import numpy as np

def local_median_filter(signal, window_size, step_size):
    if window_size <= 0 or step_size <= 0 or window_size > len(signal) or step_size > len(signal):
        raise ValueError("Window and step sizes must be greater than 0 and not greater than the length of the signal.")
    filtered_signal = []
    for i in range(0, len(signal) - window_size + 1, step_size):
        window = signal[i:i+window_size]
        median = np.median(window)
        filtered_signal.append(median)
    return np.array(filtered_signal)

