def do_boxes_overlap(box1, box2):
    x1, y1, w1, h1 = box1
    x2, y2, w2, h2 = box2
    x1_top_left, y1_top_left = x1, y1
    x1_bottom_right, y1_bottom_right = x1 + w1, y1 + h1
    x2_top_left, y2_top_left = x2, y2
    x2_bottom_right, y2_bottom_right = x2 + w2, y2 + h2

    if x2_top_left >= x1_top_left and x2_top_left <= x1_bottom_right and y2_top_left >= y1_top_left and y2_top_left <= y1_bottom_right:
        return True
    elif x1_top_left >= x2_top_left and x1_top_left <= x2_bottom_right and y1_top_left >= y2_top_left and y1_top_left <= y2_bottom_right:
        return True
    else:
        return False

