from typing import List, Tuple

def get_distinct_tuple(lst: List[int]) -> Tuple[set, set, set]:
    """
    Returns a tuple of sets based on the frequency of integers in a given list.
    The first set contains all distinct integers, the second set contains integers
    that occur exactly once, and the third set contains integers that occur more
    than once.
    """
    freq_dict = {}
    for i in lst:
        if i not in freq_dict:
            freq_dict[i] = 1
        else:
            freq_dict[i] += 1

    distinct = set()
    exactly_once = set()
    more_than_once = set()

    for i, freq in freq_dict.items():
        distinct.add(i)
        if freq == 1:
            exactly_once.add(i)
        else:
            more_than_once.add(i)

    return distinct, exactly_once, more_than_once

import json

def serialize_to_json(data: dict) -> str:
    class ValidateEncoder(json.JSONEncoder):
        def default(self, o):
            if isinstance(o, (int, float, str, bool, None)):
                return str(o)
            else:
                raise TypeError("Value must be an int, float, str, bool, or None.")

    return json.dumps(data, indent=4, sort_keys=True, cls=ValidateEncoder)

