def count_islands(arr):
    if not isinstance(arr, list) or not all(isinstance(element, list) for element in arr):
        raise ValueError("'arr' must be a 2D array.")
    def check_neighbors(row, col):
        if 0 <= row < len(arr) and 0 <= col < len(arr[0]):
            if arr[row][col] == '1':
                arr[row][col] = '0'  # Mark as visited
                check_neighbors(row + 1, col)
                check_neighbors(row - 1, col)
                check_neighbors(row, col + 1)
                check_neighbors(row, col - 1)
    islands = 0
    for row in range(len(arr)):
        for col in range(len(arr[0])):
            if arr[row][col] == '1':
                islands += 1
                check_neighbors(row, col)

    return islands

