def slope_intercept_to_pixel_coordinates(slope, intercept, image_size):
    """
    Converts the slope-intercept equation parameters to pixel coordinates on an image.
    """
    if not isinstance(slope, (int, float)):
        raise ValueError("Invalid slope, must be a number.")
    if not isinstance(intercept, (int, float)):
        raise ValueError("Invalid intercept, must be a number.")
    if not isinstance(image_size, (tuple, list)) or len(image_size) != 2:
        raise ValueError("Invalid image size, must be a tuple or list of length 2.")
    if not isinstance(image_size[0], int) or image_size[0] <= 0:
        raise ValueError("Invalid image width, must be a positive integer.")
    if not isinstance(image_size[1], int) or image_size[1] <= 0:
        raise ValueError("Invalid image height, must be a positive integer.")
    x = (image_size[1] - intercept) / slope
    y = slope * x + intercept

    return x, y

