from typing import List

def sieve_of_erastothenes(limit: int) -> List[int]:
    primes = [True] * (limit + 1)
    primes[0] = False
    primes[1] = False

    for i in range(2, int(limit**0.5) + 1):
        if primes[i]:
            for j in range(i * i, limit + 1, i):
                primes[j] = False

    return [i for i in range(limit + 1) if primes[i]]

