import urllib.request

def make_get_request(url, headers={}, params={}, timeout=10):
    """
    Make a GET request to the specified URL with optional headers, parameters, and timeout.

    Args:
        url (str): The URL to make the GET request to.
        headers (dict): A dictionary of headers to be included in the request.
        params (dict): A dictionary of parameters to be included in the URL.
        timeout (int): The number of seconds to wait before timing out the request.

    Returns:
        str: The response data as a string. If an error occurs, a string error message is returned instead.

    Raises:
        ValueError: If `timeout` is not a positive integer.
    """
    if not isinstance(timeout, int) or timeout <= 0:
        raise ValueError("`timeout` must be a positive integer.")

    request = urllib.request.Request(url)
    if headers:
        for key, value in headers.items():
            request.add_header(key, value)
    if params:
        query_string = urllib.parse.urlencode(params)
        url += f"?{query_string}"

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        return f"Error: HTTP Error {e.code} - {e.reason}"
    except urllib.error.URLError as e:
        return f"Error: {e.reason}"
    except:
        return "Error: An unknown error occurred."

