def find_closest(lst):
    lst.sort()

    def anonymous_function(x):
        if x in lst:
            return x
        left = 0
        right = len(lst) - 1
        closest = None
        while left <= right:
            mid = (left + right) // 2
            if lst[mid] == x:
                return lst[mid]
            elif lst[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        if left < len(lst) and closest is None:
            closest = lst[left]
        if right >= 0 and closest is None:
            closest = lst[right]
        return closest

    return anonymous_function

