def fetch_value(tensor, idx):
    if len(idx) != len(tensor):
        return None  # Invalid index
    for i in idx:
        if i < 0 or i >= len(tensor):
            return None  # Index out of range
    if not isinstance(tensor, list) or not all(isinstance(item, list) for item in tensor):
        raise ValueError("Invalid tensor: not a nested list")
    if not all(len(item) == len(tensor[0]) for item in tensor):
        raise ValueError("Invalid tensor: unequal lengths in nested lists")
    value = tensor
    for i in idx:
        value = value[i]
    return value

