def product_except_current(nums: List[int]) -> List[int]:
    """
    Takes in a list of integers and returns the product of all the integers in the list except for the integer at the current index.
    """
    result = []

    for i, num in enumerate(nums):
        product = 1
        for j, n in enumerate(nums):
            if j != i:
                product *= n

        result.append(product)

    return result

