def connected_components(edges):
    vertices = set()
    components = {}

    for edge in edges:
        v1, v2 = edge
        vertices.add(v1)
        vertices.add(v2)

        if v1 in components:
            components[v1].add(v2)
        else:
            components[v1] = {v2}

        if v2 in components:
            components[v2].add(v1)
        else:
            components[v2] = {v1}

    connected_components = []

    for vertex in components:
        if vertex not in components[vertex]:
            components[vertex].add(vertex)

        if components[vertex] not in connected_components:
            connected_components.append(components[vertex])

    return connected_components

