def dot_product(matrix_a, matrix_b):
    validate_matrix(matrix_a)
    validate_matrix(matrix_b)

    rows_a = len(matrix_a)
    columns_a = len(matrix_a[0])
    rows_b = len(matrix_b)
    columns_b = len(matrix_b[0])

    if columns_a != rows_b:
        raise ValueError("Matrix dimensions are incompatible.")

    result_matrix = [[0 for _ in range(columns_b)] for _ in range(rows_a)]

    for row_a in range(rows_a):
        for column_b in range(columns_b):
            dot_product = 0
            for column_a in range(columns_a):
                dot_product += matrix_a[row_a][column_a] * matrix_b[column_a][column_b]
            result_matrix[row_a][column_b] = dot_product

    return result_matrix

