def kronecker_product(a, b):
    m, n = len(a), len(a[0])
    p, q = len(b), len(b[0])
    kron = [[0] * (n * q) for _ in range(m * p)]

    for i in range(m):
        for j in range(n):
            for k in range(p):
                for l in range(q):
                    kron[i * p + k][j * q + l] = a[i][j] * b[k][l]

    return kron

def trailing_zeros_in_factorial(n):
    if n <= 0:
        return 0
    if n > 1e12:
        return -1
    factorial = 1
    for i in range(1, n + 1):
        factorial *= i
    trailing_zeros = 0
    while factorial % 10 == 0:
        factorial //= 10
        trailing_zeros += 1
    return trailing_zeros

