def generate_parenthesized_combinations(s):
    def generate_combinations(s, start, end):
        if start > end:
            return [""]
        if start == end:
            return [s[start]]
        combinations = []
        for i in range(start, end + 1):
            left_combinations = generate_combinations(s, start, i - 1)
            right_combinations = generate_combinations(s, i + 1, end)
            for left in left_combinations:
                for right in right_combinations:
                    combinations.append("(" + left + ")" + right)
        return combinations

    return generate_combinations(s, 0, len(s) - 1)

