def persistent_cache(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if func.__name__ in _cache:
            cached_func = _cache[func.__name__]
            if cached_func.__doc__ != func.__doc__ or cached_func.__code__.co_varnames != func.__code__.co_varnames:
                cached_func.__doc__ = func.__doc__
                cached_func.__code__.co_varnames = func.__code__.co_varnames
        else:
