import sys


def shortest_path_weight(matrix):
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])

    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = matrix[0][0]

    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    for j in range(1, cols):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    return dp[-1][-1]

def calculate_cardinality(shape):
    cardinality = 1
    for dim in shape:
        if isinstance(dim, list):
            cardinality *= calculate_cardinality(dim)
        else:
            cardinality *= dim
    return cardinality

