def complete_partial_path(partial_path, directory=None):
    if not directory:
        directory = os.getcwd()
    normalized_path = os.path.normpath(directory).rstrip(os.sep)
    full_path = os.path.join(normalized_path, partial_path)
    if os.path.isdir(full_path):
        full_path = os.path.join(full_path, '')
    matches = glob.glob(full_path)
    if len(matches) == 1:
        return matches[0]
    elif len(matches) > 1:
        print(f"Multiple matches found for '{partial_path}':")
        for i, match in enumerate(matches, start=1):
            print(f"{i}. {match}")
        while True:
            selection = input("Select a match (1-{}): ".format(len(matches)))
            try:
                index = int(selection) - 1
                if 0 <= index < len(matches):
                    return matches[index]
                else:
                    print("Invalid selection. Please select a valid match.")
            except ValueError:
                print("Invalid input. Please input a number.")
    else:
