def traverse_quadtree(node):
    if not node:
        return []

    if node.is_leaf():
        return [node.value]

    cache = {}

    def preorder_traversal(node):
        if node in cache:
            return cache[node]

        if node.is_leaf():
            cache[node] = [node.value]
        else:
            cache[node] = []
            for child in node.children:
                cache[node] += preorder_traversal(child)

        return cache[node]

    return preorder_traversal(node)

