        return source

    def remove_block_comments(text, start=0):
        matches = re.finditer(r'/\*.*?\*/', text)
        for match in matches:
            text = text[:match.start()] + text[match.end():]
            if start < match.start():
                text = remove_block_comments(text, start=match.start())
        return text

    return remove_comments(remove_block_comments(source))

