def find_longest_text_block(timestamps):
    memo = {}  # Memo table to store results for subproblems

    def longest_text_block_length(n):
        if n in memo:
            return memo[n]  # Return result from memo table if it's already computed
        if n <= 1:
            return 0  # Subproblem with 0 or 1 timestamp has length 0
        elif n == 2:
            return timestamps[1] - timestamps[0]  # Length is the time difference between the two timestamps
        memo[n] = max(
            longest_text_block_length(n - 1),
            timestamps[n - 1] - timestamps[n - 2] + longest_text_block_length(n - 2),
        )
        return memo[n]

    return longest_text_block_length(len(timestamps))

