def get_data_structure_diff_count(data1, data2):
    value_diff = 0
    structure_diff = 0

    def compare_elements(el1, el2):
        nonlocal value_diff, structure_diff

        if isinstance(el1, dict) and isinstance(el2, dict):
            for key in el1.keys():
                if key not in el2:
                    structure_diff += 1
                elif el1[key] != el2[key]:
                    value_diff += 1
                    compare_elements(el1[key], el2[key])
            for key in el2.keys():
                if key not in el1:
                    structure_diff += 1
                    compare_elements(el1[key], el2[key])
        elif isinstance(el1, list) and isinstance(el2, list):
            if len(el1) != len(el2):
                structure_diff += 1
            for i in range(min(len(el1), len(el2))):
                compare_elements(el1[i], el2[i])
        elif el1 != el2:
