    if len(items) <= 1:
        return items

    mid = len(items) // 2
    left = merge_sort(items[:mid], key)
    right = merge_sort(items[mid:], key)
    return merge(left, right, key)

def merge(left, right, key):
    result = []
    i, j = 0, 0

    while i < len(left) and j < len(right):
        if key(left[i]) < key(right[j]):
            result.append(left[i])
            i += 1
        elif key(left[i]) > key(right[j]):
            result.append(right[j])
            j += 1
        else:
            if key(left[i], 1) < key(right[j], 1):
                result.append(left[i])
                i += 1
            elif key(left[i], 1) > key(right[j], 1):
                result.append(right[j])
                j += 1
            else:
                if key(left[i], 2) < key(right[j], 2):
                    result.append(left[i])
                    i += 1
                elif key(left[i], 2) > key(right[j], 2):
                    result.append(right[j])
                    j += 1
                else:
                    if key(left[i], 3) < key(right[j], 3):
                        result.append(left[i])
                        i += 1
                    elif key(left[i], 3) > key(right[j], 3):
                        result.append(right[j])
                        j += 1
                    else:
                        if key(left[i], 4) < key(right[j], 4):
                            result.append(left[i])
                            i += 1
                        elif key(left[i], 4) > key(right[j], 4):
                            result.append(right[j])
                            j += 1
                        else:
                            if key(left[i], 5) < key(right[j], 5):
                                result.append(left[i])
                                i += 1
                            else:
                                result.append(right[j])
                                j += 1

    result.extend(left[i:])
    result.extend(right[j:])
    return result

