def is_contiguous(grid, i, j, visited, value):
    if i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]):
        return False

    if grid[i][j] != value:
        return False

    if (i, j) in visited:
        return True

    visited.add((i, j))

    return is_contiguous(grid, i + 1, j, visited, value) or \
           is_contiguous(grid, i - 1, j, visited, value) or \
           is_contiguous(grid, i, j + 1, visited, value) or \
           is_contiguous(grid, i, j - 1, visited, value) or \
           is_contiguous(grid, i + 1, j + 1, visited, value) or \
           is_contiguous(grid, i + 1, j - 1, visited, value) or \
           is_contiguous(grid, i - 1, j + 1, visited, value) or \
           is_contiguous(grid, i - 1, j - 1, visited, value)

