import re

def is_valid_css_colour(colour: str) -> bool:
    assert isinstance(colour, str), "Input must be a string"
    hex_regex = "^#[0-9a-fA-F]{6}$"
    short_hex_regex = "^#[0-9a-fA-F]{3}$"
    rgb_regex = "^rgb\(([0-9]{1,3}),([0-9]{1,3}),([0-9]{1,3})\)$"
    rgb_percent_regex = "^rgb\(([0-9]{1,3})%,([0-9]{1,3})%,([0-9]{1,3})%\)$"
    if re.match(hex_regex, colour) or re.match(short_hex_regex, colour) or re.match(rgb_regex, colour):
        if re.match(rgb_regex, colour):
            r, g, b = re.match(rgb_regex, colour).groups()
            r, g, b = int(r), int(g), int(b)
            if not (0 <= r <= 255 and 0 <= g <= 255 and 0 <= b <= 255):
                return False  # If any of R, G, or B is out of range, return False
        return True  # If the string matches the hex or short hex format or is of the form "rgb(R,G,B)" with valid values, return True
    elif re.match(rgb_percent_regex, colour):
        r, g, b = re.match(rgb_percent_regex, colour).groups()
        r, g, b = int(r), int(g), int(b)
        if not (0 <= r <= 100 and 0 <= g <= 100 and 0 <= b <= 100):
            return False  # If any of R, G, or B is out of range, return False
        return True  # If the string matches the format "rgb(R%,G%,B%)" with valid values, return True
    else:
        return False  # If the string doesn't match any of the valid formats, return False

