import re

def find_orphan_functions(functions):
    function_dependencies = {}
    for func_name, func_body in functions.items():
        func_calls = re.findall(r"\w+\(", func_body)
        if func_name not in function_dependencies:
            function_dependencies[func_name] = []
        for func_call in func_calls:
            dependency = func_call[:-1]  # Remove the trailing parentheses
            function_dependencies[func_name].append(dependency)
    orphan_functions = [func for func, dependencies in function_dependencies.items() if not dependencies]

    return orphan_functions

