def binary_search_count(arr, target):
    def _binary_search_count_helper(arr, target, start, end):
        if start > end:
            return 0

        mid = (start + end) // 2
        if arr[mid] == target:
            count = 1
            i = 1
            while mid + i < len(arr) and arr[mid + i] == target:
                count += 1
                i += 1
            i = 1
            while mid - i >= 0 and arr[mid - i] == target:
                count += 1
                i += 1
            return count
        elif arr[mid] > target:
            return _binary_search_count_helper(arr, target, start, mid - 1)
        else:
            return _binary_search_count_helper(arr, target, mid + 1, end)

    return _binary_search_count_helper(arr, target, 0, len(arr) - 1)

