def get_max_value(data):
    """
    Recursively traverses a nested data structure and returns the maximum value found.
    """
    max_value = float('-inf')

    def helper(x):
        nonlocal max_value
        if isinstance(x, list) or isinstance(x, tuple):
            for item in x:
                helper(item)
        else:
            max_value = max(max_value, x)

    helper(data)
    return max_value

