import numpy as np

def calculate_accuracy(predicted_labels, actual_labels):
    predicted_labels = np.array(predicted_labels)
    actual_labels = np.array(actual_labels)
    if predicted_labels.shape != actual_labels.shape:
        raise ValueError("Mismatch in input dimensions")

    correct_predictions = np.sum(predicted_labels == actual_labels)
    total_predictions = len(predicted_labels)
    accuracy = correct_predictions / total_predictions
    return accuracy

def calculate_precision(predicted_labels, actual_labels):
    predicted_labels = np.array(predicted_labels)
    actual_labels = np.array(actual_labels)
    if predicted_labels.shape != actual_labels.shape:
        raise ValueError("Mismatch in input dimensions")

    true_positives = np.sum((predicted_labels == 1) & (actual_labels == 1))
    predicted_positives = np.sum(predicted_labels == 1)
    if predicted_positives == 0:
        precision = 0
    else:
        precision = true_positives / predicted_positives
    return precision

def calculate_recall(predicted_labels, actual_labels):
    predicted_labels = np.array(predicted_labels)
    actual_labels = np.array(actual_labels)
    if predicted_labels.shape != actual_labels.shape:
        raise ValueError("Mismatch in input dimensions")

    true_positives = np.sum((predicted_labels == 1) & (actual_labels == 1))
    actual_positives = np.sum(actual_labels == 1)
    if actual_positives == 0:
        recall = 0
    else:
        recall = true_positives / actual_positives
    return recall

def calculate_f1_score(predicted_labels, actual_labels):
    precision = calculate_precision(predicted_labels, actual_labels)
    recall = calculate_recall(predicted_labels, actual_labels)
    if precision == 0 or recall == 0:
        f1_score = 0
    else:
        f1_score = 2 * (precision * recall) / (precision + recall)
    return f1_score

def evaluate_model(predicted_labels, actual_labels, calculate_f1=False):
    accuracy = calculate_accuracy(predicted_labels, actual_labels)
    precision = calculate_precision(predicted_labels, actual_labels)
    recall = calculate_recall(predicted_labels, actual_labels)
    if calculate_f1:
        f1_score = calculate_f1_score(predicted_labels, actual_labels)
    else:
        f1_score = None
    return accuracy, precision, recall, f1_score

