def calculate_binary_classification_metrics(dataset):
    true_positives = 0
    false_positives = 0
    true_negatives = 0
    false_negatives = 0

    for example in dataset:
        predicted_label, actual_label = example['predicted_label'], example['actual_label']
        if predicted_label == 'positive' and actual_label == 'positive':
            true_positives += 1
        elif predicted_label == 'positive' and actual_label == 'negative':
            false_positives += 1
        elif predicted_label == 'negative' and actual_label == 'negative':
            true_negatives += 1
        else: # predicted_label == 'negative' and actual_label == 'positive':
            false_negatives += 1

    accuracy = (true_positives + true_negatives) / len(dataset)
    precision = true_positives / (true_positives + false_positives)
    recall = true_positives / (true_positives + false_negatives)
    f1_score = 2 * precision * recall / (precision + recall)

    return accuracy, precision, recall, f1_score

def fibonacci_with_memoization(n: int) -> int:
    cache = {}

    def fib(n: int) -> int:
        if n <= 1:
            return n
        if n not in cache:
            cache[n] = fib(n - 1) + fib(n - 2)
        return cache[n]

    return fib(n)

