def is_version_compatible(api_version, my_version):
    api_version_numbers = api_version.split('.')  # Split the version string into major, minor, and patch versions
    my_version_numbers = my_version.split('.')

    major_version_match = api_version_numbers[0] == my_version_numbers[0]  # Check for major version compatibility
    if not major_version_match:
        return False  # Major versions don't match, so API is not compatible
    if api_version_numbers[1] < my_version_numbers[1]:
        return True  # Minor version is higher, so API is compatible
    elif api_version_numbers[1] > my_version_numbers[1]:
        return False  # Minor version is lower, so API is not compatible
    if api_version_numbers[2] < my_version_numbers[2]:
        return True  # Patch version is higher, so API is compatible
    elif api_version_numbers[2] > my_version_numbers[2]:
        return False  # Patch version is lower, so API is not compatible
    return True

