def encrypt_string(s: str) -> str:
    """
    Encrypts a string by applying a Caesar Cipher, shifting the ASCII characters by 3 and
    wrapping around the ASCII limits. If the character is lowercase, preserve its case before
    encryption. If the character is uppercase, shift it down to lowercase before encryption and
    then shift it back up to uppercase after encryption.
    """
    encrypted_characters = []

    for char in s:
        ascii_value = ord(char)
        shifted_value = (ascii_value + 3) % 256

        if char.islower():
            encrypted_character = chr(shifted_value)
        elif char.isupper():
            encrypted_character = chr((shifted_value + 32) % 256).lower()
            encrypted_character = encrypted_character.upper()
        else:
            encrypted_character = char

        encrypted_characters.append(encrypted_character)

    return ''.join(encrypted_characters)

