def detect_singleton(array: List[int]) -> bool:
    """
    Detects if a non-empty array contains a single unique element.
    """
    if not array:
        return False
    frequencies = {}

    for element in array:
        if element not in frequencies:
            frequencies[element] = 1
        else:
            frequencies[element] += 1
    return len([freq for freq in frequencies.values() if freq == 1]) == 1

