    lines = func_def_str.split("\n")
    docstring_line_index = next((i for i, line in enumerate(lines) if line.startswith('"""')), None)
    if docstring_line_index is None:
        return ""
    next_line_index = docstring_line_index + 1
    if lines[next_line_index].startswith('"""'):
