def binary_search(lst, value):
    """
    Searches for the given value in the given sorted list using binary search.
    Returns a tuple of index and number of iterations. If the value is not found, returns (-1, number of iterations).
    """
    iterations = 0

    left = 0
    right = len(lst) - 1

    while left <= right:
        iterations += 1

        mid = (left + right) // 2

        if lst[mid] == value:
            return mid, iterations
        elif value < lst[mid]:
            right = mid - 1
        else:
            left = mid + 1

    return -1, iterations


def linear_search(lst, value):
    """
    Searches for the given value in the given unsorted list using linear search.
    Returns a tuple of index and number of iterations. If the value is not found, returns (-1, number of iterations).
    """
    iterations = 0

    for i, item in enumerate(lst):
        iterations += 1

        if item == value:
            return i, iterations

    return -1, iterations


def search(lst, value, is_sorted=False):
    """
    Searches for the given value in the given list.
    If the list is sorted, binary search is used. Otherwise, linear search is used.
    Returns a tuple of index and number of iterations. If the value is not found, returns (-1, number of iterations).
    """
    if is_sorted:
        return binary_search(lst, value)
    else:
        return linear_search(lst, value)

