def get_all_values(dictionary):
    """
    This function takes a dictionary as input and returns a list of all the values
    in the dictionary, including any nested lists or dictionaries.
    """
    result = []

    def helper(d):
        """
        Helper function that recursively iterates through a dictionary and its nested elements
        and adds all values to the `result` list.
        """
        for key, value in d.items():
            if isinstance(value, dict):
                helper(value)
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
                        helper(item)
                    else:
                        result.append(item)
            else:
                result.append(value)

    helper(dictionary)
    return result

