def get_rooted_paths(paths):
    rooted_paths = []
    for path in paths:
        if not path:
            continue
        if path.startswith("/") or path.startswith("~") or path.startswith("C:"):
            if path.startswith("C:"):
                rooted_paths.append(path[:2])
