from collections import defaultdict

def convert_dict(input_dict):
    output_dict = defaultdict(list)
    keys_seen = set()

    def _convert_dict_recursive(input_dict, path):
        for key, value in input_dict.items():
            if key in keys_seen:
                raise ValueError("Overlapping keys detected")
            keys_seen.add(key)
            if isinstance(value, dict):
                _convert_dict_recursive(value, path + (key,))
            else:
                output_dict[path + (key,)] = value

    _convert_dict_recursive(input_dict, ())
    return output_dict

