def can_be_shuffled(string1, string2):
    if len(string1) != len(string2):
        return False
    mask1 = 0
    mask2 = 0
    for c in string1:
        mask1 |= 1 << ord(c)
    for c in string2:
        mask2 |= 1 << ord(c)
    mask_and = mask1 & mask2
    if mask_and == mask1:
        return True
    else:
        return False

