import threading

class BitwiseOperation(threading.Thread):
    def __init__(self, input_list, output_list):
        super().__init__()
        self.input_list = input_list
        self.output_list = output_list

    def run(self):
        for i, elem in enumerate(self.input_list):
            if i % 2 == 0:
                self.output_list[i] = elem | self.output_list[i + 1]
            else:
                self.output_list[i] = self.output_list[i - 1] | elem

def async_bitwise_or(input_list):
    output_list = [0] * len(input_list)
    threads = [BitwiseOperation(input_list, output_list) for _ in input_list]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    return output_list[-1]

