def heaps_algorithm(elements):
    if len(elements) <= 1:
        return [elements]

    permutations = []
    for i in range(len(elements)):
        sub_elements = elements[:i] + elements[i+1:]
        sub_permutations = heaps_algorithm(sub_elements)
        for sub_permutation in sub_permutations:
            permutation = [elements[i]] + sub_permutation
            permutations.append(permutation)

    return permutations

def find_min_max_circular(values, clockwise=True):
    min_val = values[0]
    max_val = values[0]
    step = 1 if clockwise else -1
    for value in values[::step]:
        if value < min_val:
            min_val = value
        if value > max_val:
            max_val = value
    return min_val, max_val

from typing import List

def calculator(tokens: List[str]) -> int:
    """
    Simulates a simple calculator with four operations: addition, subtraction,
    multiplication, and division.
    """
    stack = []
    for token in tokens:
        if token == "+":
            b, a = stack.pop(), stack.pop()
            stack.append(a + b)
        elif token == "-":
            b, a = stack.pop(), stack.pop()
            stack.append(a - b)
        elif token == "*":
            b, a = stack.pop(), stack.pop()
            stack.append(a * b)
        elif token == "/":
            b, a = stack.pop(), stack.pop()
            stack.append(a / b)
        else:
            stack.append(int(token))
    return stack[-1]

