        return []
    result = []
    for component in components:
        if not component.attributes or len(component.attributes) == 0:
            continue
        concat_names = []
        concat_values = []
        for attribute in component.attributes:
            if not attribute.name or not attribute.value:
                continue
            concat_names.append(attribute.name)
            concat_values.append(attribute.value)
        if len(concat_names) > 1024:
            concat_names = concat_names[:1024]
        if len(concat_values) > 1024:
            concat_values = concat_values[:1024]
        component_dict = {
            'name': ''.join(concat_names),
            'value': ''.join(concat_values)
        }
        result.append(component_dict)
    return result

