def chess_tensor(matrix: np.ndarray) -> np.ndarray:
    """
    Converts a 2D matrix into a 3D tensor representation that encodes the position of each chess piece.
    """
    tensor = np.zeros((8, 8, 12))
    for i in range(8):
        for j in range(8):
