def pad_tensor_to_square(tensor, padding_value=0):
    height, width = tensor.shape

    if height != width:
        padding_size = abs(height - width)
        if height > width:
            tensor = np.pad(tensor, ((0, 0), (padding_size // 2, padding_size - padding_size // 2)),
                            mode='constant', constant_values=padding_value)
        else:
            tensor = np.pad(tensor, ((padding_size // 2, padding_size - padding_size // 2), (0, 0)),
                            mode='constant', constant_values=padding_value)

    return tensor

