def recursive_dict_traversal(input_data, key_name):
    if not isinstance(input_data, (dict, list)):
        return []

    matching_keys = []

    def traverse(data, key_name):
        if isinstance(data, dict):
            for key, value in data.items():
                if key == key_name:
                    matching_keys.append(key)
                traverse(value, key_name)
        elif isinstance(data, list):
            for item in data:
                traverse(item, key_name)

    traverse(input_data, key_name)
    return matching_keys

