def iterate_with_conditions(iterable, max_iterations=1000):
    """
    Iterates through the given iterable and returns the last element.
    If the iterable is empty, raises ValueError.
    If the iterable is infinite, raises AssertionError.
    """
    iterations = 0
    last_element = None

    try:
        while True:
            last_element = next(iterable)
            iterations += 1
            if iterations > max_iterations:
                raise AssertionError("The iterator is infinite!")
    except StopIteration:
        if last_element is None:
            raise ValueError("The iterator is empty!")
        return last_element

from functools import lru_cache

def cache_by_args(maxsize):
    def decorator(f):
        cache = {}

        @lru_cache(maxsize=maxsize)
        def wrapper(*args):
            if args in cache:
                return cache[args]
            result = f(*args)
            cache[args] = result
            return result
        return wrapper
    return decorator

