def merge_sorted_iterators(iter1, iter2):
    """
    Merges two sorted iterators and yields the elements in sorted order.
    """
    iter1 = [int(x) for x in iter1]
    iter2 = [int(x) for x in iter2]
    p1, p2 = 0, 0

    while p1 < len(iter1) and p2 < len(iter2):
        if iter1[p1] <= iter2[p2]:
            yield iter1[p1]
            p1 += 1
        else:
            yield iter2[p2]
            p2 += 1
    while p1 < len(iter1):
        yield iter1[p1]
        p1 += 1

    while p2 < len(iter2):
        yield iter2[p2]
        p2 += 1

