def is_bipartite(graph):
    n = len(graph)
    visited = [False] * n
    color = [None] * n

    queue = []
    queue.append(0)  # start BFS from source node 0
    visited[0] = True
    color[0] = 'A'

    while queue:
        node = queue.pop(0)
        for neighbor in range(n):
            if graph[node][neighbor] == 1:
                if visited[neighbor]:
                    if color[neighbor] == color[node]:
                        return False
                else:
                    visited[neighbor] = True
                    color[neighbor] = 'B' if color[node] == 'A' else 'A'
                    queue.append(neighbor)
    return True

