from typing import List

def find_closest_match(input: str, candidates: List[str]) -> str:
    """
    Finds the closest match in `candidates` to `input` using Levenshtein distance.
    """
    min_distance = float('inf')
    closest_match = ''

    for candidate in candidates:
        distance = levenshtein_distance(input, candidate)

        if distance < min_distance:
            min_distance = distance
            closest_match = candidate

    return closest_match

def levenshtein_distance(str1: str, str2: str) -> int:
    """
    Calculates the Levenshtein distance between two strings.
    """
    if str1 == '':
        return len(str2)
    elif str2 == '':
        return len(str1)
    if str1[-1] == str2[-1]:
        return levenshtein_distance(str1[:-1], str2[:-1])
    else:
        insertion = 1 + levenshtein_distance(str1, str2[:-1])
        deletion = 1 + levenshtein_distance(str1[:-1], str2)
        substitution = 1 + levenshtein_distance(str1[:-1], str2[:-1])

        return min(insertion, deletion, substitution)

