def false_positive_rate(predictions, ground_truth):
    if len(predictions) != len(ground_truth):
        return None
    if any(prediction not in (0, 1) for prediction in predictions) \
        or any(gt not in (0, 1) for gt in ground_truth):
        return None
    num_false_positives = 0
    num_negatives = 0
    for prediction, gt in zip(predictions, ground_truth):
        if prediction == 1 and gt == 0:
            num_false_positives += 1
        if gt == 0:
            num_negatives += 1
    if num_negatives == 0:
        return None
    fpr = num_false_positives / num_negatives
    return fpr

