def construct_tree(objects):
    tree = {}
    levels = {}

    for obj in objects:
        tree[obj['id']] = {'children': [], 'level': None}
        levels[obj['id']] = 0

    for obj in objects:
        if obj['parent_id'] is not None:
            tree[obj['parent_id']]['children'].append(obj['id'])

    def find_level(node_id):
        if node_id not in levels:
            return
        for child_id in tree[node_id]['children']:
            levels[child_id] = levels[node_id] + 1
            find_level(child_id)

    for obj in objects:
        if obj['parent_id'] is None:
            find_level(obj['id'])

    for obj in objects:
        tree[obj['id']]['level'] = levels[obj['id']]

    return tree

