import math

def distance_point_line(x1, y1, x2, y2, x, y):
    line_length = math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)
    dot_product = (x2 - x1) * (x - x1) + (y2 - y1) * (y - y1)
    if dot_product < 0:
        return math.sqrt((x1 - x) ** 2 + (y1 - y) ** 2)
    elif dot_product > line_length ** 2:
        return math.sqrt((x2 - x) ** 2 + (y2 - y) ** 2)
    projected_x = x1 + dot_product / line_length ** 2 * (x2 - x1)
    projected_y = y1 + dot_product / line_length ** 2 * (y2 - y1)
    return math.sqrt((projected_x - x) ** 2 + (projected_y - y) ** 2)

