import json

def deserialize(json_string):
    """
    Deserializes a JSON string into an equivalent Python object.
    Args:
        json_string (str): The JSON string to be deserialized.
    Returns:
        The equivalent Python object.
    """
    if not json_string:
        return None

    data = json.loads(json_string)

    def _deserialize_recursively(data):
        if isinstance(data, dict):
            return {key: _deserialize_recursively(value) for key, value in data.items()}
        elif isinstance(data, list):
            return [_deserialize_recursively(item) for item in data]
        else:
            return data

    return _deserialize_recursively(data)

