def memoized_product(lst):
    prime_product_table = {}

    def product_prime(lst):
        if not lst:
            return 1
        head, *tail = lst
        if head in prime_product_table:
            return prime_product_table[head]
        product = head * product_prime(tail)
        prime_product_table[head] = product
        return product

    for prime in lst:
        if prime in prime_product_table:
            continue
        product_prime(lst)
    return product_prime(lst)

