import numpy as np

def complex_matrix_multiply(A, B):
    N = len(A)
    if len(A) != N or len(B) != N:
        raise ValueError("Only square matrices of size N are allowed")
    C = np.empty((N, N), dtype=complex)
    for i in range(N):
        for j in range(N - 1, -1, -1):
            C[i, j] = sum(A[i, k] * B[k, j] for k in range(N))

    return C

def search(matrix, target, start=0):
    if not matrix:
        return None

    def search_in_range(matrix, target, start, end):
        if start > end:
            return None

        mid = (start + end) // 2
        row, col = divmod(mid, len(matrix[0]))

        if matrix[row][col] == target:
            return (row, col)
        elif matrix[row][col] < target:
            return search_in_range(matrix, target, mid + 1, end)
        else:
            return search_in_range(matrix, target, start, mid - 1)

    matrix_size = len(matrix) * len(matrix[0])
    return search_in_range(matrix, target, start, matrix_size - 1)

