import inspect

def extract_function_annotations(cls):
    method_names = [m for m in dir(cls) if not m.startswith('__')]
    method_annotations = {}
    for method_name in method_names:
        method = getattr(cls, method_name)
        if callable(method):
            signature = inspect.signature(method)
            args = [p.name for p in signature.parameters.values()]
            return_annotation = signature.return_annotation
            method_annotations[method_name] = {'args': args, 'return': return_annotation}
    return method_annotations

