def has_tag(xml_tree, tag_name):
    def traverse(node):
        if node.tag == tag_name:
            return True
        for child in node:
            if traverse(child):
                return True
        return False
    return traverse(xml_tree)

from functools import wraps

def function_with_keyword_arguments(fn):
    @wraps(fn)
    def wrapped_function(*args, **kwargs):
        return fn(*args, **kwargs)
    setattr(wrapped_function, '__name__', f'{fn.__name__}_{kwargs}')

    return wrapped_function

