def is_version_string_valid(version_string: str) -> bool:
    components = version_string.split('.')
    if len(components) != 3:
        return False

    for component in components:
        try:
            int_component = int(component)
        except ValueError:
            return False

        if not (0 <= int_component <= 255):
            return False

        if component != str(int_component):
            return False

    return True

def string_to_int(string_num):
    result = 0
    is_negative = string_num[0] == '-'
    if is_negative:
        start_index = 1
    else:
        start_index = 0
    for i in range(start_index, len(string_num)):
        digit = int(string_num[i])
        result = result * 10 + digit
    if is_negative:
        result = -result

    return result

