def difference_between_max_and_min(sequence):
    try:
        if len(sequence) == 0 or any(not isinstance(x, (int, float)) for x in sequence):
            raise ValueError("Invalid input: sequence must contain numeric values.")
        maximum = sequence[0]
        minimum = sequence[0]
        for value in sequence[1:]:
            if value > maximum:
                maximum = value
            if value < minimum:
                minimum = value
        return maximum - minimum

    except Exception as e:
        print(f"An error occurred: {e}")
        return None

