def cache(func):
    def new_func(*args):
        if not hasattr(func, '__cache__'):
            func.__cache__ = {}
        if args not in func.__cache__:
            func.__cache__[args] = func(*args)
        return func.__cache__[args]
    return new_func

import logging

class SingletonLogger:
    __instance = None

    def __new__(cls, name, level):
        if cls.__instance is None:
            cls.__instance = SingletonLogger.__setup_logging(name, level)
        return cls.__instance

    @staticmethod
    def __setup_logging(name, level):
        formatter = logging.Formatter("%(asctime)s - %(name)s - %(levelname)s - %(message)s")
        handler = logging.StreamHandler()
        handler.setFormatter(formatter)

        logger = logging.getLogger(name)
        logger.setLevel(level)
        logger.addHandler(handler)

        return logger

