def is_first_version_greater_or_equal(first: str, second: str) -> bool:
    first_revisions = first.split('.')
    second_revisions = second.split('.')
    if len(first_revisions) < len(second_revisions):
        first_revisions.extend(['0'] * (len(second_revisions) - len(first_revisions)))
    elif len(first_revisions) > len(second_revisions):
        second_revisions.extend(['0'] * (len(first_revisions) - len(second_revisions)))
    for first_revision, second_revision in zip(first_revisions, second_revisions):
        if int(first_revision) > int(second_revision):
            return True
        if int(first_revision) < int(second_revision):
            return False
    return False

def traverse_and_format(data):
    results = []
    for key, value in data.items():
        if isinstance(value, (list, tuple)):
            for element in value:
                results.append(f"{key}: {element}")
        elif isinstance(value, dict):
            for result in traverse_and_format(value):
                results.append(f"{key}: {result}")
        elif isinstance(value, (str, int, float)):
            results.append(f"{key}: {value}")
        else:
            raise TypeError("Value is not a list, tuple, dictionary, string, integer, or float.")
    return results

import os

def create_file(file_name, file_content, dir_path, overwrite=False):
    if not os.path.exists(dir_path):
        os.makedirs(dir_path)
    file_path = os.path.join(dir_path, file_name)
    if os.path.exists(file_path) and not overwrite:
        return f"Error: File {file_name} already exists in directory {dir_path}."
    with open(file_path, "w") as file:
        file.write(file_content)
    return f"File {file_name} created successfully in directory {dir_path}."

