import re

def get_config_type(filename: str) -> str:
    json_pattern = r'.*\.json$'
    yaml_pattern = r'.*\.yaml$'
    toml_pattern = r'.*\.toml$'
    ini_pattern = r'.*\.ini$'
    xml_pattern = r'.*\.xml$'
    csv_pattern = r'.*\.csv$'
    if re.match(json_pattern, filename):
        return 'json'
    elif re.match(yaml_pattern, filename):
        return 'yaml'
    elif re.match(toml_pattern, filename):
        return 'toml'
    elif re.match(ini_pattern, filename):
        return 'ini'
    elif re.match(xml_pattern, filename):
        return 'xml'
    elif re.match(csv_pattern, filename):
        return 'csv'
    else:
        raise ValueError("Unsupported file type")

