def find_neighbors(img, row, col):
    neighbors = []
    for i in range(max(0, row - 1), min(len(img), row + 2)):
        for j in range(max(0, col - 1), min(len(img[0]), col + 2)):
            if i == row and j == col:
                continue
            neighbors.append((i, j))
    return neighbors
def find_nearest_neighbors(img, row, col):
    if not is_valid_pixel(img, row, col):
        raise ValueError("Invalid pixel indices")
    return find_neighbors(img, row, col)

def format_timespan(seconds):
    units = ['d', 'h', 'm', 's']
    remaining = seconds
    result = []
    for unit in units:
        num_unit = remaining // 86400 if unit == 'd' else remaining // 3600 if unit == 'h' else remaining // 60 if unit == 'm' else remaining
        result.append(f"{num_unit}{unit}")
        remaining -= num_unit * 86400 if unit == 'd' else num_unit * 3600 if unit == 'h' else num_unit * 60 if unit == 'm' else num_unit
    return " ".join(result)

import functools

def print_args(num_args=1):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            print(f"Printing {num_args} arguments:")
            for i in range(num_args):
                if i < len(args):  # Check if there are enough positional arguments
                    print(f"Argument {i+1}: {args[i]}")
                elif i - len(args) in kwargs:  # Check if there are enough keyword arguments
                    print(f"Argument {i+1}: {kwargs[i - len(args)]}")
                else:
                    print(f"Argument {i+1}: Not provided")
            return func(*args, **kwargs)
        return wrapper
    return decorator

