def r2_score(predicted, true):
    if predicted is None or true is None:
        return 0
    if not isinstance(predicted, list) or not isinstance(true, list):
        return 0
    true_mean = sum(true) / len(true)
    ss_tot = sum([(y - true_mean) ** 2 for y in true])
    ss_res = sum([(y_pred - y) ** 2 for y_pred, y in zip(predicted, true)])
    r2 = 1 - (ss_res / ss_tot)
    return r2

