def convert_date_to_tuple(date_string: str) -> tuple:
    date_format = re.compile(r"(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})")
    match = date_format.match(date_string)
    if match:
        year, month, day, hour, minute, second = match.groups()
        date_time = datetime.datetime(int(year), int(month), int(day), int(hour), int(minute), int(second))
        return (date_time.year, date_time.month, date_time.day)
    else:
        raise ValueError("Invalid date string format.")

