def create_edge_queries(nodes: List[Dict[str, int]]) -> List[str]:
    """
    Creates Cypher queries for constructing edges between nodes in the given list of nodes.
    """
    queries = []
    for i, node_a in enumerate(nodes):
        for j, node_b in enumerate(nodes):
            if i < j:
                query = f"MATCH (a:Node {{id: {node_a['id']}}}), (b:Node {{id: {node_b['id']}}}) CREATE (a)-[:CONNECTED_TO]->(b)"
