def find_furthest_points(points):
    furthest_points = []
    for i in range(len(points)):
        max_dist = -np.inf
        max_dist_idx = -1
        for j in range(i):
            dist = np.linalg.norm(points[i] - points[j])
            if dist > max_dist:
