from typing import List

def binary_search_first_occurrence(haystack: List[str], needle: str) -> int:
    """
    Searches for the first occurrence of `needle` in a sorted `haystack` array.
    If `needle` is not found, the function returns -1.
    """
    haystack.sort()
    left, right = 0, len(haystack) - 1

    while left <= right:
        mid = (left + right) // 2

        if haystack[mid] < needle:
            left = mid + 1
        elif haystack[mid] > needle:
            right = mid - 1
        else:
            while mid >= 0 and haystack[mid] == needle:
                mid -= 1
            return mid + 1
    return -1

