    Computes the frequency of the most frequent element in a list of numbers.
    """
    freq_count = {}
    for num in nums:
        if num not in freq_count:
            freq_count[num] = 0
        freq_count[num] += 1
    max_freq, max_freq_num = 0, 0
    for num, freq in freq_count.items():
