import string
base64_alphabet = string.ascii_letters + string.digits + '+/'
def to_binary(text):
    return ''.join(format(ord(char), '08b') for char in text)
def pad_binary(binary_string):
    remainder = len(binary_string) % 6
    if remainder:
        binary_string += '0' * (6 - remainder)
    return binary_string
def group_binary(binary_string):
    return [binary_string[i:i+6] for i in range(0, len(binary_string), 6)]
def bin_to_char(binary_chunk):
    binary_value = int(binary_chunk, 2)
    return base64_alphabet[binary_value]
def base64_encode(text):
    binary_string = to_binary(text)
    binary_string = pad_binary(binary_string)
    binary_chunks = group_binary(binary_string)
    base64_chars = [bin_to_char(chunk) for chunk in binary_chunks]
    return ''.join(base64_chars)

