def compute_max_disagreement(nums):
    """
    Compute the maximum disagreement of a set of numbers.
    """
    if len(nums) < 2:
        raise ValueError("There must be at least two numbers to compute disagreement.")

    smallest = largest = nums[0]
    max_disagreement = 0

    for num in nums[1:]:
        if num < smallest:
            smallest = num
        elif num > largest:
            largest = num

        disagreement = max(num - smallest, largest - num)
        if disagreement > max_disagreement:
            max_disagreement = disagreement

    return max_disagreement

