import itertools

def find_combinations(numbers):
    unique_combinations = set()
    for combination in itertools.combinations(numbers, 3):
        if combination not in unique_combinations and reversed(combination) not in unique_combinations:
            unique_combinations.add(combination)
    return unique_combinations

