    if isinstance(nested_object, dict):
        for key_item in nested_object:
            if key_item == key:
                return nested_object[key_item]
            if isinstance(nested_object[key_item], (dict, list)):
                value = get_value_from_nested_object(nested_object[key_item], key)
                if value is not None:
                    return value
    elif isinstance(nested_object, list):
        for item in nested_object:
            if isinstance(item, (dict, list)):
                value = get_value_from_nested_object(item, key)
                if value is not None:
                    return value
    return None

