def group_and_sort_records(records):
    groups = {}
    for record in records:
        first, second = record
        if first in groups:
            groups[first].append(record)
        else:
            groups[first] = [record]

    for group in groups.values():
        group.sort(key=lambda rec: rec[1])

    return [record for group in groups.values() for record in group]

