def min_steps_to_climb(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 2
    steps = [0] * (n + 1)
    steps[1] = 1
    steps[2] = 2
    for i in range(3, n + 1):
        steps[i] = steps[i - 1] + steps[i - 2]
    return steps[n]

def shortest_path_sum(graph):
    row, col = len(graph), len(graph[0])
    dp = [[0] * col for _ in range(row)]
    for i in range(row):
        for j in range(col):
            if i == 0 and j == 0:
                dp[i][j] = graph[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j-1] + graph[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + graph[i][j]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + graph[i][j]
    return dp[row-1][col-1]

