def calculate_distance(color1, color2):
    color1_r, color1_g, color1_b = int(color1[0:2], 16), int(color1[2:4], 16), int(color1[4:6], 16)
    color2_r, color2_g, color2_b = int(color2[0:2], 16), int(color2[2:4], 16), int(color2[4:6], 16)
    return math.sqrt((color1_r - color2_r) ** 2 + (color1_g - color2_g) ** 2 + (color1_b - color2_b) ** 2)
def generate_colors(n, min_dist, max_tries, palette):
    colors = set()
    attempts = 0
    while len(colors) < n and attempts < max_tries:
        color = generate_color(palette)
        if all(calculate_distance(color, c) >= min_dist for c in colors):
            colors.add(color)
            attempts = 0
        else:
            attempts += 1
    return list(colors)

def bitwise_rotate(x: int, n: int) -> int:
    if not isinstance(x, int):
        raise TypeError("x must be an integer")
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    return (x << n) | (x >> (32 - n))

