def bfs_find_path(graph, start_node, target_node):
    if start_node == target_node:
        return [start_node]

    visited = set()
    queue = [[start_node]]
    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node == target_node:
            return path
        if node not in visited:
            visited.add(node)
            neighbors = adjacency_list.get(node, [])
            for neighbor in neighbors:
                new_path = list(path)
                new_path.append(neighbor)
                queue.append(new_path)
    return None

