def arithmetic_operation_matrix(matrix, scalar, operation):
    result = []
    for row in matrix:
        new_row = []
        for element in row:
            if operation == "+":
                new_row.append(element + scalar)
            elif operation == "-":
                new_row.append(element - scalar)
            elif operation == "*":
                new_row.append(element * scalar)
            elif operation == "/":
                new_row.append(element / scalar)
        result.append(new_row)
