import xml.etree.ElementTree as ET

def parse_xml_document(xml_document: str) -> dict:
    root = ET.fromstring(xml_document)
    if root.tag != 'root':
        raise ValueError("The root element must be 'root'")
    if len(root) == 0:
        raise ValueError("The 'root' element must contain at least one 'item' element")
    for item in root:
        if item.tag != 'item':
            raise ValueError(f"Invalid element '{item.tag}' found. Expected 'item'")
        if len(item) != 2:
            raise ValueError(f"The 'item' element must have exactly two child elements: 'name' and 'price'")
        if item[0].tag != 'name' or item[1].tag != 'price':
            raise ValueError(f"Invalid element '{item[0].tag}' found. Expected 'name' or '{item[1].tag}' found. Expected 'price'")
    result = {}
    for item in root:
        name = item.find('name').text
        price = item.find('price').text
        if name is None or price is None:
            raise ValueError("Both 'name' and 'price' elements must have a value")
        result[name] = int(price)

    return result

