def next_prime(S):
    max_num = max(S)  # Find the maximum number in S
    num = max_num + 1  # Increment the maximum number by 1
    while True:
        is_prime = True  # Assuming the number is prime until proven otherwise
        for i in range(2, num // 2 + 1):  # Check if num is prime
            if num % i == 0:
                is_prime = False
