def parse_queue(q):
    count_dict = {}
    lock = threading.Lock()

    while not q.empty():
        lock.acquire()
        try:
            val = q.get()
            if val in count_dict:
                count_dict[val] += 1
            else:
                count_dict[val] = 1
        finally:
            lock.release()

    return count_dict

