def binary_to_hex(binary_data: bytes) -> str:
    hex_string = []
    for byte in binary_data:
        chunk = (byte & 0xF0) >> 4
        hex_string.append(hex_lookup_table[chunk])
        chunk = (byte & 0x0F)
        hex_string.append(hex_lookup_table[chunk])
    return ''.join(hex_string)

