import re

def parse_text_output(text_output):
    process_pattern = re.compile(r"^(?P<process_id>\d+) (?P<process_name>\w+) (?P<threads>\d+)")
    thread_pattern = re.compile(r"^(?P<thread_id>\d+) (?P<thread_name>\w+)")
    processes = []
    for line in text_output.splitlines():
        match = process_pattern.match(line)
        if match:
            process = {
                "process_id": match.group("process_id"),
                "process_name": match.group("process_name"),
                "threads": [],
            }
            processes.append(process)
        else:
            match = thread_pattern.match(line)
            if match:
                thread = {
                    "thread_id": match.group("thread_id"),
                    "thread_name": match.group("thread_name"),
                }
                process["threads"].append(thread)
    return processes

