def install_and_load_packages(package_list):
    for package_name in package_list:
        try:
            importlib.import_module(package_name)
        except ModuleNotFoundError:
            try:
                pip.main(['install', package_name])
            except SystemExit:
                pass  # Ignore any errors during installation
            installed_package = importlib.import_module(package_name)
            installed_package_deps = getattr(installed_package, '__requires__', [])
            install_and_load_packages(installed_package_deps)
    for package_name in package_list:
        module = importlib.import_module(package_name)
        sys.modules[package_name] = module

