def calculate_pairwise_euclidean_distances(coordinates):
    distances = []

    for i in range(len(coordinates)):
        for j in range(i + 1, len(coordinates)):
            distance = math.sqrt((coordinates[i][0] - coordinates[j][0])**2 + (coordinates[i][1] - coordinates[j][1])**2 + (coordinates[i][2] - coordinates[j][2])**2)
            distances.append((coordinates[i], coordinates[j], distance))

    return distances

def find_subgraphs(edges):
    n = max(max(edge) for edge in edges) + 1
    parent = list(range(n))
    size = [1] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if size[root_x] < size[root_y]:
                parent[root_x] = root_y
                size[root_y] += size[root_x]
            else:
                parent[root_y] = root_x
                size[root_x] += size[root_y]
    for u, v in edges:
        union(u, v)
    subgraphs = [set() for _ in range(n)]
    for i in range(n):
        root = find(i)
        subgraphs[root].add(i)
    return [s for s in subgraphs if s]

