def matrix_mult(A, B):
    m = len(A)
    n = len(A[0])
    p = len(B[0])
    C = [[0 for j in range(p)] for i in range(m)]

    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]

    return C

