    """
    Handles key press events and returns the new index.
    """
    new_index = current_index

    if key == "down":
        new_index = min(current_index + 1, len(items) - 1)
    elif key == "up":
        new_index = max(current_index - 1, 0)
    elif key == "right":
        new_index = min(current_index + len(items) // 2, len(items) - 1)
    elif key == "left":
