import hmac

def hmac_sha256_auth(secret_key: bytes, message: bytes, digest: bytes) -> bool:
    calculated_digest = hmac.new(secret_key, message, digestmod='SHA256').hexdigest()
    if len(calculated_digest) != len(digest):
        return False
    result = 0
    for x, y in zip(calculated_digest.encode(), digest.encode()):
        result |= x ^ y
    return result == 0

