def is_connected(graph):
    for vertex in range(len(graph)):
        if len(graph[vertex]) == 0:
            return -1
    visited = [False] * len(graph)
    stack = [0]
    while stack:
        vertex = stack.pop()
        if not visited[vertex]:
            visited[vertex] = True
            stack.extend(graph[vertex])
    return all(visited)

