def calculate_manhattan_distance(points: List[Tuple[int, int]]) -> int:
    """
    Calculates the maximum Manhattan distance between any two points in the list.
    If the input list is empty or contains a single point, raises an InvalidInputError.
    """
    if len(points) < 2:
        raise InvalidInputError("Invalid input: list must contain at least two points")

    max_distance = 0

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            distance = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            max_distance = max(max_distance, distance)

    return max_distance

