import re

def validate_time_range_in_pst(time_range):
    pattern = r"^(\d{2}):(\d{2})-(\d{2}):(\d{2})$"  # Regular expression to match the time format
    match = re.match(pattern, time_range)
    if not match:
        return False
    hour_1, minute_1, hour_2, minute_2 = map(int, match.groups())
    if not (0 <= hour_1 <= 23 and 0 <= minute_1 <= 59 and 0 <= hour_2 <= 23 and 0 <= minute_2 <= 59):
        return False
    if hour_1 > hour_2 or (hour_1 == hour_2 and minute_1 >= minute_2):
        return False
    hour_1 = (hour_1 - 8) % 24  # Convert to Eastern time zone
    hour_2 = (hour_2 - 8) % 24
    if not (0 <= hour_1 <= 23 and 0 <= hour_2 <= 23):
        return False
    return True

