def covariance(x, y):
    assert len(x) == len(y), "The vectors must be of equal length"
    mean_x = sum(x) / len(x)
    mean_y = sum(y) / len(y)
    summation = 0
    for x_i, y_i in zip(x, y):
        summation += (x_i - mean_x) * (y_i - mean_y)
    return summation / (len(x) - 1)

def max_sum_non_adj(nums):
