def run_async_jobs(jobs):
    results = {}
    for job in jobs:
        p = multiprocessing.Process(target=job)
        p.start()
        results[job] = {'status': 'Running', 'process': p}
    while not all(result['status'] == 'Completed' for result in results.values()):
        for job, result in results.items():
            if result['status'] == 'Running':
