from math import sqrt

def pezcf(points):
    nearest_neighbors = []
    for i, point in enumerate(points):
        nearest_dist = float('inf')
        nearest_index = -1
        for j, other in enumerate(points):
            if i == j:
                continue
            dist = sqrt((point[0] - other[0]) ** 2 + (point[1] - other[1]) ** 2 + (point[2] - other[2]) ** 2)
            if dist < nearest_dist:
                nearest_dist = dist
                nearest_index = j
        nearest_neighbors.append((nearest_index, nearest_dist))
    pezcfs = []
    for i, (nearest_index, nearest_dist) in enumerate(nearest_neighbors):
        point = points[i]
        nearest_point = points[nearest_index]
        dist_to_point = sqrt((point[0] - nearest_point[0]) ** 2 + (point[1] - nearest_point[1]) ** 2 + (point[2] - nearest_point[2]) ** 2)
        pezcfs.append(dist_to_point / nearest_dist)
