def replace_commas_and_exclamation_points(string: str) -> str:
    """
    Replaces commas and exclamation points with periods in the input string.
    If an exclamation point follows a comma, replaces both with periods.
    """
    result = []

    for i in range(len(string)):
        if string[i] == ',':
            if i + 1 < len(string) and string[i + 1] == '!':
                result.append('.')
                i += 1
            else:
                result.append('.')
        elif string[i] == '!':
            result.append('.')
        else:
            result.append(string[i])

    return ''.join(result)

