def crop_image_array(image_array, center, half_height, half_width):
    if image_array.dtype not in [np.uint8, np.uint16]:
        raise ValueError('Unsupported image array type')

    y_min, y_max = center[0] - half_height, center[0] + half_height
    x_min, x_max = center[1] - half_width, center[1] + half_width

    if y_min < 0 or y_max > image_array.shape[0] or x_min < 0 or x_max > image_array.shape[1]:
        raise ValueError('Specified dimensions exceed the bounds of the image')

    cropped_array = image_array[y_min:y_max, x_min:x_max]

    return cropped_array

def match_with_wildcard(pattern, string):
    if pattern == string:
        return True
    if pattern == '*':
        return True
    if len(pattern) > 0 and len(string) > 0:
        if pattern[-1] == '*' and match_with_wildcard(pattern[:-1], string):
            return True
        if pattern[-1] == string[-1] and match_with_wildcard(pattern[:-1], string[:-1]):
            return True
        if pattern[-1] == '*' and match_with_wildcard(pattern, string[:-1]):
            return True
    return False

def backslash_escape(string):
