def find_nodes_with_degree_one(graph: List[List[int]]) -> List[int]:
    """
    Finds the nodes in `graph` with degree 1.
    """
    node_degrees = [0] * len(graph)
    for node in graph:
        for neighbor in node:
            node_degrees[neighbor] += 1
    return [node for node, degree in enumerate(node_degrees) if degree == 1]

