def generate_latex_table_of_contents(chapters):
    """
    Generates LaTeX code for a table of contents, given a list of chapters.

    Args:
        chapters: A list of chapters, where each chapter is represented as a tuple
            (chapter_name, page_number) or a string (if the page number is unknown).

    Returns:
        A string of LaTeX code for the table of contents.
    """
    toc_lines = []
    for index, chapter in enumerate(chapters):
        if isinstance(chapter, tuple):
            chapter_name, page_number = chapter
        else:
            chapter_name, page_number = chapter, None

        toc_line = f"\\chapter{{{chapter_name}}}"
