    latitude_parts = latitude_part[:-1].split("'")
    longitude_parts = longitude_part[:-1].split("'")
    latitude = float(latitude_parts[0]) + (float(latitude_parts[1]) / 60) + (float(latitude_parts[2]) / 3600)
    longitude = float(longitude_parts[0]) + (float(longitude_parts[1]) / 60) + (float(longitude_parts[2]) / 3600)
    if latitude_direction == 'S':
