        if i < 0 or j < 0:
            return ""
        elif s1[i] == s2[j]:
            return helper(i - 1, j - 1) + s1[i]
        else:
            return max(helper(i - 1, j), helper(i, j - 1), key=len)
    return helper(len(s1) - 1, len(s2) - 1)

import random

def quicksort_with_duplicates(arr):
    if len(arr) <= 1:
        return arr
    pivot_index = random.choice([0, len(arr) // 2, len(arr) - 1])
    pivot_count = arr.count(arr[pivot_index])
    less_than_pivot = [x for x in arr if x < arr[pivot_index]]
    equal_to_pivot = [x for x in arr if x == arr[pivot_index]]
    greater_than_pivot = [x for x in arr if x > arr[pivot_index]]
    return quicksort_with_duplicates(less_than_pivot) + equal_to_pivot + quicksort_with_duplicates(greater_than_pivot)

