def gcf(numbers):
    """
    Calculates the greatest common factor (GCF) of two or more numbers using the Euclidean algorithm.
    """
    def _gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    return reduce(_gcd, numbers)

