def lsd_radix_sort(nums):
    max_digits = len(str(max(nums)))
    sorted_nums = [0] * len(nums)
    for digit in range(max_digits):
        counts = [0] * 10
        for num in nums:
            counts[num // 10 ** digit % 10] += 1
        for i in range(1, 10):
            counts[i] += counts[i - 1]
        for i in range(len(nums) - 1, -1, -1):
            index = counts[nums[i] // 10 ** digit % 10] - 1
            sorted_nums[index] = nums[i]
            counts[nums[i] // 10 ** digit % 10] -= 1
        nums = sorted_nums.copy()

    return nums

