def validate_schema(schema):
    """
    Validates the data format of a schema object.
    The schema object is a list of dictionaries, where each dictionary represents a field in the schema.
    The function checks the following conditions:
    - Every field in the schema has a `type` key.
    - The `type` key in every field can only have the following values: `string`, `int`, or `bool`.
    - Every field in the schema has a `nullable` key.
    - The `nullable` key in every field can only have the following values: `True` or `False`.
    """
    valid_types = {"string", "int", "bool"}
    valid_nullables = {True, False}

    for field in schema:
        if "type" not in field:
            return False

        if field["type"] not in valid_types:
            return False

        if "nullable" not in field:
            return False

        if field["nullable"] not in valid_nullables:
            return False

    return True

def number_to_english(number):
    digits_to_words = {
        0: 'Zero', 1: 'One', 2: 'Two', 3: 'Three', 4: 'Four', 5: 'Five',
        6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine', 10: 'Ten', 11: 'Eleven',
        12: 'Twelve', 13: 'Thirteen', 14: 'Fourteen', 15: 'Fifteen',
        16: 'Sixteen', 17: 'Seventeen', 18: 'Eighteen', 19: 'Nineteen',
        20: 'Twenty', 30: 'Thirty', 40: 'Forty', 50: 'Fifty', 60: 'Sixty',
        70: 'Seventy', 80: 'Eighty', 90: 'Ninety'
    }

    if number < 0 or number > 9999:
        raise ValueError('Input must be between 0 and 9999 inclusive.')
    elif number < 20:
        return digits_to_words[number]
    elif number < 100:
        tens_digit = number // 10 * 10
        ones_digit = number % 10
        if ones_digit == 0:
            return digits_to_words[tens_digit]
        else:
            return f'{digits_to_words[tens_digit]} {digits_to_words[ones_digit]}'
    elif number < 1000:
        hundreds_digit = number // 100
        remainder = number % 100
        if remainder == 0:
            return f'{digits_to_words[hundreds_digit]} Hundred'
        else:
            return f'{digits_to_words[hundreds_digit]} Hundred {number_to_english(remainder)}'
    else:
        thousands_digit = number // 1000
        remainder = number % 1000
        if remainder == 0:
            return f'{digits_to_words[thousands_digit]} Thousand'
        else:
            return f'{digits_to_words[thousands_digit]} Thousand {number_to_english(remainder)}'

def is_date_valid(date_string: str) -> bool:
    if len(date_string) != 10 or date_string[4] != '-' or date_string[7] != '-':
        return False
    try:
        year = int(date_string[:4], base=10)
        month = int(date_string[5:7], base=10)
        day = int(date_string[8:], base=10)
    except ValueError:
        return False
    if year < 1000 or year > 9999:
        return False
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False
    if month == 2:  # February
        if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):  # Leap year
            return day <= 29
        else:
            return day <= 28
    elif month in [4, 6, 9, 11]:  # April, June, September, November
        return day <= 30
    else:
        return day <= 31
    return True

