def integer_square_root(n):
    lo, hi = 0, n
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        sq_mid = mid ** 2
        if sq_mid == n:
            return mid
        elif sq_mid < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

