import re

MAX_IPV4 = 2 ** 32 - 1
MAX_IPV6 = 2 ** 128 - 1

def is_valid_ipv4_or_ipv6(string: str) -> bool:
    if re.match(r'^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$', string):
        parts = string.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            value = int(part)
            if value < 0 or value > 255:
                return False
        return True
    elif re.match(r'^[0-9a-fA-F]+:[0-9a-fA-F]+:[0-9a-fA-F]+:[0-9a-fA-F]+:[0-9a-fA-F]+:[0-9a-fA-F]+:[0-9a-fA-F]+:[0-9a-fA-F]+$', string):
        parts = string.split(':')
        if len(parts) != 8:
            return False
        for part in parts:
            value = int(part, base=16)
            if value < 0 or value > MAX_IPV6:
                return False
        return True
    else:
        return False

