from abc import ABC, abstractmethod

class Series(ABC):
    @abstractmethod
    def generate(self, n):
        pass

class Fibonacci(Series):
    def generate(self, n):
        a, b = 0, 1
        for _ in range(n):
            yield a
            a, b = b, a + b

class Lucas(Series):
    def generate(self, n):
        a, b = 2, 1
        for _ in range(n):
            yield a
            a, b = b, a + b

def generate_series(n, series_type='Fibonacci'):
    if series_type == 'Fibonacci':
        series = Fibonacci()
    elif series_type == 'Lucas':
        series = Lucas()
    else:
        raise ValueError(f"Invalid series type: {series_type}")
    return list(series.generate(n))

