def detect_suspicious_activity(input_list):
    for i in range(len(input_list) - 2):
        user, ip = input_list[i][0], input_list[i][1]
        if user == input_list[i + 1][0] and user == input_list[i + 2][0] and ip == input_list[i + 1][1] and ip == input_list[i + 2][1]:
            return True  # Suspicious activity detected: User has used the same IP address three times in a row
        count = 0
        for j in range(i + 1, len(input_list)):
            if user == input_list[j][0] and ip == input_list[j][1]:
                count += 1
        if count > 3:
            return True  # Suspicious activity detected: User has used the same IP address more than three times in total

    for i in range(len(input_list) - 5):
        user, ip = input_list[i][0], input_list[i][1]
        count = 0
        for j in range(i + 1, len(input_list)):
            if user == input_list[j][0] and ip != input_list[j][1]:
