def is_valid_placement(board, row, column):
    for i in range(len(board)):
        if board[i][column] == 'Q':
            return False
    for i in range(len(board)):
        for j in range(len(board)):
            if i == row and j == column:
                continue
            if abs(i - row) == abs(j - column) and board[i][j] == 'Q':
                return False

    return True

