from typing import Optional

def is_perfect_number(num: int) -> bool:
    """
    Checks if `num` is a perfect number, i.e., a positive integer that is equal to the sum of its
    positive divisors except itself.
    """
    if not isinstance(num, int) or num <= 1:
        return False

    divisor_sum = 0
    for divisor in range(1, num // 2 + 1):
        if num % divisor == 0:
            divisor_sum += divisor

    return divisor_sum == num

import pickle
import threading

class CacheFile:
    def __init__(self, key):
        self.key = key
        self.lock = threading.Lock()

    def __enter__(self):
        self.lock.acquire()
        self.file = open(self.key, 'wb')
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.file.close()
        self.lock.release()

    def write(self, value):
        pickle.dump(value, self.file)

def synchronize_cache_access(func):
    cache_file_locks = {}

    def synchronized_func(key, value):
        with CacheFile(key) as cache_file:
            func(cache_file, value)

    def get_cache_file_lock(key):
        lock = cache_file_locks.get(key, None)
        if lock is None:
            lock = threading.Lock()
            cache_file_locks[key] = lock
        return lock

    def locked_func(key, value):
        with get_cache_file_lock(key):
            return synchronized_func(key, value)

    return locked_func

@synchronize_cache_access
def cache(cache_file, value):
    cache_file.write(value)

def bfs_path(start, target, graph):
    queue = [start]
    visited = set([start])
    while queue:
        node = queue.pop(0)
        if node == target:
            return True
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append(neighbor)
                visited.add(neighbor)
    return False

