import numpy as np

def conditional_value_assignment_and_extraction(tensor):
    new_tensor = np.empty_like(tensor)
    extracted_tensor = []

    for i in range(tensor.size):
        value = tensor.flat[i]
        if value < 0:
            new_tensor.flat[i] = 0
            extracted_tensor.append(value)
        else:
            new_tensor.flat[i] = value

    extracted_tensor = np.array(extracted_tensor, dtype=np.float32)
    return new_tensor, extracted_tensor

