def check_object_attr(obj, cls, attr):
    """
    Checks if `obj` is an instance of `cls`, and if it is, checks if it has an attribute
    named `attr`, and if it does, returns the value of that attribute. Otherwise, returns
    `None`.
    """
    if isinstance(obj, cls):
        try:
            return obj.__getattribute__(attr)
        except AttributeError:
            return None
    return None

