import math

def compute_distance(coords1, coords2):
    distance = 0
    for (x1, y1), (x2, y2) in zip(coords1, coords2):
        distance += math.sqrt((x2 - x1)**2 + (y2 - y1)**2)
    return distance

def find_second_largest(arr):
    if len(arr) < 2:
        return -1

    largest_index, largest_element = 0, arr[0]
    for i, num in enumerate(arr[1:], start=1):
        if num > largest_element:
            largest_index = i
            largest_element = num

    second_largest_index = -1
    second_largest_element = -1
    for i, num in enumerate(arr):
        if num > second_largest_element and i != largest_index:
            second_largest_index = i
            second_largest_element = num

    return second_largest_index

