def partition_odd_even(numbers):
    def helper(numbers, odd_numbers, even_numbers):
        if not numbers:
            return (odd_numbers, even_numbers)

        num = numbers[0]
        if num % 2 == 1:
            return helper(numbers[1:], odd_numbers + [num], even_numbers)
        else:
            return helper(numbers[1:], odd_numbers, even_numbers + [num])

    return helper(numbers, [], [])

