import torch

def generate_wavelet(wavelet_function, sampling_rate, length):
    time_samples = torch.arange(0, length, 1 / sampling_rate)
    if wavelet_function == "sine":
        wavelet = torch.sin(2 * torch.pi * time_samples)
    elif wavelet_function == "cosine":
        wavelet = torch.cos(2 * torch.pi * time_samples)
    elif wavelet_function == "square":
        wavelet = torch.where(time_samples % (1 / sampling_rate) < 0.5, torch.ones_like(time_samples), -torch.ones_like(time_samples))
    elif wavelet_function == "sawtooth":
        wavelet = torch.remainder(time_samples, 1 / sampling_rate) / (1 / sampling_rate) - 0.5
    elif wavelet_function == "triangle":
        wavelet = torch.abs((torch.remainder(time_samples, 1 / sampling_rate) / (1 / sampling_rate)) - 0.5) - 0.5
    elif wavelet_function == "white_noise":
        wavelet = torch.randn_like(time_samples)
    else:
        raise ValueError("Invalid wavelet function.")

    return wavelet

