def total_runtime(jobs):
    jobs = sorted(jobs, key=lambda job: job[1])
    runtime = 0
    for i, job in enumerate(jobs):
        if i == 0:
            start_time, walltime = job[1], job[2]
            end_time = start_time + walltime
        else:
            if jobs[i-1][1] <= start_time < jobs[i-1][1] + jobs[i-1][2]:
                end_time = max(end_time, start_time + walltime)
            else:
                runtime += end_time - jobs[i-1][1]
                start_time, walltime = job[1], job[2]
                end_time = start_time + walltime
    runtime += end_time - jobs[i-1][1]

    return runtime

