def power_mod(a, b, c):
    if b == 0:
        return 1 % c
    if b == 1:
        return a % c
    if b % 2 == 0:
        half = power_mod(a, b // 2, c)
        return (half * half) % c
    else:
        half = power_mod(a, b // 2, c)
        return ((half * half) % c * a) % c

