def get_nodes_data(trees, path):
    path_list = path.split('.')

    def traverse(tree, current_node, path_list):
        if current_node in tree:
            if path_list:
                next_node = path_list.pop(0)
                children = tree[current_node]
                for child in children:
                    data = traverse(child, next_node, path_list)
                    if data is not None:
                        return data
            else:
                return tree[current_node]
        return None

    for tree in trees:
        data = traverse(tree, path_list[0], path_list[1:])
        if data is not None:
            return data

def find_string_in_circular_array(string, circular_array):
    n = len(string)
    k = len(circular_array)
    if n > k:
        return -1
    i = 0
    while i < k:
        is_match = True
        for j in range(n):
            if string[j] != circular_array[(i + j) % k]:
                is_match = False
                break
        if is_match:
            return i
        i += 1
    return -1

