import re
decimal_pattern = r'^(\d+)(\.\d+)?$'
hexadecimal_pattern = r'^0x([0-9a-fA-F]+)(\.[0-9a-fA-F]+)?$'
unit_pattern = r'^(\d+\.?\d*)(cm|m|km|in)$'
units = {
    'cm': 1e-2,
    'm': 1.0,
    'km': 1e3,
    'in': 0.0254
}

def parse_number(s):
    match = re.match(decimal_pattern, s)
    if match:
        return float(match.group(1))
    match = re.match(hexadecimal_pattern, s)
    if match:
        return int(match.group(1), 16)
    match = re.match(unit_pattern, s)
    if match:
        num = float(match.group(1))
        unit = match.group(2)
        if unit in units:
            return num * units[unit]
    print(f"Warning: {s} is not a valid number")
    return None

