def special_round(num: float) -> int:
    """
    Rounds the `num` according to the following special cases:
    - If the number is negative, round the number up to the nearest integer.
    - If the number is greater than or equal to 5, round the number down to the nearest integer.
    - If the number is less than 5, round the number up to the nearest integer.
    - If the number is an integer, return the number.
    """
    try:
        if num < 0:
            return math.ceil(num)
        elif num >= 5:
            return math.floor(num)
        elif num < 5:
            return math.ceil(num)
        else:
            return num
    except Exception as e:
        print(f"Error occurred: {e}")
        return None

