def batch_sequences(sequences: List[List], batch_size: int) -> List[List[List]]:
    """
    Takes a list of sequences and a GPU batch size as arguments, and returns a list of batches,
    where each batch is a list of sequences. The sequences in each batch should have equal length.
    """
    batches = []
    current_batch = []
    current_length = 0
    for sequence in sequences:
        if len(sequence) != current_length or len(current_batch) == batch_size:
            if current_batch:
                batches.append(current_batch)
            current_batch = [sequence]
            current_length = len(sequence)
        else:
            current_batch.append(sequence)
    if current_batch:
        batches.append(current_batch)
    return batches

def find_longest_increasing_subsequence(nums):
