def huffman_code(string):
    if len(string) == 1:
        yield {string: '0'}
        return
    if len(string) == 2:
        yield {string[0]: '0', string[1]: '1'}
        return

    left, right = string[:len(string)//2], string[len(string)//2:]
    left_codes = huffman_code(left)
    right_codes = huffman_code(right)
    left_code = next(left_codes)
    right_code = next(right_codes)

    left_bit = '0'
    right_bit = '1'

    code = {}
    for char in left_code:
        code[char] = left_bit + left_code[char]
    for char in right_code:
        code[char] = right_bit + right_code[char]

    yield code

