def generate_unique_string(num):
    base26_digits = []
    while num > 0:
        digit = (num - 1) % 26
        base26_digits.append(digit)
        num = (num - 1) // 26
    base26_digits.reverse()

    str_list = []
    for digit in base26_digits:
        if digit >= 0 and digit <= 25:
            str_list.append(chr(ord('A') + digit))
        else:
            str_list.append(chr(ord('A') + digit - 26))
            str_list.append('A')
    return ''.join(str_list)

