from datetime import datetime, timedelta

def generate_time_series(start_date, end_date, interval):
    start_date = datetime.strptime(start_date, '%Y-%m-%d')
    end_date = datetime.strptime(end_date, '%Y-%m-%d')

    time_series = []
    current_date = start_date
    while current_date <= end_date:
        if interval == '1d':
            current_date = current_date.replace(hour=0, minute=0, second=0, microsecond=0)
            time_series.append(current_date)
        elif interval == '1w':
            current_date = current_date.replace(hour=0, minute=0, second=0, microsecond=0)
            time_series.append(current_date)
        elif interval == '1m':
            current_date = current_date.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            time_series.append(current_date)
        elif interval == '1y':
            current_date = current_date.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
            time_series.append(current_date)
        else:
            time_series.append(current_date)
        if interval == '1d':
            current_date += timedelta(days=1)
        elif interval == '1w':
            current_date += timedelta(weeks=1)
        elif interval == '1m':
            current_date += timedelta(days=30)
        elif interval == '1y':
            current_date += timedelta(days=365)

    return time_series

