class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text = ''

    def handle_starttag(self, tag, attrs):
        self.text += f'<{tag}>'

    def handle_endtag(self, tag):
        self.text += f'</{tag}>'

    def handle_data(self, data):
        self.text += data

    def handle_comment(self, data):
        self.text += f'<!--{data}-->'

    def get_text(self) -> str:
        return self.text

    def clear_text(self):
        self.text = ''

def extract_text(node: Union[str, HTMLParser]) -> str:
    if isinstance(node, str):
        text_extractor = TextExtractor()
        text_extractor.feed(node)
        return text_extractor.get_text()
    elif isinstance(node, HTMLParser):
        text_extractor = node
    else:
        raise ValueError("Invalid node type: expected a string or HTMLParser")

    text_extractor.clear_text()
    text_extractor.feed(node.get_data())

    return text_extractor.get_text()

def switched_case(string):
    new_string = ''
    for char in string:
        if char.islower():
            new_string += char.upper()
        elif char.isupper():
            new_string += char.lower()
        else:
            new_string += char
    return new_string

