def apply_func_to_iterable(func, iterable):
    results = []

    for element in iterable:
        argspec = inspect.getfullargspec(func)

        if 'value' in argspec.args:
            result = func(value=element)
        else:
            result = func(element)

        results.append(result)

    return results

