def prod_all_except_self(seq):
    if len(seq) <= 1:
        raise ValueError("Input sequence must have at least two elements")

    result = []
    for i, val in enumerate(seq):
        prod = 1
        for j, other_val in enumerate(seq):
            if j != i:
                prod *= other_val
        result.append(prod)
    return result

