import re

def replace_curly_braces(string, dictionary):
    """
    Replaces curly braces in a string with corresponding values from a dictionary.
    Supports nested curly braces and backslash escaping.
    """
    def replace_match(match):
        key = match.group(1)
        if "\\" in key:
            return key

        if key in dictionary:
            return str(dictionary[key])
        else:
            return match.group()

    return re.sub(r'\{(.*?)\}', replace_match, string)

def signed_integer_to_binary(signed_integer):
    if isinstance(signed_integer, int):
        if signed_integer < 0:
            absolute_value = abs(signed_integer)
            complement = 2**len(bin(absolute_value)) - 1 - absolute_value
            return bin(complement)
        else:
            return bin(signed_integer)
    else:
        raise ValueError("The input must be an integer.")

