def append_squared(input_list):
    result = []
    seen = set()
    for item in input_list:
        result.append(item)
        if item not in seen:
            result.append(item**2)
            seen.add(item)
    return result

def filter_nested_list(nested_list):
    result = []
    for element in nested_list:
        if isinstance(element, list):
            filtered_element = filter_nested_list(element)
            if filtered_element:
                result.append(filtered_element)
        else:
            if element or (isinstance(element, list) and all(not e for e in element)):
                result.append(element)
    return result

