def first_unique_char(s):
    """Find the first unique character in a given string.
    Args:
        s (str): The input string.
    Returns:
        str: The first unique character in the string, or -1 if there is no unique character.
    """
    if not s:
        return -1

    frequencies = {}
    for c in s:
        frequencies[c] = frequencies.get(c, 0) + 1

    for c in s:
        if frequencies[c] == 1:
            return c

    return -1

