import base64
import json

def rate_limit(max_msgs_per_second):
    def decorator(func):
        import time

        last_call_time = time.time()
        max_interval = 1 / max_msgs_per_second

        def wrapper(*args, **kwargs):
            nonlocal last_call_time
            now = time.time()

            if now - last_call_time < max_interval:
                elapsed_time = max_interval - (now - last_call_time)
                time.sleep(elapsed_time)

            last_call_time = now
            return func(*args, **kwargs)
        return wrapper
    return decorator


@rate_limit(max_msgs_per_second=10)
def process_pubsub_messages(messages):
    decoded_messages = []

    for message in messages:
        try:
            payload = message.data
            decoded_payload = base64.b64decode(payload).decode('utf-8')
            decoded_message = json.loads(decoded_payload)
            decoded_messages.append(decoded_message)
        except Exception as e:
            logging.error(f"Error decoding message: {e}")

    return decoded_messages

import math

def poisson_distribution(x, lambda_):
    if x < 0 or lambda_ < 0:
        raise ValueError("x and lambda must be non-negative integers.")
    if not isinstance(x, int) or not isinstance(lambda_, int):
        raise TypeError("x and lambda must be integers.")
    poisson_prob = (lambda_ ** x) * (math.e ** (-lambda_)) / math.factorial(x)

    return poisson_prob

