import json

def find_values(json_file_path, keyword):
    try:
        with open(json_file_path) as json_file:
            json_data = json.load(json_file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError("Invalid JSON file")
    results = []
    def _find_values_recursive(data):
        if isinstance(data, list):
            for element in data:
                _find_values_recursive(element)
        elif isinstance(data, dict):
            for key, value in data.items():
                if key == keyword:
                    results.append(value)
                _find_values_recursive(value)
        else:
            return
    _find_values_recursive(json_data)
    return results

def resolve_attribute(obj, attr_str):
    """
    Dynamically resolve the value of a class's method or nested class member based on a string input.
    """
    attr_names = attr_str.split('.')
    for attr_name in attr_names:
        try:
            obj = getattr(obj, attr_name)
        except AttributeError:
            raise AttributeError(f"Attribute '{attr_name}' not found on object '{obj}'.")
    return obj

def determine_frequency_band(frequency):
    frequency_bands = {
        "Very Low Band": (135, 146),
        "Low Band": (146, 180),
        "Medium Band": (180, 210),
        "High Band": (210, 270),
        "Very High Band": (270, 470)
    }
    for band, (start, end) in frequency_bands.items():
        if start <= frequency <= end:
            return band
    raise AssertionError(f"Invalid frequency: {frequency}")

def direction_to_angle(direction):
    cardinals = {"N": 0, "E": 90, "S": 180, "W": 270}
    angle_deviation = int(direction.split()[1])

    if direction.startswith("N"):
        angle = cardinals["N"] - angle_deviation
    elif direction.startswith("E"):
        angle = cardinals["E"] + angle_deviation
    elif direction.startswith("S"):
        angle = cardinals["S"] + angle_deviation
    elif direction.startswith("W"):
        angle = cardinals["W"] - angle_deviation
    else:
        raise ValueError("Invalid direction: {}".format(direction))

    return angle % 360

