def generate_permutations(string):
    if len(string) == 1:
        return [string]
    else:
        permutations = []
        for i in range(len(string)):
            remaining_string = string[:i] + string[i+1:]
            for permutation in generate_permutations(remaining_string):
                permutations.append(string[i] + permutation)
        return permutations

def are_brackets_balanced(brackets: str) -> bool:
    opening_brackets = ['(', '[']
    closing_brackets = [')', ']']
    stack = []

    for char in brackets:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or closing_brackets.index(char) != opening_brackets.index(stack[-1]):
                return False
            stack.pop()
        else:
            return False

    return len(stack) == 0

