class Graph:
    def __init__(self):
        self.nodes = []

    def add_node(self, node):
        self.nodes.append(node)

    def add_edge(self, source, dest):
        source.neighbors.append(dest)
        dest.neighbors.append(source)


def count_nodes_in_graph(graph):
    if not graph or not graph.nodes:
        return 0

    visited = set()
    queue = [graph.nodes[0]]

    while queue:
        node = queue.pop()
        if node not in visited:
            visited.add(node)
            queue.extend(node.neighbors)

    return len(visited)

