def average_edge_length(edges):
    edge_lengths = {}
    for edge in edges:
        length = edge[-1]  # Assuming the last value of each edge is its length
        edge_lengths[length] = edge_lengths.get(length, 0) + 1
    total_length = 0
    total_edges = 0
    for length, num_edges in edge_lengths.items():
        total_length += length * num_edges
        total_edges += num_edges
    return total_length / total_edges

