def split_by_pattern(string, pattern):
    if not pattern:
        return list(string)
    index = string.find(pattern)
    if index == -1:
        return [string]
    last_index = string.rindex(pattern)
    substrings = []
    start_index = 0

    while index != -1:
        substrings.append(string[start_index:index])
        start_index = index + len(pattern)
        index = string.find(pattern, start_index)
    substrings.append(string[start_index:])

    return substrings

