def build_text_lines(text, width):
    lines = []
    words = text.split()
    line = ''

    for word in words:
        if len(line) + len(word) + 1 <= width:
            line += ' ' + word
        else:
            lines.append(line.strip())
            line = word

            if len(word) > width:
                for part in word.split():
                    if len(line) + len(part) + 1 <= width:
                        line += ' ' + part
                    else:
                        lines.append(line.strip())
                        line = part

    lines.append(line.strip())

    return lines

