def search_graph(graph, property_name, property_value):
    q = []
    visited = set()
    start_node = graph[0]
    q.append(start_node)
    while q:
        node = q.pop()
        if node[property_name] == property_value:
            return node
        visited.add(node['id'])
        for neighbor_id in node['neighbors']:
            neighbor = next((n for n in graph if n['id'] == neighbor_id), None)
            if neighbor and neighbor['id'] not in visited:
                q.append(neighbor)
    return None

