def calculate_electricity_bill(usage):
    if usage <= 0:
        return 0

    if usage <= 100:
        rate = 0.10
    elif usage <= 200:
        rate = 0.08
    elif usage <= 300:
        rate = 0.06
    else:
        rate = 0.04

    total_amount = rate * usage
    return round(total_amount, 3)

