from collections import Counter

def lists_same(list1, list2):
    """
    Check if two lists have the same number of elements and the same elements, regardless of order.
    """
    counter1 = Counter(list1)
    counter2 = Counter(list2)
    if len(list1) != len(list2):
        return False
    for element, count in counter1.items():
        if counter2[element] != count:
            return False

    return True

