import numpy as np

def construct_transition_matrix(graph):
    adjacency_matrix = np.zeros((len(graph), len(graph)))
    for i in range(len(graph)):
        for j in range(len(graph[i])):
            if graph[i][j] > 0:
                adjacency_matrix[i][j] = 1
    degree_matrix = np.sum(adjacency_matrix, axis=1)
    normalized_edge_weights = adjacency_matrix / np.sqrt(degree_matrix[:, None] * degree_matrix[None, :])
    transition_matrix = normalized_edge_weights / np.sum(normalized_edge_weights, axis=1)[:, None]
    alpha = 0.1 # Adjust as needed
    transition_matrix += alpha / len(graph)

    return transition_matrix

