def transform_dict_keys(dicts, keys):
    """
    Transforms a list of dictionaries to a list of dictionaries with different keys.
    The new keys are the values of the original dictionaries' keys and the values are 1
    if the original dictionary contains a key matching the name of the new label and 0 otherwise.
    """
    transformed = []

    for d in dicts:
        transformed_dict = {}
        for k in d.keys():
            transformed_dict[k] = 0
            if k in keys:
                transformed_dict[k] = 1
        transformed.append(transformed_dict)

    return transformed

