import numpy as np

def gaussian(x, mean, std):
    return (1 / (std * np.sqrt(2 * np.pi))) * np.exp(-((x - mean)**2 / (2 * (std**2))))

def bayes_classifier(x, data):
    classes = len(np.unique(data[:, 1]))
    class_probs = np.zeros(classes)
    for i in range(classes):
        class_data = data[data[:, 1] == i]
        mean = np.mean(class_data[:, 0])
        std = np.std(class_data[:, 0])
        class_probs[i] = gaussian(x, mean, std)
    return np.argmax(class_probs)

