def encode_binary_to_decimal(binary_string):
    result = 0
    binary_string = binary_string.strip()

    if binary_string[0] == '-':
        sign = -1
        binary_string = binary_string[1:]
    else:
        sign = 1

    for i, char in enumerate(binary_string[::-1]):
        result += int(char) * 2**i

    return result * sign

