def extract_data(structure, keys, index=0):
    if index == len(keys):
        return structure
    elif isinstance(structure, dict) and keys[index] in structure:
        structure = structure[keys[index]]
        index += 1
    elif isinstance(structure, list) and isinstance(keys[index], int):
        structure = structure[keys[index]]
        index += 1
    else:
        return None

    try:
        return extract_data(structure, keys, index)
    except Exception as e:
        raise e

