def calculate_power(base, exponent):
    if exponent == 0:
        return 1
    if exponent % 2 == 0:
        return calculate_power(base * base, exponent // 2)
    else:
        return base * calculate_power(base, exponent - 1)

def power_function(base, exponent):
    result = calculate_power(base, exponent)
    if exponent < 0:
        return 1 / result
    return result

