import hashlib

def hash_image(filepath):
    md5 = hashlib.md5()
    chunk_size = 1024
    with open(filepath, 'rb') as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            md5.update(chunk)
    return md5.hexdigest()

