import math

def degrees_to_radians(func):
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        return math.radians(result)
    wrapper.__doc__ = f"Convert the input angle from degrees to radians. {func.__doc__}"
    return wrapper

