import random

def random_chromosomes_crossover(chromosomes):
    length = len(chromosomes[0])
    for chromosome in chromosomes[1:]:
        if len(chromosome) != length:
            raise ValueError("Chromosomes must be of the same length.")

    crossover_point = random.randint(0, length - 1)
    return [chromosome[:crossover_point] + chromosome[crossover_point:].replace('A', 'B').replace('B', 'A') for chromosome in chromosomes]

import numpy as np

def find_first_integer(array, integer):
    if not isinstance(array, np.ndarray):
        raise TypeError("Invalid input: array must be a numpy array.")
    if not isinstance(integer, int):
        raise TypeError("Invalid input: integer must be an integer.")
    indices = np.where(array == integer)[0]
    if len(indices) == 0:
        return None
    index = indices[0]
    count = np.count_nonzero(array == integer)
    return (index, count)

