def compute_maf(matrix):
    """
    Computes the minor allele frequency (MAF) for each site in the given matrix.
    The matrix should have two columns (alleles) for each site (row).

    The minor allele frequency is the frequency of the second most common allele.
    """
    if not matrix:
        raise ValueError("Invalid input matrix. Matrix should have at least one row.")

    mafs = []

    for allele_counts in matrix:
        if len(allele_counts) != 2:
            raise ValueError("Invalid input matrix. Each site should have two columns.")
        allele_freqs = {0: 0, 1: 0, 2: 0}
        for allele in allele_counts:
            allele_freqs[allele] += 1
        allele_freqs_sorted = sorted(allele_freqs.values(), reverse=True)
        maf = allele_freqs_sorted[1] / sum(allele_freqs_sorted)
        mafs.append(maf)

    return mafs

