def evaluate_logical_expression(expression):
    operators = {
        "!": lambda x: not x,
        "&&": lambda x, y: x and y,
        "||": lambda x, y: x or y
    }
    def evaluate_subexpression(subexpression):
        operator = subexpression[1]
        operands = [evaluate_subexpression(operand) for operand in subexpression[2:]]
        return operators[operator](*operands)
    try:
        return evaluate_subexpression(eval(expression))
    except:
        return False

