def find_slot(num, intervals):
    if num < intervals[0][0] or num > intervals[-1][1]:
        return 0
    low = 0
    high = len(intervals) - 1
    while low <= high:
        mid = (low + high) // 2
        if intervals[mid][0] <= num <= intervals[mid][1]:
            return mid
        elif num < intervals[mid][0]:
            high = mid - 1
        else:
            low = mid + 1
    return 0
