def prefix_to_infix(prefix_formula, lookup_table):
    if prefix_formula[0] == 'v':
        return '(' + prefix_to_infix(prefix_formula[1], lookup_table) + ' v ' + prefix_to_infix(prefix_formula[2], lookup_table) + ')'
    elif prefix_formula[0] == '->':
        return '(' + prefix_to_infix(prefix_formula[1], lookup_table) + ' -> ' + prefix_to_infix(prefix_formula[2], lookup_table) + ')'
    elif prefix_formula[0] == 'X':
        return 'X' + prefix_to_infix(prefix_formula[1], lookup_table)
    elif prefix_formula[0] == 'F':
        return 'F' + prefix_to_infix(prefix_formula[1], lookup_table)
    elif prefix_formula[0] == 'G':
        return 'G' + prefix_to_infix(prefix_formula[1], lookup_table)
    elif prefix_formula[0] == '~':
        return '~' + prefix_to_infix(prefix_formula[1], lookup_table)
    elif prefix_formula[0] == 'U':
        return '(' + prefix_to_infix(prefix_formula[1], lookup_table) + ' U ' + prefix_to_infix(prefix_formula[2], lookup_table) + ')'
    elif prefix_formula[0] == '&':
        return '(' + prefix_to_infix(prefix_formula[1], lookup_table) + ' & ' + prefix_to_infix(prefix_formula[2], lookup_table) + ')'
    else:
        return lookup_table[prefix_formula]

class InvalidNumberSequence(Exception):
