def check_number_sequence(numbers):
    if not numbers:
        raise InvalidNumberSequence("The number array is empty.")

    num_ones = 0
    for i, n in enumerate(numbers):
        if n == 0:
            if i > 0 and numbers[i - 1] == 1:
                num_ones += 1
            else:
                raise InvalidNumberSequence("A 0 must be preceded by a 1.")
        elif n == 1:
            num_ones += 1
        else:
            raise InvalidNumberSequence("Each element must be either 0 or 1.")

    if num_ones % 2 != 0:
        raise InvalidNumberSequence("The number of 1s must be even.")

    return True

def process_instructions(memory, input_instructions):
    relative_base = 0
    ip = 0
    while ip < len(memory):
        instruction = memory[ip]
        opcode = instruction % 100
        parameter_modes = instruction // 100
        if opcode == 1:
            if parameter_modes % 10 == 0:
                param1 = memory[memory[ip + 1]]
            elif parameter_modes % 10 == 1:
                param1 = memory[ip + 1]
            elif parameter_modes % 10 == 2:
                param1 = memory[memory[ip + 1] + relative_base]
            if parameter_modes // 10 % 10 == 0:
                param2 = memory[memory[ip + 2]]
            elif parameter_modes // 10 % 10 == 1:
                param2 = memory[ip + 2]
            elif parameter_modes // 10 % 10 == 2:
                param2 = memory[memory[ip + 2] + relative_base]
            if parameter_modes // 100 % 10 == 0:
                output_address = memory[ip + 3]
            elif parameter_modes // 100 % 10 == 2:
