def is_balanced(brackets):
    stack = []

    for char in brackets:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack or not is_matching(stack[-1], char):
                return False
            else:
                stack.pop()

    return len(stack) == 0

