def generate_paths(root):
    paths = []

    def dfs(node, path):
        if not node.left and not node.right:
            paths.append(path)
        else:
            if node.left:
                dfs(node.left, path + [node.left.val])
            if node.right:
                dfs(node.right, path + [node.right.val])

    dfs(root, [root.val])
    return paths

