    assert len(date_components) == 3, "Invalid number of date components"

    time_components = components[1].split(":")
    assert len(time_components) == 3, "Invalid number of time components"
    year, month, day = map(int, date_components)
    hour, minute, second = map(int, time_components)

    assert 1000 <= year <= 9999, "Invalid year"
    assert 1 <= month <= 12, "Invalid month"
    assert 1 <= day <= 31, "Invalid day"
    assert 0 <= hour <= 23, "Invalid hour"
    assert 0 <= minute <= 59, "Invalid minute"
