import os

def check_disk_usage(directory_path, threshold):
    disk_usage = os.path.getsize(directory_path)

    if disk_usage > threshold:
        files = os.listdir(directory_path)
        files.sort(key=os.path.getmtime)
        for file in files[:len(files) // 2]:
            os.remove(os.path.join(directory_path, file))

        print(f"Deleted files to free up space in '{directory_path}'.")
    else:
        print(f"No need to delete files in '{directory_path}', disk usage is okay.")

