def average_field_value(objects: List[dict], field_name: str) -> int:
    """
    Returns the average value of the specified field, converted to int type.
    If any objects in the array do not have the specified field name, return None.
    """
    field_values = [obj[field_name] for obj in objects if field_name in obj]

    if not field_values:
        return None
    if all(isinstance(value, int) for value in field_values):
        return int(sum(field_values) / len(field_values))
    field_values = [int(value) if not isinstance(value, int) else value for value in field_values]

    return int(sum(field_values) / len(field_values))

