import re

def most_frequent_error_code(log_file):
    error_codes = {}
    with open(log_file, 'r') as f:
        for line in f:
            match = re.search(r'\[ERROR\] \[(\d{3})\]', line)
            if match:
                error_code = match.group(1)
                error_codes[error_code] = error_codes.get(error_code, 0) + 1

    most_common = max(error_codes.values())
    return min(error_code for error_code, count in error_codes.items() if count == most_common)

def generate_sequence(start: int, step: int):
