def construct_type_hint(schema: Union[str, dict]) -> str:
    if isinstance(schema, str):
        with open(schema, 'r') as f:
            schema = json.load(f)

    if schema['type'] == 'object':
        properties = schema['properties']
        type_hint = 'dict['
        for key, value in properties.items():
            type_hint += f"'{key}': "
            if value['type'] in ['string', 'number']:
                type_hint += value['type']
            else:
                type_hint += construct_type_hint(value)
            type_hint += ', '
        type_hint = type_hint[:-2] + ']'
    elif schema['type'] == 'array':
        item_type = schema['items']['type']
        if item_type in ['string', 'number']:
            type_hint = f'list[{item_type}]'
        else:
            type_hint = f'list[{construct_type_hint(schema["items"])}]'
    else:
        type_hint = schema['type']
    return type_hint

