class TrieNode:
    def __init__(self):
        self.children = {}
        self.end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, string):
        node = self.root
        for char in string:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.end = True

def longest_common_substring(strings):
    trie = Trie()
    for string in strings:
        trie.insert(string)
    node = trie.root
    result = []  # Store the longest common substring
    while node and len(node.children) == 1:
        char = next(iter(node.children))  # Get the first character of the child node
        result.append(char)
        node = node.children[char]

    return "".join(result)

def match_recursive(pattern, event_type):
    if not pattern:
        return True
    if len(pattern) > len(event_type):
        return False

    if pattern[0] == "*":
        return match_recursive(pattern[1:], event_type) or match_recursive(pattern, event_type[1:])
    else:
        return pattern[0] == event_type[0] and match_recursive(pattern[1:], event_type[1:])

def match_events(events, event_types):
    if not events:
        raise ValueError("Input events cannot be empty")

    matched_events = []
    for event in events:
        event_type = event["event_type"]
        for event_pattern in event_types:
            if match_recursive(event_pattern, event_type):
                matched_events.append(event)
                break
    return matched_events

def first_greater_or_equal(array, target):
    left, right = 0, len(array) - 1
    while left <= right:
        mid = (left + right) // 2
        if array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

