def find_values(dictionary, key):
    values = []

    if isinstance(dictionary, dict):
        for k, v in dictionary.items():
            if k == key:
                values.append(v)

            values.extend(find_values(v, key))

    elif isinstance(dictionary, list):
        for item in dictionary:
            values.extend(find_values(item, key))

    return values

import torch

def split_tensor_contiguous(tensor: torch.Tensor, chunk_size: int) -> torch.Tensor:
    num_chunks = tensor.size(0) // chunk_size

    chunks = []
    for i in range(num_chunks):
        chunk = tensor.narrow(0, i * chunk_size, chunk_size)
        chunks.append(chunk)

    return torch.stack(chunks)

def string_transformer(string):
    transformed_string = ''

    for char in string:
        if char.islower():
            transformed_string += char.upper()
        elif char.isupper():
            transformed_string += char.lower()
        elif char.isdigit():
            transformed_string += '*'
        else:
            transformed_string += char

    return transformed_string.format(string)

