def augment_matrix(matrix, bits):
    if not isinstance(matrix, list) or not isinstance(bits, list) or \
       not isinstance(matrix[0], list) or not isinstance(bits[0], list):
        raise TypeError("Both matrix and bits must be lists.")

    if len(matrix) != len(bits):
        raise ValueError("The length of matrix and bits must be equal.")

    for i in range(len(matrix)):
        if len(matrix[i]) != len(bits[i]):
            raise ValueError("The length of each row in matrix and bits must be equal.")

    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            matrix[i][j] += bits[i][j]

    return matrix

