def is_valid_ipv4(ip):
    octets = ip.split('.')
    if len(octets) != 4:
        return False
    for octet in octets:
        if not octet.isdigit() or int(octet) < 0 or int(octet) > 255:
            return False
    return True

def is_valid_ipv6(ip):
    hexes = ip.split(':')
    if len(hexes) != 8:
        return False
    for hex in hexes:
        if not all(c in "0123456789abcdefABCDEF" for c in hex):
            return False
    return True

def is_valid_ip_address(ip):
