import xml.etree.ElementTree as ET

def xml_to_dict(xml_file_path):
    tree = ET.parse(xml_file_path)
    root = tree.getroot()
    def convert_element_to_dict(element):
        if len(element) == 0:
            return element.text

        return {element.tag: {
            child.tag: convert_element_to_dict(child)
            for child in element
        }}
    dict_data = convert_element_to_dict(root)

    return dict_data

