def calculate_false_positive_rate(probabilities):
    false_positives = 0
    threshold = 0.5

    for probability in probabilities:
        if probability > threshold:
            false_positives += 1

    false_positive_rate = false_positives / len(probabilities)

    return false_positive_rate

import re

def check_valid_graph(string):
    if not string.startswith('[') or not string.endswith(']'):
        return False
    if not string[1:]:
        return False
    pairs = re.findall(r'\(\d+,\d+\)', string)
    for pair in pairs:
        nums = pair[1:-1].split(',')
        if not all(num.isdigit() for num in nums):
            return False
        if any(int(num) <= 0 for num in nums):
            return False
    seen_nums = set()
    for pair in pairs:
        nums = pair[1:-1].split(',')
        if tuple(int(num) for num in nums) in seen_nums:
            return False
        seen_nums.add(tuple(int(num) for num in nums))
    edges = []
    for pair in pairs:
        nums = pair[1:-1].split(',')
        edges.append((int(nums[0]), int(nums[1]), int(nums[0]) + int(nums[1])))

    return edges

