def clean_string(string):
    string = string.strip()  # Remove leading and trailing whitespace
    if string.startswith('"') and string.endswith('"'):
        string = string[1:-1]  # Remove double quotes
    elif string.startswith("'") and string.endswith("'"):
        string = string[1:-1]  # Remove single quotes
    elif string.startswith('"') and string.endswith("'"):
        string = string[1:-1]  # Remove both double and single quotes
    string = string.replace("'", "").replace('"', "")  # Remove single and double quotes
    return string


