def process_text_data(file_path):
    word_counts = {}
    with open(file_path, 'r') as f:
        for line in f:
            words = line.split()
            for word in words:
                word = re.sub("[^A-Za-z']+", '', word)
                if word in word_counts:
                    word_counts[word] += 1
                else:
                    word_counts[word] = 1

    return word_counts

def phone_number_format(phone_number):
    phone_number = ''.join([c for c in phone_number if c.isnumeric()])
    if len(phone_number) != 10:
        return 'Invalid phone number'
    area_code = phone_number[:3]
    exchange_code = phone_number[3:6]
    subscriber_number = phone_number[6:]
    return '-'.join([area_code, exchange_code, subscriber_number])

