def is_valid_ipv4_address(ip_address: str) -> bool:
    parts = ip_address.split('.')

    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False

        num = int(part)
        if not 0 <= num <= 255:
            return False

    return True

