def validate_dict(dict_val, schema):
    if isinstance(schema, type):
        return isinstance(dict_val, schema)
    if isinstance(schema, dict):
        if not isinstance(dict_val, dict):
            return False
        for key, value in schema.items():
            if key not in dict_val:
                return False
            if not validate_dict(dict_val[key], value):
                return False
        return True
    if isinstance(schema, list):
        if not isinstance(dict_val, list):
            return False
        for element in dict_val:
            if not validate_dict(element, schema[0]):
                return False
        return True

