def get_case_params(config_obj):
    case_params = {}
    if 'case_type' not in config_obj:
        raise ValueError("Configuration object must have a 'case_type' attribute.")

    case_type = config_obj['case_type']
    if case_type == 'A':
        if 'param_a' in config_obj and config_obj['param_a'] == '1':
            case_params['param_a'] = config_obj['param_a']
        if 'param_b' in config_obj and config_obj['param_b'] == '2':
            case_params['param_b'] = config_obj['param_b']
    elif case_type == 'B':
        if 'param_c' in config_obj and config_obj['param_c'] == '3':
            case_params['param_c'] = config_obj['param_c']
        if 'param_d' in config_obj and config_obj['param_d'] == '4':
            case_params['param_d'] = config_obj['param_d']
    else:
        raise ValueError("Unsupported case type.")

    return case_params

