def get_all_leaf_nodes(tree: dict) -> set:
    """
    Traverses a tree represented in a nested dictionary structure, where the keys
    represent node labels and the values are a list of adjacent nodes. Returns
    all leaf nodes (nodes with no child nodes) in the tree as a set.
    """
    all_leaf_nodes = set()

    def traverse(node):
        if not tree.get(node):
            all_leaf_nodes.add(node)
        else:
            for child in tree[node]:
                traverse(child)

    traverse(list(tree.keys())[0])
    return all_leaf_nodes

