def validate_dictionary(dictionary: dict) -> None:
    """
    Validates a dictionary by checking the presence of a top-level `metadata` key that is a dictionary.
    If the `metadata` dictionary does not contain a `version` key, a `MissingFieldError` is raised.
    If the `metadata` dictionary contains a `version` key but is not a non-empty string, an `InvalidFieldError` is raised.
