    graph = {obj: [] for obj in objects}
    for src, dst in edges:
        graph[src].append(dst)
    visited = set()
    stack = [objects[0]]
    while stack:
        curr = stack.pop()
        if curr not in visited:
            visited.add(curr)
            stack.extend(graph[curr])
    return [(obj, obj) for obj in visited]

