def is_same_side(x1, y1, x2, y2, px, py):
    if px == x1 and py == y1 or px == x2 and py == y2:
        return True
    v1 = (x2 - x1, y2 - y1)
    v2 = (px - x1, py - y1)
    cross_product = v1[0] * v2[1] - v1[1] * v2[0]
    if cross_product == 0:
        return True
    elif cross_product > 0:
        return True
    else:
        return False

