class LogConstructorArguments(type):
    def __new__(cls, name, bases, attrs):
        def log_arguments(*args, **kwargs):
            class_name = get_class_name(cls)
            log_file = class_name + '.log'
            with open(log_file, 'a') as f:
                f.write(str(args) + '\n')
                f.write(str(kwargs) + '\n')

        attrs['__init__'] = log_arguments
        return super(LogConstructorArguments, cls).__new__(cls, name, bases, attrs)

