def apply_projection(physical_state, projection_rules):
    """Applies a projection function to the physical state and returns the strategic-tactical state.

    Args:
        physical_state (dict): A dictionary representing the physical state, with keys as concepts and values as their values.
        projection_rules (dict): A dictionary of rules for projection, with keys as physical concepts and values as their corresponding strategic concepts.

    Returns:
        dict: The strategic-tactical state, which is a dictionary with pruned key-value pairs based on the projection function and rules.
    """
    strategic_state = {}
    for physical_concept, strategic_concept in projection_rules.items():
        if physical_concept in physical_state:
            strategic_state[strategic_concept] = physical_state[physical_concept]
    return strategic_state

def prune_projection(strategic_state, pruning_rules):
    """Prunes the strategic-tactical state based on a set of pruning rules.

    Args:
        strategic_state (dict): The strategic-tactical state, which is a dictionary with pruned key-value pairs based on the projection function and rules.
        pruning_rules (dict): A dictionary of rules for pruning, with keys as strategic concepts and values as their corresponding pruning conditions.

    Returns:
        dict: The pruned strategic-tactical state, which is a dictionary with pruned key-value pairs based on the pruning rules.
    """
    pruned_state = {}
    for strategic_concept, condition in pruning_rules.items():
        if strategic_concept in strategic_state and condition(strategic_state[strategic_concept]):
            pruned_state[strategic_concept] = strategic_state[strategic_concept]
    return pruned_state

