import functools
import warnings

def package_warn_once(allowed_packages):
    def decorator(func):
        @functools.wraps(func)
        @functools.lru_cache(maxsize=None)
        def wrapped(*args, **kwargs):
            if func.__module__ not in allowed_packages:
                warnings.warn(
                    f"Function {func.__name__} is not allowed to be called by the package {func.__module__}.",
                    category=UserWarning,
                )
            return func(*args, **kwargs)
        return wrapped
    return decorator

from typing import List

def two_sum_hash_map(nums: List[int], target: int) -> List[int]:
    """
    Finds indices of two numbers in `nums` that add up to `target` using a hash map.
    """
    num_index_map = {}

    for i, num in enumerate(nums):
        complement = target - num

        if complement in num_index_map:
            return [num_index_map[complement], i]
        else:
            num_index_map[num] = i

    return []

