def project_intervals(intervals, interval):
    projected_intervals = []
    for start, end in intervals:
        if start < interval[1] and end > interval[0]:
            start = max(start, interval[0])
            end = min(end, interval[1])
            projected_intervals.append((start, end))

    return projected_intervals

