import numpy as np

def convert_1d_to_2d(array, num_rows, num_columns):
    num_items = len(array)
    if num_items % (num_rows * num_columns) != 0:
        padded_array = np.pad(array, (0, num_rows * num_columns - num_items), constant_values=(np.nan,))
    else:
        padded_array = array
    return np.reshape(padded_array, (num_rows, num_columns))

