def compute_shorthand(string):
    if len(string) <= 3:
        return string

    shorthand = ""
    counter = 1
    for i in range(len(string) - 1):
        if string[i] == string[i + 1]:
            counter += 1
        else:
            shorthand += string[i] + str(counter)
            counter = 1

    if string[-1] not in shorthand:
        shorthand += string[-1] + str(counter)

    return shorthand

