def format_string(string, dictionary):
    def interpolate(string, dictionary):
        for key, value in dictionary.items():
            if isinstance(value, str):
                string = string.replace("{" + key + "}", "\x1b[32m" + value + "\x1b[0m")
            else:
                string = string.replace("{" + key + "}", "\x1b[32m" + str(value) + "\x1b[0m")
        return string

    def sprintf(string, dictionary):
        for key, value in dictionary.items():
            if isinstance(value, str):
                string = string.replace("{" + key + "}", "\x1b[32m" + value + "\x1b[0m")
            else:
                string = string.replace("{" + key + "}", "\x1b[32m" + str(value) + "\x1b[0m")
        return string

    if "{" in string:
        return interpolate(string, dictionary)
    else:
        return sprintf(string, dictionary)

