def get_version_classification(version_str: str) -> str:
    major_version_pattern = r"^\d+\.\d+\.\d+$"
    minor_version_pattern = r"^\d+\.\d+$"
    patch_version_pattern = r"^\d+$"
    if re.match(major_version_pattern, version_str):
        return "major"
    elif re.match(minor_version_pattern, version_str):
        return "minor"
    elif re.match(patch_version_pattern, version_str):
        return "patch"
    else:
        return "invalid"

