import re

def check_api(code):
    func_pattern = r"def\s+(\w+)\((.*)\):"
    match = re.search(func_pattern, code, re.DOTALL)
    if not match:
        raise SyntaxError("Invalid function signature")
    func_name, args = match.groups()
    arg_names = args.split(",")
    if len(arg_names) == 1 and arg_names[0].strip() == '':
        arg_names = []
    doc_pattern = r"'''(.*?)'''"
    match = re.search(doc_pattern, code, re.DOTALL)
    if not match:
        return False
    docstring = match.group(1)
    sections = docstring.split("\n\n")
    section_names = ["Description", "Parameters", "Returns", "Raises"]
    expected_sections = dict(zip(section_names, [""] * len(section_names)))
    for section in sections:
        header, content = section.split("\n", 1)
        if header in section_names:
            expected_sections[header] = content
    param_pattern = r"- (\w+):(.*)"
    for param, description in re.findall(param_pattern, expected_sections["Parameters"]):
        if param not in arg_names:
            return False
    raise_pattern = r"- (\w+):(.*)"
    for exc, description in re.findall(raise_pattern, expected_sections["Raises"]):
        try:
            eval(exc)
        except NameError:
            return False

    return True

