def convert_to_objects(string):
    objects = []
    parts = string.split(',')

    for part in parts:
        type, value = part.split(':')

        if type == 's':
            value = value
        elif type == 'i':
            value = int(value)
        elif type == 'b':
            value = value == 'true'
        else:
            raise ValueError('Invalid type')

        objects.append({'type': type, 'value': value})

    return objects

