def write_geojson(coordinates, file_path):
    """
    Write a GeoJSON feature collection to a file.

    Args:
        coordinates (list): A list of coordinates to be written as GeoJSON.
        file_path (str): The path of the file to write the GeoJSON to.
    """
    features = []

    for coordinate in coordinates:
        feature = {
            "type": "Feature",
            "geometry": {
                "type": "Point",
                "coordinates": coordinate
            }
        }
        features.append(feature)

    feature_collection = {
        "type": "FeatureCollection",
