def thermal_conduction(dimensions, thermal_conductivity, thermal_conductivity_unit, temperature_difference, temperature_difference_unit):
    if thermal_conductivity_unit == 'BTU/hr-ft-R':
        thermal_conductivity *= 0.173073  # Convert BTU/hr-ft-R to W/m-K
    elif thermal_conductivity_unit == 'cal/s-cm-C':
        thermal_conductivity *= 4.1868  # Convert cal/s-cm-C to W/m-K
    if temperature_difference_unit == 'K':
        temperature_difference -= 273.15  # Convert Kelvin to Celsius
    elif temperature_difference_unit == 'R':
