        return '-' + convert_to_roman_numerals(-num)

    if num >= 1000:
        return 'M' + convert_to_roman_numerals(num - 1000)

    if num >= 900:
        return 'CM' + convert_to_roman_numerals(num - 900)

    if num >= 500:
        return 'D' + convert_to_roman_numerals(num - 500)

    if num >= 400:
        return 'CD' + convert_to_roman_numerals(num - 400)

    if num >= 100:
        return 'C' + convert_to_roman_numerals(num - 100)

    if num >= 90:
        return 'XC' + convert_to_roman_numerals(num - 90)

    if num >= 50:
        return 'L' + convert_to_roman_numerals(num - 50)

    if num >= 40:
        return 'XL' + convert_to_roman_numerals(num - 40)

    if num >= 10:
        return 'X' + convert_to_roman_numerals(num - 10)

    if num >= 9:
        return 'IX' + convert_to_roman_numerals(num - 9)

    if num >= 5:
