def compute_conditional_probability(p, q, k):
    if not all([elem > 0 for elem in p]) or not all([elem > 0 for elem in q]):
        raise Exception("All elements of p and q must be positive.")
    if sum(p) != 1:
        raise Exception("The sum of elements in p must be 1.")
    if sum(q) != 1:
        raise Exception("The sum of elements in q must be 1.")
    if k < 0 or k >= len(p):
        raise Exception("k must be between 0 and len(p) - 1.")

    numerator = q[k] * p[k]
    denominator = sum([q[i] * p[i] for i in range(len(p))])
    conditional_probability = numerator / denominator

    return conditional_probability

