def get_water_velocity(depth: float, temperature: float, constant_flag: int) -> float:
    """
    Returns the water velocity based on the depth, temperature, and constant flag.
    """
    if constant_flag == 1:
        a, b1, b2, b3 = (0.0042, 0.0001, -0.0000012, 0.000000002)
        z1_min, z1_max = (0.00002, 0.00003)
        z2_min, z2_max = (0.00004, 0.00005)
    elif constant_flag == 2:
        a, b1, b2, b3 = (0.0042, 0.0001, -0.000001, 0.000000001)
        z1_min, z1_max = (0.00002, 0.00003)
        z2_min, z2_max = (0.00004, 0.00005)
    else:
        raise ValueError("Invalid constant flag.")
    if z1_min <= depth <= z1_max:
        z = z1_min
    elif z2_min <= depth <= z2_max:
        z = z2_min
    else:
        raise ValueError("Depth not within applicable range.")
    return a + b1 * z + b2 * z ** 2 + b3 * z ** 3

