from typing import List

def calculate_minimal_edit_distance(s1: str, s2: str) -> int:
    """
    Calculates the minimal edit distance between s1 and s2. The edit distance
    is defined as the minimum number of single-character insertions, deletions,
    and substitutions required to transform one string into the other.
    """
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1

    return dp[m][n]

