from typing import List, Tuple

def detect_cycles(edges: List[Tuple[int, int]]) -> bool:
    """
    Detect cycles in a directed graph given a list of edges.
    Returns True if there is a cycle, otherwise False.
    """
    adj_list = [[] for _ in range(len(edges) + 1)]
    for u, v in edges:
        adj_list[u].append(v)
    visited = [False] * (len(edges) + 1)
    rec_stack = [False] * (len(edges) + 1)
    def dfs(u: int) -> bool:
        visited[u] = True
        rec_stack[u] = True

        for v in adj_list[u]:
            if not visited[v]:
                if dfs(v):
                    return True
            elif rec_stack[v]:
                return True

        rec_stack[u] = False
        return False
    for u in range(1, len(edges) + 1):
        if not visited[u]:
            if dfs(u):
                return True

    return False

