def lagrange_interpolation(x_arr, y_arr, x):
    n = len(x_arr)
    if n == 1:
        return y_arr[0]

    y = 0
    for i in range(n):
        product = 1
        for j in range(n):
            if i != j:
                product *= (x - x_arr[j]) / (x_arr[i] - x_arr[j])
        y += y_arr[i] * product

    return y

