from decimal import getcontext, Decimal
getcontext().prec = 100

def cube_root(num: Decimal, precision: int) -> Decimal:
    current_guess = Decimal(1)
    num_decimal = Decimal(num)
    def f(x):
        return x ** 3 - num_decimal

    def derivative(x):
        return 3 * x ** 2

    while True:
        new_guess = current_guess - f(current_guess) / derivative(current_guess)
        if abs(new_guess - current_guess) < Decimal(10) ** -precision:
            break
        current_guess = new_guess

    return current_guess.quantize(Decimal(10) ** -precision)

