def depth_first_traversal(root):
    """Traverses a binary tree in a depth-first manner using an explicit stack."""
    if not root:
        return []

    stack = [root]
    results = []

    while stack:
        node = stack.pop()
        results.append(node.val)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)

    return results

