def fraction_operation(num1, num2, operation):
    num1_parts = num1.split("/")
    num1_numerator = int(num1_parts[0])
    num1_denominator = int(num1_parts[1])
    num2_parts = num2.split("/")
    num2_numerator = int(num2_parts[0])
    num2_denominator = int(num2_parts[1])
    result_numerator = 0
    result_denominator = 1
    if operation == "add":
        result_numerator = num1_numerator * num2_denominator + num2_numerator * num1_denominator
        result_denominator = num1_denominator * num2_denominator
    elif operation == "subtract":
        result_numerator = num1_numerator * num2_denominator - num2_numerator * num1_denominator
        result_denominator = num1_denominator * num2_denominator
    elif operation == "multiply":
        result_numerator = num1_numerator * num2_numerator
        result_denominator = num1_denominator * num2_denominator
    for i in range(2, min(result_numerator, result_denominator) + 1):
        if result_numerator % i == 0 and result_denominator % i == 0:
            result_numerator //= i
            result_denominator //= i
    return str(result_numerator) + "/" + str(result_denominator)

