def create_unary_operator(lst, binary_op):
    if not isinstance(lst, list):
        raise TypeError("Input list is not a list")
    if any(not isinstance(item, int) for item in lst):
        raise TypeError("Input list contains non-integer elements")
    if not callable(binary_op):
        raise TypeError("Binary operation is not a function")
    arity = len(inspect.getfullargspec(binary_op).args)
    if arity != 2:
        raise ValueError("Binary operation must take two arguments")
    def unary_op(x):
