from typing import List

def check_winner(board: List[List[str]], player: str) -> bool:
    """
    Checks if the given player has won the game of Tic-Tac-Toe.
    """
    row_counts = {i: 0 for i in range(len(board))}
    col_counts = {j: 0 for j in range(len(board[0]))}
    left_diag_count, right_diag_count = 0, 0

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == player:
                row_counts[i] += 1
                col_counts[j] += 1

                if i == j:
                    left_diag_count += 1

                if i + j == len(board) - 1:
                    right_diag_count += 1
    for count in row_counts.values():
        if count == 3:
            return True

    for count in col_counts.values():
        if count == 3:
            return True

    if left_diag_count == 3 or right_diag_count == 3:
        return True

    return False

def calculate_hashrate(hash_counter, time_elapsed, energy_consumption, hash_unit, time_unit):
    if hash_unit == 'h/s':
        hash_rate = hash_counter
    else:
        hash_rate = hash_counter / 1000

    if time_unit == 's':
        power_consumption = energy_consumption
    else:
        power_consumption = energy_consumption / 3.6

    hash_rate_per_second = hash_rate / time_elapsed
    power_consumption_watts = power_consumption / time_elapsed

    return hash_rate_per_second, power_consumption_watts

def compute_binomial_coefficient(n, k, repetition=False):
    if n < 0 or k < 0 or k > n:
        raise ValueError("Invalid input: n must be non-negative and k must be in the range [0, n]")
    if k == 0 or n == k:
        return 1
    if repetition:  # Generalized binomial coefficient
        return compute_binomial_coefficient(n + k - 1, k, False)
    else:  # Standard binomial coefficient
        return compute_binomial_coefficient(n - 1, k - 1, False) * n // k

