class Graph:
    def __init__(self):
        self.vertices = {}

    def add_vertex(self, vertex):
        self.vertices[vertex] = []

    def add_edge(self, vertex_1, vertex_2):
        self.vertices[vertex_1].append(vertex_2)
        self.vertices[vertex_2].append(vertex_1)

    def depth_first_search(self, vertex, visited=None):
        if visited is None:
            visited = set()
        visited.add(vertex)
        for neighbour in self.vertices[vertex]:
            if neighbour not in visited:
                self.depth_first_search(neighbour, visited)
        return visited

