def shortest_path(grid, start, target):
    def neighbors(cell):
        i, j = cell
        return [(i + di, j + dj) for di, dj in [(1, 0), (-1, 0), (0, 1), (0, -1)]
                if 0 <= i + di < len(grid) and 0 <= j + dj < len(grid[0]) and not grid[i + di][j + dj]]
    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])
    open_set = set([start])
    closed_set = set()
    g_values = {start: 0}
    h_values = {start: heuristic(start, target)}
    f_values = {start: h_values[start]}
    parents = {start: None}
    while open_set:
        current = min(open_set, key=lambda cell: f_values[cell])
        open_set.remove(current)
        if current == target:
            path = [current]
            while current != start:
                current = parents[current]
                path.append(current)
            path.reverse()
            return path
        closed_set.add(current)
        for neighbor in neighbors(current):
            if neighbor in closed_set:
                continue
            g_value = g_values[current] + 1
            if neighbor not in open_set or g_value < g_values[neighbor]:
                open_set.add(neighbor)
                g_values[neighbor] = g_value
                h_values[neighbor] = heuristic(neighbor, target)
                f_values[neighbor] = g_values[neighbor] + h_values[neighbor]
                parents[neighbor] = current
    return []

