import time

def timed_func(method_name):
    def decorator(cls):
        def timed_wrapper(self, *args, **kwargs):
            start = time.time()
            result = getattr(self, method_name)(*args, **kwargs)
            end = time.time()
            print(f"{method_name} took {end - start:.4f} seconds")
            return result
        setattr(cls, method_name, timed_wrapper)
        return cls
    return decorator

def group_into_sublists(items, max_length):
    if not items:
        return []

    sublists = []
    current_sublist = []
    for item in items:
        if len(current_sublist) < max_length:
            current_sublist.append(item)
        else:
            sublists.append(current_sublist)
            current_sublist = [item]
    if current_sublist:
        sublists.append(current_sublist)

    return sublists

