import time

def timeit(func):
    """Measure the execution time of a function."""
    def timed(*args, **kwargs):
        t0 = time.perf_counter()
        result = func(*args, **kwargs)
        t1 = time.perf_counter()
        print(f"Elapsed time: {t1-t0} seconds")
        return result
    return timed

@timeit
def find_longest_common_prefix(strings: List[str]) -> str:
    if not strings:
        return ""
    longest_common_prefix = strings[0]
    for string in strings[1:]:
        i = 0
        while i < len(longest_common_prefix) and i < len(string):
            if longest_common_prefix[i] != string[i]:
                break
            i += 1
        longest_common_prefix = longest_common_prefix[:i]
    return longest_common_prefix

