def convert_string_to_word_count(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError("Input text must be a string.")
    text = text.lower()
    text = text.replace(".", "")
    text = text.replace(",", "")
    text = text.replace("!", "")
    text = text.replace("?", "")
    text = text.replace("'", "")
    words = text.split()
    word_counts = {}
    for word in words:
        if word not in word_counts:
            word_counts[word] = 1
        else:
            word_counts[word] += 1
    return word_counts

def xor_binary(x: int, y: int) -> int:
    """
    Computes the XOR of two binary numbers represented as integers.
    """
    x_bin = bin(x)[2:]  # Convert x to binary string
    y_bin = bin(y)[2:]  # Convert y to binary string
    if len(x_bin) < len(y_bin):
        x_bin = '0' * (len(y_bin) - len(x_bin)) + x_bin
    elif len(x_bin) > len(y_bin):
        y_bin = '0' * (len(x_bin) - len(y_bin)) + y_bin
    xor_bin = ''
    for i in range(len(x_bin)):
        if x_bin[i] == y_bin[i]:
            xor_bin += '0'
        else:
            xor_bin += '1'
    return int(xor_bin, base=2)

