def binary_tree_string(root):
    if not root:
        return ""
    queue = [root]
    result = []
    while queue:
        level = []
        next_level = []
        for node in queue:
            level.append(node.data)
            if node.left:
                next_level.append(node.left)
            if node.right:
                next_level.append(node.right)
        queue = next_level
        result.append(" ".join(map(str, level)))
    return "\n".join(result)
