def is_valid_movement(current_position, operation):
    directions = {
        "up": (0, -1),
        "down": (0, 1),
        "left": (-1, 0),
        "right": (1, 0),
    }
    row, column = current_position
    if row < 0 or column < 0:
        return False
    if operation not in directions:
        return False
    new_row, new_column = directions[operation]
    new_position = (row + new_row, column + new_column)
    if new_position[0] < 0 or new_position[1] < 0:
        return False
    return True

