def select_params(params, selector):
    if isinstance(selector, str):
        if selector in params:
            return {selector: params[selector]}
        else:
            raise KeyError("Key not found in parameters")
    elif isinstance(selector, int):
        return select_params(params, slice(selector, selector + 1))
    elif isinstance(selector, slice):
        result = {}
        keys = list(params.keys())
        for key in keys[selector]:
            result[key] = params[key]
        return result
    else:
        raise TypeError("Selector must be a key, index, or slice")

