def is_symmetric(node):
    def is_mirror(left_node, right_node):
        if left_node is None and right_node is None:
            return True
        elif left_node is not None and right_node is not None:
            return left_node.value == right_node.value and is_mirror(left_node.left, right_node.right) and is_mirror(left_node.right, right_node.left)
        else:
            return False

    return is_mirror(node.left, node.right)

