def calculate_tfidf(texts):
    num_texts = len(texts)
    word_counts = Counter()
    for text in texts:
        word_counts.update(text.split())

    tfidf = {}
    for word, count in word_counts.items():
        tf = count / len(texts)
        idf = log(num_texts / count)
        tfidf[word] = tf * idf

    return tfidf

def calculate_cosine_similarity(query, text):
    dot_product = sum(query[word] * text[word] for word in query if word in text)
    norm_query = sum(query[word] ** 2 for word in query) ** 0.5
    norm_text = sum(text[word] ** 2 for word in text) ** 0.5
    return dot_product / (norm_query * norm_text)

def rank_texts(texts, query):
    tfidf = calculate_tfidf(texts)
    query_tfidf = {word: tfidf[word] for word in query if word in tfidf}

    text_scores = {}
    for text in texts:
        text_words = text.split()
        text_tfidf = {word: tfidf[word] for word in text_words if word in tfidf}
        text_scores[text] = calculate_cosine_similarity(query_tfidf, text_tfidf)

    top_texts = sorted(text_scores, key=lambda x: text_scores[x], reverse=True)[:3]
    return top_texts
