from struct import pack, unpack

def ip_convert(ip_str: str, is_deserialize: bool) -> int:
    """
    Converts an IP address string to a 32-bit unsigned integer and the other way around.
    """
    if is_deserialize:
        octets = unpack('!4B', pack('!I', ip_str))
        return '.'.join(str(octet) for octet in octets)
    else:
        octets = [int(octet) for octet in ip_str.split('.')]
        if any(octet < 0 or octet > 255 for octet in octets):
            raise ValueError('Invalid IP address')
        return unpack('!I', pack('!4B', *octets))[0]

