import re

def replace_pronouns(text, name):
    pronouns = ['I', 'my', 'me', 'mine']
    possessive_forms = ['my', 'mine']
    regex = re.compile(r'\b(' + '|'.join(pronouns) + r')\b')

    def replacement(match):
        if match.group(1) in possessive_forms:
            return name + "'s"
        else:
            return name

    replacements, _ = regex.subn(replacement, text)
    return replacements

