    if input_size % 2 == 0:
        top_bottom_padding = (kernel_size - 1) * dilation
        left_right_padding = (kernel_size - 1) * dilation + (stride - 1)
    else:
        top_bottom_padding = (kernel_size - 1) * dilation + 1
        left_right_padding = (kernel_size - 1) * dilation + (stride - 1) + 1
    return (top_bottom_padding, top_bottom_padding, left_right_padding, left_right_padding)

