    def __init__(self):
        self.stack = []

    def push(self, item):
        self.stack.append(item)

    def pop(self):
        return self.stack.pop()

    def is_empty(self):
        return len(self.stack) == 0

def reverse(s):
    if s.is_empty():
        return

    top = s.pop()
    reverse(s)
    insert_at_bottom(s, top)

def insert_at_bottom(s, item):
    if s.is_empty():
        s.push(item)
    else:
        temp = s.pop()
        insert_at_bottom(s, item)
        s.push(temp)

