def find_subclasses(cls):
    subclasses = []
    for child_cls in cls.__subclasses__():
        mro = inspect.getmro(child_cls)
        mro_len = len(mro)
        if mro_len > 1:
            depth = mro_len - mro.index(cls) - 1
        else:
            depth = 0
        subclasses.append((child_cls, child_cls.__name__, depth))
        subclasses.extend(find_subclasses(child_cls))
    return subclasses

from math import sqrt

def nearest_distance(points_a, points_b):
    if not points_a or not points_b:
        return None

    nearest_dist = float('inf')
    for point_a in points_a:
        for point_b in points_b:
            dist = sqrt((point_b[0] - point_a[0]) ** 2 + (point_b[1] - point_a[1]) ** 2)
            if dist < nearest_dist:
                nearest_dist = dist

    return nearest_dist

