def parse_structured_string(s, args=None, command_line=False):
    """
    Parses a structured string and returns a dictionary containing the key-value pairs extracted from the string.

    Args:
        s (str): The structured string to parse.
        args (list, optional): A list of key names as string to extract only the specified keys and their corresponding values. Defaults to None.
        command_line (bool, optional): Indicates whether the function is being called from the command line. Defaults to False.

    Returns:
        dict: A dictionary containing the key-value pairs extracted from the string.

    Raises:
        TypeError: If the parameter types are invalid.
        ValueError: If the structured string format is not valid.
    """
    if not isinstance(s, str):
        raise TypeError('The parameter s must be a string.')
    if args is not None and not isinstance(args, list):
        raise TypeError('The parameter args must be a list.')
    if not isinstance(command_line, bool):
        raise TypeError('The parameter command_line must be a boolean.')
    pairs = s.split()
    if not all(len(pair.split(':')) == 2 for pair in pairs):
        raise ValueError('The structured string format is not valid.')
    parsed_pairs = {}
    for pair in pairs:
        key, value = pair.split(':')
        parsed_pairs[key] = value
    if args is not None:
        parsed_pairs = {key: parsed_pairs[key] for key in args if key in parsed_pairs}
    if command_line:
        print(' '.join(f'{key}={value}' for key, value in parsed_pairs.items()))

    return parsed_pairs

