from typing import Callable

def wrapper_function(func: Callable[[float, float], float]) -> Callable[[int, int], float]:
    """
    Wraps an input function `func` and returns a new function that converts both
    arguments to float before calling `func`. If `func` is not a function type,
    the wrapper function returns None.
    """
    try:
        if not isinstance(func, Callable):
            raise TypeError('Input argument is not a function type.')

        def new_function(x: int, y: int) -> float:
            """
            The new function that takes int arguments and converts them to float,
            then calls the input function `func` with the converted arguments.
            """
            return func(float(x), float(y))

        return new_function
    except Exception as e:
        print(f'Error: {e}')
        return None

def intersection(array1, array2):
    array1.sort()
    array2.sort()

    common_elements = []

    for element in array1:
        if binary_search(array2, element):
            common_elements.append(element)

    return common_elements, len(common_elements)


def binary_search(array, target):
    left = 0
    right = len(array) - 1

    while left <= right:
        middle = left + (right - left) // 2

        if array[middle] == target:
            return True
        elif array[middle] < target:
            left = middle + 1
        else:
            right = middle - 1

    return False

