def spiral_print(matrix):
    rows, cols = len(matrix), len(matrix[0])
    row_start, row_end = 0, rows - 1
    col_start, col_end = 0, cols - 1

    while row_start <= row_end and col_start <= col_end:
        for col in range(col_start, col_end + 1):
            print(matrix[row_start][col], end=' ')
        row_start += 1
        for row in range(row_start, row_end + 1):
            print(matrix[row][col_end], end=' ')
        col_end -= 1
        for col in reversed(range(col_start, col_end + 1)):
            print(matrix[row_end][col], end=' ')
        row_end -= 1
        for row in reversed(range(row_start, row_end + 1)):
            print(matrix[row][col_start], end=' ')
        col_start += 1

