import math

def detect_bonds(pos, threshold):
    bonds = []
    for i in range(len(pos)):
        for j in range(i + 1, len(pos)):
            distance = math.sqrt((pos[i][0] - pos[j][0]) ** 2 +
                                 (pos[i][1] - pos[j][1]) ** 2 +
                                 (pos[i][2] - pos[j][2]) ** 2)
            if distance <= threshold:
                bonds.append((i, j))
    return bonds

