def divide_interval(start, end, width):
    if width >= end - start:
        return [(start, end)]
    else:
        first_part_end = start + width
        second_part_start = first_part_end
        second_part_end = end

        first_part_intervals = divide_interval(
            start, first_part_end, width
        )
        second_part_intervals = divide_interval(
            second_part_start, second_part_end, width
        )

        return first_part_intervals + second_part_intervals

