import time

def timeit(number):
    def decorator(func):
        def wrapper(*args, **kwargs):
            total_time = 0.0
            for _ in range(number):
                start_time = time.time()
                result = func(*args, **kwargs)
                end_time = time.time()
                total_time += end_time - start_time
            avg_time = total_time / number
            return f"{func.__name__}: {avg_time:.6f} seconds for {number} runs"
        return wrapper
    return decorator

