import math

def log_sum_probabilities(p1, p2):
    if p1 < 0 or p1 > 1 or p2 < 0 or p2 > 1:
        raise ValueError("Probabilities must be between 0 and 1")
    if p1 == 0 or p2 == 0:
        return math.inf
    return math.log(p1 + p2)

