import random

class ChemicalElement:
    def __init__(self, atomic_number):
        self.atomic_number = atomic_number
        self.isotope_abundances = {
            1: 0.99985, # Example isotope abundance
            2: 0.00015, # Example isotope abundance
        }

    def get_random_isotope(self):
        isotopes = list(self.isotope_abundances.keys())
        abundances = list(self.isotope_abundances.values())
        return random.choices(isotopes, weights=abundances)[0]

    def get_next_isotope(self, current_isotope):
        isotopes = sorted(self.isotope_abundances.keys())
        if current_isotope in isotopes:
            next_isotope_index = isotopes.index(current_isotope) + 1
            if next_isotope_index < len(isotopes):
                return isotopes[next_isotope_index]
            else:
                return None
        else:
            return None

    def get_prev_isotope(self, current_isotope):
        isotopes = sorted(self.isotope_abundances.keys())
        if current_isotope in isotopes:
            prev_isotope_index = isotopes.index(current_isotope) - 1
            if prev_isotope_index >= 0:
                return isotopes[prev_isotope_index]
            else:
                return None
        else:
            return None

