def get_top_labels(labels, values):
    if len(labels) != len(values):
        raise ValueError("The length of the labels and values arrays must be the same.")

    if len(labels) == 0:
        return []
    label_values_dict = dict(zip(labels, values))
    sorted_labels = sorted(label_values_dict, key=label_values_dict.get, reverse=True)
    top_labels = []
    if len(labels) < 2:
        top_labels = sorted_labels
    else:
        top_labels = sorted_labels[:2]

