import random

def miller_rabin_test(n, k=10):
    if n % 2 == 0:
        return False
    a = random.randint(1, n-1)
    b = pow(a, n-1, n)
    if b == 1 or b == n-1:
        return True
    for i in range(k-1):
        b = pow(b, 2, n)
        if b == 1:
            return False
        if b == n-1:
            return True

    return False

