import json

def extract_values(json_obj):
    result = []

    def traverse(obj):
        if isinstance(obj, list):
            for item in obj:
                traverse(item)
        elif isinstance(obj, dict):
            for key, value in obj.items():
                traverse(value)
        else:
            if isinstance(obj, str):
                result.append(obj)

    traverse(json_obj)
    return ", ".join(result)
