def filter_words(words, lo, hi):
    def binary_search(words, target):
        left, right = 0, len(words) - 1
        while left <= right:
            mid = (left + right) // 2
            if target == words[mid]:
                return mid
            elif target > words[mid]:
                left = mid + 1
            else:
                right = mid - 1
        return left

    lo_index = binary_search(words, lo)
    hi_index = binary_search(words, hi)
    return words[lo_index:hi_index+1]

