def compare_versions(version_1, version_2):
    def split_version(version):
        major, minor, patch = version.split('.')
        return int(major), int(minor), int(patch)

    major_1, minor_1, patch_1 = split_version(version_1)
    major_2, minor_2, patch_2 = split_version(version_2)

    if major_1 != major_2:
        return 1 if major_1 > major_2 else -1
    elif minor_1 != minor_2:
        return 1 if minor_1 > minor_2 else -1
    elif patch_1 != patch_2:
        return 1 if patch_1 > patch_2 else -1
    else:
        return 0

import re

def parse_keys_values(input_string):
    quoted_strings = re.findall(r'".*?"', input_string)
    for quoted_string in quoted_strings:
        input_string = input_string.replace(quoted_string, quoted_string.replace(' ', '_'))
    pairs = input_string.split(',')
    keys_values = {}
    for pair in pairs:
        key, value = pair.split(':')
        keys_values[key.strip().strip('"').replace('_', ' ')] = value.strip().strip('"').replace('_', ' ')

    return keys_values

