def dot_product_of_matrices(A, B):
    result = [[0 for _ in range(len(A))] for _ in range(len(A))]
    for i in range(len(A)):
        for j in range(len(A)):
            for k in range(len(A)):
                result[i][j] += A[i][k] * B[k][j]
    return result

from typing import List, Dict

def count_words(text: str, categories: List[str]) -> Dict[str, int]:
    """
    Counts the frequency of words in `text` and categorizes them based on `categories`.
    """
    counts = {category: 0 for category in categories}
    for word in text.split():
        category = categorize_word(word, categories)
        if category:
            counts[category] += 1

    return counts

def categorize_word(word: str, categories: List[str]) -> str:
    """
    Categorizes a word based on its prefix. For example, `word = "find"` will be categorized
    as "verb" since it starts with "fin".
    """
    for category in categories:
        if word.startswith(category):
            return category
    return None

