def generate_query(query_template, args):
    """Generate an SQL query from a template with given arguments."""
    formatted_args = []
    for arg in args:
        if isinstance(arg, int):
            formatted_arg = str(arg)
        elif isinstance(arg, str):
            escaped_arg = escape_special_characters(arg)
            formatted_arg = f"'{escaped_arg}'"
        elif isinstance(arg, list):
            formatted_arg = f"({', '.join(str(item) for item in arg)})"
        else:
            raise ValueError(f"Unsupported argument type: {type(arg)}")
        formatted_args.append(formatted_arg)
    return query_template.format(*formatted_args)

def escape_special_characters(s):
    """Escape special characters in a string."""
    special_characters = ["'", '"', '%', '_']
    escaped_s = ""
    for char in s:
        if char in special_characters:
            escaped_s += f"\\{char}"
        else:
            escaped_s += char
    return escaped_s

def process_sites(sites):
    valences = {}
    bond_types = {}

    for site in sites:
        valences[site['name']] = site['valence']
        for bond in site['bonds']:
