        return -1

    unmatched_quote = None
    quote_stack = []

    for i, c in enumerate(string):
        if c in ('"', "'"):
            if i > 0 and string[i - 1] != "\\":
                if c == unmatched_quote:
                    unmatched_quote = None
                    quote_stack.pop()
                else:
                    unmatched_quote = c
                    quote_stack.append(i)

    if quote_stack:
        return quote_stack[0]
    else:
        return -1

