import numpy as np

def polynomial_interpolation(data, order):
    if not isinstance(data, list) or not all(isinstance(point, list) and len(point) == 2 and all(isinstance(x, float) or isinstance(x, int) for x in point) for point in data):
        raise ValueError("Invalid input: data must be a list of lists representing (x, y) points, where x and y are floats.")

    if order <= 0 or order > len(data):
        raise ValueError("Invalid order: order must be greater than 0 but less than or equal to the number of data points.")
    x = np.array([point[0] for point in data])
    y = np.array([point[1] for point in data])
    powers = np.array([x ** i for i in range(order + 1)]).T
    coefficients = np.linalg.solve(powers, y)
    return coefficients.tolist()

