def segregation_index(state):
    num_0s = 0
    num_1s = 0
    for row in state:
        for cell in row:
            if cell == 0:
                num_0s += 1
            elif cell == 1:
                num_1s += 1
            else:
                raise ValueError("Invalid cell value in the state.")
    p_empty = num_0s / (num_0s + num_1s)
    p_occupied = num_1s / (num_0s + num_1s)
    seg_index = p_empty - p_occupied

    return seg_index

