def sum_dist(array, distance):
    n = len(array)
    a = np.zeros((n, n))
    center_coord = (n // 2, n // 2)
    for i in range(n):
        for j in range(n):
            dist = abs(i - center_coord[0]) + abs(j - center_coord[1])
            if dist <= distance:
                a[i, j] = array[i, j]
    return np.sum(a)

