def longest_ascending_subsequence(nums):
    memo = {}

    def helper(nums, i):
        if i == len(nums):
            return 0

        if i in memo:
            return memo[i]

        if i < len(nums) - 1 and nums[i] < nums[i + 1]:
            result = 1 + helper(nums, i + 1)
        else:
            result = helper(nums, i + 1)

        memo[i] = result
        return result

    max_len = 0
    start_index = 0
    for i, num in enumerate(nums):
        length = helper(nums, i)
        if length > max_len:
            max_len = length
            start_index = i

    return nums[start_index:start_index + max_len + 1]

