import unicodedata

def check_non_ascii(text):
    non_ascii_chars = []
    for char in text:
        if not char.isascii():
            char_name = unicodedata.name(char)
            if char_name is not None:
                non_ascii_chars.append(f"{char} ({char_name})")
            else:
                char_category = unicodedata.category(char)
                non_ascii_chars.append(f"{char} ({char_category})")
    return non_ascii_chars

