def largest_square_root(n: int) -> int:
    if n < 0:
        return -1

    lo = 0
    hi = n

    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if mid * mid <= n:
            lo = mid + 1
        else:
            hi = mid - 1

    return lo - 1

