def convert_tuple_to_string(items: tuple) -> str:
    """
    Converts a tuple of string items into a single string, where the items
    are separated by commas and enclosed in double quotes if they contain commas.
    """
    result = ""

    for i, item in enumerate(items):
        if "," in item:
            item = f'"{item}"'

        if i == len(items) - 1:
            result += item
        else:
            result += f"{item}, "

