    return value * conversion_factor

import json

def get_value_from_json(json_data: str, key: str) -> str:
    """
    Returns the value associated with `key` in the given JSON string `json_data`. If the key
    is not found, returns None.
    """
    dict_data = json.loads(json_data)

    def recurse(data: dict, key: str) -> str:
        """
        Recursively searches `data` for the value associated with `key`. If the key is not
        found, returns None.
        """
        for k, v in data.items():
            if k == key:
                return v
            elif isinstance(v, dict):
                result = recurse(v, key)
                if result is not None:
                    return result
        return None

    return recurse(dict_data, key)

class TreeNode:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

    def sum(self):
        result = self.value

        if self.left:
            result += self.left.sum()

        if self.right:
            result += self.right.sum()

        return result

def find_longest_sequence(A, B):
    A.sort()
    B.sort()
    dp = [[0 for _ in B] for _ in A]
    max_length = 0
    for i, a in enumerate(A):
        for j, b in enumerate(B):
            if a < b:
                dp[i][j] = dp[i-1][j-1] + 1
                max_length = max(max_length, dp[i][j])
    return max_length

def linear_annealing(initial_lr, num_epochs):
