class Node:
    def __init__(self, value):
        self.value = value
        self.children = []

def find_duplicate_node(node, seen=None):
    """
    Finds the first duplicate node in a tree structure.
    """
    if seen is None:
        seen = set()

    if node in seen:
        return node

    seen.add(node)

    for child in node.children:
        duplicate = find_duplicate_node(child, seen)
        if duplicate:
            return duplicate

    return None

