def convert_timestamp_to_seconds(timestamp):
    if isinstance(timestamp, str):
        parsed_timestamp = datetime.datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
    elif isinstance(timestamp, tuple):
        year, month, day, hour, minute, second = timestamp
        parsed_timestamp = datetime.datetime(year, month, day, hour, minute, second)
    elif isinstance(timestamp, object):
        year = getattr(timestamp, 'year', None)
        month = getattr(timestamp, 'month', None)
        day = getattr(timestamp, 'day', None)
        hour = getattr(timestamp, 'hour', None)
        minute = getattr(timestamp, 'minute', None)
        second = getattr(timestamp, 'second', None)
        parsed_timestamp = datetime.datetime(year, month, day, hour, minute, second)
    return (parsed_timestamp - datetime.datetime(1970, 1, 1)).total_seconds()

