    max_len = 0
    max_seq = []
    current_len = 1
    current_seq = [sorted_list[0]]
    for i in range(1, len(sorted_list)):
        if sorted_list[i] - sorted_list[i-1] == 1:
            current_len += 1
            current_seq.append(sorted_list[i])
        else:
            if current_len > max_len:
                max_len = current_len
                max_seq = current_seq
            current_len = 1
