        raise ValueError("Invalid lattice type. Expected 'square' or 'hexagonal'")
    scaled_radius = scaling * radius
    if lattice_type == 'square':
        sublattice = [
            (i, j)
            for i in range(-size, size + 1)
            for j in range(-size, size + 1)
            if abs(i) + abs(j) >= scaled_radius
        ]
    elif lattice_type == 'hexagonal':
        sublattice = [
            (x, y)
            for x in range(-size, size + 1)
            for y in range(-size, size + 1)
            for i in range(-1, 2)
            for j in range(-1, 2)
            if abs(x + i) + abs(y + j) >= scaled_radius
        ]
    if return_dict:
        return {
            'lattice_type': lattice_type,
            'radius': radius,
            'scaled_radius': scaled_radius,
            'size': size,
            'sublattice': sublattice
        }
    else:
        return sublattice

