def calculate_atoms(pdb_file: str) -> dict:
    """
    Calculates the number of atoms in a protein chain, given the atoms and their connections in a
    PDB file. The function returns a dictionary mapping each element to the total number of atoms
    for that element.
    """
    atom_counts = defaultdict(int)

    for line in pdb_file.splitlines():
