class Module:
    def __init__(self, name):
        self.name = name
        self.imports = []

    def add_import(self, module):
        self.imports.append(module)

    def has_cycle(self):
        visited = set()
        def dfs(module):
            if module in visited:
                return True
            visited.add(module)
            for imported_module in module.imports:
                if dfs(imported_module):
                    return True
            visited.remove(module)
            return False
        return dfs(self)

