def compare_version_numbers(version1, version2):
    pattern = r"(\d+)(?:\.(\d+)(?:\.(\d+)(?:\.(\d+))?)?)?"
    match1 = re.search(pattern, version1)
    match2 = re.search(pattern, version2)
    parts1 = [int(match1.group(i)) if match1.group(i) else 0 for i in range(1, 5)]
    parts2 = [int(match2.group(i)) if match2.group(i) else 0 for i in range(1, 5)]
    for i in range(4):
        if parts1[i] > parts2[i]:
            return True
        elif parts1[i] < parts2[i]:
            return False
    return False

