from typing import List

def smallest_bounding_box(boxes: List[List[int]]) -> List[int]:
    """Returns the smallest bounding box that encloses all the given bounding boxes."""
    if not boxes:
        return None
    minx, miny, maxx, maxy = boxes[0]
    for box in boxes:
        if box[0] < minx:
            minx = box[0]
        if box[1] < miny:
            miny = box[1]
        if box[2] > maxx:
            maxx = box[2]
        if box[3] > maxy:
            maxy = box[3]
    return [minx, miny, maxx, maxy]

