def shortest_distance_dfs(graph, source, destination):
    stack = [source]
    min_distance = -1
    distances = {}
    distances[source] = 0
    visited = {}
    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            visited[vertex] = True
            if vertex == destination:
                min_distance = min(min_distance, distances[vertex]) if min_distance != -1 else distances[vertex]
            else:
                for neighbor in graph[vertex]:
                    if neighbor not in visited:
                        stack.append(neighbor)
                        distances[neighbor] = distances[vertex] + 1
    return min_distance

import hashlib

def calculate_sha256_checksum(file_path, block_size=65536):
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(block_size)
            if not data:
                break
            sha256.update(data)
    return sha256.hexdigest()

