import heapq

def top_k_entries(data, k, key):
    values = {}
    for entry in data:
        if entry[key] in values:
            values[entry[key]] += entry['value']
        else:
            values[entry[key]] = entry['value']
    heap = []
    for key, value in values.items():
        heapq.heappush(heap, (-value, key))
    result = []
    for _ in range(k):
        value, key = heapq.heappop(heap)
        result.append((key, -value))
    return result

