def read_tar_file(byte_stream):
    tar = tarfile.open(fileobj=byte_stream)
    tar.extractall()
    file_contents = []
    for member in tar.getmembers():
        if member.isfile():
            with tar.extractfile(member) as f:
                file_contents.append(f.read().decode('utf-8'))

    return file_contents

def filter_discounts(objects):
    filtered_objects = []
    for obj in objects:
        if not hasattr(obj, 'price') or not hasattr(obj, 'discount'):
            continue
        if not isinstance(obj.discount, int) or not 1 <= obj.discount <= 99:
            continue
        if not obj.price > 0:
            continue
        price_after_discount = obj.price * (1 - obj.discount / 100)
        if price_after_discount >= 0.2 * obj.price:
            filtered_objects.append(obj)
    return filtered_objects

def prime_number_generator(limit, output_format):
    if type(limit) is not int or limit < 1:
        raise ValueError('Limit must be a positive integer.')
    primes = []
    is_prime = [True] * (limit + 1)
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i * 2, limit + 1, i):
                is_prime[j] = False
    if output_format == 'set':
        return set(primes)
    elif output_format == 'list':
        return primes
    else:
        raise ValueError('Invalid output format.')

def find_best_player(players):
    best_player = None
    best_score = -float('inf')
    for player, score in players.items():
        if score > best_score:
            best_score = score
            best_player = player
    return best_player

