        if isinstance(node, ast.stmt):
            parent_nodes.append(ast)
        traverse_ast(node, parent_nodes)

import json

def convert_json_to_dict(data, single_key=False, key_name=None):
    data_json = json.loads(data)
    if isinstance(data_json, list):
        if single_key and key_name is not None:
            return {key_name: convert_json_to_dict_helper(data_json)}
        else:
            return convert_json_to_dict_helper(data_json)
    elif isinstance(data_json, dict):
        return convert_json_to_dict_helper(data_json)
    else:
        raise ValueError("Unexpected data type: {}".format(type(data_json)))

def convert_json_to_dict_helper(obj):
    if isinstance(obj, list):
        return [convert_json_to_dict_helper(item) for item in obj]
    elif isinstance(obj, dict):
        return {key: convert_json_to_dict_helper(value) for key, value in obj.items()}
    else:
        return obj

def filter_unique_words(strings):
    filtered_list = []
    unique_words = set()

    for string in strings:
        words = string.split()
        for word in words:
            if word not in unique_words:
                unique_words.add(word)
                filtered_list.append(word)

    return filtered_list

