def complement_array(a):
    b = [[0 for _ in range(len(a[0]))] for _ in range(len(a))]
    for i in range(len(a)):
        for j in range(len(a[0])):
            if a[i][j] == 0:
                b[i][j] = 1
            elif a[i][j] == 1:
                b[i][j] = 0
            else:
                raise AssertionError("Input array contains invalid value")
    return b

