from functools import reduce

def merge_dicts(d1, d2):
    def update_dict(acc, key):
        acc[key] = d2[key] if key in d2 else acc[key]
        return acc

    return reduce(update_dict, d2, d1)

def get_workload_status(current_status, minutes):
    remaining_minutes = {
        'ready': 0,
        'waiting for execution': 10,
        'executing': 5,
        'complete': 30
    }
    for _ in range(minutes):
        if current_status == 'ready':
            return current_status
        elif current_status == 'waiting for execution':
            remaining_minutes['waiting for execution'] -= 1
            if remaining_minutes['waiting for execution'] == 0:
                current_status = 'executing'
        elif current_status == 'executing':
            remaining_minutes['executing'] -= 1
            if remaining_minutes['executing'] == 0:
                current_status = 'complete'
        else:
            remaining_minutes['complete'] -= 1
            if remaining_minutes['complete'] == 0:
                current_status = 'ready'
    return current_status

