def compute_coverage(files, commits):
    coverage = {}
    for file_path, file_content in files:
        coverage[file_path] = [line.strip() for line in file_content.split("\n")]
    for commit in commits:
        changed_files = commit.get("changed_files", [])
        for changed_file in changed_files:
            lines_covered = changed_file.get("lines_covered", [])
            file_path = changed_file.get("file_path", "")
            if file_path in coverage:
                for line in lines_covered:
                    coverage[file_path][line - 1] = "+"  # Mark the line as covered
    for file_path, lines in coverage.items():
        coverage[file_path] = lines.count("+") / len(lines)

    return coverage

