class BinaryTree:
    def __init__(self, val=None, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def find_min(node):
    if node is None:
        return None
    min_val = node.val
    left_min = find_min(node.left)
    if left_min is not None and left_min < min_val:
        min_val = left_min
    right_min = find_min(node.right)
    if right_min is not None and right_min < min_val:
        min_val = right_min
    return min_val

