class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def serialize(root):
    nodes = []
    def preorder(node):
        if node:
            nodes.append(str(node.val))
            preorder(node.left)
            preorder(node.right)
        else:
            nodes.append('null')
    preorder(root)
    return ' '.join(nodes)

def deserialize(data):
    nodes = data.split()
    def build_tree(nodes):
        if nodes:
            val = nodes.pop(0)
            if val == 'null':
                return None
            else:
                node = TreeNode(int(val))
                node.left = build_tree(nodes)
                node.right = build_tree(nodes)
                return node
    return build_tree(nodes)

