import re

def perform_variable_substitution(input_string, variable_dict):
    if not input_string:
        raise ValueError("Input string must not be empty")

    def replace_variable(match):
        var = match.group(1)
        if var in variable_dict:
            return str(variable_dict[var])
        else:
            return ""

    pattern = r"\{([a-zA-Z0-9_]+)\}"
    return re.sub(pattern, replace_variable, input_string)

def subsets(lst):
    if len(lst) == 0:
        return [[]]
    else:
        subsets_without_last = subsets(lst[:-1])
        subsets_with_last = [[lst[-1]] + subset for subset in subsets_without_last]
        return subsets_without_last + subsets_with_last

def union_of_subsets(lst):
    subsets_lst = subsets(lst)
    union = []
    for element in lst:
        for subset in subsets_lst:
            if element in subset:
                union.append(element)
                break
    return union

