def deep_flatten(nested_dict):
    flattened = {}
    for key, val in nested_dict.items():
        if isinstance(val, dict):
            flattened.update({f"{key}.{subkey}": subval for subkey, subval in deep_flatten(val).items()})
        else:
            flattened[key] = val
    return flattened


def deep_unflatten(flattened_dict):
    unflattened = {}
    for key, val in flattened_dict.items():
        parts = key.split(".")
        if len(parts) > 1:
            if parts[0] not in unflattened:
                unflattened[parts[0]] = {}
            unflattened[parts[0]][".".join(parts[1:])] = val
        else:
            unflattened[key] = val
    return unflattened


