def calculate_sequence_similarity(sequence_1, sequence_2):
    residue_types = {
        'C': 15,
        'D': 16,
        'H': 17,
        'K': 18,
        'N': 19,
        'T': 20,
        'Y': 21,
        'W': 22
    }
    similarity_score = 0
    n_pairs = 0
    for residue_1, residue_2 in zip(sequence_1, sequence_2):
        if residue_1 in residue_types and residue_2 in residue_types:
            n_pairs += 1
            if residue_1 == residue_2:
                similarity_score += residue_types[residue_1] * residue_types[residue_2]
            else:
                similarity_score += abs(residue_types[residue_1] - residue_types[residue_2])
    if n_pairs != 0:
        similarity_score /= n_pairs

    return similarity_score

