def pu_score(y, f):
    numerator = 0
    denominator = 0
    for i in range(len(y)):
        if y[i]:
            denominator += 1
            if f[i]:
                numerator += 1
    if denominator > 0:
        return numerator / denominator
    else:
        return 0

import json

def json_to_dict(json_string):
    try:
        json_obj = json.loads(json_string)
        return convert_json_object(json_obj)
    except json.JSONDecodeError:
        return None

def convert_json_object(json_obj):
    if isinstance(json_obj, str):
        return json_obj
    elif isinstance(json_obj, int) or isinstance(json_obj, float):
        return json_obj
    elif isinstance(json_obj, bool):
        return json_obj
    elif json_obj is None:
        return None
    elif isinstance(json_obj, list):
        return [convert_json_object(item) for item in json_obj]
    elif isinstance(json_obj, dict):
        return {key: convert_json_object(value) for key, value in json_obj.items()}
    else:
        return None

