def is_latin_square(matrix):
    N = len(matrix)
    for i in range(N):
        row = set(matrix[i])
        col = set([matrix[j][i] for j in range(N)])
        if len(row) != N or len(col) != N:
            return False
        for j in range(N):
            if matrix[i][j] not in range(1, N + 1) or matrix[j][i] not in range(1, N + 1):
                return False

    return True

