import re

def replace_arithmetic_tokens(expression: str) -> str:
    replacement_patterns = [
        (r'\+', '-'),  # Replace plus with its negation
        (r'[^\d\s\(\)\-\+\*\/]+', ' ')  # Replace other tokens with space
    ]
    def replacement_function(match: re.Match) -> str:
        token = match.group(0)
        if token == '+':
            return '-'
        return ' '
    for pattern, replacement in replacement_patterns:
        expression = re.sub(pattern, replacement_function, expression)
    expression = re.sub(r'\*', '/', expression)

    return expression

