def variants_to_dataframe(variants):
    columns = []
    for variant in variants:
        if isinstance(variant, dict):
            columns.extend(variant.keys())
        elif isinstance(variant, list):
            columns.extend(i for i in range(len(variant)))
        else:
            raise ValueError("Invalid variant format.")
    columns = list(set(columns))

    data = {}
    for column in columns:
        values = []
        for variant in variants:
            if isinstance(variant, dict):
                values.append(variant.get(column, None))
            elif isinstance(variant, list):
                values.append(variant[column] if len(variant) > column else None)
            else:
                raise ValueError("Invalid variant format.")
        data[column] = values

    return pd.DataFrame(data)

