            if matrix[row][col] == word[0]:
                if dfs_search(matrix, word, row, col, 0):
                    return True
    return False

def dfs_search(matrix, word, row, col, idx):
    if idx == len(word):
        return True
    if row < 0 or row >= len(matrix) or col < 0 or col >= len(matrix[row]):
        return False
    if matrix[row][col] != word[idx]:
        return False
    tmp = matrix[row][col]
    matrix[row][col] = None
    found = dfs_search(matrix, word, row + 1, col, idx + 1) or \
        dfs_search(matrix, word, row - 1, col, idx + 1) or \
        dfs_search(matrix, word, row, col + 1, idx + 1) or \
        dfs_search(matrix, word, row, col - 1, idx + 1) or \
        dfs_search(matrix, word, row + 1, col + 1, idx + 1) or \
        dfs_search(matrix, word, row - 1, col - 1, idx + 1) or \
        dfs_search(matrix, word, row + 1, col - 1, idx + 1) or \
        dfs_search(matrix, word, row - 1, col + 1, idx + 1)
    matrix[row][col] = tmp
    return found

