def validate_arithmetic_expression(expression):
    stack = []
    for char in expression:
        if char == '(':
            stack.append(')')
        elif char == ')':
            if len(stack) == 0:
                return False
            elif stack[-1] != ')':
                return False
            else:
                stack.pop()
        elif char == '{':
            stack.append('}')
        elif char == '}':
            if len(stack) == 0:
                return False
            elif stack[-1] != '}':
                return False
            else:
                stack.pop()
        elif char == '[':
            stack.append(']')
        elif char == ']':
            if len(stack) == 0:
                return False
            elif stack[-1] != ']':
                return False
            else:
                stack.pop()
    return len(stack) == 0

