def calculate_overlapping_area(region1, region2):
    x1, y1, width1, height1 = region1
    x2, y2, width2, height2 = region2

    if width1 <= 0 or height1 <= 0 or width2 <= 0 or height2 <= 0:
        return "Error: width or height is less than or equal to 0."

    x_overlap = min(x1 + width1, x2 + width2) - max(x1, x2)
    y_overlap = min(y1 + height1, y2 + height2) - max(y1, y2)

    if x_overlap <= 0 or y_overlap <= 0:
        return "Error: no overlapping area."

    return x_overlap * y_overlap

