def kmp_search(string, term):
    table = [0] * len(term)
    i = 1
    j = 0
    while i < len(term):
        if term[i] == term[j]:
            table[i] = j + 1
            i += 1
            j += 1
        elif j > 0:
            j = table[j - 1]
        else:
            table[i] = 0
            i += 1
    indices = []
    i = 0
    j = 0
    while i < len(string):
        if string[i] == term[j]:
            i += 1
            j += 1
            if j == len(term):
                indices.append("{}:{}".format(i - j, term))
                j = 0
        elif j > 0:
            j = table[j - 1]
        else:
            i += 1

    return indices

