def classify_data_points(data_points: List[Tuple[float, float]]) -> List[int]:
    num_data_points = len(data_points)
    cluster_counts = {i: 0 for i in clusters}  # Initialize cluster counts to 0
    classified_points = []
    for point in data_points:
        distances = {cluster: np.linalg.norm(np.subtract(point, avg_dist)) for cluster, avg_dist in clusters.items()}
        closest_cluster = min(distances, key=distances.get)
        cluster_counts[closest_cluster] += 1
        classified_points.append(closest_cluster)
    zero_copy_clusters = [cluster for cluster, count in cluster_counts.items() if count / num_data_points < 0.05]
    for i, point in enumerate(data_points):
        if point in zero_copy_clusters:
            classified_points[i] = -1

    return classified_points

