def transpose_complex_matrix(matrix):
    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise TypeError("Input matrix must be a list of lists.")
    if not all(len(row) == len(matrix[0]) for row in matrix):
        raise ValueError("Input matrix must have the same number of columns in each row.")
    if not all(isinstance(item, (int, float, complex)) for row in matrix for item in row):
        raise TypeError("Input matrix must contain only numbers.")
    transposed_matrix = [[None] * len(matrix) for _ in range(len(matrix[0]))]
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            transposed_matrix[j][i] = matrix[i][j]
    for i in range(len(transposed_matrix)):
        for j in range(len(transposed_matrix[0])):
            if isinstance(transposed_matrix[i][j], complex):
                transposed_matrix[i][j] = complex(transposed_matrix[i][j].real, transposed_matrix[i][j].imag)

    return transposed_matrix

