def calculate_subtended_angle(center_x, center_y, point_x, point_y, radius):
    if radius <= 0:
        raise Exception("Radius must be positive.")
    distance = math.sqrt((center_x - point_x) ** 2 + (center_y - point_y) ** 2)

    if distance == radius:
        return 0
    elif distance > radius:
        return None
    else:
        arc_length = 2 * math.asin(distance / (2 * radius))
        return arc_length

def get_range_in_time_window(data, start_time, end_time):
    min_value = None
    max_value = None

    for point in data:
        if start_time <= point["timestamp"] <= end_time:
            if min_value is None or point["value"] < min_value:
                min_value = point["value"]

            if max_value is None or point["value"] > max_value:
                max_value = point["value"]

    if min_value is None or max_value is None:
        return 0

    return max_value - min_value

def distance_to_line_segment(point, line_start, line_end):
    line_length = ((line_start[0] - line_end[0]) ** 2 + (line_start[1] - line_end[1]) ** 2) ** 0.5
    dot_product = ((point[0] - line_start[0]) * (line_end[0] - line_start[0]) + (point[1] - line_start[1]) * (line_end[1] - line_start[1]))
    if dot_product <= 0:
        distance = ((point[0] - line_start[0]) ** 2 + (point[1] - line_start[1]) ** 2) ** 0.5
    elif dot_product >= line_length ** 2:
        distance = ((point[0] - line_end[0]) ** 2 + (point[1] - line_end[1]) ** 2) ** 0.5
    else:
        distance = abs((line_end[1] - line_start[1]) * point[0] - (line_end[0] - line_start[0]) * point[1] + line_end[0] * line_start[1] - line_end[1] * line_start[0]) / line_length

    return distance

