def find_deepest_level(items):
    item_dict = {item["id"]: item for item in items}
    max_depth = float("-inf")
    deepest_item_id = None

    def traverse(item_id, depth):
        nonlocal max_depth, deepest_item_id
        if depth > max_depth:
            max_depth = depth
            deepest_item_id = item_id
        for child_id in item_dict[item_id]["children"]:
            traverse(child_id, depth + 1)

    for item in items:
        traverse(item["id"], 0)

    return deepest_item_id

