def string_to_cents(string: str) -> int:
    """
    Converts a string in the format of USD currency to its price in cents.
    """
    pattern = r"^\$(\d+)\.(\d{2})$"
    match = re.match(pattern, string)

    if match is None:
        raise ValueError("Input string is not in the correct format.")

    dollars, cents = match.groups()

    if len(cents) != 2:
