T = TypeVar('T')

def most_common_elements(elements: List[T]) -> List[T]:
    """
    Accepts a list of arbitrary types and returns a list of the most common elements.
    The function should return an empty list if the input list is empty.
    The function should also support type hints for specifying the input and output types.
    The function should not use any built-in functions other than len and type.
    """
    if not elements:
        return []
    frequency = {}

    for element in elements:
        if element not in frequency:
            frequency[element] = 1
        else:
            frequency[element] += 1
    max_frequency = max(frequency.values())
    return [element for element, count in frequency.items() if count == max_frequency]

