from typing import List, Dict

def count_occurrences(nums: List[int]) -> Dict[int, int]:
    """
    Counts the occurrences of each element in a sorted array. If an exception
    occurs, returns an empty dictionary instead.
    """
    result = {}

    for num in nums:
        try:
            first_idx = find_first_occurrence(nums, num)
            last_idx = find_last_occurrence(nums, num)
            result[num] = last_idx - first_idx + 1
        except Exception as e:
            print(f"An exception occurred: {e}")
            return {}

    return result

def find_first_occurrence(nums: List[int], target: int) -> int:
    """
    Finds the first occurrence of `target` in `nums` using binary search.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid

    if nums[left] == target:
        return left
    else:
        raise Exception(f"Could not find the first occurrence of {target}.")

def find_last_occurrence(nums: List[int], target: int) -> int:
    """
    Finds the last occurrence of `target` in `nums` using binary search.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2 + 1

        if nums[mid] > target:
            right = mid - 1
        else:
            left = mid

    if nums[right] == target:
        return right
    else:
        raise Exception(f"Could not find the last occurrence of {target}.")

