def custom_power(base, power, precision=2):
    if not isinstance(power, int):
        integer_power = int(power)
        fractional_power = power - integer_power
        result = (base ** integer_power) * (base ** fractional_power)
    elif power < 0:
        result = base ** power  # This is a negative power.
    else:
        result = 1
        for _ in range(power):
            result *= base
    return round(result, precision)

