        return -1

    bin_size = 10  # Adjust the bin size as needed
    bins = [array[i:i + bin_size] for i in range(0, len(array), bin_size)]

    for bin_index, bin in enumerate(bins):
        if target in bin:
            return start_index + bin.index(target)
