def binary_search(array, target, comparator):
    start = 0
    end = len(array) - 1
    while start <= end:
        middle = (start + end) // 2
        if comparator(target, array[middle]) == 0:
            return middle
        elif comparator(target, array[middle]) < 0:
            end = middle - 1
        else:
            start = middle + 1
    if target < array[0]:
        return 0
    elif target > array[-1]:
        return len(array)
    return -1

