def symbolic_matrix_multiplication(matrix_1, matrix_2):
    num_rows_1 = len(matrix_1)
    num_cols_1 = len(matrix_1[0])
    num_rows_2 = len(matrix_2)
    num_cols_2 = len(matrix_2[0])
    if num_cols_1 != num_rows_2:
        raise ValueError("Incompatible dimensions for symbolic matrix multiplication")
    result_matrix = [[0 for _ in range(num_cols_2)] for _ in range(num_rows_1)]
    for row_idx in range(num_rows_1):
        for col_idx in range(num_cols_2):
            for k in range(num_cols_1):
                result_matrix[row_idx][col_idx] += matrix_1[row_idx][k] * matrix_2[k][col_idx]

    return result_matrix

