def run_commands(commands, working_dir, target):
    for command in commands:
        target_escaped = shlex.quote(target)
        command = command.replace("{{target}}", target_escaped)
        shell_command = " && ".join(command)
        try:
            process = subprocess.Popen(shell_command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=working_dir, shell=True)
            stdout, stderr = process.communicate()
        except Exception as e:
            print(f"Error executing command: {command}")
            print(f"Error: {e}")
            continue
        if process.returncode == 0:
            print(f"Command: {command} successfully executed")
        else:
            print(f"Command: {command} failed with return code {process.returncode}")
        return commands

