def compute_precision_recall_f1(recommended_items, actual_items):
    common_items = set(recommended_items).intersection(set(actual_items))
    num_common_items = len(common_items)

    if len(recommended_items) > 0:
        precision = num_common_items / len(recommended_items)
    else:
        precision = 0

    if len(actual_items) > 0:
        recall = num_common_items / len(actual_items)
    else:
        recall = 0

    if precision + recall > 0:
        f1 = 2 * precision * recall / (precision + recall)
    else:
        f1 = 0

    return {"precision": precision, "recall": recall, "f1": f1}

