def piecewise_linear_function(coordinates):
    equations = []
    for i in range(len(coordinates) - 1):
        x1, y1 = coordinates[i]
        x2, y2 = coordinates[i + 1]
        slope = (y2 - y1) / (x2 - x1)
        intercept = y1 - slope * x1
        equations.append((slope, intercept, x2))

    def f(x):
        for slope, intercept, x_max in equations:
            if x <= x_max:
                return slope * x + intercept

    return f

