def generate_permutations(nums, length):
    def backtrack(prefix, used):
        if len(prefix) == length:
            result.append(prefix[:])
            return

        for i in range(len(nums)):
            if i not in used:
                used.add(i)
                prefix.append(nums[i])
                backtrack(prefix, used)
                prefix.pop()
                used.remove(i)

    result = []
    backtrack([], set())
    return result

