def path_exists(start, dest, edges):
    if start == dest:
        return True
    visited = set()
    visited.add(start)
    def traverse_graph(node):
        if node == dest:
            return True
        for edge in edges:
            if edge[0] == node:
                dest_node = edge[1]
                if dest_node not in visited:
                    visited.add(dest_node)
                    if traverse_graph(dest_node):
                        return True
        return False
    return traverse_graph(start)

