def update_time(current_time, delay_in_seconds, time_format):
    current_time_obj = datetime.datetime.strptime(current_time, '%H:%M')
    updated_time_obj = current_time_obj + datetime.timedelta(seconds=delay_in_seconds)

    if time_format == '12 hour':
        updated_time = updated_time_obj.strftime('%I:%M %p')
    else:
        updated_time = updated_time_obj.strftime('%H:%M')

    return updated_time.lstrip('0')

def average_age_by_city(users):
