def gini_impurity_index(dataset):
    labels = [instance['label'] for instance in dataset]
    label_freq = {label: labels.count(label) for label in set(labels)}
    num_instances = len(dataset)
    gini = 1 - sum([(freq / num_instances) ** 2 for freq in label_freq.values()])
    return gini

