import numpy as np

def pad_odd_dimensions(image: np.ndarray) -> np.ndarray:
    height, width, _ = image.shape
    if height % 2 == 1:
        padded_height = height + 1
    else:
        padded_height = height

    if width % 2 == 1:
        padded_width = width + 1
    else:
        padded_width = width
    padded_image = np.zeros((padded_height, padded_width, 3), dtype=np.uint8)
    padded_image[:height, :width, :] = image

    return padded_image

