def compute_2d_conv_output_shape(input_shape, kernel_size=(3, 3), strides=(1, 1), padding='same'):
    input_height, input_width, input_channels = input_shape
    kernel_height, kernel_width = kernel_size
    horizontal_stride, vertical_stride = strides

    if padding == 'same':
        padding_height = kernel_height // 2
        padding_width = kernel_width // 2
    elif padding == 'valid':
        padding_height = 0
        padding_width = 0
    else:
        raise ValueError(f"Invalid padding type: {padding}")

    output_height = (input_height + 2 * padding_height - kernel_height) // vertical_stride + 1
    output_width = (input_width + 2 * padding_width - kernel_width) // horizontal_stride + 1
    output_channels = input_channels

    return (output_height, output_width, output_channels)

