        elif isinstance(value, list):
            new_value = f"[{', '.join([str(item) for item in value])}]"
        elif isinstance(value, dict):
            new_value = f"{{{', '.join([f'{k}: {v}' for k, v in value.items()])}}}"
        elif isinstance(value, set):
            new_value = f"[{', '.join([str(item) for item in value])}]"
