def positional_encoding(max_len, d_model):
    pos_enc = np.array([
        [pos / np.power(10000, 2 * (j // 2) / d_model) for j in range(d_model)]
        for pos in range(max_len)
    ])
    pos_enc[:, 0::2] = np.sin(pos_enc[:, 0::2])  # apply sin to even indices in array
