import base64

def encode_binary_file_to_base64(input_file: str) -> str:
    CHUNK_SIZE = 4096
    try:
        with open(input_file, 'rb') as f:
            with open(input_file + '.b64', 'w') as out_file:
                while True:
                    chunk = f.read(CHUNK_SIZE)
                    if not chunk:
                        break
                    encoded_chunk = base64.b64encode(chunk)
                    out_file.write(encoded_chunk.decode())
        return encoded_chunk.decode()
    except Exception as e:
        raise ValueError(f'Error encoding file {input_file}: {e}')

