    strings = set()

    def backtrack(current_string, last_char):
        if len(current_string) == length:
            strings.add(current_string)
            return

        if last_char == '0':
            backtrack(current_string + '0', '0')
            backtrack(current_string + '1', '1')
        elif last_char == '1':
            backtrack(current_string + '0', '0')

    backtrack('', '0')
    return strings

