def utf8_encode(text: str) -> bytes:
    """
    Encodes a Unicode string to UTF-8 bytes.
    """
    encoded_bytes = bytearray()

    for char in text:
        code_point = ord(char)
        binary_representation = bin(code_point)[2:]  # Strip the '0b' prefix

        if code_point < 128:
            encoded_bytes.extend(code_point.to_bytes(1, "big"))
        elif code_point <= 2047:
            encoded_bytes.extend((0b11000000 | (code_point >> 6)).to_bytes(1, "big"))
            encoded_bytes.extend((0b10000000 | (code_point & 0b111111)).to_bytes(1, "big"))
        else:
            encoded_bytes.extend((0b11100000 | (code_point >> 12)).to_bytes(1, "big"))
            encoded_bytes.extend((0b10000000 | ((code_point >> 6) & 0b111111)).to_bytes(1, "big"))
            encoded_bytes.extend((0b10000000 | (code_point & 0b111111)).to_bytes(1, "big"))

    return bytes(encoded_bytes)

