def get_nested_property(d, prop_string):
    prop_parts = prop_string.split('.')

    def get_property(obj, prop):
        if isinstance(obj, dict) and prop in obj:
            return obj[prop]
        return None

    current_obj = d
    for prop in prop_parts:
        current_obj = get_property(current_obj, prop)
        if current_obj is None:
            return None

    return current_obj

