import re

def next_semantic_version(version):
    major, minor, patch = [int(part) for part in re.findall(r'\d+', version)]
    if patch < 9:
        patch += 1
    elif minor < 9:
        minor += 1
        patch = 0
    else:
        major += 1
        minor = patch = 0
    return f'{major}.{minor}.{patch}'

def intersect_ranges(range1, range2):
    min1, max1 = range1
    min2, max2 = range2

    if min1 <= max2 and min2 <= max1:
        start = max(min1, min2)  # Start of intersection range
        end = min(max1, max2)  # End of intersection range
        return (start, end)
    else:
        return None

