import re

class Parameter:
    def __init__(self, name, default):
        self.name = name
        self.default = default

def format_string(string, **kwargs):
    parameters = re.findall(r"\{(\w+)\}", string)
    parameters = [Parameter(name, kwargs.get(name, None)) for name in parameters]
    for param in parameters:
        if param.default is not None:
            string = string.replace("{" + param.name + "}", str(param.default))

    return string

def map_values_to_words(dictionary, values):
    if not isinstance(dictionary, dict):
        raise ValueError("dictionary must be a dictionary")
    if not isinstance(values, list):
        raise ValueError("values must be a list")
    if not all(isinstance(v, int) for v in values):
        raise ValueError("values must be a list of integers")
    min_key = min(dictionary)
    max_key = max(dictionary)
    return [dictionary.get(v, "N/A") for v in values if min_key <= v <= max_key]

import re

def base5_string(n):
    if not isinstance(n, int) or not re.match(r'^[1-9]\d*$', str(n)):
        return "Invalid input"
    digits = []
    while n:
        n, remainder = divmod(n, 5)
        digits.append(str(remainder))
    return ''.join(reversed(digits))

def merge_different_keys(dict1: dict, dict2: dict) -> dict:
    result = {**dict1}  # Copy the first dictionary
    for key, value in dict2.items():
        if key not in dict1:
            result[key] = value  # Add the new key-value pair from dict2
    return result

