import re

def increment_time(time_str):
    pattern = re.compile(r"^\d{2}:\d{2}:\d{2}$")
    if not pattern.match(time_str):
        raise AssertionError("Invalid time format")
    hours, minutes, seconds = map(int, time_str.split(":"))
    if seconds == 59:
        seconds = 0
        minutes += 1
        if minutes == 60:
            minutes = 0
            hours += 1
            if hours == 24:
                hours = 0
    else:
        seconds += 1
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"

def replace_apples_with_bananas(input_string):
    apple_index = input_string.find('apple')
    if apple_index != -1:
        input_string = input_string[:apple_index] + 'banana' + input_string[apple_index + len('apple'):]
    next_apple_index = input_string.find('apple', apple_index + len('banana'))
    if next_apple_index != -1:
        input_string = replace_apples_with_bananas(input_string)
    return input_string

