def convert_arcgis_geojson_to_geojson_feature_collection(arcgis_geojson, feature_type):
    if not isinstance(arcgis_geojson, dict) or not isinstance(arcgis_geojson.get('features'), list) or not feature_type:
        raise ValueError('Invalid ArcGIS GeoJSON object or missing feature_type argument.')
    features = arcgis_geojson.get('features')
    if not features:
        raise ValueError('No features found in the ArcGIS GeoJSON object.')
    feature_collection = {
        'type': 'FeatureCollection',
        'features': []
    }
    for feature in features:
        geometry = feature.get('geometry')
        properties = feature.get('attributes')
        feature_collection['features'].append({
            'type': 'Feature',
            'geometry': geometry,
            'properties': properties
        })

    return feature_collection

