def extract_kv(obj, key_path=None):
    result = {}
    if key_path is None:
        key_path = ""
    if isinstance(obj, list):
        for i, item in enumerate(obj):
            new_key_path = f"{key_path}[{i}]"
            item_result = extract_kv(item, new_key_path)
            result.update(item_result)
    elif isinstance(obj, dict):
        for key, value in obj.items():
            new_key_path = f"{key_path}.{key}" if key_path else key
            value_result = extract_kv(value, new_key_path)
            result.update(value_result)
    else:
        result[key_path] = obj

    return result

