import numpy as np

def f(x, mu, sigma):
    return (1 / (np.sqrt(2 * np.pi * sigma**2))) * np.exp(-((x - mu)**2) / (2 * sigma**2))

def calculate_f(x_list, mu, sigma):
    f_values = []
    for x in x_list:
        f_values.append(f(x, mu, sigma))
    return f_values

def is_palindrome(s):
    return s == ''.join(reversed(s))

def filter_palindromes(strings):
