def find_max_node(tree, target):
    if not tree:
        return None

    if not isinstance(target, (int, float)):
        return None

    max_node = None

    def dfs(node):
        nonlocal max_node
        if node['value'] <= target:
            if max_node is None or node['value'] > max_node['value']:
                max_node = node
        left_index = node['left']
        right_index = node['right']
        if left_index != -1:
            dfs(tree[left_index])
        if right_index != -1:
            dfs(tree[right_index])

    dfs(tree[0])
    return max_node

import re

def extract_file_types(filenames):
    file_types = []
    for filename in filenames:
        match = re.search(r"\.(\w+)\Z", filename)
        if match and match.group(1) in ["mp3", "wav", "flac", "ogg", "mp4", "webm", "avi", "jpg", "jpeg", "png", "txt", "pdf", "docx", "xlsx", "csv"]:
