def convert_binary_string_to_decimal(binary_string: str) -> int:
    if binary_string[0] == '-':
        sign = -1
        binary_string = binary_string[1:]
    else:
        sign = 1
    decimal_value = 0
    for i, digit in enumerate(reversed(binary_string)):
        digit_value = int(digit)
        power_of_two = 2 ** i
        decimal_value += digit_value * power_of_two
    return sign * decimal_value

