import numpy as np

def find_LCA(tree: np.ndarray, node1: int, node2: int) -> int:
    assert isinstance(tree, np.ndarray), "tree must be a NumPy ndarray"
    assert node1 >= 0 and node1 < tree.shape[0], "node1 must be a valid node index"
    assert node2 >= 0 and node2 < tree.shape[0], "node2 must be a valid node index"
    lca = None
    path1 = set()
    path2 = set()
    curr = 0
    while curr != -1:
        if curr == node1:
            path1.add(curr)
            break
        if curr == node2:
            path2.add(curr)
            break
        path1.add(curr)
        path2.add(curr)
        if tree[curr, 0] != -1:
            curr = tree[curr, 0]
        elif tree[curr, 1] != -1:
            curr = tree[curr, 1]
        else:
            curr = -1
    for node in path1:
        if node in path2:
            lca = node
            break

    return lca

