def dec_to_bin(decimal):
    binary = ''
    while decimal > 0:
        binary += str(decimal & 1)  # Extract the least significant bit
        decimal >>= 1  # Shift the decimal number right by 1 bit
    return binary[::-1]  # Reverse the binary string

