from html import escape

def generate_html_tag(tag, content, attributes):
    tag_start = f"<{tag}"
    if attributes:
        for attribute, value in attributes:
            tag_start += f' {attribute}="{escape(value)}"'
    tag_start += ">"
    if content:
        return f"{tag_start}{escape(content)}</{tag}>"
    else:
        return f"{tag_start}"

import re

def classify_question(question):
    yes_no_pattern = re.compile(r'^Is this a.*\?$')
    non_binary_pattern = re.compile(r'^How many.*are in this.*\?$')
    if yes_no_pattern.match(question):
        return "Yes/No Question", 1.0
    elif non_binary_pattern.match(question):
        return "Non-Binary Question", 0.5
    else:
        return "Unknown Question Type", 0.0

