def get_last_written_variables(instructions):
    lines = instructions.split('\n')
    variable_assignments = {}
    for line in lines:
        parts = line.split('=')
        if len(parts) == 2 and parts[0].strip() and parts[1].strip():
            variable_name = parts[0].strip()
            if variable_name in variable_assignments:
                if parts[1].strip() != variable_assignments[variable_name]:
                    return []
            variable_assignments[variable_name] = parts[1].strip()
    last_assigned_variable = max(variable_assignments, key=lambda x: variable_assignments[x])
    return [last_assigned_variable]

