from typing import Any, List

def flatten_list(lst: List[Any]) -> List[Any]:
    """Recursively flattens a list of lists."""
    flattened = []
    for item in lst:
        if item is None:
            continue
        if isinstance(item, list):
            flattened.extend(flatten_list(item))
        else:
            flattened.append(item)
    return flattened

def transform_list(lst: List[Any]) -> List[Any]:
    """Transforms a list according to the given rules."""
    flattened = flatten_list(lst)
    return [item for item in flattened if item is not None]

import numpy as np

def compute_mean_of_clusters(clusters: np.ndarray) -> np.ndarray:
    num_clusters = clusters.shape[0]
    cluster_means = np.zeros(num_clusters)

    for i in range(num_clusters):
        num_points = clusters[i].size
        if num_points > 0:
            cluster_means[i] = clusters[i].sum() / num_points

    return cluster_means

def convert_dict_ints_to_binary(d):
    if not isinstance(d, dict):
        raise ValueError('Invalid input: input should be a dictionary.')

    if not d:
        raise ValueError('Empty input dictionary.')

    for key, value in d.items():
        if not isinstance(value, int):
            raise ValueError(f'Invalid value: {value} is not an integer.')

    return {key: bin(value) for key, value in d.items()}

from typing import List

def longest_non_decreasing_subsequence_length(nums: List[int]) -> int:
    """
    Finds the length of the longest non-decreasing subsequence in the given list.
    """
    n = len(nums)
    dp = [1] * n  # Initialize `dp` with all 1's

    for i in range(1, n):
        for j in range(i):
            if nums[j] <= nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def handle_functions(functions, params):
    if len(functions) < len(params):
        return None

    for func in functions:
        func_params = func.__code__.co_argcount
        if func_params == len(params):
            return func(*params)
        elif func_params > len(params):
            return func(*params[:func_params])

import time

def measure_time(func, *args):
    start_time = time.time()  # Capture the start time
    func(*args)
    end_time = time.time()    # Capture the end time
    return end_time - start_time  # Return the difference between the end and start times

