def sum_and_odds_evens(nums):
    if not isinstance(nums, list):
        raise ValueError("Input must be a list")

    total = 0
    odds = []
    evens = []

    for num in nums:
        if not isinstance(num, int):
            raise ValueError("Input must be a list of integers")

        total += num

        if num % 2 == 0:
            evens.append(num)
        else:
            odds.append(num)

    return total, odds, evens

