from functools import reduce

def count_characters_frequency(string: str) -> dict:
    """
    Counts the frequency of each character in a string.
    """
    return reduce(
        lambda freq, char: freq.update({char: freq.get(char, 0) + 1}) or freq,
        reversed(string),
        {}
    )

