def sort_and_count(strings):
    counts = {}
    for string in strings:
        counts[string] = counts.get(string, 0) + 1

    sorted_keys = sorted(counts, key=lambda x: (-counts[x], x))

    return [(key, counts[key]) for key in sorted_keys]

