def convert_integer_to_byte_array(integer, byte_order='big', signed=False):
    byte_order_enum = {'big': 'big', 'little': 'little'}
    byte_order = byte_order_enum.get(byte_order, 'big')
    bytes_object = integer.to_bytes(integer.bit_length() // 8 + 1, byteorder=byte_order, signed=signed)
    byte_array = bytes_object.ljust(integer.bit_length() // 8, b'\x00')

    return byte_array

