def find_max_object_by_attr(obj_list, attr_name):
    if not obj_list:
        return None
    if not hasattr(obj_list[0], attr_name):
        raise ValueError(f"Attribute '{attr_name}' does not exist in the first object.")
    max_value = getattr(obj_list[0], attr_name)
    max_obj = obj_list[0]
    for obj in obj_list[1:]:
        try:
            curr_value = getattr(obj, attr_name)
        except AttributeError:
            continue

        if not isinstance(curr_value, (int, float)):
            continue
        if curr_value > max_value:
            max_value = curr_value
            max_obj = obj
    return max_obj

