def create_coordinate_dict(coordinate_pairs):
    """
    Create a dictionary that maps x values to a list of y values from a list of pairs of coordinates.

    Parameters:
    - coordinate_pairs: A list of pairs of coordinates, where each coordinate is a tuple or a list.

    Returns:
    - A dictionary with keys representing the x values and values representing a list of y values associated with the corresponding key.

    Example:
    Input: [(1, 2), (2, 3), (1, 4)]
    Output: {1: [2, 4], 2: [3]}
    """
    coordinate_dict = {}

    for pair in coordinate_pairs:
        x, y = pair[0], pair[1]
        if x not in coordinate_dict:
            coordinate_dict[x] = []
        coordinate_dict[x].append(y)
    sorted_dict = {k: v for k, v in sorted(coordinate_dict.items(), key=lambda item: item[0])}

    return sorted_dict

