import re

def parse_directions(directions):
    pattern = re.compile(r"(L|R|U|D)(\d+)")
    matches = pattern.findall(directions)
    coordinates = [(0, 0)]
    for direction, num in matches:
        steps = int(num)
        x, y = coordinates[-1]
        if direction == "L":
            x -= steps
        elif direction == "R":
            x += steps
        elif direction == "U":
            y += steps
        elif direction == "D":
            y -= steps
        coordinates.append((x, y))
    return coordinates

