def rgb_to_hsv(r, g, b):
    hsl_h, hsl_s, hsl_l = convert_rgb_to_hsl(r, g, b)
    hsv_h = hsl_h
    hsv_s = hsl_s * hsl_l
    hsv_v = hsl_l

    return hsv_h, hsv_s, hsv_v

def convert_rgb_to_hsl(r, g, b):
    max_value = max(r, g, b)
    min_value = min(r, g, b)
    chroma = max_value - min_value
    lightness = (max_value + min_value) / 2
    if chroma == 0:
        hue = 0
    elif max_value == r:
        hue = ((g - b) / chroma) % 6
    elif max_value == g:
        hue = ((b - r) / chroma) + 2
    elif max_value == b:
        hue = ((r - g) / chroma) + 4

    hue *= 60
    if hue < 0:
        hue += 360

    return hue, chroma / max_value, lightness

