import hmac
import hashlib

def compute_hmac_sha256(message, key):
    if not isinstance(message, str):
        raise TypeError("Message must be a string.")
    hmac_sha256 = hmac.new(key.encode(), digestmod=hashlib.sha256)
    hmac_sha256.update(message.encode())
    return hmac_sha256.hexdigest()

def iterate_grid(grid_length, grid_width, elem=None):
    if elem is None:
        for row in range(grid_length):
            for col in range(grid_width):
                yield (row, col)
    elif isinstance(elem, list):
        for i, e in enumerate(elem):
            yield from iterate_grid(grid_length, grid_width, e)
    else:
        yield elem

import numpy as np

def pauli_operator_matrix(operator):
    if operator == "X":
        return np.array([[0, 1], [1, 0]], dtype=complex)
    elif operator == "Y":
        return np.array([[0, -1j], [1j, 0]], dtype=complex)
    elif operator == "Z":
        return np.array([[1, 0], [0, -1]], dtype=complex)
    else:
        raise ValueError(f"Invalid operator: {operator}")

def calculate_matrix_element(state_1, operator, state_2):
    operator_matrix = pauli_operator_matrix(operator)
    return np.matmul(np.matmul(state_1.conj().T, operator_matrix), state_2)

