def compute_percentage_error(pipeline, dataset, target):
    errors = []
    for obj, target_value in zip(dataset, target):
        features = obj
        for stage in pipeline:
            features = stage(features)
        difference = abs(target_value - features)
        error_percentage = (difference / target_value) * 100
        errors.append(error_percentage)
    return errors

