def decimal_to_binary(num: int) -> str:
    """
    Converts a positive integer number from its decimal representation to its binary (base 2) representation.
    """
    if num == 0:
        return ""

    return decimal_to_binary(num // 2) + str(num % 2)

def rotate_array_90_clockwise(arr):
    for i in range(len(arr)):
        for j in range(i + 1, len(arr[i])):
            arr[i][j], arr[j][i] = arr[j][i], arr[i][j]
    for row in arr:
        row.reverse()

    return arr

def intersection_of_lists(list1, list2):
    if len(list1) > len(list2):
        long_list, short_list = list1, list2
    else:
        long_list, short_list = list2, list1

    set_of_strings = set(long_list)

    intersection = []
    for string in short_list:
        if string in set_of_strings:
            intersection.append(string)

    return intersection

