def find_largest_value(dictionary):
    max_value = float('-inf')
    max_key = None

    def traverse(dictionary):
        nonlocal max_value, max_key
        for key, value in dictionary.items():
            if isinstance(value, dict):
                traverse(value)
            else:
                if value > max_value:
                    max_value = value
                    max_key = key
    traverse(dictionary)

    return max_key

