def compare_xml_elements(element1, element2):
    if element1.tag != element2.tag:
        return False

    if element1.attrib != element2.attrib:
        return False
    for child1, child2 in zip(element1, element2):
        if not compare_xml_elements(child1, child2):
            return False

    return True

import urllib.parse

def encode_dict_to_url_string(dictionary: dict) -> str:
    encoded_pairs = []
    for key, value in dictionary.items():
        encoded_key = urllib.parse.quote(key)
        encoded_value = urllib.parse.quote(value)
        encoded_pair = f"{encoded_key}={encoded_value}"
        encoded_pairs.append(encoded_pair)

    encoded_pairs.sort()
    return '&'.join(encoded_pairs)

import re

def replace_middle_name(name):
    match = re.search(r'^(.*)\s+(.*)\s+(.*)$', name)
    if match:
        first_name, last_name = match.group(1), match.group(3)
        return f'{first_name} * {last_name}'
    else:
        return name

