import re

def is_url_safe(url):
    match = re.match(r'^https?://\w+(\.\w+)*(/.*)?$', url)
    if match is None:
        return False
    if not url:
        return False
    unsafe_patterns = ['^https?://\w+(\.\w+)*:\d+(/.*)?$',
                       '^https?://\w+(\.\w+)*(/.*)?\?.*$',
                       '^https?://\w+(\.\w+)*(/.*)?\#.*$']
    for pattern in unsafe_patterns:
        match = re.search(pattern, url)
        if match:
            return False

    return True

