    Returns a list of n-grams of length n from the input text.
    """
    n_grams = {}
    for i in range(len(text) - n + 1):
        n_gram = text[i:i+n]
        if n_gram in n_grams:
            n_grams[n_gram] += 1
        else:
            n_grams[n_gram] = 1
    return n_grams

