def parse_headers(filename):
    with open(filename, 'r') as file:
        headers = {}
        for line in file:
            line = line.strip()  # Remove any leading or trailing whitespace
            if not line:  # Skip blank lines
                continue
            if line.startswith('#'):  # Skip comments
                continue
            header, value = line.split(':')  # Split the line into header and value
            header = header.strip()  # Remove any leading or trailing whitespace
            value = value.strip()  # Remove any leading or trailing whitespace
            if header not in headers:
                headers[header] = value
            else:
                if isinstance(headers[header], str):
                    headers[header] = [headers[header], value]
                else:
                    headers[header].append(value)
    return headers

