import gzip

def extract_kmers(fasta_file, k, gzip_path):
    with open(fasta_file, 'r') as f:
        lines = f.readlines()
    sequence = ''
    for line in lines:
        if line.startswith('>'):
            continue  # Skip header lines
        sequence += line.strip()
    kmers = set()
    for i in range(len(sequence) - k + 1):
        kmer = sequence[i:i+k]
        kmers.add(kmer)
    with gzip.open(gzip_path, 'wb') as f:
        for kmer in kmers:
            f.write((kmer + '\n').encode('utf-8'))

