def convert_integer_between_bases(n: int, base: int) -> str:
    assert n >= 0, "Input integer must be positive"
    assert 2 <= base <= 36, "Target base must be between 2 and 36"
    digits = {10: "A", 11: "B", 12: "C", 13: "D", 14: "E", 15: "F", 16: "G", 17: "H", 18: "I", 19: "J", 20: "K", 21: "L", 22: "M", 23: "N", 24: "O", 25: "P", 26: "Q", 27: "R", 28: "S", 29: "T", 30: "U", 31: "V", 32: "W", 33: "X", 34: "Y", 35: "Z"}

    converted_number = []
    while n > 0:
        remainder = n % base
        n = n // base
        if remainder >= 10:
            remainder_char = digits[remainder]
            converted_number.append(remainder_char)
        else:
            converted_number.append(str(remainder))
    converted_number = converted_number[::-1]

    return "".join(converted_number)

