from cryptography.hazmat.primitives.ciphers import algorithms

def detect_block_cipher(ciphertext):
    block_ciphers = [algorithms.AES, algorithms.Blowfish]
    for cipher in block_ciphers:
        block_size = cipher.block_size // 8
        if len(ciphertext) % block_size == 0:
            return True
    for i in range(1, len(ciphertext) // 2):
        pattern = ciphertext[:i]
        repeated_pattern = pattern * (len(ciphertext) // i)
        if repeated_pattern == ciphertext:
            return True

    return False

