def generate_random_string(length):
    """Generates a random string of lowercase letters."""
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'
    parts = [vowels, consonants, vowels, consonants, vowels, consonants, vowels, consonants, vowels, consonants]

    def generate_char(index):
        if index >= length:
            return ''
        part = parts[index % len(parts)]
        if part == vowels:
            return random.choice(vowels) + generate_char(index + 1)
        else:
            return random.choice(consonants) + generate_char(index + 1)

    return generate_char(0)

