import re

def compile_namespaces(input_string):
    mappings = input_string.split(';')
    compiled_mappings = []
    for mapping in mappings:
        source, destination = mapping.split(' to ')
        alias = re.search('(?: as )(\w+)', destination)
        if alias:
            alias = alias.group(1)
        else:
            alias = None
        if alias:
            compiled_mapping = f'{source} -> {alias}'
        else:
            compiled_mapping = f'{source} -> {destination}'
        compiled_mappings.append(compiled_mapping)
    return ';'.join(compiled_mappings)

