def extract_imaginary_parts(input_tensor):
    """
    Extracts the imaginary parts of a 2D torch tensor containing complex numbers.
    If the input tensor contains only real numbers, the output tensor should be
    a zero tensor of the same shape.
    """
    output_tensor = torch.zeros_like(input_tensor)
    for i in range(input_tensor.shape[0]):
        for j in range(input_tensor.shape[1]):
            if torch.is_complex(input_tensor[i, j]):
                output_tensor[i, j] = torch.imag(input_tensor[i, j])

    return output_tensor

