from typing import List, Tuple, Sequence

def gift_wrapping(points: Sequence[Tuple[float, float]]) -> List[Tuple[float, float]]:
    """
    Given a list of coordinate points, returns the convex hull of the points using the Gift-Wrapping algorithm.
    """
    leftmost_index = 0
    for i, (x, y) in enumerate(points):
        if x < points[leftmost_index][0]:
            leftmost_index = i
    convex_hull = [points[leftmost_index]]
    current_point_index = leftmost_index
    while True:
        next_point_index = current_point_index + 1
        if next_point_index == len(points):
            next_point_index = 0

        for i, (x, y) in enumerate(points):
            if i == current_point_index or i == next_point_index:
                continue
            vector1 = (points[next_point_index][0] - points[current_point_index][0], points[next_point_index][1] - points[current_point_index][1])
            vector2 = (x - points[current_point_index][0], y - points[current_point_index][1])
            cross_product = vector1[0] * vector2[1] - vector1[1] * vector2[0]
            if cross_product > 0:
                next_point_index = i
        convex_hull.append(points[next_point_index])
        current_point_index = next_point_index
        if current_point_index == leftmost_index:
            break

    return convex_hull

