def binary_search(lst, target):
    if not lst:
        return False, -1

    def lower_bound(lst, target):
        lo, hi = 0, len(lst) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if lst[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return lo

    i = lower_bound(lst, target)
    if i < len(lst) and lst[i] == target:
        return True, i
    else:
        return False, -1

def sieve_of_eratosthenes(n):
    primes = [True for i in range(n + 1)]
    primes[0] = primes[1] = False
    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            for j in range(i * i, n + 1, i):
                primes[j] = False
    return primes

def sum_of_primes(n):
    primes = sieve_of_eratosthenes(n)
    return sum([i for i in range(n + 1) if primes[i]])

