import xml.etree.ElementTree as ET

def parse_xml(xml_string):
    root_element = ET.fromstring(xml_string)
    def traverse_xml(element, tag_values):
        for child in element:
            tag = child.tag
            value = child.text.strip()
            if tag not in tag_values:
                tag_values[tag] = []
            tag_values[tag].append(value)
            traverse_xml(child, tag_values)
    tag_values = {}
    traverse_xml(root_element, tag_values)
    return tag_values

def lower(s):
    result = ""
    for c in s:
        if ord(c) >= ord("A") and ord(c) <= ord("Z"):
            result += chr(ord(c) + 32)
        else:
            result += c
    return result

def get_value_counts(values):
