class MakeVariableString:
    def __init__(self, variable_dict):
        self.variable_dict = variable_dict

    def quote_if_necessary(self, value):
        if ' ' in value or '=' in value:
            return f"'{value}'"
        return value

    def escape_if_necessary(self, value):
        if '$' in value:
            return value.replace('$', '$$')
        return value

    def generate_variable_string(self):
        variable_string = ""
        for name, value in self.variable_dict.items():
            value = self.escape_if_necessary(self.quote_if_necessary(value))
            variable_string += f"{name}={value}\n"
        return variable_string

def divide_with_remainder(numerator, denominator):
    try:
        if denominator == 0:
            return None, numerator
        quotient = numerator // denominator
        remainder = numerator % denominator
        return quotient, remainder
    except:
        return None, numerator

