def generate_params(urls, params, default_params=None):
    if len(urls) != len(params):
        raise Exception("The length of urls and params must be the same.")

    result = []

    for url, url_params in zip(urls, params):
        if url_params:
            result.append((url, url_params))
        elif default_params:
            result.append((url, default_params))
        else:
            raise Exception("Either params or default_params must be specified.")

    return result

