class TaxonomyNode:
    def __init__(self, name, parent=None):
        self.name = name
        self.parent = parent
        self.children = []

def build_taxonomy_tree(nodes):
    tree = {}
    for node in nodes:
        taxonomy_node = TaxonomyNode(node['name'], node['parent'])
        tree[taxonomy_node.name] = taxonomy_node
    for node in nodes:
        if node['parent'] is not None:
            parent_node = tree[node['parent']]
            parent_node.children.append(tree[node['name']])

    return tree

import re

def parse_sql_directive(directive):
    tokens = re.split(r'\s+', directive)
    if len(tokens) < 2:
        raise ValueError('Invalid directive format')

    if tokens[0] == 'USE':
        return {'directive': 'USE', 'database': tokens[1]}
    elif tokens[0] == 'CREATE' and tokens[1] == 'TABLE':
        return {'directive': 'CREATE TABLE', 'table': tokens[2]}
    elif tokens[0] == 'ALTER' and tokens[1] == 'TABLE':
        return {'directive': 'ALTER TABLE', 'table': tokens[2]}
    else:
        raise ValueError('Invalid directive')

