import pytz

def convert_datetime_to_utc(date: datetime, target_timezone: str) -> datetime:
    """
    Converts a datetime object from one time zone to UTC.
    """
    try:
        target_timezone_obj = pytz.timezone(target_timezone)
    except pytz.exceptions.UnknownTimeZoneError:
        raise Exception("Unknown time zone")
    try:
        return date.astimezone(target_timezone_obj).astimezone(pytz.utc)
    except pytz.exceptions.AmbiguousTimeError:
        raise Exception("Ambiguous time")
    except pytz.exceptions.NonExistentTimeError:
        raise Exception("Non-existent time")

