def interpolate_nonlinear_range(nonlinear_values, linear_values, target):
    min_idx = 0
    max_idx = len(nonlinear_values)-1
    while min_idx < max_idx - 1:
        mid_idx = (min_idx + max_idx) // 2
        if nonlinear_values[mid_idx] > target:
            max_idx = mid_idx
        else:
            min_idx = mid_idx
    linear_range = linear_values[max_idx] - linear_values[min_idx]
    nonlinear_range = nonlinear_values[max_idx] - nonlinear_values[min_idx]
    interpolation_factor = (target - nonlinear_values[min_idx]) / nonlinear_range
    return linear_values[min_idx] + linear_range * interpolation_factor

def prefix_filter(nested_dict: dict, prefix: str) -> dict:
    filtered_dict = {}
    for key, value in nested_dict.items():
        if key.startswith(prefix):
            filtered_dict[key] = value
        if isinstance(value, dict):
            filtered_value = prefix_filter(value, prefix)
            if filtered_value:
                filtered_dict[key] = filtered_value
    return filtered_dict

def escape_latex_special_characters(text: str) -> str:
    special_characters = {
        '#': '\\#',
        '$': '\\$',
        '%': '\\%',
        '&': '\\&',
        '~': '\\~{}',
        '_': '\\_',
        '^': '\\^{}',
        '\\': '\\textbackslash{}',
        '{': '\\{',
        '}': '\\}'
    }

    escaped_text = ''
    for char in text:
        if char in special_characters:
            escaped_text += special_characters[char]
        else:
            escaped_text += char

    return escaped_text

def extract_area_codes(input_string, area_code_mappings):
    area_codes = input_string.split(',')
    area_codes_and_states = []
    for area_code in area_codes:
        parts = area_code.split(';')
        if len(parts) == 1:
            area_codes_and_states.append((parts[0], 'XX'))
        elif len(parts) == 2:
            area_codes_and_states.append(parts)
    mapped_area_codes_and_states = []
    for area_code, state in area_codes_and_states:
        if area_code in area_code_mappings:
            mapped_state = area_code_mappings[area_code]
        else:
            mapped_state = 'XX'  # Unknown state
        mapped_area_codes_and_states.append((area_code, mapped_state))
    unique_area_codes_and_states = list(set(mapped_area_codes_and_states))

    return unique_area_codes_and_states

