def traverse_tree(root, target_value):
    if root is None:
        return False
    if root.left is not None and root.left.value == root.right.value == target_value:
        return True
    left_result = traverse_tree(root.left, target_value)
    right_result = traverse_tree(root.right, target_value)
    return left_result or right_result

import math

def fibonacci_term(n: int) -> int:
    phi = (1 + math.sqrt(5)) / 2
    one_minus_phi = (1 - math.sqrt(5)) / 2
    term = (phi ** n - one_minus_phi ** n) / math.sqrt(5)
    return round(term)

