import re

def extract_id_and_value(string):
    id_pattern = re.compile(r'id of (\d+)')
    value_pattern = re.compile(r'value of (\d+\.\d+)')
    id_match = id_pattern.search(string)
    value_match = value_pattern.search(string)

    if id_match and value_match:
        unique_id = id_match.group(1)
        value = value_match.group(1)
        return (unique_id, value)
    else:
        return None

from typing import Dict, List, Union

def bfs_first(graph: Dict[str, List[str]], start: str, condition: str) -> Union[str, None]:
    if not graph or start not in graph:
        return None

    queue = [start]
    visited = set(start)

    while queue:
        node = queue.pop(0)

        if condition(node):
            return node

        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append(neighbor)
                visited.add(neighbor)

    return None

