def spiral_order(arr):
    m = len(arr) # Number of rows
    n = len(arr[0]) # Number of columns
    result = []
    r = 0 # Starting row index
    c = 0 # Starting column index

    while r < m and c < n:
        for i in range(c, n):
            result.append(arr[r][i])

        r += 1 # Increment the row index
        for i in range(r, m):
            result.append(arr[i][n-1])

        n -= 1 # Decrement the column index
        if r < m:
            for i in range(n-1, c-1, -1):
                result.append(arr[m-1][i])

        m -= 1 # Decrement the row index
        if c < n:
            for i in range(m-1, r-1, -1):
                result.append(arr[i][c])

        c += 1 # Increment the column index

    return result

