def dynamic_call(module_name, function_name, args, kwargs):
    module = importlib.import_module(module_name)

    if not hasattr(module, function_name):
        raise AttributeError(f"The module {module_name} does not have a function named {function_name}")

    function = getattr(module, function_name)
    type_hints = get_type_hints(function)

    for arg, type_hint in zip(args, type_hints):
        if not isinstance(arg, type_hint):
            raise TypeError(f"Argument {arg} is not of type {type_hint}")

    return function(*args, **kwargs)

