    num_days = len(next(iter(attendance_record.values())))
    total_present = [0] * num_days
    for student, absent_days in attendance_record.items():
        for day in range(num_days):
            total_present[day] += num_days - absent_days[day]
    for student, absent_days in attendance_record.items():
        probability = {}
