def exchange(denominations, amount):
    min_coins = [0] * (amount + 1)

    for target in range(1, amount + 1):
        min_coins[target] = float('inf')
        for coin in denominations:
            if coin <= target:
                remaining_amount = target - coin
                min_coins[target] = min(min_coins[target], min_coins[remaining_amount] + 1)

    if min_coins[amount] == float('inf'):
        return -1
    else:
        return min_coins[amount]

def factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n == 0:
        return 1
    return n * factorial(n - 1)

def approximate_e(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    sum_ = 1.0
    for i in range(n, 0, -1):
        sum_ += 1.0 / factorial(i)
    return sum_

