    return result

import numpy as np

def gram_schmidt(vectors):
    orthonormal_vectors = []
    for vector in vectors:
        proj = np.zeros(3)
        for ortho_vector in orthonormal_vectors:
            proj += np.dot(vector, ortho_vector) * ortho_vector
        orthonormal_vectors.append(vector - proj)
    return orthonormal_vectors

