def largest_rectangle_area(s):
    if not s:
        return 0

    dp = [1] * len(s)
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            dp[i] = dp[i-1] + 1

    max_area = 0
    for i in range(len(s) - 2):
        if s[i] == s[i+1] == s[i+2]:
            max_area = max(max_area, dp[i] * 3)

    return max_area

