def generate_combinations(elements: List[T], combination_length: int) -> List[List[T]]:
    def _helper(elements: List[T], length: int) -> List[List[T]]:
        if length == 0:
            return [[]]
        result: List[List[T]] = []
        for i, element in enumerate(elements):
