import math

def ucb1(rewards, pulls, time_step):
    arms = len(rewards)
    arm_to_be_pulled = None
    best_score = float('-inf')

    for arm in range(arms):
        try:
            average_reward = rewards[arm] / pulls[arm]
        except ZeroDivisionError:
            average_reward = 0

        score = average_reward + math.sqrt(2 * math.log(time_step) / pulls[arm])

        if score > best_score:
            best_score = score
            arm_to_be_pulled = arm

    pulls[arm_to_be_pulled] += 1
    return arm_to_be_pulled

