    if anchor_1_position < score < anchor_2_position:
        interpolation_factor = (score - anchor_1_position) / (anchor_2_position - anchor_1_position)
        score = (1 - interpolation_factor) * anchor_1_score + interpolation_factor * anchor_2_score
    elif score < anchor_1_position:
