from collections import deque

def partition_bipartite_graph(edges):
    adjacency_list = {vertex: set() for vertex in set(sum(edges, ()))}
    for u, v in edges:
        adjacency_list[u].add(v)
        adjacency_list[v].add(u)
    queue = deque()
    colors = {}
    vertex = next(iter(adjacency_list))
    colors[vertex] = 0
    queue.append(vertex)
    while queue:
        vertex = queue.popleft()
        for neighbor in adjacency_list[vertex]:
            if neighbor not in colors:
                colors[neighbor] = 1 - colors[vertex]
                queue.append(neighbor)
            elif colors[neighbor] == colors[vertex]:
                return []
    partition_1 = [vertex for vertex, color in colors.items() if color == 0]
    partition_2 = [vertex for vertex, color in colors.items() if color == 1]

    return [partition_1, partition_2]

