class MaxHeap:
    def __init__(self, array):
        self.elements = array
        self.heap_size = len(array)
        self.heapify()

    def heapify(self):
        last_parent = (self.heap_size - 2) // 2
        for i in range(last_parent, -1, -1):
            self.max_heapify(i)

    def max_heapify(self, i):
        left_child = 2 * i + 1
        right_child = 2 * i + 2
        max_index = i

        if left_child < self.heap_size and self.elements[left_child] > self.elements[max_index]:
            max_index = left_child

        if right_child < self.heap_size and self.elements[right_child] > self.elements[max_index]:
            max_index = right_child

        if max_index != i:
            self.elements[i], self.elements[max_index] = self.elements[max_index], self.elements[i]
            self.max_heapify(max_index)

    def build_heap(self, root):
        array = []
        self.traverse_bst(root, array)
        self.elements = array
        self.heap_size = len(array)

        self.heapify()
        return self.elements[0]

    def traverse_bst(self, node, array):
        if node:
            self.traverse_bst(node.left, array)
            array.append(node.value)
            self.traverse_bst(node.right, array)

