def flatten(obj, prefix="", source=""):
    flattened_obj = {}

    for key, value in obj.items():
        if isinstance(value, dict):
            nested_flattened_obj = flatten(value, prefix + key + "_", source)
            flattened_obj.update(nested_flattened_obj)
        elif isinstance(value, list):
            for i, item in enumerate(value):
                if isinstance(item, dict) or isinstance(item, list):
                    flattened_obj.update(flatten(item, prefix + key + "_" + str(i) + "_"))
                else:
                    flattened_obj[prefix + key + "_" + str(i)] = item
        else:
            flattened_obj[prefix + key] = value

    flattened_obj['source'] = source

    return flattened_obj

