def rotate_character(c, n):
    if not c.isalpha():
        return c
    c_lower = c.lower()
    letter_index = ord(c_lower) - ord('a')
    rotated_index = (letter_index + n) % 26
    return chr(rotated_index + ord('a')) if c.islower() else chr(rotated_index + ord('A'))

