def dfs(graph, start_node):
    visited = set()
    def dfs_recursive(visited, graph, node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs_recursive(visited, graph, neighbor)
        return visited
    return dfs_recursive(visited, graph, start_node)

