import copy

def game_of_life(board):
    """
    Simulates the game of Life and returns the final state of the board.
    The function takes a board, a two-dimensional array of 0s and 1s indicating
    the initial state of the cells.
    """
    def check_neighbors(i, j, board):
        """
        Checks the number of live neighbors of a cell at (i, j) on the board.
        """
        count = 0
        for x in range(i - 1, i + 2):
            for y in range(j - 1, j + 2):
                if x == i and y == j:
                    continue
                if (0 <= x < len(board)) and (0 <= y < len(board[0])):
                    if board[x][y] == 1:
                        count += 1
        return count

    m, n = len(board), len(board[0])
    new_board = copy.deepcopy(board)

    for i in range(m):
        for j in range(n):
            num_neighbors = check_neighbors(i, j, board)
            if board[i][j] == 1:
                if num_neighbors < 2 or num_neighbors > 3:
                    new_board[i][j] = 0
            else:
                if num_neighbors == 3:
                    new_board[i][j] = 1

    return new_board

