from typing import TypeVar, List, Iterable
from queue import PriorityQueue

T = TypeVar('T')

def get_top_k(items: Iterable[T], k: int) -> List[T]:
    """
    Returns the top-k ranked items in `items` based on their scores. The scores are
    derived from their comparable types.
    """
    if k <= 0:
        raise ValueError('k must be a positive integer')
    queue = PriorityQueue()
    for item in items:
        queue.put(item)
        if queue.qsize() > k:
            queue.get()
    return sorted([queue.get() for _ in range(queue.qsize())], reverse=True)

