import math

def is_point_in_polygon(point, polygon):
    num_vertices = len(polygon)
    inside = False
    for i in range(num_vertices):
        j = (i + 1) % num_vertices
        if (polygon[i][1] > point[1]) != (polygon[j][1] > point[1]) and \
                (point[0] < polygon[i][0] + (polygon[j][0] - polygon[i][0]) * (point[1] - polygon[i][1]) / (polygon[j][1] - polygon[i][1])):
            inside = not inside
    return inside

def handle_point_outside_polygon(point, polygon, tolerance=1e-6):
    min_x = min(polygon, key=lambda p: p[0])[0]
    max_x = max(polygon, key=lambda p: p[0])[0]
    min_y = min(polygon, key=lambda p: p[1])[1]
    max_y = max(polygon, key=lambda p: p[1])[1]
    if point[0] < min_x - tolerance or point[0] > max_x + tolerance or point[1] < min_y - tolerance or point[1] > max_y + tolerance:
        raise ValueError("The given point is outside the polygon's bounding box.")

def handle_point_on_polygon_boundary(point, polygon, tolerance=1e-6):
    for i in range(len(polygon)):
        j = (i + 1) % len(polygon)
        distance = math.sqrt((polygon[j][0] - polygon[i][0])**2 + (polygon[j][1] - polygon[i][1])**2)
        if distance > 0:
            projection = ((point[0] - polygon[i][0]) * (polygon[j][0] - polygon[i][0]) + (point[1] - polygon[i][1]) * (polygon[j][1] - polygon[i][1])) / distance**2
            if projection >= 0 and projection <= 1:
                distance_to_boundary = math.sqrt((point[0] - (polygon[i][0] + projection * (polygon[j][0] - polygon[i][0])))**2 + (point[1] - (polygon[i][1] + projection * (polygon[j][1] - polygon[i][1])))**2)
                if distance_to_boundary < tolerance:
                    raise ValueError("The given point is on the polygon's boundary.")

