def is_valid_html_tag_name(tag_name: str) -> bool:
    """
    Checks whether `tag_name` is a valid HTML tag name.
    """
    if not tag_name:
        return False
    if not re.match(r'^\w+$', tag_name):
        return False
    if re.match(r'^\d', tag_name):
        return False
    if re.search(r'--|-_|_-', tag_name):
        return False
    if not re.search(r'[a-zA-Z]', tag_name):
        return False
    return True

