def area_polygon(points):
    x_coords = [p[0] for p in points]
    y_coords = [p[1] for p in points]
    n = len(points)
    area = 0.0

    for i in range(n):
        j = (i + 1) % n
        area += x_coords[i] * y_coords[j] - x_coords[j] * y_coords[i]

    return abs(area / 2.0)

