    inner_nodes = []

    def traverse_tree(node):
        if node is None:
            return

        if node.left is None and node.right is None:
            leaves.append(node.val)
        else:
            inner_nodes.append(node.val)

        traverse_tree(node.left)
        traverse_tree(node.right)

    traverse_tree(root)

    return leaves, inner_nodes

def hex_string_to_integer(hex_string: str) -> int:
    hex_string = hex_string.lstrip('0x')
    result = 0
    for i, char in enumerate(reversed(hex_string)):
        num_value = ord(char) - 48
        if 'A' <= char <= 'F':
            num_value -= 7
        result += num_value * (16 ** i)

    return result

