def elementwise_add(tensor1, tensor2):
    if tensor1.shape != tensor2.shape:
        raise ValueError("Input tensors must be of the same shape.")
    output_tensor = np.empty_like(tensor1)
    for i in range(tensor1.shape[0]):
        for j in range(tensor1.shape[1]):
            if tensor1[i, j] < 0 or tensor2[i, j] < 0:
                raise ValueError("Input tensors cannot contain negative elements.")
            output_tensor[i, j] = tensor1[i, j] + tensor2[i, j]

    return output_tensor

