def get_month_year_ranges(dates):
    groupings = {}

    for date in dates:
        parsed_date = datetime.strptime(date, '%Y-%m-%d')
        month_year = f'{parsed_date.year}-{parsed_date.month:02}'
        if month_year not in groupings:
            groupings[month_year] = []
        groupings[month_year].append(parsed_date)
    results = []

    for month_year, date_list in groupings.items():
        date_list.sort()
        results.append((month_year, date_list[0].strftime('%Y-%m-%d'), date_list[-1].strftime('%Y-%m-%d')))

