def is_valid_position(board, row, col):
    for i in range(8):
        if board[row][i] == 'Q' or board[i][col] == 'Q':
            return False
    for i in range(8):
        for j in range(8):
            if abs(row - i) == abs(col - j) and board[i][j] == 'Q':
                return False

    return True


def solve_queens(board, row):
    if row == 8:
        return True

    for col in range(8):
        if is_valid_position(board, row, col):
            board[row][col] = 'Q'

            if solve_queens(board, row + 1):
                return True
            board[row][col] = '_'

    return False


def find_queens_solution():
    board = [['_' for _ in range(8)] for _ in range(8)]
    solution = []

    if solve_queens(board, 0):
