def parse_html_elements(html_string):
    html_elements = []
    split_string = html_string.split(",")
    has_angle_brackets = re.search(r"</?[^>]+>", split_string[0])
    if has_angle_brackets:
        for s in split_string:
            html_tag = re.search(r"<\s*([^>]+)>", s)
            html_content = re.search(r"=\s*([^>]+)\s*>", s)
            if html_tag and html_content:
                html_element = {"name": html_tag.group(1), "content": html_content.group(1)}
                html_elements.append(html_element)

            else:
                print("Error: No match found for the HTML element.")
    else:
        print("Error: The input string does not have angle brackets.")
    return html_elements

