def fibonacci_sequence(n: int) -> list:
    """
    Generates the first `n` numbers in the Fibonacci sequence using recursion.
    """
    if not isinstance(n, int) or n <= 0:
        raise AssertionError("Invalid input: `n` must be a positive integer.")

    def helper(index: int, prev1: int, prev2: int) -> int:
        """Helper function to recursively generate the Fibonacci sequence."""
        if index == 0:
            return prev2
        if index == 1:
            return prev1

        return helper(index - 1, prev1 + prev2, prev1)

    return [helper(index, 1, 0) for index in range(n)]

