def extract(data, path, default=None, func=None):
    """
    Extract a value from a nested dictionary at a given path,
    applying a transformation func to the value before returning it.
    """
    keys = path.split('.')
    def _extract(data, keys, default):
        if not keys:
            return data
        key = keys.pop(0)

        if isinstance(data, dict) and key in data:
            return _extract(data[key], keys, default)
        else:
            return default

    value = _extract(data, keys, default)
    if func:
