from typing import List, Dict

def prepare_data_for_dynamodb_batch_write_item(items: List[Dict[str, str]], table_name: str, condition_keys: List[str] = []) -> Dict[str, Dict[str, List[Dict[str, Dict[str, Dict[str, str]]]]]]:
    """
    Prepares data in a specific format for DynamoDB BatchWriteItem request.

    Args:
        items (List[Dict[str, str]]): A list of dictionaries representing items.
        table_name (str): The target table name.
        condition_keys (List[str], optional): A list of condition keys to be used for conditional updates. Defaults to [].

    Returns:
        Dict[str, Dict[str, List[Dict[str, Dict[str, Dict[str, str]]]]]]: A dictionary with a `RequestItems` key pointing to a dictionary with the target table name as the key and a list of dictionaries as the value, each representing a DynamoDB request item.
    """

    request_items = {
        table_name: [
            {
                "Insert": {
                    "Item": item,
                    "Expected": {condition_key: {"Exists": False} for condition_key in condition_keys}
                }
            }
            for item in items
        ]
    }

    return {"RequestItems": request_items}

