class MyClass:
    """A class with a private attribute and some magic methods."""

    def __init__(self, public_attribute, private_attribute):
        """Initialize the object with a public attribute and a private attribute."""
        self.public_attribute = public_attribute
        self._private_attribute = private_attribute

    def __repr__(self):
        """Return a string representation of the object."""
        return f"MyClass(public_attribute={self.public_attribute}, private_attribute={self._private_attribute})"

    def __eq__(self, other):
        """Return True if the objects are equal, False otherwise."""
        return self.public_attribute == other.public_attribute and self._private_attribute == other._private_attribute

    def __add__(self, other):
        """Return a new object with the sum of the public attributes."""
        new_public_attribute = self.public_attribute + other.public_attribute
        new_private_attribute = self._private_attribute + other._private_attribute
        return MyClass(new_public_attribute, new_private_attribute)

