def find_top_k(points, k):
    def merge_top_k(top_k_a, top_k_b):
        top_k = []
        i, j = 0, 0
        while len(top_k) < k and i < len(top_k_a) and j < len(top_k_b):
            if top_k_a[i][1] < top_k_b[j][1]:
                top_k.append(top_k_a[i])
                i += 1
            else:
                top_k.append(top_k_b[j])
                j += 1
        return top_k

    if len(points) <= k:
        return points
    elif len(points) == k + 1:
        return points
    else:
        mid = len(points) // 2
        top_k_left = find_top_k(points[:mid], k)
        top_k_right = find_top_k(points[mid:], k)
        return merge_top_k(top_k_left, top_k_right)

