import re

def parse_tag(string):
    pattern_1 = re.compile(r'^<(?P<tag>[\w-]+)\s+(?P<attrs>[^>]*).*?</\1>$')
    pattern_2 = re.compile(r'^<(?P<tag>[\w-]+)\s+(?:(?P<attrs>[^>]*).*?></\1>|[^>]*>)$')

    match_1 = pattern_1.match(string)
    match_2 = pattern_2.match(string)

    if match_1:
        tag_name = match_1.group('tag')
        attrs = match_1.group('attrs')
    elif match_2:
        tag_name = match_2.group('tag')
        attrs = match_2.group('attrs')
    else:
        return None

    return (string, (tag_name, attrs))

