def clamp_integer(value, range):
    if not isinstance(value, int) and not isinstance(value, float):
        raise ValueError('Input value must be an integer or float')
    if not isinstance(range, tuple) or len(range) != 2:
        raise ValueError('Range must be a tuple of length 2')

    min_value, max_value = range
    if not isinstance(min_value, int) and not isinstance(min_value, float):
        raise ValueError('Range minimum value must be an integer or float')
    if not isinstance(max_value, int) and not isinstance(max_value, float):
        raise ValueError('Range maximum value must be an integer or float')
    clamped_value = min(max(value, min_value), max_value)

    return clamped_value

