def is_nested(brackets):
    stack = []

    for char in brackets:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack or (char == ')' and stack[-1] != '(') or (char == ']' and stack[-1] != '[') or (char == '}' and stack[-1] != '{'):
                return False
            stack.pop()
        else:
            continue

    return len(stack) == 0

