def factorial(n):
    if n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def get_matching_layout_patterns(layout_patterns, time_axis):
    if not isinstance(layout_patterns, list):
        raise TypeError("layout_patterns must be a list of dicts")
    if not isinstance(time_axis, int):
        raise TypeError("time_axis must be an integer")
    matching_layout_patterns = []
    for layout_pattern in layout_patterns:
        if not isinstance(layout_pattern, dict):
            raise TypeError("layout_patterns must be a list of dicts")
        if 'time_range' not in layout_pattern:
            raise KeyError("layout_pattern must have the 'time_range' key")
        time_range = layout_pattern['time_range']
        if not isinstance(time_range, list) or len(time_range) != 2 or not all(isinstance(x, int) for x in time_range):
            raise TypeError("'time_range' value must be a list of 2 integers")
        start_time, end_time = time_range[0], time_range[1]
        if start_time <= time_axis <= end_time:
            matching_layout_patterns.append(layout_pattern)
    return matching_layout_patterns

