def follow_path(path: str) -> str:
    movements = {
        'U': (0, 1), 'D': (0, -1), 'R': (1, 0), 'L': (-1, 0),
        'F': (1, 0), 'B': (-1, 0),  # Assume facing east initially
    }
    x, y = 0, 0
    curr_dir = movements[path[0]]
    for ch in path:
        if ch in movements:
            dx, dy = movements[ch]
            x += dx * curr_dir[0]
            y += dy * curr_dir[1]
        elif ch == 'F':
            curr_dir = movements[curr_dir]
        elif ch == 'B':
            curr_dir = movements[curr_dir][::-1]
        else:
            pass
    return f'({x}, {y})'

