from collections import OrderedDict

def combine_lists_without_duplicates(list_1: list, list_2: list) -> list:
    set_1 = set(list_1)
    set_2 = set(list_2)
    combined_set = set_1.union(set_2)
    ordered_dict = OrderedDict()
    for element in list_1 + list_2:
        if element in combined_set:
            ordered_dict[element] = None
            combined_set.remove(element)
    return list(ordered_dict.keys())

