def parse_crontab_field(field):
    values = []
    for element in field.split(","):
        if element == "?":
            continue  # Skip '?'
        elif element == "*":
            values.extend(range(60))  # Add all possible values
        elif "-" in element:
            start, end = element.split("-")
            values.extend(range(int(start), int(end)+1))  # Add range of values
        elif "/" in element:
            start, interval = element.split("/")
            if start.isdigit():
                values.extend(range(int(start), 60, int(interval)))  # Add range of values with interval
            else:
                values.extend(range(0, 60, int(interval)))  # Add range of all values with interval
        else:
            values.append(int(element))  # Add single value
    return values

def traverse_matrix(matrix):
    visited = [[0] * len(matrix[0]) for _ in range(len(matrix))]
    for row in range(len(matrix)):
        for col in range(len(matrix[0])):
            if visited[row][col] == 1:
                continue
            matrix[row][col] = 1 - matrix[row][col]
            visited[row][col] = 1

