    if not isinstance(constituents, list) or not all(isinstance(item, tuple) for item in constituents):
        raise TypeError("Input must be a list of tuples.")
    if not all(len(item) == 2 for item in constituents):
        raise ValueError("Each tuple must have two elements.")
    formula = {}
    for symbol, count in constituents:
        if symbol in formula:
            formula[symbol] += count
        else:
            formula[symbol] = count
    return formula

