import os

def get_size(path):
    if not os.path.exists(path):
        raise FileNotFoundError('The path does not exist.')

    total_size = 0
    for root, dirs, files in os.walk(path):
        for file in files:
            total_size += os.path.getsize(os.path.join(root, file))

    return total_size

