import re

def convert_to_html_objects(text: str) -> list:
    lines = text.splitlines()
    objects = []
    for line in lines:
        tag = re.search(r'<(\w+).*>', line)
        text = re.sub(r'<.*?>', '', line)
        if tag:
            objects.append({
                'tag': tag.group(1),
                'text': text.strip()
            })

    return objects

