def pairwise_dot_product(vectors1, vectors2):
    if len(vectors1) != len(vectors2):
        return []
    result = []
    for v1, v2 in zip(vectors1, vectors2):
        dot_product = {}
        for dim in v1:
            if dim in v2:
                dot_product[dim] = v1[dim] * v2[dim]
        result.append(dot_product)

    return result

def sum_tensors(tensors):
    if not isinstance(tensors, list):
        raise TypeError("tensors must be a list of tensors")

    if len(tensors) == 0:
        return None

    first_tensor = tensors[0]
    if not all(tensor.shape == first_tensor.shape for tensor in tensors):
        raise ValueError("All tensors must have the same shape")
    if not all(tensor.is_contiguous() for tensor in tensors):
        raise ValueError("All tensors must be contiguous in memory")

    result = torch.empty_like(first_tensor)
    result.copy_(tensors[0])

    for tensor in tensors[1:]:
        result.add_(tensor)

    return result

