import copy

def normalize_annotations(obj, normalization_factor):
    normalized_obj = copy.deepcopy(obj)

    def normalize_annotations_recursive(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key in ("start", "end"):
                    obj[key] /= normalization_factor
                elif isinstance(value, dict):
                    normalize_annotations_recursive(value)
                elif isinstance(value, list):
                    for item in value:
                        normalize_annotations_recursive(item)

    normalize_annotations_recursive(normalized_obj)
    return normalized_obj

