def get_average_speed(distance: float, time: float) -> float:
    """
    Calculates the average speed of an object given its distance and time (in km and hours respectively).
    Returns the average speed in km/h rounded to one decimal place.
    """
    if time <= 0:
        raise ValueError("Time cannot be negative or zero.")
    if distance < 0:
        raise ValueError("Distance cannot be negative.")
    average_speed = distance / time
    return round(average_speed, 1)

