def combine_strings_with_quotes(strings):
    combined_string = ""
    for string in strings:
        lowercase_string = string.lower()
        if lowercase_string.startswith('"') and lowercase_string.endswith('"'):
            processed_string = lowercase_string
        else:
            processed_string = f'"{lowercase_string}"'
        combined_string += processed_string
