import math

def float_repr(f, precision, rounding_mode):
    rounded = round(f, precision)
    if rounding_mode == 0:
        rounded = round(f, precision)
    elif rounding_mode == 1:
        rounded = math.ceil(f * (10 ** precision)) / (10 ** precision)
    elif rounding_mode == -1:
        rounded = math.floor(f * (10 ** precision)) / (10 ** precision)
    else:
        raise ValueError("Invalid rounding_mode")
    return format(rounded, f".{precision}f")

