    num_parts = min(num_parts1, num_parts2)

    for i in range(num_parts):
        result = compare_parts(parts1[i], parts2[i])
        if result != 0:
            return result

    if num_parts1 < num_parts2:
        return -1
    elif num_parts1 > num_parts2:
        return 1
    else:
        return 0

