def create_extension_to_mime_type_dictionary(paths: List[str]) -> dict:
    """
    Creates a dictionary that maps file extensions to their MIME types.
    The input is a list of file paths, and the output is a dictionary
    mapping file extensions to MIME types.
    """
    extension_to_mime_type = {}

    for path in paths:
        file_extension = path.split('.')[-1]
        mime_type = mimetypes.guess_type(path)[0]
        if file_extension in extension_to_mime_type:
            if mime_type not in extension_to_mime_type[file_extension]:
                extension_to_mime_type[file_extension].append(mime_type)
        else:
            extension_to_mime_type[file_extension] = [mime_type]

    return extension_to_mime_type

