    def split(input_string, substrings):
        if not input_string:
            return
        delimiter_index = input_string.find(delimiter)
        if delimiter_index == -1:
            substrings.append(input_string)
            return
        if delimiter_index == 0:
            input_string = input_string[len(delimiter):]
        else:
            substrings.append(input_string[:delimiter_index])
            input_string = input_string[delimiter_index + len(delimiter):]

        split(input_string, substrings)

    split(input_string, substrings)
