def is_valid_mathematical_expression(expression):
    parentheses_stack = []
    brackets_stack = []
    curly_braces_stack = []

    for char in expression:
        if char == '(':
            parentheses_stack.append(char)
        elif char == ')':
            if not parentheses_stack:
                return False
            else:
                parentheses_stack.pop()
        elif char == '{':
            brackets_stack.append(char)
        elif char == '}':
            if not brackets_stack:
                return False
            else:
                brackets_stack.pop()
        elif char == '[':
            curly_braces_stack.append(char)
        elif char == ']':
            if not curly_braces_stack:
                return False
            else:
                curly_braces_stack.pop()

    if parentheses_stack or brackets_stack or curly_braces_stack:
        return False
    else:
        return True

