def find_peak(nums: List[int]) -> Optional[int]:
    """
    Finds the first element that is greater than both its neighboring elements, if any.
    If there are no such elements, returns `None`.
    """
    for i in range(1, len(nums) - 1):
        if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
            return nums[i]

    return None

def calculate_power_of_two(num: int):
    """
    Calculates the power of two for a given integer. If the result exceeds the maximum
    value of an integer, returns `None`.
    """
    if num == 0:
        return 0
    elif num < 0:
        return None
    elif num == 1:
        return num
    else:
        result = 1
        while result <= num:
            result <<= 1
        return result >> 1

