def binary_file_shift(in_filename, out_filename):
    try:
        with open(in_filename, 'rb') as in_file, open(out_filename, 'wb') as out_file:
            while True:
                byte = in_file.read(1)
                if not byte:
                    break
                shifted_byte = byte >> 1
                out_file.write(shifted_byte)
    except Exception as e:
        return f'Error: {str(e)}'
    finally:
        in_file.close()
        out_file.close()

