def parse_commands(commands_string):
    commands = []

    tokens = commands_string.split(',')

    for token in tokens:
        command_name, *args = token.split(':')
        command_name = command_name.strip()

        if command_name == 'set':
            if len(args) != 1:
                raise ValueError('Invalid "set" command: missing argument')
            arg = int(args[0])
        elif command_name == 'add':
            if len(args) != 1:
                raise ValueError('Invalid "add" command: missing argument')
            arg = str(args[0])
        elif command_name == 'remove':
            if len(args) != 1:
                raise ValueError('Invalid "remove" command: missing argument')
            arg = float(args[0])
        elif command_name == 'display':
            if len(args) != 0:
                raise ValueError('Invalid "display" command: unexpected argument')
            arg = None
        else:
            raise ValueError(f'Invalid command: {command_name}')

        commands.append({'name': command_name, 'arg': arg})

    return commands

