def integral_image(image):
    integral_image = [[0] * (len(image[0]) + 1) for _ in range(len(image) + 1)]
    for i in range(1, len(image) + 1):
        for j in range(1, len(image[0]) + 1):
            integral_image[i][j] = image[i - 1][j - 1] + integral_image[i - 1][j] + integral_image[i][j - 1] - integral_image[i - 1][j - 1]
