    for column_name, value in attributes.items():
        if value is None:
            parameter = 'NULL'
        else:
            parameter = f'%s'
            parameters.append(value)
        column_set_clause += f'{column_name} = {parameter}, '
    column_set_clause = column_set_clause[:-2]
    where_clause = 'WHERE '
