import urllib.parse

def parse_url_query_string(query_string: str) -> dict:
    query_pairs = query_string.split('&')
    params = {}
    for query_pair in query_pairs:
        key, value = query_pair.split('=')
        params[key] = urllib.parse.unquote(value)
    return params

