def reverse_order(my_list):
    def reverse_two(i, j):
        my_list[i], my_list[j] = my_list[j], my_list[i]

    def reverse_all():
        for i in range(len(my_list) // 2):
            reverse_two(i, len(my_list) - i - 1)

    return reverse_all

