import re

def is_text_node(node, regex):
    if node.nodeType == 3:  # Text node
        if re.match(regex, node.data):
            return True
    elif node.nodeType == 1:  # Element node
        for child in node.childNodes:
            if is_text_node(child, regex):
                return True
    return False

def find_intervals(numbers):
    numbers.sort()
    intervals = []
    current_interval = None
    for num in numbers:
        if current_interval is None or num == current_interval[1] + 1:
            if current_interval is None:
                current_interval = [num, num]
            else:
                current_interval[1] = num
        else:
            intervals.append(current_interval)
            current_interval = [num, num]
    if current_interval is not None:
        intervals.append(current_interval)

    return intervals

