def bfs_traverse(root):
    if root is None:
        return []

    queue = [root]
    res = [[root.val]]

    while queue:
        next_level = []
        for node in queue:
            if node.left:
                next_level.append(node.left)
            if node.right:
                next_level.append(node.right)
        if next_level:
            res.append([node.val for node in next_level])
        queue = next_level

    return res

