def add_one(num: int) -> int:
    def increment(num: int, pos: int) -> int:
        if pos == 0:  # Add one to the least significant digit
            return num + 1
        else:
            return ((num // (10 ** pos)) * (10 ** pos)) + increment(num % (10 ** pos), pos - 1)

    return increment(num, len(str(num)) - 1)

def gcd_euclid(*args):
    if any(num <= 0 for num in args):
        return ()
    gcds = [gcd(args[0], args[1])]
    for i in range(1, len(args) - 1):
        gcds.append(gcd(args[i], args[i + 1]))

    return tuple(gcds)


