from abc import ABC, abstractmethod

class TeamSportsLeague(ABC):
    @abstractmethod
    def get_home_team(self):
        pass

    @abstractmethod
    def get_away_team(self):
        pass

    @abstractmethod
    def get_home_goals(self):
        pass

    @abstractmethod
    def get_away_goals(self):
        pass

    def get_game_winner(self):
        if len(self.get_home_goals()) > len(self.get_away_goals()):
            return self.get_home_team()
        elif len(self.get_home_goals()) < len(self.get_away_goals()):
            return self.get_away_team()
        else:
            return "Draw"

    def get_game_loser(self):
        if len(self.get_home_goals()) < len(self.get_away_goals()):
            return self.get_home_team()
        elif len(self.get_home_goals()) > len(self.get_away_goals()):
            return self.get_away_team()
        else:
            return "Draw"

    def get_score(self):
        return f"{len(self.get_home_goals())} - {len(self.get_away_goals())}"

    def get_home_points(self):
        if self.get_game_winner() == self.get_home_team():
            return 3
        elif self.get_game_winner() == "Draw":
            return 1
        else:
            return 0

    def get_away_points(self):
        if self.get_game_winner() == self.get_away_team():
            return 3
        elif self.get_game_winner() == "Draw":
            return 1
        else:
            return 0

