def xor_encrypt(string, key):
    result = bytearray()
    for i in range(len(string)):
        result.append(ord(string[i]) ^ ord(key[i % len(key)]))
    return result

def xor_decrypt(encrypted_string, key):
    result = bytearray()
    for i in range(len(encrypted_string)):
        result.append(encrypted_string[i] ^ ord(key[i % len(key)]))
    return result.decode()

