import json

def parse_log_entries(filehandle):
    entries = []
    entry_pattern = re.compile(r"^\[(.*?)\] (.*?): (.*)$")

    for line in filehandle:
        match = entry_pattern.match(line)
        if match:
            timestamp, log_type, message = match.groups()
            try:
                message_data = json.loads(message)
                entry = {
                    "timestamp": timestamp,
                    "type": log_type,
                    "message": message_data
                }
                entries.append(entry)
            except json.JSONDecodeError:
                pass

    return entries

def complex_valued_neural_network(network_parameters):
    network = []

    for i in range(len(network_parameters)):
        weight = complex(network_parameters[i].real, 0)
        bias = complex(0, network_parameters[i].imag)
        neuron = weight + bias

        if i == 0:
            activation_function = "sigmoid"
        elif i == len(network_parameters) - 1:
            activation_function = "softmax"
        else:
            activation_function = "relu"

        network.append((neuron, activation_function))

    return network

def range_generator(start, end, step=1):
    if step == 0:
        raise ValueError("Step size cannot be zero")
    direction = 1 if step > 0 else -1
    if direction == 1:
        current = start
        upper_bound = end
    else:
        current = end - 1
        upper_bound = start - 1
    while current * direction < upper_bound * direction:
        yield current
        current += step

