import time

def spawn_and_wait(N, command, timeout):
    processes = []
    for i in range(N):
        processes.append(subprocess.Popen(command, shell=True))

    for i in range(len(processes)):
        result = processes[i].poll()
        if result is None:
            time.sleep(timeout)
            result = processes[i].poll()
        if result is None:
            return processes[i].pid
        elif result != 0:
            return processes[i].pid

    return 0

