def is_prime_deterministic(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True
def is_prime_probabilistic(n):
    a = randint(2, n - 1)
    return pow(a, n - 1, n) == 1
def is_prime(n):
    if is_prime_deterministic(n):
        return True
    if is_prime_probabilistic(n):
        return True
    return False

