def create_alias(original_func):
    signature = inspect.signature(original_func)
    docstring = inspect.getdoc(original_func)
    def alias_func(*args, **kwargs):
        ret = original_func(*args, **kwargs)
        return int(ret) if ret.is_integer() else float(ret.rstrip('0'))
