import math

def is_prime(num):
    if num <= 1:
        return False
    sqrt = int(math.sqrt(num))
    for i in range(2, sqrt + 1):
        if num % i == 0:
            return False
    return True

def smallest_prime_factor(num):
    if is_prime(num):
        return True
    sqrt = int(math.sqrt(num))
    for i in range(3, sqrt + 1, 2):
        if num % i == 0:
            return i
    return num

