def compare_time_ranges(time_ranges, other_time_ranges):
    overlaps = []

    for time_range in time_ranges:
        for other_time_range in other_time_ranges:
            start_time, end_time = time_range
            other_start_time, other_end_time = other_time_range

            if (start_time >= other_start_time and start_time <= other_end_time) or (other_start_time >= start_time and other_start_time <= end_time):
                overlap_start_time = max(start_time, other_start_time)
                overlap_end_time = min(end_time, other_end_time)
                overlaps.append((overlap_start_time, overlap_end_time))

    return overlaps

