def utf8_encoding_length(string: str) -> int:
    if not string:
        return 0

    num_bytes = 0
    for char in string:
        code_point = ord(char)
        if code_point < 128:
            num_bytes += 1
        elif code_point < 2048:
            num_bytes += 2
        elif code_point < 65536:
            num_bytes += 3
        else:
            num_bytes += 4

    return num_bytes

def largest_sum_subsequence(matrix):
    if not matrix:
        return 0
    if len(matrix) == 1 and len(matrix[0]) == 1:
        return matrix[0][0]
    dp = [[0] * len(matrix[0]) for _ in range(len(matrix))]
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            adjacent_cells = [(i-1, j-1), (i-1, j), (i-1, j+1), (i, j-1), (i, j+1), (i+1, j-1), (i+1, j), (i+1, j+1)]
            for x, y in adjacent_cells:
                if 0 <= x < len(matrix) and 0 <= y < len(matrix[0]):
                    dp[i][j] = max(dp[i][j], dp[x][y])

            dp[i][j] += matrix[i][j]
    return max(max(row) for row in dp)

def convert_to_table(data):
    if not data:
        return ""

    headers = data[0].keys()
    columns = zip(*data)
    column_lengths = [max(map(len, str(value))) for value in columns]
    header_lengths = [max(map(len, header)) for header in headers]

    def format_value(value):
        if value is None:
            return " " * max(column_lengths)
        return str(value).ljust(max(column_lengths, key=len))

    def format_header(header):
        return header.ljust(max(header_lengths, key=len))

    formatted_headers = "  ".join(map(format_header, headers))
    formatted_data = [
        "  ".join(map(format_value, row)) for row in data
    ]

    return formatted_headers + "\n" + "\n".join(formatted_data)

