def simulate_live_queue(people: List[Person], checkpoint_func: callable) -> List[Person]:
    """
    Simulates a live queue.

    Args:
        people (List[Person]): A list of people to process through the queue.
        checkpoint_func (callable): A function that takes a person as input and returns True if they have reached the stage, or False if they have been rejected.

    Returns:
        List[Person]: A list of people who have reached the stage.
    """
    reached = []
    queue = people[:]
    while queue:
        person = queue.pop(0)
        try:
            if checkpoint_func(person):
                reached.append(person)
            else:
                queue.append(person)
        except AssertionError as ex:
            print(f"Error processing person {person}: {ex}")
            continue

    return reached

