def flatten_dict(d, parent_key="", sep="."):
    counter = {}
    result = {}

    def item_key(key):
        count = counter.get(key, 0)
        counter[key] = count + 1
        return key + sep + str(count) if count > 0 else key

    for k, v in d.items():
        key = parent_key + sep + k if parent_key else k
        if isinstance(v, dict):
            result.update(flatten_dict(v, parent_key=key, sep=sep))
        else:
            result[item_key(key)] = v

    return result

