import urllib.parse

def send_http_post_request(url: str, data: dict, headers: dict = {}) -> str:
    parsed_url = urllib.parse.urlparse(url)
    if not (parsed_url.scheme == 'http' or parsed_url.scheme == 'https'):
        raise ValueError('Invalid URL scheme')
    request = urllib.request.Request(url, data=urllib.parse.urlencode(data).encode('utf-8'), headers=headers)
    try:
        response = urllib.request.urlopen(request, timeout=5)
    except (urllib.error.HTTPError, urllib.error.URLError) as e:
        return f'Request failed with status code {e.code}'
    content_type = response.info().get('Content-Type')
    if 'application/json' in content_type:
        return response.read().decode('utf-8')
    elif 'text/html' in content_type:
        return response.read().decode('utf-8')
    else:
        return response.read()

