class Conv2d:
    def __init__(self, kernel_size):
        self.kernel_size = kernel_size

    def apply_convolution(self, image):
        if self.kernel_size > image.shape[1] or self.kernel_size > image.shape[2]:
            return "Error: Kernel size is larger than the image."

        if not hasattr(self, "kernel"):
            self.kernel = torch.rand(self.kernel_size, self.kernel_size)

        result = torch.zeros(image.shape)
        for i in range(image.shape[1] - self.kernel_size + 1):
            for j in range(image.shape[2] - self.kernel_size + 1):
                patch = image[:, i:i+self.kernel_size, j:j+self.kernel_size]
                result[0, i, j] = torch.sum(patch * self.kernel)

        return result

