def deepest_node(root):
    def dfs(node, depth):
        if not node:
            return None, 0

        if not node.left and not node.right:
            return node.val, depth

        max_left, max_depth_left = dfs(node.left, depth + 1)
        max_right, max_depth_right = dfs(node.right, depth + 1)

        if max_depth_left > max_depth_right:
            return max_left, max_depth_left
        else:
            return max_right, max_depth_right

    deepest, depth = dfs(root, 0)
    return deepest

