def has_adjacent_true(arr):
    num_rows, num_cols = arr.shape
    new_arr = np.empty(arr.shape, dtype=bool)
    for row in range(num_rows):
        for col in range(num_cols):
            if arr[row, col]:
                new_arr[row, col] = True
            else:
                if row > 0 and arr[row - 1, col]:
                    new_arr[row, col] = True
                elif row < num_rows - 1 and arr[row + 1, col]:
                    new_arr[row, col] = True
                elif col > 0 and arr[row, col - 1]:
                    new_arr[row, col] = True
                elif col < num_cols - 1 and arr[row, col + 1]:
                    new_arr[row, col] = True
                else:
                    new_arr[row, col] = False

    return new_arr

