def find_furthest_corners(coordinates):
    max_distance = 0
    max_corner_coords = None
    for i in range(len(coordinates)):
        for j in range(i + 1, len(coordinates)):
            distance = np.linalg.norm(np.array(coordinates[i]) - np.array(coordinates[j]))
