def dec_to_hex(num):
    hex_chars = {10: 'A', 11: 'B', 12: 'C', 13: 'D', 14: 'E', 15: 'F'}
    result = []
    while num > 0:
        remainder = num % 16
        if remainder <= 9:
            result.append(str(remainder))
        else:
            result.append(hex_chars[remainder])
        num //= 16
    return ''.join(result[::-1])

