def num_paths(maze):
    num_paths = [[0] * len(maze[0]) for _ in range(len(maze))]
    num_paths[0][0] = 1 if maze[0][0] == 0 else 0
    for i in range(len(maze)):
        for j in range(len(maze[0])):
            if i == 0 and j == 0:
                continue
            if maze[i][j] == 1:
                num_paths[i][j] = 0
            else:
                num_paths[i][j] = num_paths[i - 1][j] + num_paths[i][j - 1]
    return num_paths[-1][-1]

