def binary_search(weights, random_value):
    start = 0
    end = len(weights) - 1

    while start <= end:
        mid = (start + end) // 2
        weight_to_left = sum(weights[:mid])
        weight_to_right = sum(weights[mid + 1:])

        if weight_to_left <= random_value < weight_to_left + weights[mid]:
            return mid
        elif random_value < weight_to_left:
            end = mid - 1
        else:
            start = mid + 1

    return None

