        if option_config["required"] and option_name not in args:
            return f"Error: Required option '{option_name}' is missing"
        if option_name not in args:
            result[option_name] = option_config["default"]
            continue
        try:
            if option_config["type"] == int:
                result[option_name] = int(args[option_name])
            elif option_config["type"] == float:
                result[option_name] = float(args[option_name])
            elif option_config["type"] == str:
                result[option_name] = str(args[option_name])
            else:
                raise Exception("Invalid option type")
