class Triangle:
    def __init__(self, a, b, c):
        self.a = a
        self.b = b
        self.c = c

    @classmethod
    def check_triangle(cls, a, b, c):
        if a + b <= c or a + c <= b or b + c <= a:
            raise ValueError("Invalid triangle side lengths")
        return cls(a, b, c)

    def calculate_area(self):
        s = (self.a + self.b + self.c) / 2
        area = sqrt(s * (s - self.a) * (s - self.b) * (s - self.c))
        return area

def resolve_dependencies(dependency_dict):
    visited = {}
    result = []
    def dfs(package):
        if package in visited:
            return
        visited[package] = True
        dependencies = dependency_dict.get(package, [])
        for dep in dependencies:
            dfs(dep)
        result.append(package)
    for package in dependency_dict:
        dfs(package)
    return result

