    digits = "0123456789abcdefghijklmnopqrstuvwxyz"[:base]
    def convert(number):
        if number < 0:
            sign = "-"
            number = abs(number)
        else:
            sign = ""
        result = ""
        while number > 0:
            number, remainder = divmod(number, base)
            result = digits[remainder] + result

        return sign + result

    return convert

