import torch

def count_zeros_in_rows(tensor):
    if not isinstance(tensor, torch.Tensor):
        raise ValueError("Input must be a PyTorch tensor")
    if len(tensor.shape) != 2:
        raise ValueError("Input tensor must be 2D")

    if tensor.is_cuda:
        tensor = tensor.cpu()  # Move the tensor to CPU if it's on GPU

    num_rows = tensor.shape[0]
    num_zeros = []
    for row_idx in range(num_rows):
        row_tensor = tensor[row_idx]
        zeros_mask = torch.eq(row_tensor, torch.tensor([0]))
        num_zeros.append(zeros_mask.sum().item())

