def find_contiguous_shape(matrix):
    visited = set()
    shape_cells = []

    def dfs(i, j):
        if (i, j) in visited or matrix[i][j] == 0:
            return
        visited.add((i, j))
        shape_cells.append((i, j))
        for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
            if 0 <= x < len(matrix) and 0 <= y < len(matrix[0]):
                dfs(x, y)

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            dfs(i, j)

    return shape_cells

def dfs(vertices, adjacency_matrix):
    """
    Performs a depth-first traversal of the graph, starting from the first vertex. Yields
    vertex visits as they occur.
    """
    visited = set()

    def dfs_helper(vertex):
        visited.add(vertex)
        yield vertex
        for neighbor in range(len(adjacency_matrix[vertex])):
            if adjacency_matrix[vertex][neighbor] and neighbor not in visited:
                yield from dfs_helper(neighbor)

    yield from dfs_helper(0)

