def count_white_squares(grid):
    if not isinstance(grid, list):
        raise ValueError('The input must be a list representing a 2D array.')
    if not all(isinstance(row, list) for row in grid):
        raise ValueError('Each element of the input must be a list representing a row.')
    if not all(len(row) == len(grid[0]) for row in grid):
        raise ValueError('The rows of the input must be of equal length.')
    if not all(isinstance(element, int) for row in grid for element in row):
        raise ValueError('Each element of the input must be an integer.')
    if not all(element in {0, 1} for row in grid for element in row):
        raise ValueError('Each element of the input must be either 0 or 1.')
    if not all(grid[0][i] == 1 for i in range(len(grid[0]))):
        raise ValueError('The first row of the input must be filled with 1s.')
    if not all(grid[-1][i] == 1 for i in range(len(grid[-1]))):
        raise ValueError('The last row of the input must be filled with 1s.')
    if not all(grid[i][0] == 1 for i in range(len(grid))):
        raise ValueError('The first column of the input must be filled with 1s.')
    if not all(grid[i][-1] == 1 for i in range(len(grid))):
        raise ValueError('The last column of the input must be filled with 1s.')
    return sum(element == 0 for row in grid for element in row)

