import math

def primes_up_to(n: int) -> int:
    """
    Generates all prime numbers up to and including `n`.

    Args:
        n (int): The maximum number to generate prime numbers up to.

    Yields:
        int: The generated prime numbers.
    """
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.sqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    for i in range(2, n + 1):
        if is_prime[i]:
            yield i

