def count_pattern_substring_occurrences(pattern, text):
    def compute_lps(pattern):
        """
        Computes the LPS (Longest Proper Suffix) array for a given pattern.

        Args:
            pattern: The pattern string for which to compute the LPS array.

        Returns:
            A list representing the LPS array for the pattern.
        """
        lps = [0] * len(pattern)
        i = 1
        len_lps = 0

        while i < len(pattern):
            if pattern[i] == pattern[len_lps]:
                len_lps += 1
                lps[i] = len_lps
                i += 1
            else:
                if len_lps != 0:
                    len_lps = lps[len_lps - 1]
                else:
                    lps[i] = 0
                    i += 1

        return lps

    lps = compute_lps(pattern)
    i = 0
    j = 0
    count = 0

    while i < len(text):
        if text[i] == pattern[j]:
            i += 1
            j += 1

            if j == len(pattern):
                count += 1
                j = lps[j - 1]
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return count

