def corner_to_center(corner):
    center = {
        'x': (corner['left'] + corner['right']) / 2,  # Average of x-coordinates
        'y': (corner['top'] + corner['bottom']) / 2   # Average of y-coordinates
    }
    width = corner['right'] - corner['left']
    height = corner['bottom'] - corner['top']
    return {'center': center, 'width': width, 'height': height}

