def shunting_yard(input_string: str) -> str:
    """
    Converts an infix arithmetic expression to a postfix expression.
    """
    output = []
    stack = []

    precedence = {
        "*": 3,
        "/": 3,
        "+": 2,
        "-": 2,
        "(": 1,
        ")": 1,
    }

    for char in input_string:
        if char.isdigit() or char.isalpha():  # operand
            output.append(char)
        elif char == "(":
            stack.append(char)
        elif char == ")":
            while stack and stack[-1] != "(":
                output.append(stack.pop())
            stack.pop()  # discard "("
        elif char in precedence:
            while stack and precedence[stack[-1]] >= precedence[char]:
                output.append(stack.pop())
            stack.append(char)
        elif char == " ":
            continue
        else:
            raise ValueError(f"Invalid character: {char}")

    while stack:
        output.append(stack.pop())

    return " ".join(output)

