import json

def format_json(json_string):
    def dump_json(obj):
        if isinstance(obj, dict):
            return {k: dump_json(v) for k, v in sorted(obj.items())}
        elif isinstance(obj, list):
            return [dump_json(v) for v in obj]
        else:
            return obj
    obj = json.loads(json_string)
    obj = {k: dump_json(v) for k, v in sorted(obj.items())}
    return json.dumps(obj, indent=4, sort_keys=True, default=dump_json)

func_counts = {}

def count_calls(func):
    func_name = func.__name__
    counter = 0

    def wrapper(*args, **kwargs):
        nonlocal counter
        counter += 1
        func_counts[func_name] = counter
        return func(*args, **kwargs)

    return wrapper

