from typing import Any, Dict

@dataclass
class Person:
    first_name: str
    last_name: str
    age: int

    def to_dict(self) -> Dict[str, Any]:
        """Converts the object to a dictionary using custom attribute renaming."""
        return {field.name: getattr(self, field.name) for field in fields(self)}

    @staticmethod
    def json_default(obj: Any) -> Any:
        """Custom serialization function for specific data types."""
        if isinstance(obj, Person):
            return obj.to_dict()
        else:
            raise TypeError(f"Object of type {type(obj)} is not JSON serializable")

    def to_json(self) -> str:
        """Serializes the object to JSON format."""
        return json.dumps(self, default=self.json_default)

