def find_largest_negative(matrix):
    if not matrix:
        return None
    largest_negative = None
    largest_negative_location = None
    for row_num, row in enumerate(matrix):
        for col_num, element in enumerate(row):
            if element < 0 and (largest_negative is None or element > largest_negative):
                largest_negative = element
                largest_negative_location = (row_num, col_num)
    return largest_negative_location

import re

def parse_global_attributes(s):
    if not re.match(r'\[.*\]', s):
        raise ValueError('Invalid global attributes string.')
    global_attributes = {}
    for m in re.finditer(r'(?P<key>\w+): (?P<value>[^;]+)', s):
        key, value = m.group('key'), m.group('value')
        global_attributes[key] = value

    return global_attributes

