def min_coins(coins, target):
    dp = [float('inf')] * (target + 1)
    dp[0] = 0  # Base case
    for coin in coins:
        for i in range(coin, target + 1):
            dp[i] = min(dp[i], dp[i-coin] + 1)

    return dp[target]

