class InvalidEncodingError(Exception):
    pass

def read_file_and_print(file_path: str, encoding: str = 'utf-8') -> None:
    if not file_path:
        raise ValueError("No file path provided.")
    if not encoding:
        raise ValueError("No encoding provided.")
    try:
        "test".encode(encoding)
    except LookupError:
        raise InvalidEncodingError(f"Invalid encoding: {encoding}")
    try:
        with open(file_path, 'r', encoding=encoding) as f:
            while True:
                chunk = f.read(4096)
                if not chunk:
                    break
                print(chunk, end='')
    except FileNotFoundError as e:
        raise ValueError(f"Error opening file: {e}")
    except UnicodeDecodeError as e:
        raise ValueError(f"Error decoding file with encoding {encoding}: {e}")

