Option = namedtuple('Option', 'id value')

def find_default_option(options, id):
    same_id_value_options = []
    for option in options:
        if option['id'] == id and option['value'] not in [o['value'] for o in same_id_value_options]:
            same_id_value_options.append(option)
    for option in same_id_value_options:
        if option['is_default'] == True:
            return option
    return Option(id=None, value=None)

