from typing import List

def apply_rules(nums: List[int]) -> List[bool]:
    """
    Applies the following rules to a list of integers:
    - If the input integer is negative, the output should be False.
    - If the input integer is 0, the output should be True.
    - If the input integer is positive, the output should be the result of applying the `is_prime` function to the input integer.
    """
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    return [False if num < 0 else True if num == 0 else is_prime(num) for num in nums]

