import json

def find_all_integer_values(json_str):
    try:
        data = json.loads(json_str)
    except ValueError:
        return []

    def traverse(obj):
        if isinstance(obj, dict):
            return [val for val in obj.values() if isinstance(val, int)]
        elif isinstance(obj, list):
            return [val for val in obj if isinstance(val, int)]
        else:
            return []

    result = []
    stack = [data]
    while stack:
        obj = stack.pop()
        result.extend(traverse(obj))
        if isinstance(obj, dict):
            stack.extend(obj.values())
        elif isinstance(obj, list):
            stack.extend(obj)
    return result

