def check_nesting(list_of_tuples):
    left_parens, right_parens = 0, 0
    left_brackets, right_brackets = 0, 0
    left_curly_brackets, right_curly_brackets = 0, 0

    for item in list_of_tuples:
        if item == '(':
            left_parens += 1
        elif item == ')':
            right_parens += 1
        elif item == '[':
            left_brackets += 1
        elif item == ']':
            right_brackets += 1
        elif item == '{':
            left_curly_brackets += 1
        elif item == '}':
            right_curly_brackets += 1

    return (
        left_parens == right_parens
        and left_brackets == right_brackets
        and left_curly_brackets == right_curly_brackets
    )

