def group_files_by_category(file_paths: List[str], extension_to_category: Dict[str, str]) -> Dict[str, List[str]]:
    """
    Groups the file paths by their file extensions and assigns each group to the corresponding category.
    The output is a dictionary with category names as keys and lists of file names as values.
    Sort the file names in each category alphabetically.
    If the input file paths are empty, return an empty dictionary.
    """
    if not file_paths:
        return {}
    file_extensions = [os.path.splitext(path)[1] for path in file_paths]
    categories = [extension_to_category.get(ext, "Unknown") for ext in file_extensions]
    grouped_paths = {category: [] for category in set(categories)}
    for path, category in zip(file_paths, categories):
        grouped_paths[category].append(path)
    for category in grouped_paths:
        grouped_paths[category].sort()

    return grouped_paths

def fibonacci_tail_recursion(n):
    """
    Compute the n-th Fibonacci number using tail recursion.

    Args:
        n (int): The index of the Fibonacci number to compute.

    Returns:
        int: The n-th Fibonacci number.

    Precondition:
        n must be a non-negative integer.

    Raises:
        ValueError: If n is negative.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer.")

    def helper(n, prev=0, curr=1):
        if n == 0:
            return prev
        if n == 1:
            return curr
        return helper(n - 1, curr, prev + curr)

    return helper(n)

