import torch

def calculate_loss(preds: torch.Tensor, labels: torch.Tensor) -> float:
    """
    Calculates the loss between two tensors of the same shape.
    The loss is defined as the absolute value of the difference if the tensors are of size 1,
    otherwise it's the mean absolute error.
    """
    if preds.shape != labels.shape:
        raise ValueError("Input tensors must have the same shape.")
    diff = torch.abs(preds - labels)
    if preds.numel() == 1:
        return torch.abs(diff).item()
    else:
        return torch.mean(diff).item()

