def move_to_waypoints(waypoints):
    moves = []
    robot_position = (0, 0)
    while waypoints:
        closest_waypoint = waypoints.pop(0)
        if robot_position == closest_waypoint:
            continue  # Robot is already at the waypoint, so no move is required
        diff = (closest_waypoint[0] - robot_position[0], closest_waypoint[1] - robot_position[1])
        if diff[0] > 0:
            moves.append('R')  # Move right
        elif diff[0] < 0:
            moves.append('L')  # Move left
        if diff[1] > 0:
            moves.append('U')  # Move up
        elif diff[1] < 0:
            moves.append('D')  # Move down
        robot_position = closest_waypoint

    return moves

