import torch

def normalize_tensor(tensor):
    if not isinstance(tensor, torch.FloatTensor):
        tensor = tensor.float()
    mean = torch.mean(tensor)
    std = torch.std(tensor)
    normalized = (tensor - mean) / std
    if isinstance(tensor, torch.IntTensor):
        normalized = normalized.int()
    if tensor.is_cuda:
        normalized = normalized.cuda()

    return normalized

