def reverse_list(head):
    if not head:
        return head  # Empty list
    if not head.next:
        return head  # List with one element

    def reverse_helper(current, prev):
        if not current:  # Base case: Reached the end of the list
            return prev

        next_node = current.next
        current.next = prev
        prev = current
        current = next_node
        return reverse_helper(current, prev)

    return reverse_helper(head.next, head)

