def clean_grid(grid):
    m = len(grid)
    n = len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or visited[i][j] or grid[i][j] != 0:
            return
        visited[i][j] = True
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                dfs(i, j)

    for i in range(m):
        for j in range(n):
            if visited[i][j]:
                grid[i][j] = 1

