    if len(points) < 3:
        raise ValueError("The input is not a valid polygon.")
    x1, y1 = points[0]
    x2, y2 = points[1]
    x3, y3 = points[2]
    det = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1)
    if det > 0:
        return 1  # clockwise
    elif det < 0:
        return -1  # counterclockwise
    else:
        return 0  # special point

