def binary_search(lst, target):
    left, right = 0, len(lst) - 1
    while left <= right:
        mid = (left + right) // 2
        if lst[mid] < target:
            left = mid + 1
        elif lst[mid] > target:
            right = mid - 1
        else:
            return mid
    return -1
def binary_search_recursive(lst, target, left=0, right=None):
    if right is None:
        right = len(lst) - 1
    if left > right:
        return -1
    mid = (left + right) // 2
    if lst[mid] < target:
        return binary_search_recursive(lst, target, mid + 1, right)
    elif lst[mid] > target:
        return binary_search_recursive(lst, target, left, mid - 1)
    else:
        return mid

