import types

def create_binary_tree_module(node_value_type, node_key_type):
    class BinaryTree:
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.left = None
            self.right = None

        def insert(self, key, value):
            if key < self.key:
                if self.left is None:
                    self.left = BinaryTree(key, value)
                else:
                    self.left.insert(key, value)
            elif key > self.key:
                if self.right is None:
                    self.right = BinaryTree(key, value)
                else:
                    self.right.insert(key, value)
            else:
                self.value = value

        def find(self, key):
            if key < self.key:
                if self.left is None:
                    return None
                else:
                    return self.left.find(key)
            elif key > self.key:
                if self.right is None:
                    return None
                else:
                    return self.right.find(key)
            else:
                return self.value

        def delete(self, key):
            if key < self.key:
                if self.left is not None:
                    self.left = self.left.delete(key)
            elif key > self.key:
                if self.right is not None:
                    self.right = self.right.delete(key)
            else:
                if self.left is None:
                    return self.right
                elif self.right is None:
                    return self.left
                else:
                    min_node = self.right
                    while min_node.left is not None:
                        min_node = min_node.left
                    self.key = min_node.key
                    self.value = min_node.value
                    self.right = self.right.delete(min_node.key)
            return self

        def traverse(self):
            result = []
            if self.left:
                result += self.left.traverse()
            result.append((self.key, self.value))
            if self.right:
                result += self.right.traverse()
            return result
    module = types.ModuleType('BinaryTree')
    setattr(module, 'BinaryTree', BinaryTree)
    return module

