    Args:
        n (float or str or None): The number to be checked.
        is_positive (bool): Flag to indicate whether the number needs to be positive.

    Returns:
        bool: `True` if the number is valid, `False` otherwise.

    Raises:
        ValueError: If the provided number is not a string nor a number.
    """
    if n is None:
        return False
    if isinstance(n, str):
        try:
            n = float(n)
        except ValueError:
            return False
    if not isinstance(n, (int, float)):
        raise ValueError("The provided number is not a string nor a number.")
    if is_positive and n < 0:
        return False
    return True

