def point_in_line_segment(x1, y1, x2, y2, x3, y3):
    line_length = sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)
    vector_projection = ((x3 - x1) * (x2 - x1) + (y3 - y1) * (y2 - y1)) / line_length ** 2
    if 0 <= vector_projection <= line_length:
        return True
    else:
        return False

def ascii_to_hex(text):
    hex_representation = ''

    for char in text:
        ascii_code = ord(char)
        hex_code = '{:02x}'.format(ascii_code)
        hex_representation += hex_code + ' '

    return hex_representation.strip()

