import re

def unique_name(input_string, counter=None):
    if not input_string or not isinstance(input_string, str) or not re.match(r"^[a-zA-Z0-9]+$", input_string):
        raise ValueError("Invalid input string. Input string must be a non-empty string containing only alphanumeric characters.")
    if counter is not None and not isinstance(counter, int):
        raise TypeError("Counter must be an integer.")
    unique_names = set(["Default"])
    while True:
        if counter is not None:
            name = f"{input_string}{counter}"
        else:
            name = input_string
        if name not in unique_names:
            unique_names.add(name)
            return name
        else:
            if counter is not None:
                counter += 1
            else:
                counter = 1

def combine_numbers(strings):
    numbers = []

    for string in strings:
        if ',' in string:
            split_numbers = string.split(',')
        else:
            split_numbers = string.split()

        for num in split_numbers:
            numbers.append(int(num))

    return numbers

import ast

def modify_ast_variable_names(node: ast.AST) -> ast.AST:
    if isinstance(node, ast.Name):
        node.id = type(node).__name__
    for field in node._fields:
        value = getattr(node, field)
        if isinstance(value, list):
            for item in value:
                modify_ast_variable_names(item)
        elif isinstance(value, ast.AST):
            modify_ast_variable_names(value)
    return node

def unique_pair_combinations(elements):
    combinations = set()
    for i, element in enumerate(elements):
        for j in range(i + 1, len(elements)):
            combinations.add((element, elements[j]))
    return combinations

def group_points(points):
    grouped_points = []
    prev_x = None
    for x, y, z in points:
        if x != prev_x:
            grouped_points.append([])
        grouped_points[-1].append((x, y, z))
        prev_x = x
    return grouped_points

