def create_tree(data, indent=False):
    nodes = {}
    root_nodes = []

    for node in data:
        node_id = node["id"]
        parent_id = node["parent_id"]
        label = node["label"]
        if node_id not in nodes:
            nodes[node_id] = {"id": node_id, "parent_id": parent_id, "label": label, "children": []}
        if parent_id is not None and parent_id in nodes:
            nodes[parent_id]["children"].append(nodes[node_id])
        else:
            root_nodes.append(nodes[node_id])
    if indent:
        def indent_label(node, level=0):
            node["label"] = "\t" * level + node["label"]
            for child in node["children"]:
                indent_label(child, level + 1)

        for node in root_nodes:
            indent_label(node)
    return root_nodes

class Node:
