import os
import fnmatch

def recursive_file_matching(root_path, pattern):
    matched_files = []
    if not os.path.exists(root_path):
        return matched_files
    if os.path.isfile(root_path):
        if fnmatch.fnmatch(os.path.basename(root_path), pattern):
            matched_files.append(root_path)
        return matched_files
    for item in os.listdir(root_path):
        item_path = os.path.join(root_path, item)
        matched_files.extend(recursive_file_matching(item_path, pattern))

    return matched_files

