def radix_sort(input_list, base=10):
    passes = len(str(max(input_list)))
    buckets = [[] for _ in range(base)]
    for p in range(passes):
        for n in input_list:
            digit = n // base ** p % base
            buckets[digit].append(n)
        input_list = [n for bucket in buckets for n in bucket]
        buckets = [[] for _ in range(base)]
    return input_list

