def dict_to_string(d: dict) -> str:
    """
    Converts a dictionary to a string representation.
    """
    def _serialize(obj):
        """
        Helper function that recursively serializes the dictionary.
        """
        if isinstance(obj, dict):
            return "{" + ", ".join(f"{k}: {_serialize(v)}" for k, v in obj.items()) + "}"
        elif isinstance(obj, list):
            return "[" + ", ".join(_serialize(v) for v in obj) + "]"
        else:
            return str(obj)

    return _serialize(d)

