from collections import deque

def find_shortest_pathway(knowledge_base, gene_set):
    queue = deque([1])  # Start with the first pathway
    visited = set()  # Keep track of visited pathways

    while queue:
        pathway = queue.popleft()
        if pathway not in visited:
            if all(gene in knowledge_base[pathway - 1][1] for gene in gene_set):
                return pathway
            for next_pathway in range(1, len(knowledge_base) + 1):
                if next_pathway not in visited and len(knowledge_base[next_pathway - 1][1].intersection(gene_set)) > 0:
                    queue.append(next_pathway)
            visited.add(pathway)

    return None

