def cartesian_product(iterable1, iterable2):
    def generate_pairs(iterable1, iterable2):
        for symbol1 in iterable1:
            for symbol2 in iterable2:
                yield (symbol1, symbol2)

    return generate_pairs(iterable1, iterable2)

def square_distance(x, y):
    if len(x) != len(y):
        raise ValueError("Vectors are not of equal length")

    square_diff_sum = 0
    for x_i, y_i in zip(x, y):
        square_diff = (x_i - y_i) ** 2
        square_diff_sum += square_diff

    return square_diff_sum

