def escape_html(text: str) -> str:
    escape_dict = {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
    }

    escaped_text = ""
    for char in text:
        if char in escape_dict:
            escaped_text += escape_dict[char]
        else:
            escaped_text += char

    return escaped_text

def gcd(a, b):
