def product_array(nums):
    prod = 1
    zero_count = 0

    for n in nums:
        if n == 0:
            zero_count += 1
        else:
            prod *= n

    if zero_count > 1:
        return [0] * len(nums)
    elif zero_count == 1:
        return [0 if n == 0 else prod for n in nums]

    return [prod // n for n in nums]

