import math

def calculate_average_std(num_list):
    num_count = len(num_list)
    if num_count == 0:
        return (0.0, 0.0)
    total = sum(num_list)
    average = total / num_count
    variance = sum((x - average) ** 2 for x in num_list) / num_count
    std = math.sqrt(variance)
    return (average, std)

