from dataclasses import dataclass
@dataclass
class Part:
    part_id: int
    loading_time: int
    manufacturing_time: int

def manufacture(parts: List[Part]) -> List[Part]:
    """
    Simulates the manufacturing process using a state machine.
    Returns a list of parts that have been manufactured successfully.
    """
    state = "LOADING"
    loading_bays = 3
    work_cells = 2
    manufactured_parts = []

    for part in parts:
        if state == "LOADING":
            if loading_bays > 0:
                loading_bays -= 1
                state = "MANUFACTURING"
            else:
                continue

        if state == "MANUFACTURING":
            if work_cells > 0:
                work_cells -= 1
                part.completion_time = part.loading_time + part.manufacturing_time
                manufactured_parts.append(part)
                state = "LOADING"
            else:
                continue

    return manufactured_parts

