def merge_sort_sublists(sublists):
    """
    Sorts the sublists in alphabetical order while preserving their original order.
    """
    if len(sublists) <= 1:
        return sublists

    mid = len(sublists) // 2
    left = merge_sort_sublists(sublists[:mid])
    right = merge_sort_sublists(sublists[mid:])

    def merge(left, right):
        merged = []
        i, j = 0, 0

        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                merged.append(left[i])
                i += 1
            elif left[i] > right[j]:
                merged.append(right[j])
                j += 1
            else:
                merged.append(left[i])
                merged.append(right[j])
                i += 1
                j += 1

        while i < len(left):
            merged.append(left[i])
            i += 1

        while j < len(right):
            merged.append(right[j])
            j += 1

        return merged

    return merge(left, right)

