import argparse

def validate_options(host, port, protocol):
    parser = argparse.ArgumentParser()
    parser.add_argument('--host', help='Hostname or IP address of the target')
    parser.add_argument('--port', type=int, help='Port number to connect to')
    parser.add_argument('--protocol', help='Protocol to use for the connection')
    if not host:
        raise ValueError('Missing required option: --host')
    if not port:
        raise ValueError('Missing required option: --port')
    if not 1 <= port <= 65535:
        raise ValueError('Invalid port number: must be between 1 and 65535')
    if not protocol:
        raise ValueError('Missing required option: --protocol')
    supported_protocols = ['http', 'https', 'ssh', 'ftp', 'sftp']
    if protocol not in supported_protocols:
        raise ValueError(f'Unsupported protocol: {protocol}. Supported protocols are: {", ".join(supported_protocols)}')
    return {'host': host, 'port': port, 'protocol': protocol}

