import numpy as np

def object_info(obj):
    attributes = {}
    methods = {}
    for name, value in vars(obj).items():
        attributes[name] = value
    for name in dir(obj):
        if callable(getattr(obj, name)):
            methods[name] = getattr(obj, name).__doc__ or 'No docstring'
    attribute_keys = np.array(list(attributes.keys()))
    attribute_values = np.array(list(attributes.values()))
    method_keys = np.array(list(methods.keys()))
    method_values = np.array(list(methods.values()))
    result = {
        'attribute_names': attribute_keys,
        'attribute_values': attribute_values,
        'method_names': method_keys,
        'method_definitions': method_values
    }
    return result

import json

def format_json(data):
    formatted_data = ""

    def format_value(value):
        nonlocal formatted_data
        if isinstance(value, str):
            formatted_data += f'"{value}"'
        elif isinstance(value, (int, float)):
            formatted_data += str(value)
        elif isinstance(value, list):
            formatted_data += "["
            for item in value:
                format_value(item)
                formatted_data += ", "
            formatted_data = formatted_data[:-2] + "]"
        elif isinstance(value, dict):
            formatted_data += "{"
            for key, val in value.items():
                formatted_data += f'"{key}": '
                format_value(val)
                formatted_data += ", "
            formatted_data = formatted_data[:-2] + "}"
        else:
            formatted_data += str(value)

    format_value(data)
    return formatted_data

