def validate_matrix(matrix):
    """
    Validates that the input matrix is a non-empty 2D list of non-empty lists.
    """
    if not isinstance(matrix, list) or not matrix:
        return False
    for row in matrix:
        if not isinstance(row, list) or not row:
            return False
    return True


def find_smallest_in_column(matrix, column_index):
    """
    Finds the smallest value in a given column of a matrix.
    """
    if not validate_matrix(matrix):
        return None
    if column_index < 0 or column_index >= len(matrix[0]):
        return None
    smallest = matrix[0][column_index]
    for row in matrix[1:]:
        smallest = min(smallest, row[column_index])
    return smallest

