def binary_string_to_decimal(binary_string: str) -> int:
    decimal_equivalent = 0
    for index, digit in enumerate(binary_string):
        digit = int(digit)
        if digit not in [0, 1]:
            raise ValueError(f"Invalid binary digit {digit} at position {index}")
        decimal_equivalent <<= 1
        decimal_equivalent += digit

    return decimal_equivalent

