class TreeNode:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def create_tree(array):
    root = None
    size = len(array)
    array_index = 0
    def insert_into_tree(node, index):
        nonlocal array_index
        if index < size:
            if node is None:
                node = TreeNode(array[index])
                array_index += 1
            node.left = insert_into_tree(node.left, 2 * index + 1)
            node.right = insert_into_tree(node.right, 2 * index + 2)
        return node
    root = insert_into_tree(root, 0)
    return root

