    for i in range(len(points)):
        for j in range(i+1, len(points)):
            dist = math.sqrt((points[i][0] - points[j][0]) ** 2 + (points[i][1] - points[j][1]) ** 2)
            distances.append(f"distance from ({points[i][0]},{points[i][1]}) to ({points[j][0]},{points[j][1]}): {dist}")
    return distances

def code_type(code: str) -> str:
    """
    Identifies the type of code in a given string. Returns "expression" if the string is a
    valid Python expression, "statement" if it is a valid Python statement, or
    "invalid" if it is neither.
    """
    try:
        compile(code, "<string>", "eval")
        return "expression"
    except SyntaxError:
        try:
            compile(code, "<string>", "exec")
            return "statement"
        except SyntaxError:
            return "invalid"

