def apply_max_pooling(image, kernel_size):
    assert isinstance(image, list) and all(isinstance(row, list) for row in image), "Image must be a 2D array"
    assert isinstance(kernel_size, int) and kernel_size > 0, "Kernel size must be a positive integer"
    assert all(len(row) == len(image[0]) for row in image), "Image must be a rectangular array"
    result = [[0] * (len(image[0]) - kernel_size + 1) for _ in range(len(image) - kernel_size + 1)]
    for i in range(len(result)):
        for j in range(len(result[0])):
            kernel_region = [row[j:j+kernel_size] for row in image[i:i+kernel_size]]
            result[i][j] = max(max(row) for row in kernel_region)

    return result

