def find_paths(tree, current_node=None, path=[]):
    if current_node is None:
        current_node = tree

    if not current_node:
        return []

    path.append(current_node[0])

    if len(current_node) == 1:
        return [path]

    paths = []

    for child in current_node[1:]:
        child_paths = find_paths(child, path=path[:])
        paths.extend(child_paths)

