def smooth(sequence, smoothing_factor=0):
    sequence = [float(x) for x in sequence]
    if smoothing_factor > 0 and smoothing_factor < 1:
        smoothed = [x * smoothing_factor + (1 - smoothing_factor) * y for x, y in
                    zip(sequence, sequence[1:] + [sequence[-1]])]
    elif smoothing_factor == 0:
        smoothed = sequence[:]
    else:
        smoothed = [sum(sequence) / len(sequence)] * len(sequence)

    return smoothed

