import random

def randomized_quick_select(array, k):
    if len(array) == 1:
        return array[0]

    pivot_index = random.randint(0, len(array) - 1)
    pivot_value = array[pivot_index]

    left = [x for x in array if x < pivot_value]
    right = [x for x in array if x > pivot_value]

    if k < len(left):
        return randomized_quick_select(left, k)
    elif k > len(left):
        return randomized_quick_select(right, k - len(left) - 1)
    else:
        return pivot_value

def parse_keywords(keywords_str):
    """
    Parses a string of keywords and their values and returns a dictionary of keywords and values.
    The string should be in the format "key1=value1, key2=value2, ...", where each key-value pair
    is separated by a comma. If a key has no value, the function sets its value to True. If a value
    is an empty string, the function sets its value to None.
    """
    return {
        key.strip(): None if value.strip() == '' else int(value) if value.isdigit() else float(value) if value.replace('.', '', 1).isdigit() else value
        for key, value in (pair.split('=') for pair in keywords_str.split(','))
    }

