def flood_fill(object_map, segmentation_map, x, y, object_id):
    object_height, object_width = object_map.shape
    if x < 0 or x >= object_width or y < 0 or y >= object_height:
        return
    if object_map[y, x] == 1 and segmentation_map[y, x] == 0:
        segmentation_map[y, x] = object_id
        flood_fill(object_map, segmentation_map, x - 1, y, object_id)
        flood_fill(object_map, segmentation_map, x + 1, y, object_id)
        flood_fill(object_map, segmentation_map, x, y - 1, object_id)
        flood_fill(object_map, segmentation_map, x, y + 1, object_id)

def create_segmentation_map(object_map):
    segmentation_map = np.zeros_like(object_map)
    object_id = 1
    for y in range(object_map.shape[0]):
        for x in range(object_map.shape[1]):
            if object_map[y, x] == 1 and segmentation_map[y, x] == 0:
                flood_fill(object_map, segmentation_map, x, y, object_id)
                object_id += 1
    return segmentation_map

import json

def generate_json(dictionary):
    def default(obj):
        if isinstance(obj, dict):
            return {key: default(value) for key, value in obj.items()}
        elif isinstance(obj, list):
            return [default(item) for item in obj]
        else:
            return obj

    json_string = json.dumps(dictionary, indent=2, default=default)
    return json_string

def tokenize_strings(strings, vocab):
