    for string in strings:
        indices = []
        for token in string.split():
            if token in vocab:
                indices.append(vocab[token])
            else:
                indices.append(-1)  # Replace this with a special index if the word is not in the vocabulary
        tokenized_strings.append(indices)

    return tokenized_strings

