import re

def round_decimal_values(strings):
    pattern = r'(\d+\.\d+)|(\d+)'  # Extract the decimal part of the string
    result = []

    for item in strings:
        match = re.search(pattern, item.strip())  # Remove leading/trailing spaces and match the pattern
        if match:
            decimal_part = match.group()
            rounded_integer = int(round(float(decimal_part)))
            result.append(rounded_integer)
        else:
            result.append(item)  # Return the original string if it doesn't match the pattern

    return result

