import math

def log_spaced_points(data, step, base):
    if not isinstance(data, list):
        raise TypeError("data must be a list")
    if not isinstance(step, (int, float)) or step <= 0:
        raise ValueError("step must be a positive number")
    if not isinstance(base, (int, float)) or base <= 0:
        raise ValueError("base must be a positive number")
    transformed_data = [math.log(d, base) for d in data]
    data_range = max(transformed_data) - min(transformed_data)
    spacing = data_range / step
    sampled_points = []
    for i in range(int(step) + 1):
        index = min(transformed_data) + i * spacing
        sampled_points.append(data[int(round(index))])

    return sampled_points

