def demultiplex(stream1, stream2, criteria):
    assert stream1 and stream2 and callable(criteria), "Invalid input"

    for value1 in stream1:
        if criteria(value1):
            yield value1

    for value2 in stream2:
        if not criteria(value2):
            yield value2

