import re

def parse_custom_file_format(lines):
    config = {}
    config['layers'] = []

    for line in lines:
        if line.startswith("#"):
            continue

        match = re.match(r"^(\w+)=(\w+)$", line)
        if not match:
            raise ValueError("Invalid line found: {}".format(line))

        key, value = match.groups()

        if key == "N":
            config['layers'].append({
                'N': int(value)
            })
        elif key == "activation":
            if len(config['layers']) == 0:
                raise ValueError("Invalid activation found before N.")

            config['layers'][-1]['activation'] = value
        else:
            raise ValueError("Invalid key found: {}".format(key))

    return config

