import re

def replace_string(string, replacement_patterns):
    def replacement_func(match):
        matched_group = match.group(0)
        if matched_group in replacement_patterns:
            return replacement_patterns[matched_group]
        return matched_group
    return re.sub('|'.join(replacement_patterns), replacement_func, string)

