def max_difference(nums):
    if not nums or len(nums) == 1:
        return 0

    max_diff = 0
    for i in range(len(nums) - 1, 0, -1):
        diff = nums[i] - nums[i - 1]
        if diff > max_diff:
            max_diff = diff
        elif diff >= max_diff:
            return max_diff

    return max_diff

