def identify_command_for_file(file_path):
    with open(file_path, 'rb') as file:
        file_signature = file.read(4) # Read the first 4 bytes of the file
        file_extension = file_path.split('.')[-1] # Extract the file extension

        compression_type = None

        if file_signature == b'PK\x03\x04':
            compression_type = 'ZIP'
        elif file_signature == b'\x1f\x8b\x08\x08':
            compression_type = 'GZIP'
        else:
            compression_type = file_extension.upper() # Default to the file extension

        commands = [('GZIP', 'gunzip'), ('ZIP', 'unzip'), ('JPEG', 'jpegtran')]

        for command_type, command in commands:
            if compression_type == command_type:
                return command

    return None # If no matching command is found

