    indices = re.findall(r"\bWHERE\s*(.*)\b", query, flags=re.IGNORECASE)
    for index in indices:
        columns = re.findall(r"\b(SELECT|FROM|WHERE|ORDER BY|GROUP BY|DISTINCT|DROP TABLE|UNION|DELETE|INSERT)\b", query, flags=re.IGNORECASE)
