import re

def recursive_class_traversal(obj, regex):
    if isinstance(obj, type):
        if re.match(regex, obj.__name__):
            module_name = obj.__module__
            module = __import__(module_name)
            return getattr(module, obj.__name__)
        else:
            for base_class in obj.__bases__:
                matched_class = recursive_class_traversal(base_class, regex)
                if matched_class:
                    return matched_class
    return None

