    Converts a JSON string to a dictionary while performing type casting.
    """
    def custom_object_hook(obj: dict) -> dict:
        """
        Custom JSON object hook function that performs type casting based on the type of each value.
        """
        for key, value in obj.items():
            if isinstance(value, str):
                try:
                    obj[key] = int(value)
                except ValueError:
                    try:
                        obj[key] = float(value)
                    except ValueError:
                        obj[key] = value
            elif isinstance(value, list):
                obj[key] = custom_object_hook(value)
