from typing import List, Tuple

def two_sum_sorted(nums: List[int], target: int) -> Tuple[int, int]:
    """
    Finds two numbers from `nums` that add up to `target`. The function returns a tuple of
    two numbers. If there are no two numbers that sum up to `target`, the function returns
    (-1, -1). The function runs in O(n log(n)) time, where `n` is the length of the list.
    """
    if len(nums) < 2:
        return (-1, -1)
    nums.sort()

    for i, num in enumerate(nums):
        complement = target - num
        left, right = i + 1, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == complement:
                return (num, complement)
            elif nums[mid] < complement:
                left = mid + 1
            else:
                right = mid - 1
    return (-1, -1)

