def infix_to_postfix(infix: str) -> str:
    stack = []
    postfix = ""
    precedence = {
        "+": 1,
        "-": 1,
        "*": 2,
        "/": 2,
    }
    for token in infix:
        if token.isdigit():
            postfix += token
        elif token in precedence:
            while stack and stack[-1] in precedence and precedence[token] <= precedence[stack[-1]]:
                postfix += stack.pop()
            stack.append(token)
        elif token == "(":
            stack.append(token)
        elif token == ")":
            while stack[-1] != "(":
                postfix += stack.pop()
            stack.pop()
    while stack:
        postfix += stack.pop()
    return postfix

