        if num % prime == 0:
            return False
    return True

def nth_prime_memoized(n: int) -> int:
    if n <= len(primes):
        return primes[n - 1]
    current_num = primes[-1] + 2
    while len(primes) < n:
        if is_prime(current_num):
            primes.append(current_num)
        current_num += 2

    return primes[n - 1]

