import numpy as np

def schulze_method(pairwise_preferences):
    num_candidates = len(pairwise_preferences)
    strength = np.zeros((num_candidates, num_candidates))
    defeater_counts = np.zeros((num_candidates, num_candidates))

    for i in range(num_candidates):
        for j in range(num_candidates):
            if i == j:
                continue
            for k in range(num_candidates):
                if pairwise_preferences[i, k] > pairwise_preferences[j, k]:
                    strength[i, j] += 1

    for i in range(num_candidates):
        for j in range(num_candidates):
            if i == j or strength[i, j] <= strength[j, i]:
                continue
            defeater_counts[i, j] = strength[j, i]

    ranks = np.zeros((num_candidates,))
    for i in range(num_candidates):
        for j in range(num_candidates):
            if i == j:
                continue
            if defeater_counts[i, j] > 0:
                ranks[i] += 1

    ranked_candidates = np.argsort(ranks)[::-1]
    return ranked_candidates

def binary_tree_paths(root):
    result = []

    def traverse(node, path):
        if node is None:
            return

        path.append(node.value)

        if node.left is None and node.right is None:
            result.append(path[:])
        else:
            traverse(node.left, path)
            traverse(node.right, path)

        path.pop()

    traverse(root, [])

    return result

