def assign_devices_to_aps(devices: List[int], aps: List[str], threshold: float) -> Dict[str, List[int]]:
    """
    Assigns devices to access points (APs) based on their IDs, AP IDs, and a threshold.
    """
    if len(devices) != len(aps):
        raise ValueError("The number of devices and APs must be equal.")

    device_count = len(devices)
    ap_count = len(set(aps))

