def ease(t, b, c, d, easing_function):
    if easing_function not in ('linear', 'ease-in', 'ease-out', 'ease-in-out'):
        return None

    if d == 0:
        return None

    if t < 0 or t > 1:
        return None

    if easing_function == 'linear':
        return t * c / d + b
    elif easing_function == 'ease-in':
        t /= d
        return c * t * t + b
    elif easing_function == 'ease-out':
        t /= d
        return -c * t * (t - 2) + b
    elif easing_function == 'ease-in-out':
        t /= d / 2
        return c / 2 * t * t * t + b
    return None

