from typing import List
from heapq import heappush, heappop

def knn_classify(training_data: List[List[float]], test_data: List[List[float]], k: int) -> List[str]:
    """
    Classifies each instance in `test_data` using k-nearest neighbors based on the `training_data`.
    """
    class_labels = []

    for test_instance in test_data:
        heap = []
        for i, training_instance in enumerate(training_data):
            distance = sum((x - y) ** 2 for x, y in zip(training_instance[:-1], test_instance))
            if len(heap) < k:
                heappush(heap, (-distance, i))
            elif distance < -heap[0][0]:
                heappop(heap)
                heappush(heap, (-distance, i))
        class_counts = {}
        for _, i in heap:
            if training_data[i][-1] not in class_counts:
                class_counts[training_data[i][-1]] = 1
            else:
                class_counts[training_data[i][-1]] += 1

        class_labels.append(max(class_counts, key=class_counts.get))

    return class_labels

