import re

def natural_sort(str_list):
    """
    Performs natural sorting on a list of strings based on the numerical values within them.
    The sorting considers each string as a list of substrings separated by one or more non-numeric characters.
    Each substring is interpreted as an integer and sorted accordingly.
    """
    def convert(string):
        return tuple(int(s) if s.isdigit() else s for s in re.split(r'(\d+)', string))

    return sorted(str_list, key=convert)

