def arbitrary_precision_exponentiation(x: Union[int, float], n: int) -> Union[int, float]:
    """
    Returns the value of x to the power n, where x is an arbitrary-precision number
    and n is an integer. The result is an arbitrary-precision number as well.
    """
    if n == 0:
        return 1
    elif n == 1:
        return x
    elif n > 0:
        result = x
        for _ in range(n - 1):
            result *= x
    else:
        result = 1 / x
        for _ in range(abs(n) - 1):
            result /= x

    return result

