    elements = re.findall(r'[A-Z][a-z]?', molecule)
    numbers = re.findall(r'[0-9]+', molecule)
    tags = {'element': elements, 'number': numbers}

    return tags

def nCk(n, k):
    if k > n:
        return 0
    result = 1
    for i in range(k):
        result *= (n - i) / (i + 1)
    return int(result)

def probability_n_k(n, k):
    return round(nCk(n, k) * (1/2)**n, 5)

