def bits_to_bytes(bits):
    """Converts a list of bits (booleans) into bytes.
    Bits must be in multiples of 8.
    """
    if len(bits) % 8 != 0:
        raise ValueError("Bits must be in multiples of 8.")

    bytes_list = []
    for i in range(0, len(bits), 8):
        byte = 0
        for j in range(8):
            byte |= bits[i + j] << (7 - j)
        bytes_list.append(byte)

    return bytes_list

