def replace_repeated_characters(s: str) -> str:
    """
    Replaces all consecutive repeated characters with a single character and the count of repetitions.
    For example, given "aaaaabbbbbbbbccc", the result should be "a5b8c3".
    """
    result = ""
    count = 0

    for i, c in enumerate(s):
        if i == 0 or c != s[i - 1]:
            if count > 0:
                result += f"{s[i - 1]}{count}"
            count = 1
        else:
            count += 1
    result += f"{s[-1]}{count}"

    return result

