class Node:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def binary_tree_depths(root):
    if not root:
        return []

    queue = [(root, 1)]  # Store the node and its depth
    result = []

    while queue:
        node, depth = queue.pop(0)  # Pop the node and its depth from the front of the queue
        if len(result) < depth:
            result.append([node.val])  # Add a new list for the new depth
        else:
            result[depth - 1].append(node.val)  # Append the node's value to the list at the correct depth

        if node.left:
            queue.append((node.left, depth + 1))  # Add the left child to the queue with an increased depth
        if node.right:
            queue.append((node.right, depth + 1))  # Add the right child to the queue with an increased depth

    return list(zip(range(1, len(result) + 1), result))  # Zip the depths and the nodes lists together

