def extract_nodes_and_attributes(objects):
    def extract_from_object(obj):
        if isinstance(obj, Node):
            return obj
        elif isinstance(obj, dict):
            return [extract_from_object(value) for value in obj.values()]
        elif isinstance(obj, list):
            return [extract_from_object(item) for item in obj]
        else:
            raise TypeError(f"Unsupported type: {type(obj)}")

    def extract_nodes(obj):
        if isinstance(obj, Node):
            return [obj]
        elif isinstance(obj, dict):
            return [node for value in obj.values() for node in extract_nodes(value)]
        elif isinstance(obj, list):
            return [node for item in obj for node in extract_nodes(item)]
        else:
            return []

    nodes = extract_nodes(extract_from_object(objects))
    return [{node.id: node.attributes} for node in nodes]

class TreeNode:
    def __init__(self, data, left=None, right=None):
        self.data = data
        self.left = left
        self.right = right

    def is_leaf(self):
        return self.left is None and self.right is None

    def pre_order(self):
        result = []
        if self:
            result.append(self.data)
            if self.left:
                result.extend(self.left.pre_order())
            if self.right:
                result.extend(self.right.pre_order())

        return result

    def in_order(self):
        result = []
        if self:
            if self.left:
                result.extend(self.left.in_order())
            result.append(self.data)
            if self.right:
                result.extend(self.right.in_order())

        return result

    def post_order(self):
        result = []
        if self:
            if self.left:
                result.extend(self.left.post_order())
            if self.right:
                result.extend(self.right.post_order())
            result.append(self.data)

        return result

