def calculate_tf_idf(tokens, frequency_dict):
    tf_idf_scores = {}
    N = len(frequency_dict)
    for token in tokens:
        tf = frequency_dict[token]
        df = sum(1 for freq in frequency_dict.values() if freq[token] > 0)
        idf = log(1 + N / df)
        tf_idf = log(1 + tf) * idf
        tf_idf_scores[token] = tf_idf
    return tf_idf_scores

