def find_combinations(input_string, target_number):
    output_list = []
    input_list = [int(i) for i in input_string.split(',')]

    def backtrack(combination, sum_so_far, index):
        if sum_so_far == target_number:
            output_list.append(combination)
            return
        if sum_so_far > target_number:
            return
        for j in range(index, len(input_list)):
            backtrack(combination + [input_list[j]],
                      sum_so_far + input_list[j], j + 1)

    backtrack([], 0, 0)
    return output_list

