import re

def assert_tuple_fits(typecode: str, tup: tuple, buffer: bytes) -> None:
    types = re.findall(r'[a-z]', typecode)
    if len(tup) != len(types):
        raise AssertionError(f"Tuple size ({len(tup)}) does not match the number of fields ({len(types)})")
    for elem, typ in zip(tup, types):
        if typ == 'i':
            if not isinstance(elem, int):
                raise AssertionError(f"Expected int, but got {type(elem)}")
        elif typ == 'f':
            if not isinstance(elem, float):
                raise AssertionError(f"Expected float, but got {type(elem)}")
        elif typ == 's':
            if not isinstance(elem, str):
                raise AssertionError(f"Expected str, but got {type(elem)}")
        else:
            raise ValueError(f"Invalid typecode: {typ}")

def find_divisible_integers(integers, divisor):
    """
    Returns a list of integers that are divisible by `divisor` and are not already in `integers`.
    """
    divisible_set = {i for i in range(divisor) if i % divisor == 0}
    result = []

    for value in integers:
        if value not in divisible_set and value % divisor == 0:
            result.append(value)

    return result

