def add_unsigned_integers(num1: str, num2: str) -> str:
    num1 = num1[::-1]
    num2 = num2[::-1]
    sum_digits = []
    carry = 0
    for i in range(max(len(num1), len(num2))):
        digit1 = int(num1[i]) if i < len(num1) else 0
        digit2 = int(num2[i]) if i < len(num2) else 0
        sum_digit = digit1 + digit2 + carry
        if sum_digit >= 10:
            carry = 1
            sum_digit -= 10
        else:
            carry = 0
        sum_digits.append(str(sum_digit))
    if carry == 1:
        sum_digits.append('1')
    return ''.join(reversed(sum_digits))

