def shortest_path(graph, start, end):
    visited = set()
    stack = [(start, [start])]
    while stack:
        node, path = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == end:
                return path
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
    return []

def celsius_to_fahrenheit(c):
    return 9 / 5 * c + 32

def celsius_to_kelvin(c):
