import inspect

def generate_api_wrapper(api, api_params, api_key):
    def wrapper(params, key=None):
        new_params = {**api_params, **params}
        return api(new_params, api_key if key is None else key)

    wrapper.__name__ = api.__name__
    wrapper.__doc__ = api.__doc__
    wrapper.__signature__ = inspect.Signature.from_function(api)
    return wrapper

