from lib2to3.pygram import python_grammar
from lib2to3.pgen2 import driver

def count_binary_operators(cursor):
    """
    Counts the number of binary operators (+, -, *, /) in the CST that the cursor is pointing to.
    """
    parser = driver.Driver(python_grammar, convert=driver.Convert())
    with open("input_code.py", "r") as f:
        code = f.read()
    tree = parser.parse_string(code)
    binary_operators = []
    for node in tree.body:
        if node.type == "funcdef":
            for child in node.children:
                if child.type == "expr_stmt":
                    for grandchild in child.children:
                        if grandchild.type == "power":
                            binary_operators.append(grandchild)
    return len(binary_operators)

def convert_hierarchical_to_flat(data):
    result = {}

    def flatten(data, keys=None):
        if keys is None:
            keys = []
        for key, value in data.items():
            if isinstance(value, dict):
                flatten(value, keys + [key])
            else:
                result[".".join(keys + [key])] = result.get(".".join(keys + [key]), []) + [value]

    flatten(data)
    return result

