def calculate_homological_persistence(diagrams):
    """
    Calculate the homological persistence of a list of persistence diagrams.
    Args:
        diagrams (list of lists): A list of persistence diagrams, where each diagram is a list of tuples representing birth and death coordinates.
    Returns:
        list of float: A list of persistence values corresponding to each diagram. If a diagram is empty, the corresponding persistence value is -1.
    """
    result = []
    for diagram in diagrams:
        if len(diagram) == 0:
            result.append(-1)
        else:
            try:
                min_birth = min([birth for birth, _ in diagram])
                max_death = max([death for _, death in diagram])
                result.append(max_death - min_birth)
            except ValueError:
                raise ValueError("Invalid persistence diagram: {}".format(diagram))
    return result

