def generalized_recursive_operation(nums, op):
    if len(nums) == 1:
        return nums[0]

    if op == "add":
        return nums[0] + generalized_recursive_operation(nums[1:], op)
    elif op == "sub":
        return nums[0] - generalized_recursive_operation(nums[1:], op)
    elif op == "mul":
        return nums[0] * generalized_recursive_operation(nums[1:], op)
    elif op == "div":
