def same_voltage_level(system):
    graph = {}
    for bus, voltage in system['buses'].items():
        graph[bus] = []
    for bus1, bus2 in system['lines']:
        graph[bus1].append(bus2)
        graph[bus2].append(bus1)
    for switch, (bus1, bus2) in system['switches'].items():
        graph[bus1].append(bus2)
        graph[bus2].append(bus1)
    visited = set()
    connected_components = []

    for bus in graph:
        if bus not in visited:
            component = set()
            stack = [bus]
            while stack:
                node = stack.pop()
                if node not in visited:
                    visited.add(node)
                    component.add(node)
                    stack.extend(graph[node])
            connected_components.append(component)
    for component in connected_components:
        voltage_levels = set(system['buses'][bus] for bus in component)
        if len(voltage_levels) > 1:
            return False

    return True

