import hashlib

def assign_items_to_groups(items):
    group_assignments = {
        1: [],
        2: [],
        3: []
    }
    hash_values = []
    for item in items:
        hash_value = hashlib.md5(item.encode()).hexdigest()
        hash_values.append(hash_value)
    sorted_hash_values = sorted(hash_values)
    first_quarter = sorted_hash_values[:len(sorted_hash_values) // 4]
    second_quarter = sorted_hash_values[len(sorted_hash_values) // 4:len(sorted_hash_values) // 2]
    for item, hash_value in zip(items, hash_values):
        if hash_value in first_quarter:
            group_assignments[1].append(item)
        elif hash_value in second_quarter:
            group_assignments[2].append(item)
        else:
            group_assignments[3].append(item)

    return group_assignments

