def justify_words(line_length, words):
    num_words = len(words)
    total_length = sum(len(word) for word in words)
    if total_length + num_words - 1 >= line_length:
        return -1
    num_spaces = line_length - total_length
    spaces_per_word = num_spaces // (num_words - 1)
    for i in range(num_words - 1, 0, -1):
        words[i] = ' ' * spaces_per_word + words[i]
    return ' '.join(words)

