class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def check_child_node(node: TreeNode) -> str:
    """
    Checks whether a given node is a valid left child, right child, or neither.
    """
    if node.val < node.parent.val:
        return "left child"
    elif node.val > node.parent.val:
        return "right child"
    else:
        return "neither"

