import itertools

def batch_iterator(dataset, batch_size):
    dataset_iter = itertools.cycle(dataset)
    total_epochs = len(dataset) // batch_size
    for epoch in range(total_epochs):
        yield list(itertools.islice(dataset_iter, batch_size))

