    headers = {name: value for name, value in response.headers.items()}
    content_type = headers.get('Content-Type')

    if content_type == 'application/json':
        logging.warning('Content is not in JSON format.')
    else:
        message_selector = f'HTTP response code: {response_code}; headers: {headers}'
    return message_selector

def jump_game(matrix, target, x=0, y=0):
    if x >= 0 and x < len(matrix) and y >= 0 and y < len(matrix[0]):
        if matrix[x][y] == target:
            return True
        if x + 1 < len(matrix) and jump_game(matrix, target - matrix[x][y], x + 1, y):
            return True
        if y + 1 < len(matrix[0]) and jump_game(matrix, target - matrix[x][y], x, y + 1):
            return True
    return False

