def calculate_steps_per_epoch(total_steps, epochs, batch_size, dataset_size, last_epoch_steps=None):
    total_batches = dataset_size // batch_size
    if last_epoch_steps is not None:
        remaining_batches = total_batches - last_epoch_steps // batch_size
    else:
        remaining_batches = total_batches
    batches_per_epoch = remaining_batches // epochs
    steps_per_epoch = batches_per_epoch * batch_size
    return steps_per_epoch

def top_k_keys_with_highest_values(dictionary, k):
    if k == 0:
        return []

    if k > len(dictionary):
        raise ValueError('k is greater than the number of keys in the dictionary')

    top_keys = []
    for key, value in dictionary.items():
        top_keys.append((key, value))

    top_keys.sort(key=lambda x: x[1], reverse=True)

    return [top_key[0] for top_key in top_keys[:k]]

