def compute_gradient(matrix, vector):
    gradient = []

    for row in matrix:
        row_gradient = 0

        for i in range(len(row)):
            row_gradient += row[i] * vector[i]

        gradient.append(row_gradient)

    return gradient

from typing import List

def find_paths(data: dict, target: str) -> List[List[str]]:
    paths = []

    def find_path(node: dict, current_path: List[str]):
        if target in node:
            current_path.append(target)
            paths.append(current_path.copy())
            current_path.pop()
        else:
            for key, value in node.items():
                if type(value) is dict:
                    current_path.append(key)
                    find_path(value, current_path)
                    current_path.pop()

    find_path(data, [])
    return paths

