def generic_logical_computation(operators, values):
    result = True
    for operator, value in zip(operators, values):
        if operator == 'AND':
            result = result and value
        elif operator == 'OR':
            result = result or value
        elif operator == 'XOR':
            result = result ^ value
        else:
            raise ValueError('Invalid logical operator')

    return result

