import datetime

def calculate_average_monthly_sales(sales_data):
    monthly_sales = {}
    for date, sales in sales_data:
        month = date.month
        monthly_sales[month] = monthly_sales.get(month, (0, 0))
        monthly_sales[month] = (monthly_sales[month][0] + sales, monthly_sales[month][1] + 1)

    average_monthly_sales = []
    for month, (total_sales, num_days) in monthly_sales.items():
        average_sales = total_sales / num_days
        average_monthly_sales.append((month, average_sales))

    return average_monthly_sales

import re

def parse_token_string(token_string):
    match = re.match(r"^([a-z]+)\[(\d+)\-(\d+)\]$", token_string)
    if match:
        start_index = int(match.group(2))
        end_index = int(match.group(3))
        return (start_index, end_index)
    else:
        raise ValueError("Invalid token string format.")

