def is_leap_year(year: int) -> bool:
    def is_divisible(numerator: int, denominator: int) -> bool:
        return numerator % denominator == 0

    def is_between(num: int, lower: int, upper: int) -> bool:
        return lower < num < upper
    if is_divisible(year, 4):
        if is_divisible(year, 100):
            if is_divisible(year, 400):
                return True
            else:
                return False
        else:
            return True
    else:
        return False

