import hashlib

def get_sha1_hashes(files):
    hash_values = []
    buffer_size = 65536
    buffer = bytearray(buffer_size)

    for file in files:
        try:
            with open(file, 'rb') as f:
                h = hashlib.sha1()
                while True:
                    n = f.readinto(buffer)
                    if n == 0:
                        break
                    h.update(buffer[:n])
                hash_values.append(h.hexdigest())
        except (FileNotFoundError, PermissionError, ValueError) as e:
            print(f'Error reading {file}: {e}')

    return hash_values

