import inspect

def extract_class_info(module_str):
    module = inspect.getmodule(eval(module_str))
    members = inspect.getmembers(module)

    class_info = []
    for name, value in members:
        if inspect.isclass(value):
            class_info.append((name, inspect.getdoc(value)))

    return class_info

