import zipfile

def valid_files(directory, extension=None):
    valid_files = []
    for dirpath, dirnames, filenames in os.walk(directory):
        for filename in filenames:
            filepath = os.path.join(dirpath, filename)
            if os.path.isfile(filepath) and (extension is None or filename.endswith(f'.{extension}')):
                if zipfile.is_zipfile(filepath):
                    with zipfile.ZipFile(filepath) as zf:
                        files_in_zip = zf.infolist()
                        if len(files_in_zip) == 1 and files_in_zip[0].filename == 'main.py':
                            with zf.open(files_in_zip[0].filename) as f:
                                content = f.read().decode()
                                if re.search(r'^[a-zA-Z0-9]+$', content):
                                    valid_files.append(filepath)
                else:
                    valid_files.append(filepath)
    return valid_files

