import urllib.parse

def validate_youtube_url(url: str) -> bool:
    parsed_url = urllib.parse.urlparse(url)
    if parsed_url.scheme != 'https' or parsed_url.hostname != 'www.youtube.com':
        return False
    query_params = urllib.parse.parse_qs(parsed_url.query)
    video_id = query_params.get('v')
    if not video_id or len(video_id[0]) != 11 or not video_id[0].isalnum():
        return False

    return True

