import numpy as np

def softmax(x):
    assert isinstance(x, np.ndarray), "Input must be a numpy array."
    exp_x = np.exp(x)
    return exp_x / np.sum(exp_x)

def softmax_with_logits(x):
    assert isinstance(x, np.ndarray), "Input must be a numpy array."
    shift_x = x - np.max(x)
