def traverse_heap_level_by_level(heap):
    levels = []
    queue = [heap]
    while queue:
        curr_level = []
        next_level = []
        for node in queue:
            curr_level.append(node.val)
            if node.left:
                next_level.append(node.left)
            if node.right:
                next_level.append(node.right)
        levels.append(curr_level)
        queue = next_level
    return levels

