class BPlusTreeNode:
    def __init__(self, keys, is_leaf, children=None):
        self.keys = keys
        self.is_leaf = is_leaf
        self.children = children or []

    def insert(self, key):
        self.keys.append(key)
        self.keys.sort()
        if not self.is_leaf:
            key_index = self.keys.index(key)
            self.children[key_index].insert(key)

    def search(self, target):
        if target < self.keys[0]:
            return self.children[0].search(target)
        index = self.binary_search(target)
        if self.is_leaf:
            if target in self.keys:
                return self.keys.index(target)
            else:
                return -1
        return self.children[index].search(target)

    def binary_search(self, target):
        low = 0
        high = len(self.keys) - 1
        while low <= high:
            mid = (low + high) // 2
            if target == self.keys[mid]:
                return mid
            elif target < self.keys[mid]:
                high = mid - 1
            else:
                low = mid + 1
        return low

