def thread_safe_memoized(func):
    cache = {}
    lock = threading.Lock()

    def wrapped(*args):
        if args not in cache:
            with lock:
                try:
                    cache[args] = func(*args)
                except Exception as e:
                    return f'ERROR: {str(e)}'
        return cache[args]

    return wrapped

