def binary_search_sqrt(x):
    if x < 0:
        raise ValueError("Cannot take the square root of a negative number.")

    left = 0
    right = x

    while left <= right:
        mid = (left + right) // 2
        mid_squared = mid ** 2

        if mid_squared == x:
            return mid

        if mid_squared < x:
            left = mid + 1
        else:
            right = mid - 1

    return None

