def match_selector(dom_tree, selector):
    def is_match(element, selector):
        if selector == '*':
            return True
        elif selector[0] == '#':
            return element.get('id') == selector[1:]
        elif selector[0] == '.':
            return selector[1:] in element.get('class', [])
        elif selector[0] == '[' and selector[-1] == ']':
            kv = selector[1:-1].split('=')
            return element.get(kv[0]) == kv[1]
        else:
            return element.get('tag') == selector

    matches = []

    def traverse(element, selector):
        if is_match(element, selector):
            matches.append(element)
        for child in element.get('children', []):
            traverse(child, selector)

    for element in dom_tree:
        traverse(element, selector)

    return matches

