def search_values(dict_list: List[Dict], target: str) -> List[int]:
    """
    Searches for values in `dict_list` where the value of the "key" key matches `target`.
    """
    values = []
    for dictionary in dict_list:
        if dictionary["key"] == target:
            values.append(dictionary["value"])
    if values:
        return values
    left, right = 0, len(dict_list) - 1
    while left < right:
        mid = (left + right) // 2
        if dict_list[mid]["key"] <= target:
            left = mid + 1
        else:
            right = mid
    for i in range(left, len(dict_list)):
        if dict_list[i]["key"] != target:
            break
        values.append(dictionary["value"])

    return values

