def generate_xml_from_data(data):
    sorted_data = sorted(data, key=lambda x: x[0])
    aggregated_names = {}
    for id, name in sorted_data:
        if id not in aggregated_names:
            aggregated_names[id] = [name]
        else:
            aggregated_names[id].append(name)
    root = ET.Element('root')
    data_element = ET.Element('data')
    root.append(data_element)
    for id, names in aggregated_names.items():
        item_element = ET.Element('item', attrib={'id': str(id)})
        item_element.text = ', '.join(sorted(names))
        data_element.append(item_element)
    root.attrib['encoding'] = 'UTF-8'
    return root

