def days_since_year_start(date: datetime.date) -> int:
    """
    Calculates the number of days since the beginning of the year for a given date.
    """
    if date.year % 400 == 0 or (date.year % 4 == 0 and date.year % 100 != 0):
        month_lengths = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    else:
        month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    total_days = date.day
    for i in range(date.month - 1):
        total_days += month_lengths[i]
    return total_days

