def find_last_element(arr, t):
    start = 0
    end = len(arr) - 1

    while start <= end:
        mid = (start + end) // 2
        if arr[mid] == t:
            return mid
        elif arr[mid] < t:
            start = mid + 1
        else:
            end = mid - 1

    return -1

