def needleman_wunsch(seq1, seq2):
    m = len(seq1)
    n = len(seq2)
    D = [[0 for _ in range(n+1)] for _ in range(m+1)]
    for i in range(1, m+1):
        D[i][0] = D[i-1][0] - 1
    for j in range(1, n+1):
        D[0][j] = D[0][j-1] - 1
    for i in range(1, m+1):
        for j in range(1, n+1):
            score_match = D[i-1][j-1] + (1 if seq1[i-1] == seq2[j-1] else -1)
            score_delete = D[i-1][j] - 1
            score_insert = D[i][j-1] - 1
            D[i][j] = max(score_match, score_delete, score_insert)
    aligned_seq1 = ""
    aligned_seq2 = ""
    i, j = m, n
    while i > 0 and j > 0:
        if D[i][j] == D[i-1][j-1] + (1 if seq1[i-1] == seq2[j-1] else -1):
            aligned_seq1 = seq1[i-1] + aligned_seq1
            aligned_seq2 = seq2[j-1] + aligned_seq2
            i -= 1
            j -= 1
        elif D[i][j] == D[i-1][j] - 1:
            aligned_seq1 = seq1[i-1] + aligned_seq1
            aligned_seq2 = "-" + aligned_seq2
            i -= 1
        else:
            aligned_seq1 = "-" + aligned_seq1
            aligned_seq2 = seq2[j-1] + aligned_seq2
            j -= 1

    return (aligned_seq1, aligned_seq2)

