def clone_graph(node):
    cloned_nodes = {}
    def clone_node(node):
        if node.val in cloned_nodes:
            return cloned_nodes[node.val]
        else:
            cloned_node = Node(node.val, [])
            cloned_nodes[node.val] = cloned_node
            for neighbor in node.neighbors:
                cloned_neighbor = clone_node(neighbor)
                cloned_node.neighbors.append(cloned_neighbor)
            return cloned_node

    return clone_node(node)

def convert_surface_azimuth_to_hemisphere(surface_azimuth, hemisphere):
    if not (0 <= surface_azimuth <= 360):
        raise ValueError('Invalid surface azimuth')
    if hemisphere not in {'north', 'south'}:
        raise ValueError('Invalid hemisphere')

    if hemisphere == 'north':
        if surface_azimuth < 90:
            return 'north', surface_azimuth
        elif surface_azimuth < 180:
            return 'west', surface_azimuth - 90
        elif surface_azimuth < 270:
            return 'south', surface_azimuth - 180
        else:
            return 'east', surface_azimuth - 270
    else:  # hemisphere == 'south'
        if surface_azimuth < 90:
            return 'south', surface_azimuth
        elif surface_azimuth < 180:
            return 'east', surface_azimuth - 90
        elif surface_azimuth < 270:
            return 'north', surface_azimuth - 180
        else:
            return 'west', surface_azimuth - 270

