    num_cols = len(matrix[0]) if matrix else 0
    num_elements = num_rows * num_cols

    if num_elements == 0:
        return 0

    num_diagonal_elements = min(num_rows, num_cols)
    num_elements_to_average = num_elements - num_diagonal_elements

    total_sum = 0

    for i in range(num_rows):
        for j in range(num_cols):
            if i != j:
                total_sum += matrix[i][j]

    return total_sum / num_elements_to_average

