import json

def serialize_code_with_type_hints(code, type_hints):
    tree = ast.parse(code)
    code_info = []
    class CodeVisitor(ast.NodeVisitor):
        def visit_Name(self, node):
            code_info.append(node.id)
        def visit_Str(self, node):
            code_info.append(node.s)
        def visit_Num(self, node):
            code_info.append(node.n)

    visitor = CodeVisitor()
    visitor.visit(tree)
    supported_types = [int, str, list]
    supported_type_hints = []
    for type_hint in type_hints:
        if type_hint in supported_types:
            supported_type_hints.append(type_hint)
        else:
            raise ValueError(f"Unsupported type hint: {type_hint}")
    serialized_type_hints = json.dumps(supported_type_hints)
    serialized_code = json.dumps(code_info)
    serialized_string = f"code: {serialized_code}, type_hints: {serialized_type_hints}"

    return serialized_string

