import functools

def memoize(max_records=None):
    def decorator(func):
        memo = {}
        @functools.wraps(func)
        def wrapper(*args):
            if max_records is not None:
                if len(memo) >= max_records:
                    memo.popitem(last=False)
            if args in memo:
                return memo[args]
            else:
                result = func(*args)
                memo[args] = result
                return result
        return wrapper
    return decorator

