def is_valid_ssn(ssn: str) -> bool:
    ssn_pattern = r"(?P<area_code>\d{3})-(?P<group_code>\d{2})-(?P<serial_number>\d{4})"
    match = re.match(ssn_pattern, ssn)
    if match:
        area_code = int(match.group("area_code"))
        group_code = int(match.group("group_code"))
        serial_number = int(match.group("serial_number"))
        if not 1 <= area_code <= 899:
            return False
        if not 1 <= group_code <= 99:
            return False
        if not 1 <= serial_number <= 9999:
            return False
        return True
    return False

