def calculate_tensor_size(shape, data_type):
    if not isinstance(shape, list) or not isinstance(data_type, str):
        raise TypeError("Shape and data type must be valid")
    if len(shape) == 0:
        return 0
    if len(shape) == 1:
        num_elements = shape[0]
    else:
        num_elements = 1
        for dim in shape:
            num_elements *= dim
    if data_type == 'float32':
        data_size = 4
    elif data_type == 'float64':
        data_size = 8
    elif data_type == 'int32':
        data_size = 4
    elif data_type == 'int64':
        data_size = 8
    elif data_type == 'uint8':
        data_size = 1
    else:
        raise ValueError("Invalid data type")
    return num_elements * data_size

