    if not dictionary:
        return None

    if len(dictionary) == 1:
        raise Exception("Dictionary only has a single entry")

    values = list(dictionary.values())
    values_sorted_by_key_length = sorted(values, key=lambda x: len(x[0]))

    if len(values) % 2 == 0:
        middle_values = values_sorted_by_key_length[len(values) // 2 - 1 : len(values) // 2 + 1]
