def climb_stairs(n):
    memo = {}

    def helper(n):
        if n in memo:
            return memo[n]
        if n == 0 or n < 0:
            return 0
        if n == 1 or n == 2:
            return n
        memo[n] = helper(n - 1) + helper(n - 2)
        return memo[n]

    return helper(n)

def human_readable_memory_size(size_in_bytes):
