import json

def flatten_json(json_list):
    flattened_list = []

    for json_obj in json_list:
        try:
            obj = json.loads(json.dumps(json_obj))
        except ValueError:
            continue

        def recursive_flatten(obj, prefix=''):
            for key, value in obj.items():
                if isinstance(value, dict):
                    recursive_flatten(value, prefix + f'{key}.')
                elif isinstance(value, list):
                    for item in value:
                        recursive_flatten(item, prefix + f'{key}.')
                else:
                    flattened_list.append((prefix + key, value))

        recursive_flatten(obj)

