def insertion_position(arr, target):
    if not arr:
        return 0
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    if target > arr[-1]:
        return len(arr)
    return low

