def min_difference_subset(nums):
    total_sum = sum(nums)
    dp = [[None] * (total_sum // 2 + 1) for _ in range(len(nums) + 1)]
    dp[0][0] = True
    for i in range(1, len(nums) + 1):
        for j in range(total_sum // 2 + 1):
            if nums[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]
    closest_sum = total_sum // 2
    while not dp[-1][closest_sum]:
        closest_sum -= 1
    subset2 = [num for num in nums if num not in dp[-1][:closest_sum + 1]]
    return abs(sum(nums) - 2 * closest_sum)

def max_path_sum(triangle):
    rows = len(triangle)
    max_sums = [[0] * len(row) for row in triangle]
    max_sums[rows - 1] = triangle[rows - 1]
    for i in range(rows - 2, -1, -1):
        for j in range(len(triangle[i])):
            max_sums[i][j] = triangle[i][j] + max(max_sums[i + 1][j], max_sums[i + 1][j + 1])
    return max(max_sums[0])

