def serialize(obj):
    """
    Recursively serializes a nested dictionary containing objects of varying types.
    """
    if isinstance(obj, dict):
        return serialize_dict(obj)
    elif isinstance(obj, (list, tuple, set)):
        return serialize_iterable(obj)
    elif isinstance(obj, (str, int, float, bool, type(None))):
        return serialize_primitive(obj)
    elif isinstance(obj, object):
        return serialize_object(obj)
    else:
        raise TypeError(f"Unsupported type: {type(obj)}")

def serialize_dict(d):
    return "{" + ", ".join(f"{serialize(k)}: {serialize(v)}" for k, v in d.items()) + "}"

def serialize_iterable(l):
    return "[" + ", ".join(serialize(x) for x in l) + "]"

