class GraphNode:
    def __init__(self, val: int):
        self.val = val
        self.neighbors = []

def dfs_traverse(node: GraphNode, probabilities: Dict[int, float], visited: Set[int]) -> List[int]:
    """
    Traverses a graph starting from a given node in DFS order, filtering edges based on non-zero probabilities.
    """
    result = []

    if node.val not in visited:
        visited.add(node.val)
        result.append(node.val)

        for neighbor in node.neighbors:
            if probabilities.get(neighbor.val, 0.0) > 0:
                result.extend(dfs_traverse(neighbor, probabilities, visited))

    return result

