def find_x(f, y):
    lb, ub = 0, y
    while lb <= ub:
        m = (lb + ub) // 2
        fm = f(m)
        if fm == y:
            return m
        elif fm < y:
            lb = m + 1
        else:
            ub = m - 1
    raise ValueError("No solution found")

