def convert_mask_to_grayscale(mask):
    grayscale_mask = []
    for row in mask:
        grayscale_row = []
        for pixel in row:
            if pixel == 0:
                grayscale_row.append(0)
            else:
                grayscale_row.append(255)
        grayscale_mask.append(grayscale_row)
    return grayscale_mask

def apply_grayscale_mask_to_image(image, mask):
