def false_negative_rate(actual, predicted):
    def count_positives(values):
        return sum(1 for value in values if value == 1)

    total_positives = count_positives(actual)
    if total_positives == 0:
        return None

    false_negatives = len([
        a for a, p in zip(actual, predicted)
        if a == 1 and p == 0  # actual positive, predicted negative
    ])
    return false_negatives / total_positives

