import re

def range_string_to_set(range_string):
    range_regex = r"^(\d+)-(\d+)$"
    number_set = set()
    for number_or_range in range_string.split(","):
        match = re.match(range_regex, number_or_range)
        if match:
            start, end = map(int, match.groups())
            number_set.update(range(start, end + 1))
        else:
            number_set.add(int(number_or_range))
    return sorted(number_set)

