def convert_string_to_24bit_integers(string):
    bytes = [ord(c) for c in string]
    if len(bytes) % 3 != 0:
        bytes.extend([0] * (3 - (len(bytes) % 3)))
    triplets = zip(*[iter(bytes)] * 3)
    integers = []
    for triplet in triplets:
        integer = 0
        for i, byte in enumerate(triplet):
            integer |= byte << (8 * (2 - i))
        integers.append(integer)

