def linear_interpolation_1d(data_points: List[Tuple[float, float]], target_x: float, x_index: int = 0) -> float:
    """
    Performs 1D linear interpolation on a list of data points and returns the interpolated value at the target x-value.
    """
    left, right = 0, len(data_points) - 1

    while left <= right:
        mid = (left + right) // 2
        if data_points[mid][x_index] == target_x:
            return data_points[mid][x_index]
        elif data_points[mid][x_index] < target_x:
            left = mid + 1
        else:
            right = mid - 1
    x1, y1 = data_points[left - 1][x_index], data_points[left - 1][x_index + 1]
    x2, y2 = data_points[left][x_index], data_points[left][x_index + 1]

    return y1 + (target_x - x1) * (y2 - y1) / (x2 - x1)

