import numpy as np

def peak_count(data, window_size):
    window_size = min(len(data), window_size)
    data_window = np.convolve(data, np.ones(window_size) / window_size, mode='valid')
    peaks = []
    for i in range(len(data_window)):
        if data_window[i] > data[i] and data_window[i] > data[i + window_size - 1]:
            peaks.append(i + window_size // 2)
    positive_peaks = []
    negative_peaks = []
    for i in range(len(peaks) - 2):
        if data[peaks[i] - 1] < data[peaks[i]] and data[peaks[i]] > data[peaks[i] + 1]:
            positive_peaks.append(peaks[i])
        elif data[peaks[i] - 1] > data[peaks[i]] and data[peaks[i]] < data[peaks[i] + 1]:
            negative_peaks.append(peaks[i])
    if len(positive_peaks) > len(negative_peaks):
        return 1.0
    elif len(positive_peaks) < len(negative_peaks):
        return -1.0
    elif len(positive_peaks) == 0 or len(negative_peaks) == 0:
        return 0.0
    else:
        return 0.0

