def binary_search(target, arr):
    def helper(target, arr, start, end):
        if start > end:
            return -1

        mid = start + (end - start) // 2

        if arr[mid] == target:
            return mid
        elif arr[mid] > target:
            return helper(target, arr, start, mid-1)
        else:
            return helper(target, arr, mid+1, end)
    if not arr:
        return -1
    if target == arr[0]:
        return 0
    if target == arr[-1]:
        return len(arr) - 1
    return helper(target, arr, 0, len(arr)-1)

