def solve_differential_equation(k, m, y0, t):
    y = np.zeros_like(t)
    y[0] = y0
    def dydt(y, t):
        return -k / m * y
    for i in range(len(t) - 1):
        y[i + 1] = y[i] + (t[i + 1] - t[i]) * dydt(y[i], t[i])
    print(f"The solution to the differential equation is y(t) = {y0} * exp(-{k} * t / {m}).")

    return y

