def is_valid_outline_string(string):
    stack = []

    for char in string:
        if char in ['(', '[', '<']:
            stack.append(char)
        elif char in [')', ']', '>']:
            if not stack or char != matching_bracket(stack[-1]):
                return False
            stack.pop()

    return len(stack) == 0

