def merge_with(dict1: dict, dict2: dict, callback=lambda k, v1, v2: (v1, v2)):
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("Both arguments must be dictionaries")
    if callback is not None and not callable(callback):
        raise TypeError("Callback function must be a callable object if provided")
    if callback is None:
        callback = lambda k, v1, v2: (v1, v2)
    result = dict()
    for key, value in dict1.items():
        if key in dict2:
            result[key] = callback(key, value, dict2[key])
        else:
            result[key] = value

    for key, value in dict2.items():
        if key not in result:
            result[key] = value

    return result

