def matrix_vector_mul(A, b):
    """
    Multiply matrix A and vector b.
    The matrix A is a 2D NumPy array, and the vector b is a 1D NumPy array.
    """
    A_rows = A.shape[0]
    A_cols = A.shape[1]
    b_cols = b.shape[0]
    if A_cols != b_cols:
        raise ValueError("The number of columns in A must be equal to the number of elements in b.")
    result = np.zeros((A_rows, b_cols))
    for i in range(A_rows):
        for j in range(b_cols):
            for k in range(A_cols):
                result[i, j] += A[i, k] * b[k]
    return result

