def sieve(n):
    primes = [True] * (n + 1)
    primes[0] = False
    primes[1] = False
    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            for j in range(i * i, n + 1, i):
                primes[j] = False
    return [i for i in range(n + 1) if primes[i]]

def euler_phi(n):
    count = 0
    primes = sieve(n)
    for i in range(1, n + 1):
        coprime = True
        for prime in primes:
            if i % prime == 0 and n % prime == 0:
                coprime = False
                break
        if coprime:
            count += 1
    return count

