def is_robot_reachable(width, height, obstacles, start, end):
    if start in obstacles:
        return False
    queue = [start]
    visited = set(start)
    while queue:
        pos = queue.pop(0)
        if pos == end:
            return True
        for neighbor in get_neighbors(pos, width, height, obstacles):
            if neighbor not in visited:
                queue.append(neighbor)
                visited.add(neighbor)
    return False

def get_neighbors(pos, width, height, obstacles):
    x, y = pos
    neighbors = [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]
    return [(x, y) for (x, y) in neighbors if 0 <= x < width and 0 <= y < height and (x, y) not in obstacles]

