def map_to_2d(array):
    if not isinstance(array, (list, tuple, np.ndarray)):
        raise TypeError(f"Input type '{type(array)}' is not supported.")
    array = np.array(array)  # Convert to numpy array if not already
    return np.expand_dims(array, axis=1).astype(np.int32)

def longest_unique_substring(s):
    longest_substring = ""
    longest_length = 0
    start = 0
    end = 0
    while end < len(s):
        if s[end] in s[start:end]:
            start += 1
        else:
            end += 1
        if end - start > longest_length:
            longest_length = end - start
            longest_substring = s[start:end]

    return longest_substring

