import numpy as np

def sort_pixels(image):
    sorted_pixels = []
    for row in range(image.shape[0]):
        for col in range(image.shape[1]):
            pixel_value = image[row, col]
            sorted_pixels.append((row, col, pixel_value))
    return sorted(sorted_pixels, key=lambda pixel: (pixel[0], pixel[1]))

