        lines = string.splitlines()
        formatted_lines = []
        for line in lines:
            formatted_line = f'  {line}'  # Add indentation to each line
            formatted_lines.append(formatted_line)
        formatted_string = '\n'.join(formatted_lines)
        return formatted_string
