def check_line_segment_inside_rectangle(p1, p2, p3, p4, p5, p6):
    def cross_product(p1, p2, p3):
        return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])
    return cross_product(p1, p3, p4) * cross_product(p1, p5, p6) < 0 and cross_product(p2, p3, p4) * cross_product(p2, p5, p6) < 0

import json

def process_json_string(json_string):
    json_dict = json.loads(json_string)
    key_value_pairs = []
    def process_nested_object(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                process_nested_object((key, value))
        elif isinstance(obj, list):
            for element in obj:
                process_nested_object(element)
        else:
            key_value_pairs.append(obj)
    process_nested_object(json_dict)
    return key_value_pairs

