def similarity(seq1, seq2):
    min_len = min(len(seq1), len(seq2))
    return sum(1 for a1, a2 in zip(seq1, seq2) if a1 == a2) / min_len

def similarity_matrix(protein_seqs):
    n = len(protein_seqs)
    sim_matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            sim_matrix[i][j] = similarity(protein_seqs[i], protein_seqs[j])
    return sim_matrix

from functools import reduce

def memoize(func):
    """Memoization decorator to cache previously computed values."""
    cache = {}
    def memoized_func(n):
        if n not in cache:
            cache[n] = func(n)
        return cache[n]
    return memoized_func

@memoize
def factorial(n):
    """Factorial function using memoization."""
    return reduce(lambda x, y: x * y, range(1, n + 1)) if n > 0 else 1

