from functools import wraps

def initialize_once_decorator(func):
    initialized = False

    @wraps(func)
    def wrapper(*args, **kwargs):
        nonlocal initialized
        if not initialized:
            initialized = True
        return func(*args, **kwargs)

    return wrapper

def merge_arguments(*args):
    args = [arg if isinstance(arg, list) else [arg] for arg in args]
    merged = [item for arg in args for item in arg]
    return merged, len(args)

