class CustomJSONEncoder(json.JSONEncoder):
    """A custom JSON encoder that ignores all non-primitive data types."""
    def default(self, obj):
        if isinstance(obj, (int, float, bool, list, dict, str, None.__class__)):
            return super().default(obj)
