def closest_point_on_rectangle(rect, point):
    top_left = rect[0]
    bottom_right = rect[1]

    if top_left[0] <= point[0] <= bottom_right[0] and top_left[1] <= point[1] <= bottom_right[1]:
        return point

    closest_x = max(top_left[0], min(point[0], bottom_right[0]))
    closest_y = max(top_left[1], min(point[1], bottom_right[1]))

    return (closest_x, closest_y)

