def calculate_rectangle_intersection_area(x1, y1, x2, y2, x3, y3, x4, y4):
    if not (x1 < x3 < x2 and y1 < y3 < y2):
        return 0
    width = min(x2 - x1, x4 - x3)
    height = min(y2 - y1, y4 - y3)
    return width * height

