import re

def match_pattern(pattern):
    """
    Returns a nested function to check if a string matches a given pattern
    """
    def inner_func(string):
        return re.match(pattern, string) is not None
    return inner_func

def filter_with_pattern(strings, pattern):
    """
    Filters a list of strings based on a specific pattern and returns a new list of matches
    """
    matches = []
    for string in strings:
        if match_pattern(pattern)(string):
            matches.append(string)
        else:
            return matches
    return matches

