import re

def format_marc_record(control_fields_string):
    fields = re.split(r"\s+", control_fields_string)
    marc_xml_fields = []

    for field in fields:
        tag, value = re.split(r"\|", field, maxsplit=1)
        if tag == "LDR":
            marc_xml_fields.append(f"<leader>{value}</leader>")
        else:
            marc_xml_fields.append(f"<controlfield tag='{tag}'>{value}</controlfield>")

    marc_xml_record = "".join(marc_xml_fields)
    return f"<record>{marc_xml_record}</record>"

def sort_by_score(students):
    if len(students) == 0:
        return []

    def compare_students(s1, s2):
        if s1[1] > s2[1]:
            return -1
        elif s1[1] < s2[1]:
            return 1
        elif s1[0] < s2[0]:
            return -1
        else:
            return 1

    for i in range(len(students)):
        for j in range(len(students) - i - 1):
            if compare_students(students[j], students[j + 1]) > 0:
                students[j], students[j + 1] = students[j + 1], students[j]

    return students

