def add_binary(num1, num2):
    result = []
    carry = 0
    max_len = max(len(num1), len(num2))

    num1 = num1.zfill(max_len)
    num2 = num2.zfill(max_len)

    for i in range(max_len-1, -1, -1):
        digit_sum = carry + int(num1[i]) + int(num2[i])
        result.append(str(digit_sum % 2))
        carry = digit_sum // 2

    if carry:
        result.append(str(carry))

    return ''.join(reversed(result))

from typing import List

def pack_can_message(message_type: str, message_id: int, payload: List[int]) -> bytes:
    """
    Packs a CAN message and returns the message as a bytes object.
    """
    if message_type == 'data_frame':
        if message_id < 0x00 or message_id > 0x3F:
            raise ValueError('Invalid CAN message ID for data frames: 0x00 - 0x3F')
        if len(payload) > 8:
            raise ValueError('Invalid payload length for data frames: 0 - 8 bytes')
    elif message_type == 'remote_frame':
        if message_id < 0x50 or message_id > 0x5F:
            raise ValueError('Invalid CAN message ID for remote frames: 0x50 - 0x5F')
        if len(payload) > 0:
            raise ValueError('Invalid payload length for remote frames: 0 byte')
    else:
        raise ValueError('Invalid CAN message type')
    message = [message_id, len(payload)] + payload
    message_bytes = bytes(message)

    return message_bytes

from typing import List, Dict

def compute_average_values(dicts: List[Dict[str, int]]) -> Dict[str, float]:
    """
    Computes the average value of each key across all dictionaries in `dicts`. Returns a
    new dictionary containing the average value of each key.
    """
    result = {}

    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, (0, 0))
            result[key] = (result[key][0] + value, result[key][1] + 1)

    return {key: value / count for key, (value, count) in result.items()}

