def long_unique_substring(s: str) -> int:
    """
    Finds the length of the longest substring with unique characters in a given string.
    """
    start, longest = 0, 0
    char_map = {}

    for index, char in enumerate(s):
        if char in char_map:
            start = max(char_map[char], start)
        longest = max(longest, index - start + 1)
        char_map[char] = index + 1

    return longest

def traverse_and_flatten(nested_list):
    flattened_list = []

    def traverse(nested_item):
        if not isinstance(nested_item, (list, tuple)):
            return []

        for item in nested_item:
            if isinstance(item, int):
                if item % 2 == 1:
                    flattened_list.append(item)
            else:
                traverse(item)

    traverse(nested_list)
    return flattened_list

