import numpy as np

def calculate_displacement(x: np.ndarray, y: np.ndarray) -> np.ndarray:
    if x.shape != y.shape:
        raise ValueError("Input tensors must have the same shape.")

    displacements = np.linalg.norm(x - y, axis=1)
    return displacements

