    return byte_list

import base64

def unicode_to_base64(unicode_string: str) -> str:
    if not isinstance(unicode_string, str):
        raise TypeError("Input must be a string")

    if unicode_string.isascii():
        encoded_str_bytes = unicode_string.encode("ascii")
    else:
        encoded_str_bytes = unicode_string.encode("utf-8")

    base64_bytes = base64.b64encode(encoded_str_bytes)
    base64_encoded_str = base64_bytes.decode("utf-8")

    return base64_encoded_str

