import xml.etree.ElementTree as ET

def append_to_last_child(node, string):
    try:
        ET.fromstring(node)
    except ET.ParseError:
        raise ValueError("Input node is not valid XML")

    root = ET.fromstring(node)
    last_child = root.getchildren()[-1]
    last_child.text += string
    return ET.tostring(root)

def relative_volume(dna_sequences):
    total_volume = sum(sequence['volume'] for sequence in dna_sequences)
    relative_volumes = {}
    for sequence in dna_sequences:
        relative_volume = (sequence['volume'] / total_volume) * 100
        relative_volumes[sequence['id']] = relative_volume

    return relative_volumes

def find_replacements(strings, replacements):
    if not strings or not replacements:
        raise ValueError("Invalid input parameters")
    result = []
    for string in strings:
        if string in replacements:
            result.append([string, *replacements[string]])
        else:
            result.append([string])

    return result

import datetime

def seconds_elapsed(time_string):
    time_format = "%H:%M:%S"
    day_start = datetime.datetime.strptime("00:00:00", time_format)
    time_elapsed = datetime.datetime.strptime(time_string, time_format) - day_start
    return time_elapsed.total_seconds()

def rgb_to_hsv(r, g, b):
    r_norm = r / 255
    g_norm = g / 255
    b_norm = b / 255
    max_value = max(r_norm, g_norm, b_norm)
    min_value = min(r_norm, g_norm, b_norm)
    if max_value == min_value:
        hue = 0  # Grayscale
    elif max_value == r_norm:
        hue = 60 * ((g_norm - b_norm) / (max_value - min_value)) % 360
    elif max_value == g_norm:
        hue = 60 * ((b_norm - r_norm) / (max_value - min_value)) + 120
    else:
        hue = 60 * ((r_norm - g_norm) / (max_value - min_value)) + 240
    if max_value == 0:
        saturation = 0
