def filter_dicts(dicts, filters):
    def apply_filter(d):
        for operator, key, value in filters:
            if operator == 'eq':
                if d[key] != value:
                    return False
            elif operator == 'ne':
                if d[key] == value:
                    return False
            elif operator == 'lt':
                if d[key] >= value:
                    return False
            elif operator == 'gt':
                if d[key] <= value:
                    return False
            elif operator == 'lte':
                if d[key] > value:
                    return False
            elif operator == 'gte':
                if d[key] < value:
                    return False
            else:
                raise ValueError(f'Invalid operator "{operator}".')
        return True

    return list(filter(apply_filter, dicts))

