def perform_substitutions(input_str: str, variables: dict) -> str:
    result = []
    while True:
        match = re.search(r'\$\{(\w+)\}', input_str)
        if match:
            variable_name = match.group(1)
            variable_value = variables.get(variable_name)
            if variable_value is not None:
                result.append(input_str[:match.start()] + str(variable_value))
            else:
                result.append(input_str[:match.start()] + "None")
            input_str = input_str[match.end():]
        else:
            result.append(input_str)
            break

    return ''.join(result)

def extract_field(data, field, default=None):
    """
    Extracts the value of a specific field from a JSON object. If the field is
    a nested object, the function recursively extracts the value from the nested
    object. If the field is not found, the function returns a default value.
    """
    if isinstance(data, dict):
        for key, value in data.items():
            if key == field:
                return value
            elif isinstance(value, dict):
                result = extract_field(value, field, default)
                if result is not None:
                    return result
        return default
    elif isinstance(data, list):
        for value in data:
            result = extract_field(value, field, default)
            if result is not None:
                return result
        return default
    else:
        return default

