def sort_sublist(lst):
    n = len(lst)
    for i in range(1, n-1):  # Ignore the first and last elements of the sublist
        min_idx = i
        for j in range(i+1, n-1):
            if lst[j] < lst[min_idx]:
                min_idx = j
        lst[i], lst[min_idx] = lst[min_idx], lst[i]  # Swap the current element with the smallest element
    return lst

def find_longest_sublist(lst_of_lst):
