class ListSummation:
    def __init__(self, list_of_ints):
        self.list_of_ints = list_of_ints

    def sum_list_elements(self):
        if not self.list_of_ints:
            return 0
        if len(self.list_of_ints) == 1:
            return self.list_of_ints[0]
        mid_index = len(self.list_of_ints) // 2
        left_half_sum = ListSummation(self.list_of_ints[:mid_index]).sum_list_elements()
        right_half_sum = ListSummation(self.list_of_ints[mid_index:]).sum_list_elements()
        return left_half_sum + right_half_sum

