import hashlib

def md5_large_file(file_path):
    block_size = 65536  # Block size to process file in chunks
    md5_hash = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            block = f.read(block_size)
            if not block:
                break
            md5_hash.update(block)
    return md5_hash.hexdigest()

