def check_bbox_shape(bbox):
    if not isinstance(bbox, list):
        raise ValueError("Bounding box must be a 2D list.")
    if not len(bbox) == 2:
        raise ValueError("Bounding box must have two rows.")
    if not all(isinstance(row, list) for row in bbox):
        raise ValueError("Bounding box must be a 2D list.")
    if not all(len(row) == 4 for row in bbox):
        raise ValueError("Bounding box must have four columns in each row.")
    return True

