def recursive_traverse(obj, condition):
    matches = []

    if condition(obj):
        matches.append(obj)

    if isinstance(obj, dict):
        for value in obj.values():
            matches.extend(recursive_traverse(value, condition))
    elif isinstance(obj, list):
        for item in obj:
            matches.extend(recursive_traverse(item, condition))

    return matches

class KeyValueStore:
    def __init__(self):
        self.store = {}

    def add(self, key, value):
        if key not in self.store:
            self.store[key] = []
        self.store[key].append(value)

    def remove(self, key, value):
        if key not in self.store:
            raise KeyError("Key not found")
        if value not in self.store[key]:
            raise ValueError("Value not found")
        self.store[key].remove(value)

    def get(self, key):
        if key not in self.store:
            raise KeyError("Key not found")
        return self.store[key]

