class PairNotFound(Exception):
    pass

def find_first_pair(iterable, condition):
    try:
        iter_obj = iter(iterable)
        first_item = next(iter_obj)
        while not condition(first_item):
            first_item = next(iter_obj)
        second_item = next(iter_obj)
        while not condition(second_item):
            second_item = next(iter_obj)
        return (first_item, second_item)
    except StopIteration:
        raise PairNotFound("No pair found that satisfies the condition.")

def find_min_or_max_in_range(numbers, start, end, reverse=False):
    if start > end or start < 0 or end >= len(numbers):
        return None
    if start > end and len(numbers) == 0:
        return None
    if start <= end and len(numbers) == 0:
        return None
    if start <= end and len(numbers) > 0 and all(n < start or n > end for n in numbers):
        return None
    if reverse:
        return max(numbers[start:end+1])
    else:
        return min(numbers[start:end+1])
