def string_comparison(str1, str2):
    mismatch_count = 0
    index = 0
    while index < len(str1) and index < len(str2):
        if str1[index] != str2[index]:
            mismatch_count += 1
        index += 1
    if len(str1) > len(str2):
        mismatch_count += len(str1) - len(str2)
    elif len(str2) > len(str1):
        mismatch_count += len(str2) - len(str1)
    return mismatch_count

