def group_tuples(tuples: List[Tuple[int, str]]) -> Dict[int, List[Tuple[int, str]]]:
    """
    Takes a list of tuples as input, and returns a dictionary with unique values as keys and
    lists of tuples as values.
    """
    result = {}

    for val, item in tuples:
        if val not in result:
            result[val] = []
        result[val].append((val, item))

    return result

