def expected_transitions(p, q, r, s):
    if not (0 <= p <= 1 and 0 <= q <= 1 and 0 <= r <= 1 and p + q + r == 1):
        raise ValueError('Invalid transition probabilities.')

    if s == 'Hot':
        return 0

    elif s == 'Cold':
        return 1 / p + expected_transitions(r, p, q, 'Hot')

    else:
        raise ValueError('Invalid initial state.')

import json

def find_friends(json_file_path, target_user_id):
    with open(json_file_path, 'r') as f:
        json_data = json.load(f)
    target_user = None
    for user in json_data:
        if user['id'] == target_user_id:
            target_user = user
            break
    if not target_user:
        return []
    friends = target_user['friends']
    usernames = set()
    for friend_id in friends:
