def numerical_stats(sequence):
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("Sequence must be a list or a tuple.")
    if not sequence:
        return (None, None, None)
    largest, smallest = sequence[0], sequence[0]
    for element in sequence:
        if not isinstance(element, (int, float)):
            continue
        if element > largest:
            largest = element
        if element < smallest:
            smallest = element
    odd_elements = len(list(filter(lambda x: x % 2 == 1, sequence)))
    return (largest, smallest, odd_elements)

def calculate_inversions(permutation):
    inversions = 0
    for i in range(len(permutation) - 1):
        for j in range(i + 1, len(permutation)):
            if permutation[i] > permutation[j]:
                inversions += 1
    return inversions

def count_permutations_with_incorrect_parity(permutations):
    incorrect_parity_count = 0
    for permutation in permutations:
        if calculate_inversions(permutation) % 2 != 0:
            incorrect_parity_count += 1
    return incorrect_parity_count

