def extract_and_delete_zips(directory_path: str) -> None:
    directory = Path(directory_path)
    if not directory.exists():
        raise FileNotFoundError(f"Directory '{directory}' does not exist.")
    zip_files = directory.glob('*.zip')
    if not zip_files:
        raise ValueError(f"Directory '{directory}' does not contain any zip files.")
    for zip_file in zip_files:
