def count_one_bits(file_name: str) -> int:
    total_bits = 0

    try:
        with open(file_name, "rb") as f:
            chunk_size = 8
            chunk = f.read(chunk_size)
            while chunk:
                chunk_size = len(chunk)
                if chunk_size % 8 != 0:
                    padding_size = 8 - (chunk_size % 8)
                    chunk += b'\x00' * padding_size
                for byte in chunk:
                    for i in range(8):
                        if byte & (1 << i):
                            total_bits += 1
                chunk = f.read(chunk_size)
    except IOError as e:
        print(f"Error reading file: {e}")

    return total_bits

