def get_intersection_area(rect1, rect2):
    x1, y1, x2, y2 = rect1
    x3, y3, x4, y4 = rect2
    x5 = max(x1, x3)
    y5 = max(y1, y3)
    x6 = min(x2, x4)
    y6 = min(y2, y4)
    if x6 - x5 < 0 or y6 - y5 < 0:
        return 0
    return (x6 - x5) * (y6 - y5)

def contains_non_numeric(lst):
