def swap(lst, i, j):
    lst[i], lst[j] = lst[j], lst[i]


def insertion_sort(lst):
    if contains_non_numeric(lst):
        raise ValueError("The list contains non-numeric elements.")
    for i in range(1, len(lst)):
        j = i - 1
        while j >= 0 and lst[j] > lst[j + 1]:
            swap(lst, j, j + 1)
            j -= 1

class Node:
    def __init__(self, value):
        self.value = value
        self.children = []

    def add_child(self, node):
        self.children.append(node)


def bfs(node, other_nodes):
    queue = [node]
    visited = set()
    similar_nodes = 0

    while len(queue) > 0:
        current = queue.pop(0)

        for other_node in other_nodes:
            if other_node.value == current.value and other_node not in visited:
                similar_nodes += 1

        visited.add(current)

        for child in current.children:
            queue.append(child)

    return similar_nodes


def generate_similarity_matrix(functions):
    trees = []
    for function in functions:
        root = Node(function[0])
        queue = [root]
        for i in range(1, len(function), 2):
            node = queue.pop(0)
            if function[i]:
                left_child = Node(function[i])
                node.add_child(left_child)
                queue.append(left_child)
            if function[i + 1]:
                right_child = Node(function[i + 1])
                node.add_child(right_child)
                queue.append(right_child)

        trees.append(root)
    matrix = [[0] * len(functions) for _ in range(len(functions))]
    for i in range(len(functions)):
        for j in range(i + 1, len(functions)):
            matrix[i][j] = bfs(trees[i], trees[j].children)
            matrix[j][i] = matrix[i][j]  # Symmetric matrix, so the similarity score is the same in both directions

    return matrix

