def sum_items(items):
    """
    Calculates the sum of the items in a list of tuples, where each tuple has two items.
    If the list is empty or if the tuple validation fails, the function returns 0.
    """
    if not items:
        return 0

    total = 0

    for item in items:
        if len(item) != 2 or not isinstance(item[1], (int, float)):
            return 0

        total += item[1]

    return total

