def calculate_median_age(employees: List[Dict[str, int]]) -> Dict[str, float]:
    """
    Calculates the median age of males and females from a list of employee records.
    """
    if not employees:
        return {}

    male_ages = []
    female_ages = []

    for employee in employees:
        if employee["gender"] == "male":
            male_ages.append(employee["age"])
        elif employee["gender"] == "female":
            female_ages.append(employee["age"])

    median_age = {}
    median_age["male"] = statistics.median(male_ages)
    median_age["female"] = statistics.median(female_ages)

    return median_age

