from enum import Enum

def create_enumerations(names, values, docstrings):
    enum_dict = {}
    for name, value, docstring in zip(names, values, docstrings):
        class CustomEnum(Enum):
            __doc__ = docstring
            def __str__(self):
                return f"{self.name}: {self.value}"
        setattr(CustomEnum, name, value)
        enum_dict[name] = CustomEnum
    return enum_dict

