def det_3by3(matrix):
    """Calculates the determinant of a 3-by-3 matrix."""
    def det(a, b, c, d, e, f, g, h, i):
        return a * e * i - a * f * h - b * d * i + b * f * g + c * d * h - c * e * g
    a, b, c = matrix[0]
    d, e, f = matrix[1]
    g, h, i = matrix[2]

