def check_diagonal_pattern(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if rows < 2 or cols < 2:
        return False
    first_row = grid[0]
    if not all(x == first_row[0] for x in first_row):
        return False
    first_column = [row[0] for row in grid]
    if not all(x == first_column[0] for x in first_column):
        return False
    if first_row[0] != first_column[0]:
        return False
    second_row = grid[1]
    second_column = [row[1] for row in grid]
    if second_row[1] != second_column[1] or second_row[1] == first_row[0]:
        return False
    if rows >= 3 and cols >= 3:
        third_row = grid[2]
        third_column = [row[2] for row in grid]
        if third_row[2] != third_column[2] or third_row[2] == first_row[0] or third_row[2] == second_row[1]:
            return False

    return True

