def roman_to_decimal(s: str) -> int:
    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    decimal_value = 0
    i = len(s) - 1

    while i >= 0:

        if i > 0 and roman_map[s[i]] > roman_map[s[i-1]]:
            decimal_value += roman_map[s[i]] - roman_map[s[i-1]]
            i -= 2
        else:
            decimal_value += roman_map[s[i]]
            i -= 1

    return decimal_value

