def longest_substring_without_repeats(strings):
    """
    Given a list of strings, return a list of strings with each string replaced by the longest substring that has no repeated characters.
    """
    result = []
    for s in strings:
        window_size = 1
        max_substring = ''
        while window_size <= len(s):
            for i in range(len(s) - window_size + 1):
                substring = s[i:i+window_size]
                if len(set(substring)) == len(substring):
                    max_substring = substring
            window_size += 1
        result.append(max_substring)
    return result

