OPERATORS = {"AND": 0, "OR": 0, "NOT": 1}
PRECEDENCE = {"AND": 1, "OR": 2}
variables = {"A": True, "B": False, "C": True}

def evaluate_expression(expression):
    tokens = [token for token in expression.split(" ") if token]
    tree = []
    stack = []
    for token in tokens:
        if token in OPERATORS:
            while stack and stack[-1] in PRECEDENCE and PRECEDENCE[token] <= PRECEDENCE[stack[-1]]:
                operator = stack.pop()
                right = tree.pop()
                left = tree.pop()
                tree.append([operator, left, right])
            stack.append(token)
        elif token == "(":
            stack.append(token)
        elif token == ")":
            while stack and stack[-1] != "(":
                operator = stack.pop()
                right = tree.pop()
                left = tree.pop()
                tree.append([operator, left, right])
            stack.pop()
        else:
            value = variables.get(token, False)
            tree.append(value)
    while stack:
        operator = stack.pop()
        right = tree.pop()
        left = tree.pop()
        tree.append([operator, left, right])
    def evaluate_tree(tree_node):
        if isinstance(tree_node, bool):
            return tree_node
        operator, left, right = tree_node
        if operator == "NOT":
            return not evaluate_tree(left)
        elif operator == "AND":
            return evaluate_tree(left) and evaluate_tree(right)
        elif operator == "OR":
            return evaluate_tree(left) or evaluate_tree(right)

    return evaluate_tree(tree[0])

import time
from functools import wraps, lru_cache

def memoize(func):
    """Caches the previous results of a function"""
    return lru_cache()(func)

def measure(func):
    """Measures the execution time of a function"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        print(f"Execution time: {end_time - start_time} seconds")
        return result
    return wrapper

@memoize
@measure
def factorial(n):
    """Calculates the factorial of a number"""
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

