import re

def sort_version_numbers(version_numbers):
    def version_key(version):
        pattern = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")
        match = pattern.match(version)
        if match:
            major, minor, patch = match.groups()
            if int(major) >= 0 and int(minor) >= 0 and int(patch) >= 0:
                return (int(major), int(minor), int(patch))
        raise ValueError("Invalid version number: " + version)

    return sorted(version_numbers, key=version_key)

def convert_to_english(number):
    if number < 0 or number > 999:
        return ''

    if number < 20:
        return ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
                'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'][number]

    if number < 100:
        tens_digit = number // 10
        tens_name = ['twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'][tens_digit - 2]
        remainder = number % 10
        if remainder == 0:
            return tens_name
        else:
            return f'{tens_name}-{convert_to_english(remainder)}'

    if number < 1000:
        hundreds_digit = number // 100
        hundreds_name = convert_to_english(hundreds_digit) + ' hundred'
        remainder = number % 100
        if remainder == 0:
            return hundreds_name
        else:
            return f'{hundreds_name} {convert_to_english(remainder)}'

import numpy as np

def min_max_scaling(arr: np.ndarray, scaled_range: tuple = (0, 1)) -> np.ndarray:
    min_val = np.min(arr)
    max_val = np.max(arr)
    def scale_to_01(x):
        return (x - min_val) / (max_val - min_val)

    def scale_to_m1p1(x):
        return 2 * (x - min_val) / (max_val - min_val) - 1
    scaling_fn = scale_to_01 if scaled_range == (0, 1) else scale_to_m1p1
    return np.vectorize(scaling_fn)(arr)

