def partition_graph(graph):
    vertex_colors = {}
    vertex_colors[0] = 0
    queue = [0]
    while queue:
        vertex = queue.pop(0)
        for neighbor in graph[vertex]:
            if neighbor not in vertex_colors:
                vertex_colors[neighbor] = 1 - vertex_colors[vertex]
                queue.append(neighbor)
            elif vertex_colors[neighbor] != 1 - vertex_colors[vertex]:
                raise Exception("Cannot partition the graph into two subsets")
    group_1 = [vertex for vertex, color in vertex_colors.items() if color == 0]
    group_2 = [vertex for vertex, color in vertex_colors.items() if color == 1]

    return group_1, group_2

