        raise ValueError("Input must be a positive integer.")
    totient = [1] * n
    for i in range(2, n + 1):
        if totient[i - 1] == 0:
            continue
        if n % i == 0:
            for j in range(i, n + 1, i):
                totient[j - 1] = 0
    totient_value = sum(totient)

