def partition(iterable, left, right):
    pivot = iterable[right]
    i = left - 1
    for j in range(left, right):
        if iterable[j] < pivot:
            i += 1
            iterable[i], iterable[j] = iterable[j], iterable[i]
    iterable[i+1], iterable[right] = iterable[right], iterable[i+1]
    return i + 1

def quick_select(iterable, left, right, k):
    if left == right:
        return left
    pivot_index = partition(iterable, left, right)
    if k == pivot_index:
        return k
    elif k < pivot_index:
        return quick_select(iterable, left, pivot_index - 1, k)
    else:
        return quick_select(iterable, pivot_index + 1, right, k)

def merge_dictionaries(*dicts):
    """
    Merges an arbitrary number of dictionaries into a single one.
    If a key is present in both dictionaries, the value from the second dictionary
    replaces the value in the merged dictionary.
    """

    def _merge_dict(d1, d2):
        for k, v in d2.items():
            if k in d1 and isinstance(d1[k], dict) and isinstance(d2[k], dict):
                _merge_dict(d1[k], d2[k])
            else:
                d1[k] = d2[k]

    merged_dict = {}
    for d in dicts:
        _merge_dict(merged_dict, d)
    return merged_dict

