import re

def replace_is_with_are(text: str) -> str:
    pattern = re.compile(r"\bis\b")
    words = text.split()
    modified_words = []
    for word in words:
        if word.startswith("is "):
            modified_words.append("are " + word[3:])
        elif pattern.fullmatch(word):
            modified_words.append("are")
        else:
            modified_words.append(word)
    return " ".join(modified_words)

def factorial(n):
    if n <= 1:
        return 1
    else:
        return n * factorial(n - 1)

def sine_term(x, n):
    sign = 1 if n % 2 == 0 else -1
    return sign * (x ** (2 * n + 1)) / factorial(2 * n + 1)

def my_sine(x):
    result = x
