def pointwise_score(x: torch.Tensor, y: torch.Tensor) -> float:
    scores = []
    for x_elem, y_elem in zip(x, y):
        if x_elem == y_elem:
            scores.append(0)
        elif x_elem != y_elem:
            scores.append(1)
        elif x_elem < 0.5 or y_elem < 0.5:
            scores.append(2)
        elif x_elem > 0.5 and y_elem > 0.5:
            scores.append(3)

    return sum(scores)

