def count_alive_neighbors(adjacency_matrix):
    rows = len(adjacency_matrix)
    cols = len(adjacency_matrix[0])
    neighbor_counts = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            neighbors = []
            for x in range(i - 1, i + 2):
                for y in range(j - 1, j + 2):
                    if (0 <= x < rows and 0 <= y < cols and
                        (x, y) != (i, j)):
                        neighbors.append(adjacency_matrix[x][y])

            neighbor_counts[i][j] = sum(neighbors)

    return neighbor_counts

