def quicksort(array, lo, hi):
    if hi - lo <= 1:
        return

    pivot = partition(array, lo, hi)
    quicksort(array, lo, pivot)
    quicksort(array, pivot + 1, hi)

def partition(array, lo, hi):
    pivot_index = choose_pivot(lo, hi)
    pivot_value = array[pivot_index]
    array[pivot_index], array[hi - 1] = array[hi - 1], array[pivot_index]
    store_index = lo
    for i in range(lo, hi - 1):
        if array[i] < pivot_value:
            array[store_index], array[i] = array[i], array[store_index]
            store_index += 1
    array[store_index], array[hi - 1] = array[hi - 1], array[store_index]
    return store_index

