def ttc(vehicle1, vehicle2):
    relative_position = (vehicle2.x - vehicle1.x, vehicle2.y - vehicle1.y)
    relative_velocity = (vehicle2.vx - vehicle1.vx, vehicle2.vy - vehicle1.vy)

    if relative_velocity[0] * relative_position[0] + relative_velocity[1] * relative_position[1] >= 0:
        return float('inf')

    relative_velocity_magnitude = relative_velocity[0] ** 2 + relative_velocity[1] ** 2
    return (relative_position[0] * relative_velocity[0] + relative_position[1] * relative_velocity[1]) / relative_velocity_magnitude

import os
import re

def read_batch_config_files(directory_path):
    """
    Reads AWS Batch configuration files from a given directory, parses the configuration,
    and returns a dictionary with the configuration details.
    """
    config_files = []
    config_details = {}

    try:
        for entry in os.scandir(directory_path):
            if entry.is_file():
                with open(entry.path, "r") as file:
                    config_file_version = re.search("(?<=^CONFIG_FILE_VERSION=)\d+", file.read())
                    config_files.append(entry.name)
                    config_details[entry.name] = {
                        "CONFIG_FILE_VERSION": config_file_version.group()
                    }
    except Exception as e:
        print(f"Error: {e}")

    return config_details

