import math

def radial_distance(point, circle_center, radius):
    if len(point) == 2 and len(circle_center) == 2:
        dx = point[0] - circle_center[0]
        dy = point[1] - circle_center[1]
        distance = math.sqrt(dx**2 + dy**2)
    elif len(point) == 3 and len(circle_center) == 3:
        dx = point[0] - circle_center[0]
        dy = point[1] - circle_center[1]
        dz = point[2] - circle_center[2]
        distance = math.sqrt(dx**2 + dy**2 + dz**2)
    else:
        raise ValueError("Incompatible dimensions between point and circle center")

    if distance == radius:
        return 0
    elif distance < radius:
        return -distance
    else:
        return distance

