def parse_length(input_string):
    pattern = r"\s*(\d+)\s*(cm|mm|m)\s*"
    match = re.search(pattern, input_string)
    if match:
        number = match.group(1)
        unit = match.group(2)
        if not number.isdigit() or int(number) < 0:
            raise ValueError("Invalid number: Must be non-negative integer.")
        if unit == "cm":
            return int(number) / 100
        elif unit == "mm":
            return int(number) / 1000
        else:  # unit is "m"
            return int(number)
    else:
        raise ValueError("Invalid format: Must be a string in the format '<number> <unit>'.")

