def is_valid_function(func):
    if inspect.getmodule(func) is None:
        return False
    try:
        signature = inspect.signature(func)
    except ValueError:
        return False

    for param in signature.parameters.values():
        if param.default is not inspect.Parameter.empty or param.kind == inspect.Parameter.KEYWORD_ONLY:
            return False
    if signature.return_annotation is not inspect.Signature.empty and signature.return_annotation != signature.parameters['arg'].annotation:
        return False

    return True

