def longest_substring_no_duplicates(s):
    start, longest = 0, 0
    seen = {}
    for end in range(len(s)):
        if s[end] in seen:
            start = max(start, seen[s[end]] + 1)
        seen[s[end]] = end
        longest = max(longest, end - start + 1)
    return longest

