def check_string_conditions(string: str) -> bool:
    for i in range(len(string) - 1):
        if string[i] == string[i + 1]:
            return True
    if len(string) > 0 and all(c == string[0] for c in string):
        return True
    if len(string) > 0:
        substring_length = 2
        while substring_length <= len(string) // 2:
            substring = string[:substring_length]
            if all(substring[i] == substring[i + 1] for i in range(len(substring) - 1)):
                repeated_substring = substring * (len(string) // len(substring))
                if repeated_substring == string:
                    return True
            substring_length += 1

