def binary_search_iterative(arr, target):
    if not arr:
        return -1

    start = 0
    end = len(arr) - 1

    while start <= end:
        mid = (start + end) // 2

        if arr[mid] < target:
            start = mid + 1
        elif arr[mid] > target:
            end = mid - 1
        else:
            return mid

    return -1

def parse_http_uri(uri: str) -> dict:
    if not uri.startswith('http://') and not uri.startswith('https://'):
        raise ValueError('Invalid URI scheme')
    if '#' not in uri:
        raise ValueError('Missing fragment identifier')
    fragment = uri.split('#')[1]
    key_value_pairs = {}
    for query_str in fragment.split('&'):
        key, value = query_str.split('=')
        if key in key_value_pairs:
            key_value_pairs[key].append(value)
        else:
            key_value_pairs[key] = [value]

    return key_value_pairs

