def count_reachable_nodes(node, visited=None):
    """
    Counts the number of nodes reachable from the given node using a depth-first search.
    """
    if not visited:
        visited = set()
    if node not in visited:
        visited.add(node)
        count = 1
        for child in node.children:
            count += count_reachable_nodes(child, visited)

        return count
    return 0

