def longest_increasing_subsequence(nums):
    """
    Finds the longest increasing subsequence (LIS) in a list of integers.
    """
    @lru_cache(maxsize=None)
    def length(index):
        """
        Returns the length of the longest increasing subsequence that ends at the given index.
        """
        if index == 0:
            return 1

        max_length = 1
        for i in range(index):
            if nums[i] < nums[index]:
                max_length = max(max_length, length(i) + 1)

        return max_length

    max_length = 1
    for i in range(len(nums)):
        max_length = max(max_length, length(i))

    return max_length

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        elif self.rank[x_root] > self.rank[y_root]:
            self.parent[y_root] = x_root
        else:
            self.parent[y_root] = x_root
            self.rank[x_root] += 1
        return True

def kruskal(edges):
    edges.sort(key=lambda e: e[2])  # Sort edges by weight
    n = len(edges)
    mst = []
    union_find = UnionFind(n)
    for i, j, w in edges:
        if union_find.union(i, j):
            mst.append((i, j, w))
    return mst

