def binary_search_leftmost(lst, value):
    left = 0
    right = len(lst) - 1

    while left <= right:
        mid = (left + right) // 2
        if lst[mid] == value:
            if mid == 0 or lst[mid-1] < value:
                return mid
            else:
                right = mid - 1
        elif lst[mid] < value:
            left = mid + 1
        else:
            right = mid - 1
    return -1

