def count_properly_nested_parentheses(string):
    stack = []
    for char in string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) == 0:
                return False
            last_char = stack.pop()
            if last_char != '\\':
                return False
    return len(stack) == 0

