def validate_json_object(json_object, schema):
    if schema['type'] == 'object':
        for prop in schema['required']:
            if prop not in json_object:
                return False
        for prop, prop_schema in schema['properties'].items():
            if prop not in json_object:
                return False
            if not validate_json_object(json_object[prop], prop_schema):
                return False
        return True
    elif schema['type'] == 'string':
        return isinstance(json_object, str)
    elif schema['type'] == 'integer':
        return isinstance(json_object, int)
    else:
        return False
