def predict_state_space(node_states):
    state_space = []
    for node_state in node_states:
        states = [d['state'] for d in node_state]
        predicts = []
        for i in range(len(states) - 1):
            current_state = states[i]
            neighboring_states = states[i + 1:]
            predictions = []
            for neighbor_state in neighboring_states:
                prediction = current_state + neighbor_state
                predictions.append(prediction)
            predicts.append(predictions)
        state_space.append({
            'states': states,
            'predicts': predicts
        })
    return state_space

