def generate_string_function(prefix, n):
    letters = list(string.ascii_lowercase)
    def generate_string(prefix, n):
        string = prefix
        while True:
            digits = [random.choice(letters) for _ in range(n - len(prefix))]
            string += "".join(digits)
            if not string[0].isdigit():
                return string

    return generate_string(prefix, n)

