import math

def to_base(number: int, base: int) -> str:
    if number < 0 or base < 2 or base > 36:
        return None

    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = []
    while number > 0:
        last_digit = number % base
        number //= base
        result.append(digits[last_digit])
    result.reverse()
    return "".join(result)

