import torch.nn as nn

def initialize_network(layer_config):
    network = nn.Sequential()

    for layer in layer_config:
        layer_type = layer['type']
        layer_params = layer['params']

        if layer_type == 'conv':
            layer = nn.Conv2d(**layer_params)
        elif layer_type == 'linear':
            layer = nn.Linear(**layer_params)
        elif layer_type == 'relu':
            layer = nn.ReLU(**layer_params)

        network.add_module(f"{layer_type}_{len(network)}", layer)

    return network

def get_ranges(sorted_list):
    ranges = []
    start = None
    end = None

    for i, num in enumerate(sorted_list):
        if i == 0:
            start = num
            end = num
        else:
            if sorted_list[i - 1] == num - 1:
                end = num
            else:
                ranges.append((start, end))
                start = num
                end = num

    ranges.append((start, end))
    return ranges

def format_ranges(ranges):
    formatted_ranges = []
    for start, end in ranges:
        if start == end:
            formatted_ranges.append(str(start))
        else:
            formatted_ranges.append(f"{start}-{end}")

    return ", ".join(formatted_ranges)

def describe_distribution(numbers):
