import hashlib
import binascii

def compute_file_sha256_hash(filename: str) -> str:
    buffer_size = 65536 # 64 KB
    sha256_hash = hashlib.sha256()
    with open(filename, "rb") as file:
        while True:
            buffer = file.read(buffer_size)
            if not buffer:
                break
            sha256_hash.update(buffer)
    return binascii.b2a_hex(sha256_hash.digest()).decode("utf-8")

