def line_through_two_points(points):
    if len(points) < 2:
        return False
    if all(points[0] == point for point in points):
        return False
    slope = (points[1][1] - points[0][1]) / (points[1][0] - points[0][0])
    for point in points[2:]:
        if (point[1] - points[0][1]) / (point[0] - points[0][0]) != slope:
            return False

    return True

