import numpy as np
from numpy.linalg import norm

def signed_angle(v1, v2):
    angle = np.arccos(np.dot(v1, v2) / (norm(v1) * norm(v2)))
    cross_prod = np.cross(v1, v2)
    if np.dot(cross_prod, np.array([0, 0, 1])) < 0:
        angle = -angle
    return np.degrees(angle)

