import datetime

def calculate_average_delay(data):
    delay_sum = {}
    delay_count = {}

    for timestamp, delay in data:
        if delay == "NaN":
            continue
        hour = datetime.datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S").hour
        delay_sum[hour] = delay_sum.get(hour, 0) + float(delay)
        delay_count[hour] = delay_count.get(hour, 0) + 1

    average_delay = {hour: delay_sum[hour] / delay_count[hour] for hour in delay_sum}

    return average_delay

