def are_equal(arg1, arg2, debug=False):
    if type(arg1) != type(arg2):
        if debug:
            print(f"Arguments are not equal: arg1 is type {type(arg1)}, arg2 is type {type(arg2)}")
        return False
    if isinstance(arg1, list) and isinstance(arg2, list):
        if len(arg1) != len(arg2):
            return False
        for i in range(len(arg1)):
            if not are_equal(arg1[i], arg2[i]):
                return False

        return True
    if isinstance(arg1, dict) and isinstance(arg2, dict):
        if arg1.keys() != arg2.keys():
            return False
        for key in arg1.keys():
            if not are_equal(arg1[key], arg2[key]):
                return False

        return True
    return arg1 == arg2

