import string
from collections import defaultdict

def find_words_with_at_least_two_occurrences(filename):
    with open(filename, 'r') as input_file:
        word_counts = defaultdict(int)
        for line in input_file:
            line = line.translate(str.maketrans('', '', string.punctuation))
            words = line.split()
            for word in words:
                word_counts[word] += 1
    return set(word for word, count in word_counts.items() if count >= 2)

