import numpy as np

def random_select_element(elements: list, probabilities: list) -> object:
    if len(elements) != len(probabilities):
        raise ValueError("The number of elements and probabilities must be equal.")

    total_probability = sum(probabilities)
    if total_probability != 1.0:
        raise ValueError("The sum of probabilities must be equal to 1.")

    cumulative_probabilities = np.cumsum(probabilities)
    random_number = np.random.random()

    for element, cumulative_probability in zip(elements, cumulative_probabilities):
        if random_number < cumulative_probability:
            return element

    return elements[-1]

