    assert isinstance(box1, tuple) and len(box1) == 4 and isinstance(box1[0], (int, float)) and isinstance(box1[1], (int, float)) and isinstance(box1[2], (int, float)) and isinstance(box1[3], (int, float)), "Invalid input type for box1"
    assert isinstance(box2, tuple) and len(box2) == 4 and isinstance(box2[0], (int, float)) and isinstance(box2[1], (int, float)) and isinstance(box2[2], (int, float)) and isinstance(box2[3], (int, float)), "Invalid input type for box2"
    x1, y1, x2, y2 = box1
    x3, y3, x4, y4 = box2
    if x1 < x4 and x3 < x2:
