def decode_integer_from_chars(encoded_chars: str) -> int:
    if not encoded_chars:
        return 0

    decoded_integer = 0
    for i, char in enumerate(encoded_chars):
        value = ord(char) - 63
        if value & 32:
            decoded_integer <<= 5
        decoded_integer += value & 31

    return decoded_integer

