        groups = match.groupdict()
        method_name = groups["method_name"]
        arguments = groups["arguments"]
        arguments = re.sub(r"\s", "", arguments)
        arguments = re.sub(r",\s*", ",", arguments)
        return "%s(%s)" % (method_name, arguments)
    else:
        raise Exception("Invalid function definition.")

