    state_machine = {}
    for example in examples:
        input_digits = example[0].split()
        output_words = example[1].split()
        for i in range(len(input_digits)):
            input_digit = input_digits[i]
            output_word = output_words[i]
            if input_digit in state_machine:
                next_states = state_machine[input_digit]
            else:
                next_states = {}
                state_machine[input_digit] = next_states
            if output_word in next_states:
                next_states[output_word] += 1
            else:
