def binomial_coefficient(n, k):
    table = [[None for _ in range(k+1)] for _ in range(n+1)]

    def binomial(n, k):
        if k == 0 or n == k:
            return 1
        if table[n][k] is not None:
            return table[n][k]
        if k > n / 2:
            k = n - k
        result = binomial(n-1, k-1) + binomial(n-1, k)
        table[n][k] = result
        return result

    return binomial(n, k)

