def parse_shell_command_output(command, output_file, append_to_file):
    try:
        shell_output = subprocess.run(command, capture_output=True, text=True)
        pattern = re.compile(r"\d+:\s+([A-Za-z0-9_]+)\s+(.*)")
        parsed_info = {}
        for line in shell_output.stdout.splitlines():
            match = pattern.match(line)
            if match:
                pid, name = match.groups()
                parsed_info[pid] = name
        if append_to_file:
            mode = "a"
        else:
            mode = "w"
        with open(output_file, mode) as f:
            for pid, name in parsed_info.items():
                f.write(f"{pid}: {name}\n")

        return parsed_info
    except Exception as e:
        print(f"Exception occurred: {e}")
        return None

