import re

def replace_key(string, namespace):
    pattern = r"{{(\w+(?:\.\w+)*?)}}"  # Matches {{key}} with nested namespaces
    result = re.sub(pattern, lambda match: _replace_key_helper(match.group(1), namespace), string)
    return result

def _replace_key_helper(key, namespace):
    keys = key.split(".")  # Split key into individual components
    value = namespace
    for k in keys:
        if k in value:
            value = value[k]
        else:
            return "{{" + key + "}}"  # Return pattern unchanged if key not found in namespace
    return str(value)

