def sum_of_first_n_primes(n):
    prime_numbers = [True] * (n + 1)  # Create a list of boolean values
    prime_numbers[0] = False  # 0 is not a prime number
    prime_numbers[1] = False  # 1 is not a prime number

    for i in range(2, int(n ** 0.5) + 1):
        if prime_numbers[i]:
            for j in range(i * i, n + 1, i):
                prime_numbers[j] = False
    sum_of_primes = 0
    for i in range(2, n + 1):
        if prime_numbers[i]:  # Check if the number is a prime number
            sum_of_primes += i

    return sum_of_primes

