import numpy as np
import pandas as pd

def normalize_arrays_or_dataframes(dictionaries: dict) -> dict:
    """
    Normalizes the arrays or dataframes in a dictionary by standardizing each array or dataframe.
    """
    if not isinstance(dictionaries, dict):
        raise TypeError("Input must be a dictionary.")

    normalized = {}

    for key, value in dictionaries.items():
        if isinstance(value, np.ndarray) or isinstance(value, pd.DataFrame):
            mean = value.mean()
            std = value.std()
            normalized[key] = (value - mean) / std
        else:
            raise TypeError("Each value in the dictionary must be either a NumPy array or a Pandas dataframe.")

    return normalized

def extract_tree(dataset):
    if not dataset or not all('id' in d and 'parent_id' in d and 'name' in d for d in dataset):
        raise ValueError('Invalid dataset')
    nodes = {}
    for record in dataset:
        if record['id'] in nodes:
            raise ValueError(f'Duplicate record with id {record["id"]}')
        node = {'id': record['id'], 'parent_id': record['parent_id'], 'name': record['name'], 'children': []}
        nodes[record['id']] = node
    root_nodes = []
    for node in nodes.values():
        if node['parent_id'] is not None:
            parent = nodes.get(node['parent_id'])
            if parent:
                parent['children'].append(node)
            else:
                raise ValueError(f'Invalid parent_id {node["parent_id"]} for node with id {node["id"]}')
        else:
            root_nodes.append(node)
    return root_nodes

