def convert_words_to_lengths(words: Dict[str, List[str]]) -> Dict[str, int]:
    """
    Converts a dictionary of words and their variations to a dictionary of words and their lengths.
    For example, given the input `{'a': ['ab', 'abc'], 'b': ['bc', 'bcd']}`, the function returns
    a new dictionary of `{'a': 1, 'ab': 2, 'abc': 3, 'b': 1, 'bc': 2, 'bcd': 3}`.
    """
    result = {}

    for key, value in words.items():
        result[key] = len(key)
        for word in value:
            result[word] = len(word)

