def binary_addition(a: int, b: int) -> int:
    binary_a = bin(a)[2:]
    binary_b = bin(b)[2:]
    if len(binary_a) < len(binary_b):
        binary_a = binary_a.rjust(len(binary_b), '0')
    else:
        binary_b = binary_b.rjust(len(binary_a), '0')
    binary_sum = ''
    carry = 0
    for i in range(len(binary_a) - 1, -1, -1):
        sum_bit = int(binary_a[i]) + int(binary_b[i]) + carry
        binary_sum = str(sum_bit % 2) + binary_sum
        carry = sum_bit // 2
    if carry > 0:
        binary_sum = str(carry) + binary_sum
    return int(binary_sum, 2)

