def get_nested_attribute(obj, attr_path):
    """
    Retrieves the value of a nested attribute from a JSON object.
    """
    tokens = attr_path.split('.')

    def _get_attr(obj, token):
        if isinstance(obj, dict) and token in obj:
            return obj[token]
        elif isinstance(obj, list) and token.isdigit() and int(token) < len(obj):
            return obj[int(token)]
        else:
            return None
    for token in tokens:
        result = _get_attr(obj, token)
