def search_closest_key(dictionary: dict, key: int) -> str:
    """
    Searches for the closest key in `dictionary` that is less than `key`.
    If the key is not present in the dictionary, returns the value of the closest key that is less than `key`.
    If there is no such key, returns `None`.
    """
    keys = sorted(dictionary.keys())
    left, right = 0, len(keys) - 1

    while left <= right:
        mid = (left + right) // 2

        if keys[mid] < key:
            left = mid + 1
        elif keys[mid] == key:
            return dictionary[key]
        else:
            right = mid - 1

    if right < 0:
        return None
    else:
        return dictionary[keys[right]]

