def binary_search(array, target):
    def search(array, target, start, end):
        if start > end:
            return start

        mid = (start + end) // 2
        if array[mid] == target:
            return mid
        elif array[mid] < target:
            return search(array, target, mid+1, end)
        else:
            return search(array, target, start, mid-1)

    return search(array, target, 0, len(array)-1)

