def wildcard_match(string, pattern):
    string_idx = 0
    pattern_idx = 0

    while string_idx < len(string) and pattern_idx < len(pattern):
        if pattern[pattern_idx] == '*' or pattern[pattern_idx] == '?':
            string_idx += 1
            pattern_idx += 1
        elif string[string_idx] == pattern[pattern_idx]:
            string_idx += 1
            pattern_idx += 1
        else:
            return False
    return string_idx == len(string) and pattern_idx == len(pattern)

