def convert_numerical_range(value, source_range, target_range):
    if target_range[0] > target_range[1] or source_range[0] > source_range[1]:
        return None  # Invalid range

    source_min, source_max = source_range
    target_min, target_max = target_range
    if source_min != source_max:
        value = (value - source_min) * (target_max - target_min) / (source_max - source_min) + target_min
    if value < target_min:
        value = target_min
    elif value > target_max:
        value = target_max

    return value

