def fibonacci(n):
    if n < 0:
        raise ValueError("n cannot be negative")
    if n == 0:
        return 0
    memo = {0: 0, 1: 1}

    def fib(n):
        if n in memo:
            return memo[n]
        result = fib(n - 1) + fib(n - 2)
        memo[n] = result
        return result

    return fib(n)

import numpy as np

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(np.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def smallest_prime_factor(n):
    if n <= 1:
        return None
    if is_prime(n):
        return n
    for i in range(2, int(np.sqrt(n)) + 1):
        if n % i == 0 and is_prime(i):
            return i
    return n

