def execute_program(program):
    accumulator = 0
    operations = {
        1: lambda x: accumulator + x,
        2: lambda x: accumulator * x,
        3: lambda x: accumulator + x,
    }

    for instruction in program:
        operation_code, operand = instruction
        if operation_code == 4:
