def dfs(graph, start):
    """Depth-first search"""
    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            stack.extend(graph.get_neighbors(node))

    return visited

def bfs(graph, start):
    """Breadth-first search"""
    visited = set()
    queue = [start]

    while queue:
        node = queue.pop(0)
        if node not in visited:
            visited.add(node)
            queue.extend(graph.get_neighbors(node))

    return visited

