    a_pointer = 0
    b_pointer = 0
    merged_list = []

    while a_pointer < len(list_a) and b_pointer < len(list_b):
        if list_a[a_pointer] <= list_b[b_pointer]:
            merged_list.append(list_a[a_pointer])
            a_pointer += 1
        else:
            merged_list.append(list_b[b_pointer])
