def flatten_dict(dictionary: dict, prefix: str = "") -> dict:
    """
    Flattens a nested dictionary by converting data types and removing empty dictionaries.
    """
    flattened_dict = {}

    for key, value in dictionary.items():
        new_key = prefix + key

        if isinstance(value, dict):
            flattened_dict.update(flatten_dict(value, new_key + "_"))
        elif isinstance(value, list) and value:
            flattened_dict[new_key] = tuple(value)
        elif value is not None:
            flattened_dict[new_key] = _convert_to_python_type(value)

    return flattened_dict

def _convert_to_python_type(value: Any) -> Any:
    """
    Converts a value to its corresponding Python data type.
    """
    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            return value
    else:
        return value

