def is_perfect_square(n: int) -> bool:
    def square_root(n: int, low: int, high: int) -> int:
        if low > high:
            return low - 1

        mid = (low + high) // 2
        square = mid * mid

        if square == n:
            return mid
        elif square > n:
            return square_root(n, low, mid - 1)
        else:
            return square_root(n, mid + 1, high)
    if n == 0 or n == 1:
        return True
    root = square_root(n, 0, n)
    if root * root == n:
        return True
    else:
        return False

