def decode_chars_to_integer(chars: str) -> int:
    if not chars:
        return 0
    chunks = list(chars)
    value = 0

    while chunks:
        chunk = ord(chunks.pop(0)) - 63
        if chunk & 32:
            value <<= 5
            value += chunk & 31
        else:
            value <<= 5
            value += chunk
    return value

