def find_smallest_largest_average(nums: List[int]) -> Tuple[int, int, float]:
    smallest = float('inf')
    largest = float('-inf')
    average = 0

    for num in nums:
        if num < smallest:
            smallest = num
        if num > largest:
            largest = num
        average += num

    average /= len(nums)
