from collections.abc import Mapping

def transform_mapping(mapping: Mapping) -> dict:
    """
    Transforms a dictionary-like object by adding the value of the original key to the original value. For example,
    given a dictionary {'a': 1, 'b': 2}, the output should be {'a': 2, 'b': 4}. If the original value is `None`, the
    new value should also be `None`.
    """
    if not isinstance(mapping, Mapping):
        warnings.warn("The input is not a dictionary-like object.")
        return {}

    new_mapping = {}
    for key, value in mapping.items():
        if value is None:
            new_mapping[key] = value
        elif isinstance(value, Mapping):
            new_mapping[key] = transform_mapping(value)
        else:
            new_mapping[key] = value + value

    return new_mapping

