    if t < 0 or t > 1:
        raise ValueError("Interpolation factor must be between 0 and 1")
    r_interp = color1[0] + (color2[0] - color1[0]) * t
    g_interp = color1[1] + (color2[1] - color1[1]) * t
    b_interp = color1[2] + (color2[2] - color1[2]) * t
    r_interp = max(0, min(255, r_interp))
    g_interp = max(0, min(255, g_interp))
    b_interp = max(0, min(255, b_interp))

    return (r_interp, g_interp, b_interp)

