import urllib.parse

def build_tag_url(base_url, tag_definition):
    if not base_url or not isinstance(base_url, str):
        raise ValueError("Invalid base URL.")
    if not tag_definition or not isinstance(tag_definition, dict):
        raise ValueError("Invalid tag definition.")
    url_parts = urllib.parse.urlparse(base_url)
    url_query = urllib.parse.parse_qs(url_parts.query)
    url_query["tag"] = [tag_definition["tag"]]
    url_query.update(tag_definition["attributes"])
    updated_query_string = urllib.parse.urlencode(url_query, doseq=True)
    updated_url_parts = url_parts._replace(query=updated_query_string)
    updated_url = updated_url_parts.geturl()

    return updated_url

