    for variable, coefficient in dictionary.items():
        if coefficient == 0:
            continue  # Skip variable if coefficient is zero
        elif coefficient < 0:
            equation += f" - {abs(coefficient)}*{variable}"
        elif coefficient > 0:
            equation += f" + {coefficient}*{variable}"
    if equation:
        equation = equation.lstrip(" +")  # Remove leading plus sign
    else:
        equation = "0"  # Default equation if dictionary is empty
    return equation

