def is_parentheses_balanced(s: str) -> bool:
    """
    Checks if a string containing parentheses is balanced.
    Returns a boolean value indicating whether the parentheses are balanced.
    """
    stack = []

    for char in s:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if len(stack) == 0:
                return False
            elif (char == ')' and stack[-1] == '(') or (char == ']' and stack[-1] == '[') or (char == '}' and stack[-1] == '{'):
                stack.pop()
            else:
                return False

    return len(stack) == 0

