def matches_pattern(value: str, pattern: str) -> bool:
    def match_recursive(i: int, j: int) -> bool:
        if j == len(pattern):
            return i == len(value)
        if i == len(value):
            return pattern[j] == "*" and match_recursive(i, j + 1)

        if pattern[j] == "*":
            return match_recursive(i + 1, j) or match_recursive(i, j + 1)

        return pattern[j] == value[i] and match_recursive(i + 1, j + 1)

    return match_recursive(0, 0)

