import json

def escape_json(json_str):
    try:
        obj = json.loads(json_str)
        def escape_quotes(key_or_value):
            if isinstance(key_or_value, str):
                return key_or_value.replace("'", "\\'")
            return key_or_value

        escaped_obj = {escape_quotes(key): escape_quotes(value) for key, value in obj.items()}
        escaped_json_str = json.dumps(escaped_obj)

        return escaped_json_str
    except json.JSONDecodeError:
        raise ValueError('Cannot parse the input string as a JSON object')

