def detect_mime_type(file_path):
    with open(file_path, 'rb') as f:
        magic_number = f.read(4)
    magic_number_hex = magic_number.hex().upper()
    if magic_number_hex in ('FFD8FF', 'FFD8FFE0', 'FFD8FFE1', 'FFD8FFE2', 'FFD8FFE3', 'FFD8FFE8'):
        return 'image/jpeg'
    elif magic_number_hex == '89504E47':
        return 'image/png'
    elif magic_number_hex == '47494638':
        return 'image/gif'
    elif magic_number_hex == '25504446':
        return 'application/pdf'
    elif magic_number_hex in ('504B0304', '504B0506', '504B0708'):
        return 'application/zip'
    else:
        return None

