def traverse_tree_backtracking(root):
    result = []

    def visit_node(node):
        result.append(node['value'])
        if node['children']:
            for child in node['children']:
                visit_node(child)

    visit_node(root)
    return result

def process_table(table):
    num_columns = len(table[0])
    min_max_values = [[float('inf'), -float('inf')] for _ in range(num_columns)]
    for row in table:
        for i, value in enumerate(row):
            if value < min_max_values[i][0]:
                min_max_values[i][0] = value
            if value > min_max_values[i][1]:
                min_max_values[i][1] = value
    return [tuple(min_max) for min_max in min_max_values]

def bitstring_to_bytes(bitstring, endianness='little'):
    assert bitstring.isnumeric() and bitstring.isalnum(), "Input must be a bit string"
    padded_bitstring = bitstring.ljust(len(bitstring) + (8 - len(bitstring) % 8) % 8, '0')
    return bytes(int(padded_bitstring[i:i+8], 2) for i in range(0, len(padded_bitstring), 8))

