def handle_game_results(game_results, k):
    assert len(game_results) > 0, "The game needs to have at least one result."
    assert k > 0, "The threshold k must be greater than 0."

    current_level = 0
    previous_level = 0

    for result in game_results:
        if current_level <= k:
            if result > previous_level:
                current_level += 1
            else:
                current_level -= 1
        else:
            break

        previous_level = current_level

    return current_level

