import re

def convert_urls(urls):
    """
    Converts a list of URLs into a single string with each URL on a new line and a number added in front.
    """
    result = []
    domain_counts = {}
    for url in urls:
        domain = re.search(r'www\.([a-z]+)\.', url).group(1)
        domain_counts[domain] = domain_counts.get(domain, 0) + 1
    sorted_domains = sorted(domain_counts.keys(), key=lambda domain: domain_counts[domain], reverse=True)
    for index, domain in enumerate(sorted_domains):
        result.append(f"{index + 1}. www.{domain}.com")

    return "\n".join(result)

