def least_common_ancestor(root, nodes):
    if not root:
        return None
    if not nodes:
        return root

    left, right = [node for node in nodes if node.value < root.value], [node for node in nodes if node.value > root.value]

    if len(left) == len(right):
        return root
    elif len(left) > len(right):
        return least_common_ancestor(root.left, left)
    else:
        return least_common_ancestor(root.right, right)

