def get_next_integer(num_str: str) -> int:
    """
    Returns the next integer that matches the difference between the input integer and the current integer.
    Raises a ValueError if the input is not a valid integer or a positive integer, or an OverflowError
    if the difference between the input and the next integer is greater than the library size.
    """
    try:
        num = int(num_str)
    except ValueError:
        raise ValueError("Input is not a valid integer.")
    if num < 0:
        raise ValueError("Input is not a positive integer.")
    current = num

    while True:
        if current - num == num:
            return current
        current += 1

        if current > num:
            raise OverflowError("Difference between the input and the next integer is greater than the library size.")

