def dfs(graph, source, target):
    visited = set()
    stack = [source]

    while stack:
        node = stack.pop()
        if node == target:
            return True
        if node in visited:
            continue
        visited.add(node)
        neighbors = graph[node]
        for neighbor in neighbors:
            if neighbor not in visited:
                stack.append(neighbor)
    return False

def bfs(graph, source, target):
    visited = set()
    queue = [source]

    while queue:
        node = queue.pop(0)
        if node == target:
            return True
        if node in visited:
            continue
        visited.add(node)
        neighbors = graph[node]
        for neighbor in neighbors:
            if neighbor not in visited:
                queue.append(neighbor)
    return False

