def find_zero_subset(nums):
    subsets = []
    subset_sums = []
    n = len(nums)

    def dfs(idx, cur_sum, cur_subset):
        if idx == n:
            subsets.append(cur_subset)
            subset_sums.append(cur_sum)
            return
        dfs(idx + 1, cur_sum + nums[idx], cur_subset + [nums[idx]])
        dfs(idx + 1, cur_sum, cur_subset)

    dfs(0, 0, [])
    for i, subset_sum in enumerate(subset_sums):
        if subset_sum == 0:
            return subsets[i]
    return []

def format_string(s: str, n: int) -> str:
    """
    Formats a given string. Each character in the string is repeated n times,
    and the characters are concatenated together. The function uses recursion to
    format the string.
    """
    def helper(s: str, n: int) -> str:
        if n == 0 or not s:
            return ""
        curr_char = s[0]
        return curr_char * n + helper(s[1:], n)

    return helper(s, n)

def union(set1, set2):
    """
    Performs a union operation between two sets.

    Args:
        set1 (set or frozenset or list): The first set.
        set2 (set or frozenset or list): The second set.

    Returns:
        set: The resulting union set.

    Examples:
        >>> a = {1, 2, 3}
        >>> b = {2, 3, 4}
        >>> union(a, b)
        {1, 2, 3, 4}
        >>> c = frozenset([4, 5, 6])
        >>> union(b, c)
        {2, 3, 4, 5, 6}
    """
    return set(set1).union(set2)

