def traverse_binary_tree_in_order(node, result):
    if node.left:
        traverse_binary_tree_in_order(node.left, result)
    result.append(node.value)
    if node.right:
        traverse_binary_tree_in_order(node.right, result)

def traverse_binary_tree_post_order(node, result):
    if node.left:
        traverse_binary_tree_post_order(node.left, result)
    if node.right:
        traverse_binary_tree_post_order(node.right, result)
    result.append(node.value)

def traverse_binary_tree_pre_order(node, result):
    result.append(node.value)
    if node.left:
