def calculate_island_boundaries(map):
    visited = [[False for _ in range(len(map[0]))] for _ in range(len(map))]
    islands = []

    def dfs(r, c, island_boundaries):
        if r < 0 or r >= len(map) or c < 0 or c >= len(map[0]) or map[r][c] == 0 or visited[r][c]:
            return
        visited[r][c] = True
        island_boundaries[0] = min(island_boundaries[0], r)
        island_boundaries[1] = max(island_boundaries[1], r)
        island_boundaries[2] = min(island_boundaries[2], c)
        island_boundaries[3] = max(island_boundaries[3], c)
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for dr, dc in directions:
            dfs(r + dr, c + dc, island_boundaries)

    for r in range(len(map)):
        for c in range(len(map[0])):
            if map[r][c] != 0 and not visited[r][c]:
                island_boundaries = [r, r, c, c]
                dfs(r, c, island_boundaries)
                islands.append(tuple(island_boundaries))

    return islands

