        if i == len(matrix) - 1 and j == len(matrix[0]) - 1:
            return True
        matrix[i][j] = -1  # Mark the cell as visited
        return dfs(i + 1, j) or dfs(i - 1, j) or dfs(i, j + 1) or dfs(i, j - 1)

