def scale_numeric_array(array, lower_bound=0, upper_bound=1):
    if not isinstance(array, list) or not all(isinstance(element, (int, float)) for element in array):
        raise ValueError("Invalid input: input array must be a list of numeric elements.")
    if len(array) < 1:
        raise ValueError("Invalid input: input array must contain at least one element.")
    if not isinstance(lower_bound, (int, float)) or not isinstance(upper_bound, (int, float)):
        raise ValueError("Invalid input: bounds must be numeric values.")
    if lower_bound >= upper_bound:
        raise ValueError("Invalid input: lower bound must be lower than upper bound.")
    min_value = min(array)
    max_value = max(array)
    array_scaled = [(element - min_value) / (max_value - min_value) * (upper_bound - lower_bound) + lower_bound for element in array]

