def find_closest(entities, coordinate):
    def key(entity):
        return math.sqrt((entity[0] - coordinate[0]) ** 2 + (entity[1] - coordinate[1]) ** 2)
    sorted_entities = sorted(entities, key=key)
    closest = next(takewhile(lambda entity: key(entity) == key(sorted_entities[0]), sorted_entities))

    return closest

