def configure_firewall(xml_file, ip_address, allow=True):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        allowed_ips = root.findall("./allowed/ip")
        blocked_ips = root.findall("./blocked/ip")
        if any(ip.text == ip_address for ip in allowed_ips) or any(ip.text == ip_address for ip in blocked_ips):
            print(f"IP address {ip_address} is already in the firewall configuration.")
            return
        if allow:
            ET.SubElement(root.find("./allowed"), "ip").text = ip_address
        else:
            ET.SubElement(root.find("./blocked"), "ip").text = ip_address
        tree.write(xml_file)

        print(f"IP address {ip_address} added to the firewall configuration.")
    except Exception as e:
        print(f"Error occurred: {e}")

