def string_to_utf8_bytes(string):
    result = []

    for char in string:
        code_point = ord(char)
        if code_point <= 0x7F:
            result.append(code_point)
        elif code_point <= 0x7FF:
            result.append((code_point >> 6) | 0xC0)
            result.append((code_point & 0x3F) | 0x80)
        elif code_point <= 0xFFFF:
            result.append((code_point >> 12) | 0xE0)
            result.append(((code_point >> 6) & 0x3F) | 0x80)
            result.append((code_point & 0x3F) | 0x80)
        elif code_point <= 0x10FFFF:
            result.append((code_point >> 18) | 0xF0)
            result.append(((code_point >> 12) & 0x3F) | 0x80)
            result.append(((code_point >> 6) & 0x3F) | 0x80)
            result.append((code_point & 0x3F) | 0x80)
        else:
            raise ValueError("Code point out of range")

    return result

def rotated_binary_search(nums, target):
    pivot = 0
    for i in range(1, len(nums)):
        if nums[i] < nums[i - 1]:
            pivot = i
            break
    if target < nums[pivot] or target > nums[pivot - 1]:
        return -1
    if target >= nums[0]:
        start, end = 0, pivot - 1
    else:
        start, end = pivot, len(nums) - 1
    while start <= end:
        mid = (start + end) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            start = mid + 1
        else:
            end = mid - 1
    return -1

