    for key, value in dictionary.items():
        if type(value) == str:
            value = "'{}'".format(value.replace("'", "''"))
        query_string += "{} = {} AND ".format(key, value)
    query_string = query_string[:-5]  # Remove the last "AND "
    return query_string

import os
import sys
from multiprocessing import Process


def process_file(filename):
    lib = __import__(filename.replace(".py", ""))
    with open(filename) as f:
        for line in f:
            result = lib.func(line)
            print(result)


def main():
    files = sys.argv[1:]
    processes = []
    for filename in files:
        process = Process(target=process_file, args=(filename,))
        process.start()
        processes.append(process)
    for process in processes:
        process.join()


if __name__ == "__main__":
    main()

