def serialize_object(obj):
    def _serialize_object_helper(obj, prefix=None):
        if prefix is None:
            prefix = []
        if type(obj) is dict:
            for k, v in obj.items():
                yield from _serialize_object_helper(v, prefix + [k])
        elif hasattr(obj, '__dict__'):
            for k, v in obj.__dict__.items():
                yield from _serialize_object_helper(v, prefix + [k])
        else:
            yield ('.'.join(prefix), obj)
    return list(_serialize_object_helper(obj))

