def overlapping(rect1, rect2):
    if rect1[2] < rect2[0] or rect1[3] < rect2[1]:
        return False
    if rect1[0] > rect2[2] or rect1[1] > rect2[3]:
        return False
    return True

def split_str_custom(string, separator):
    result = []
    prev_idx = 0

    for i, char in enumerate(string):
        if char == separator:
            result.append(string[prev_idx:i])
            prev_idx = i + 1

    result.append(string[prev_idx:])
    return result

