def search_case_insensitive_identifier(identifier, data):
    if isinstance(data, dict):
        key_found = False
        for key, value in data.items():
            if key.lower() == identifier.lower():
                key_found = True
                result = value
                break

        if key_found:
            return result
        else:
            raise ValueError(f"Identifier '{identifier}' not found.")

    elif isinstance(data, list):
        item_found = False
        for item in data:
            if item.lower() == identifier.lower():
                item_found = True
                result = item
                break

        if item_found:
            return result
        else:
            raise ValueError(f"Identifier '{identifier}' not found.")

    else:
        raise TypeError(f"Unsupported data type: {type(data)}")

