def linear_interpolation(p1, p2, x):
    dist_p1_p2 = distance_between_points(p1, p2)
    dist_p1_x = distance_between_points(p1, x)
    return p1 + (dist_p1_x / dist_p1_p2) * (p2 - p1)

def distance_between_points(p1, p2):
    return abs(p2 - p1)

def parse_csv_string(s, default_value=[]):
    if not s:
        return default_value
    result = []
    current_number = ''
    state = 'reading_number'
    for c in s:
        if c.isdigit():
            current_number += c
            state = 'reading_number'
        elif c == ',':
            result.append(int(current_number))
            current_number = ''
            state = 'reading_separator'
        else:
            state = 'invalid_character'
            break
    if state == 'reading_number':
        result.append(int(current_number))
    elif state == 'invalid_character':
        return default_value
    return result

