def base3_representation(number):
    if number == 0:
        return '0'

    output = ''
    while number > 0:
        remainder = number % 3
        output = str(remainder) + output
        number //= 3

    return output

import json

def handle_jsonrpc_request(request):
    if not isinstance(request, dict):
        return {
            "jsonrpc": "2.0",
            "error": {
                "code": -32600,
                "message": "Invalid JSON"
            },
            "id": None
        }

    if not request.get("jsonrpc") == "2.0":
        return {
            "jsonrpc": "2.0",
            "error": {
                "code": -32601,
                "message": "Invalid JSON-RPC version"
            },
            "id": None
        }
    if request.get("method") == "echo":
        result = request.get("params", "default")
        return {
            "jsonrpc": "2.0",
            "result": result,
            "id": request.get("id"),
        }

    return {
        "jsonrpc": "2.0",
        "error": {
            "code": -32601,
            "message": "Invalid method"
        },
        "id": None
    }

def get_page(source, limit, continuation=None):
    if continuation is None:
        continuation = 0

    start = continuation
    end = continuation + limit
    page = source[start:end]

    if end >= len(source):
        next_continuation = None
    else:
        next_continuation = end

    return page, next_continuation

