def character_count(text: str) -> dict:
    """
    Returns a dictionary where the keys are the characters present in `text`, and the
    values are the number of occurrences of each character. For example, given
    `text = 'hello'`, the function should return `{'h': 1, 'e': 1, 'l': 2, 'o': 1}`.
    """
    counts = {}

    for char in text:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1

    return counts

def nusselt_criterion(flow_type, reynolds_number):
    if flow_type == "laminar":
        return 0.023 * (reynolds_number ** 0.8)
    elif flow_type == "turbulent":
        return 0.037 * (reynolds_number ** 0.8)
    else:
        raise Exception("Invalid flow type")

