def hexify(num: int) -> str:
    hex_str = ""
    while num > 0:
        digit = num & 0xF  # Get the last 4 bits
        if digit <= 9:
            hex_str += str(digit)  # Add the digit as a string
        elif digit == 10:
            hex_str += "A"
        elif digit == 11:
            hex_str += "B"
        elif digit == 12:
            hex_str += "C"
        elif digit == 13:
            hex_str += "D"
        elif digit == 14:
            hex_str += "E"
        else:
            hex_str += "F"
        num >>= 4  # Shift right by 4 bits to extract the next digit
    hex_str = "".join(reversed(hex_str))
    return "0x" + hex_str

def get_output_shape(input_shape, kernel_size, stride_size, padding_size, dilation_size):
    output_shape = [
        (input_shape[0] + 2 * padding_size[0] - dilation_size[0] * (kernel_size[0] - 1) - 1) // stride_size[0] + 1,
        (input_shape[1] + 2 * padding_size[1] - dilation_size[1] * (kernel_size[1] - 1) - 1) // stride_size[1] + 1
    ]
    return output_shape

