import math

def sum_power_series(x, precision=1e-9):
    partial_sum = 0
    n = 0
    while True:
        partial_sum += (x**n) / math.factorial(n)
        if abs(x**n) / math.factorial(n) < precision:
            break
        n += 1
    return partial_sum

def find_prime_factors(n):
    prime_factors = set()

    if n < 2:
        return prime_factors

    if n == 2:
        prime_factors.add(2)
        return prime_factors

    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            prime_factors.add(factor)
            n //= factor
        else:
            factor += 1

    prime_factors.add(n)
    return prime_factors

