def immutable_arg_checker(func):
    def wrapper(n):
        if not isinstance(n, int) or n < 0:
            raise ValueError('The argument must be an integer greater than or equal to 0.')
        return func(n)
    return wrapper

def memoize(func):
    cache = {}
    def wrapper(n):
        if n not in cache:
            cache[n] = func(n)
        return cache[n]
    return wrapper

@immutable_arg_checker
@memoize
def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

