def extract_key_value_pairs(dictionary):
    key_value_pairs = []

    def extract_pairs_from_obj(obj, prefix=""):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if isinstance(value, dict) or isinstance(value, list):
                    extract_pairs_from_obj(value, f"{prefix}{key}.")
                else:
                    key_value_pairs.append([f"{prefix}{key}", value])
        elif isinstance(obj, list):
            for index, item in enumerate(obj):
                if isinstance(item, dict) or isinstance(item, list):
                    extract_pairs_from_obj(item, f"{prefix}{index}.")
                else:
                    key_value_pairs.append([f"{prefix}{index}", item])

    extract_pairs_from_obj(dictionary)
    key_value_pairs.sort(key=lambda item: item[0])
    return key_value_pairs

class Node:
    def __init__(self, data, left=None, right=None):
        self.data = data
        self.left = left
        self.right = right

def pre_order_traversal(root):
    if root is None:
        return

    stack = []
    visited_nodes = []

    stack.append(root)
    while len(stack) > 0:
        node = stack.pop()
        visited_nodes.append(node.data)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)

    return visited_nodes

def get_public_and_private_attributes(module_name):
    try:
        module = __import__(module_name)  # Import the module
    except ModuleNotFoundError as e:
        raise Exception(f"Module not found: {module_name}") from e
    try:
        attributes = dir(module)  # Get a list of all attributes defined in the module
        public_attributes = [attr for attr in attributes if not attr.startswith("_")]
        private_attributes = [attr for attr in attributes if attr.startswith("_")]
        return (public_attributes, private_attributes)
    except AttributeError as e:
        raise Exception(f"Error accessing attributes in module: {module_name}") from e

