def validate_circuit(circuit):
    if len(circuit['name']) == 0:
        return False

    for gate in circuit['gates']:
        if len(gate['type']) == 0:
            return False

        for parameter in gate['parameters']:
            if parameter not in gate['parameters']:
                return False

            if isinstance(gate['parameters'][parameter], float):
                if gate['parameters'][parameter] < 0.0:
                    return False
    return True

def read_fasta(filename: str):
    with open(filename, 'r') as f:
        sequence = ''
        for line in f:
            if line.startswith('>'):
                if sequence:
                    yield sequence
                sequence = ''
            else:
                sequence += line.strip()
        yield sequence

