import struct

def read_int_file(file_path):
    with open(file_path, 'rb') as f:
        data = f.read()
    result = {}
    for i in range(0, len(data), 4):
        num = struct.unpack('<i', data[i:i+4])[0]  # Extract 4 bytes in little-endian format
        result[num] = result.get(num, 0) + 1  # Increment the count for this number
    return result

