def split_without_escape(text):
    sequences = []
    sequence = ""
    in_sequence = False
    for char in text:
        if in_sequence:
            if char == "'" or char == '"':  # Skip escape character and set flag to False
                in_sequence = False
            else:
                in_sequence = False  # Skip non-escape character and set flag to False
        elif char == "\\":
            in_sequence = True
        else:
            sequence += char
            if not in_sequence:
                sequences.append(sequence)
                sequence = ""
    return sequences

def get_object_attribute(obj, attr_name):
    if not isinstance(obj, object):
