class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def build_binary_tree(tree_dict):
    if not tree_dict:
        return None
    nodes = {key: Node(key) for key in tree_dict}

    root = None
    for key, (left, right) in tree_dict.items():
        node = nodes[key]
        if left is not None:
            node.left = nodes[left]
        if right is not None:
            node.right = nodes[right]
        if left is None and right is None:
            node.left = None
            node.right = None
        if root is None:
            root = node

    return root

