def reverse_first_k_chars(s: str, k: int) -> str:
    result = []
    for i in range(0, len(s), 2 * k):
        group = s[i:i + 2 * k]
        reversed_group = group[:k][::-1] + group[k:]
        result.append(reversed_group)
    return "".join(result)

def find_minimal_bounding_box(boxes):
    min_width = min([box[0] for box in boxes])
    max_width = max([box[0] for box in boxes])
    min_height = min([box[1] for box in boxes])
    max_height = max([box[1] for box in boxes])
    return ((max_width - min_width), (max_height - min_height))

class TrieNode(object):
    def __init__(self):
        self.children = {}
        self.is_word = False

class Trie(object):
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_word = True

    def search(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_word or any(node.children.values())

