def explore_paths(edges, start, target):
    all_paths = []

    def dfs(node, path):
        if node == target:
            all_paths.append(path)
            return

        for next_node in [edge[1] for edge in edges if edge[0] == node]:
            dfs(next_node, path + [next_node])

    dfs(start, [start])
    return all_paths

def calculate_triangle_perimeter(a, b, c):
    if not (isinstance(a, (int, float)) and a > 0):
        raise ValueError("a must be a positive number")
    if not (isinstance(b, (int, float)) and b > 0):
        raise ValueError("b must be a positive number")
    if not (isinstance(c, (int, float)) and c > 0):
        raise ValueError("c must be a positive number")
    if a + b <= c or b + c <= a or c + a <= b:
        raise ValueError("Invalid triangle sides")

    return a + b + c

