def make_fields_output_only(cls):
    """
    A decorator function that makes all fields of a class output-only.
    """
    new_cls = type(cls.__name__, cls.__bases__, dict(cls.__dict__))
    for attr_name in cls.__dict__:
        if not attr_name.startswith('_') and not callable(getattr(cls, attr_name)):
            new_attr_name = '_' + attr_name
            setattr(new_cls, new_attr_name, getattr(cls, attr_name))
            delattr(new_cls, attr_name)

    return new_cls

@make_fields_output_only
