def modify_url(url: str, query_params: dict) -> str:
    if not url or not urllib.parse.urlparse(url).scheme:
        return url
    if not query_params:
        return url
    if "?" in url:
        return url + "&" + urllib.parse.urlencode(query_params)
    return url + "?" + urllib.parse.urlencode(query_params)

