def newton_raphson_poly_root(poly, x0, max_iter=100):
    for i in range(max_iter):
        deriv = np.polyder(poly)
        x1 = x0 - np.polyval(poly, x0) / np.polyval(deriv, x0)
        if np.abs(x1 - x0) < 1e-8:
            return x1
        x0 = x1

    return x1

