def determine_position(sample, samples):
    if len(samples) == 0:
        return -1

    combined_coordinates = sample[0] + sample[1]

    position = -1

    for i in range(len(samples)):
        current_sample = samples[i]
        current_sample_coordinates = current_sample[0] + current_sample[1]
        if current_sample_coordinates < combined_coordinates:
            position = i
            break

    return position

