import os

def group_by_directory(file_paths):
    result = {}
    for path in file_paths:
        path_components = [component for component in path.split('/') if component != '']
        result = group_by_directory_recursive(result, path_components)
    return result

def group_by_directory_recursive(result, path_components):
    if len(path_components) == 0:
        return {}
    current_dir = path_components[0]
    if current_dir not in result:
        result[current_dir] = {}
    result[current_dir] = group_by_directory_recursive(result[current_dir], path_components[1:])
    return result

