def find_target_sum_combinations(nums, target):
    nums.sort()
    num_to_indices = {num: i for i, num in enumerate(nums)}
    result = []
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_indices and num_to_indices[complement] != i:
            if (num, complement) not in result and (complement, num) not in result:
                result.append((num, complement))
    return result

