import re

def detect_vulnerabilities(assembly_code):
    buffer_overflow_regex = re.compile(r'(\[.*\] += +.*) +rep movsb|mov (eax|ebx|ecx|edx), (\[.*\]) +rep movsb')
    use_after_free_regex = re.compile(r'call +.*destroy|mov (eax|ebx|ecx|edx), (\[.*\]) +call +.*destroy')
    format_string_regex = re.compile(r'call +.*printf|call +.*scanf')
    if re.search(buffer_overflow_regex, assembly_code) or re.search(use_after_free_regex, assembly_code) or re.search(format_string_regex, assembly_code):
        return True
    else:
        return False

