def is_valid_command(command):
    def is_valid_pair(pair):
        return (pair[0] == pair[1]) or (pair[0] == '<' and pair[1] == '>')

    if not command:
        return False
    if any(char.isspace() and char != ' ' for char in command):
        return False
    if any(char not in '<>/' for char in command):
        return False
    if command.count('/') == 0:
        return False
    if command.count('<>') == 0:
        return False
    pairs = [command[i:i+2] for i in range(len(command)-1) if command[i:i+2] in ('<>', '<>')]
    return all(is_valid_pair(pair) for pair in pairs)

