import json

def parse_json_type(json_object):
    try:
        obj = json.loads(json_object)
    except ValueError:
        return "invalid"

    obj_type = type(obj)
    if obj_type is list:
        return "list"
    elif obj_type is dict:
        return "dict"
    elif obj_type is bool:
        return "bool"
    elif obj_type is str:
        return "string"
    elif obj_type in (int, float):
        return "number"
    elif obj is None:
        return "null"
    else:
        return "other"

import heapq


def find_nth_smallest(nums, n):
    heap = []
    for num in nums:
        if len(heap) < n:
            heapq.heappush(heap, num)
        elif num < heap[0]:
            heapq.heapreplace(heap, num)
    return heap[0]

