def pascal_to_snake(string):
    snake_case = ''

    for i in range(len(string)):
        letter = string[i]
        if letter.isupper():
            if i > 0:
                snake_case += '_'
            letter = letter.lower()
        snake_case += letter

    return snake_case

import base64

def encode(byte_sequence):
    binary_string = "".join(format(b, "08b") for b in byte_sequence)
    base64_string = "".join(base64_alphabet[int(binary_string[i:i+6], 2)] for i in range(0, len(binary_string), 6))
    padding_length = (4 - len(base64_string) % 4) % 4
    return base64_string + "=" * padding_length

def decode(base64_string):
    binary_string = "".join(format(base64_alphabet_reverse[c], "06b") for c in base64_string if c != "=")
    byte_sequence = b"".join(int(binary_string[i:i+8], 2).to_bytes(1, "big") for i in range(0, len(binary_string), 8))
    return byte_sequence

def encode_bytes(byte_sequence):
    return base64.b64encode(byte_sequence)

def decode_bytes(base64_bytes):
    return base64.b64decode(base64_bytes)

