import os

def find_directories_with_files(root_dir, target_files, search_depth=None):
    found_directories = []

    for root, dirs, files in os.walk(root_dir):
        if search_depth is not None and len(root.split(os.path.sep)) > search_depth:
            continue

        for file in target_files:
            if file in files:
                found_directory = {"path": root, "files": [file]}
                found_directories.append(found_directory)
                break

    return found_directories

