import re

def natural_sort(file_paths):
    def split_components(path):
        components = path.split('/')
        for i, component in enumerate(components):
            match = re.match(r'^([a-zA-Z0-9][a-zA-Z0-9_\-]*)([0-9]+)(.*)$', component)
            if match:
                components[i] = (match.group(1), int(match.group(2)), match.group(3))
        return components

    return sorted(file_paths, key=split_components)

from typing import List

def convert_strings_to_floats(strings: List[str]) -> List[float]:
    """
    Converts a list of strings to a list of floats by converting each string to a float.
    If a string cannot be converted to a float, adds it to the list as a string.
    """
    def try_convert(string: str) -> float:
        try:
            return float(string)
        except ValueError:
            return string

    return [try_convert(string) for string in strings]

