def get_depth(node):
    depth = 0
    while node.parent is not None:
        node = node.parent
        depth += 1
    return depth
def find_lca(node1, node2):
    depth1 = get_depth(node1)
    depth2 = get_depth(node2)
    if depth1 > depth2:
        for _ in range(depth1 - depth2):
            node1 = node1.parent
    else:
        for _ in range(depth2 - depth1):
            node2 = node2.parent
    while node1 != node2:
        node1 = node1.parent
        node2 = node2.parent
    return node1

