def largest_divisor(x, y):
    if x < 1 or y < 1:
        return -1
    if x == y:
        return x
    if x > y:
        larger = x
        smaller = y
    else:
        larger = y
        smaller = x
    while smaller != 0:
        remainder = larger % smaller
        larger = smaller
        smaller = remainder
    gcd = larger
    if gcd == 1:
        return -1
    else:
        return gcd

