import numpy as np

def rescale_image(image, channel):
    """
    Rescales the R, G, B channels of an image by a given factor.
    Args:
        image: An array of shape (height, width, channels) representing the image.
        channel: An array of shape (channels,) specifying the rescaling factor for each channel.
    Returns:
        A new image array with the re-scaled R, G, B channels.
    """
    new_image = np.zeros_like(image)  # Create a new array to store the re-scaled image
    for i in range(image.shape[0]):
        for j in range(image.shape[1]):
            for k in range(image.shape[2]):
                if channel[k] != 1:
                    new_image[i, j, k] = image[i, j, k] * channel[k]
                else:
                    new_image[i, j, k] = image[i, j, k]

    return new_image

def fast_exponentiation(base, power):
    if power < 0:
        raise ValueError("Power must be non-negative")

    result = 1
    while power > 0:
        if power % 2 == 1:
            result *= base
        base *= base
        power //= 2

    return result

