def calculate_l_norm_distance(norm, array1, array2):
    if norm == 1:
        distance = sum(abs(a - b) for a, b in zip(array1, array2))
    elif norm == 2:
        distance = sum((a - b) ** 2 for a, b in zip(array1, array2)) ** 0.5
    elif norm == float('inf'):
        distance = max(abs(a - b) for a, b in zip(array1, array2))
    else:
        raise ValueError("Invalid norm.")
    return distance

