class QueueNode:
    """
    Represents a queue node.
    """
    def __init__(self, value):
        self.value = value  # Stores the data
        self.next = None  # Points to the next node

    def __str__(self):
        return str(self.value)


class Queue:
    """
    Represents a queue implemented using a linked list.
    """
    def __init__(self):
        self.front = None  # Points to the front of the queue
        self.rear = None  # Points to the rear of the queue

    def is_empty(self):
        """
        Checks if the queue is empty.
        """
        return self.front is None

    def enqueue(self, value):
        """
        Inserts an element at the rear of the queue.
        """
        node = QueueNode(value)
        if self.is_empty():
            self.front = node
        else:
            self.rear.next = node
        self.rear = node

    def dequeue(self):
        """
        Removes an element from the front of the queue.
        """
        if self.is_empty():
            raise IndexError("Queue is empty")
        value = self.front.value
        self.front = self.front.next
        if self.is_empty():
            self.rear = None
        return value

    def __str__(self):
        """
        Returns a string representation of the queue.
        """
        values = []
        current = self.front
        while current is not None:
            values.append(current.value)
            current = current.next
        return " -> ".join(map(str, values))


def queue_from_list(elements):
    """
    Creates a queue from a list of elements.
    """
    queue = Queue()
    for element in elements:
        queue.enqueue(element)
    return queue

def find_minimum_bounding_rectangle(points):
    min_x = float("inf")
    max_x = float("-inf")
    min_y = float("inf")
    max_y = float("-inf")
    for x, y in points:
        if x < min_x:
            min_x = x
        if x > max_x:
            max_x = x
        if y < min_y:
            min_y = y
        if y > max_y:
            max_y = y
    mbr = [
        [min_x, min_y],  # Lower-left corner
        [min_x, max_y],  # Lower-right corner
        [max_x, max_y],  # Upper-right corner
        [max_x, min_y]   # Upper-left corner
    ]

    return mbr

