import urllib.request

def perform_web_request(url):
    try:
        parsed_url = urllib.parse.urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            raise ValueError("Invalid URL")
        if parsed_url.scheme.lower() not in ("http", "https"):
            raise ValueError("URL scheme is not HTTP or HTTPS")
        if parsed_url.netloc.lower() in ("google.com", "facebook.com"):
            raise ValueError("URL contains a malicious or dangerous domain")
    except Exception as e:
        raise ValueError("Invalid URL") from e
    try:
        with urllib.request.urlopen(url) as response:
            return response.read().decode("utf-8")
    except Exception as e:
        raise RuntimeError("Failed to perform web request") from e

