import json

def remove_non_ascii(json_string):
    data = json.loads(json_string)
    def remove_non_ascii_from_string(s):
        return ''.join(c for c in s if ord(c) < 128)
    def remove_non_ascii_from_structure(structure):
        if isinstance(structure, str):
            return remove_non_ascii_from_string(structure)
        elif isinstance(structure, dict):
            return {k: remove_non_ascii_from_structure(v) for k, v in structure.items()}
        elif isinstance(structure, list):
            return [remove_non_ascii_from_structure(item) for item in structure]
        else:
            return structure
    data_without_non_ascii = remove_non_ascii_from_structure(data)
    json_string_without_non_ascii = json.dumps(data_without_non_ascii)

    return json_string_without_non_ascii

def max_depth(dictionary):
    max_depth = 0

    def traverse_dict(d, depth):
        nonlocal max_depth
        for key, value in d.items():
            if isinstance(value, dict):
                traverse_dict(value, depth + 1)
            else:
                max_depth = max(max_depth, depth)

    traverse_dict(dictionary, 1)

    return max_depth

def generate_asterisks(index, count, length=80):
    if count <= 0:
        raise ValueError("Count must be greater than zero.")

    if index >= length:
        return ' ' * length

    spaces_count = length - index - count
    return '*' * index + '*' * count + ' ' * spaces_count

