def generate_response(request_method, request_headers, request_body, table_id, table_data):
    if request_method not in ('GET', 'POST'):
        return 400, {}, 'Bad Request'
    if 'Authorization' not in request_headers or request_headers['Authorization'] != 'Token xxx':
        return 401, {}, 'Unauthorized'
    if request_body.startswith('{'):
        request_params = json.loads(request_body)
    else:
        request_params = parse_qs(request_body)
    try:
        table = next(table for table in table_data if table['id'] == int(table_id))
    except StopIteration:
        return 404, {}, 'Not Found'
    if request_method == 'GET':
        response_body = json.dumps(table, indent=4)
        response_headers = {'Content-Type': 'application/json'}
    else:
        response_body = '&'.join(f'{k}={v}' for k, v in table.items())
        response_headers = {'Content-Type': 'application/x-www-form-urlencoded'}

    return 200, response_headers, response_body

def rounded_sqrt(num: int) -> int:
    """
    Returns the square root of a given integer, rounded down to the nearest integer.
    """
    left, right = 0, num

    while left <= right:
        mid = (left + right) // 2
        if mid * mid == num:
            return mid
        elif mid * mid < num:
            left = mid + 1
        else:
            right = mid - 1

    return right

