def factorial_dp(n):
    cache = {0: 1, 1: 1}  # Initialize the cache with the factorials of 0 and 1

    def helper(n):
        if n in cache:  # Check if the factorial of n has already been computed
            return cache[n]
        else:
            result = n * helper(n - 1)  # Compute the factorial of n
            cache[n] = result  # Cache the result
            return result

    return helper(n)

