def validate_data(data):
    if not isinstance(data, list):
        raise InvalidDataError('Data must be a list of objects')

    for item in data:
        if not isinstance(item, dict):
            raise InvalidDataError('Each item must be an object')
        if 'name' not in item:
            raise InvalidDataError('Each object must have a "name" key')
        if not isinstance(item['name'], str):
            raise InvalidDataError('The "name" key must be a string')
        if 'value' not in item:
            raise InvalidDataError('Each object must have a "value" key')
        if not isinstance(item['value'], (int, float)):
            raise InvalidDataError('The "value" key must be a number')

    return [(item['name'], item['value']) for item in data]

