def gcd_euclidean(num1, num2):
    if not isinstance(num1, int) or not isinstance(num2, int) or num1 < 0 or num2 < 0:
        return 0
    if num1 == 0:
        return num2
    elif num2 == 0:
        return num1
    remainder = num1 % num2
    while remainder != 0:
        num1 = num2
        num2 = remainder
        remainder = num1 % num2

