def rot13_encrypt(text: str) -> str:
    encrypted_text = ""
    for char in text:
        if char.islower():
            encrypted_char = chr((ord(char) - ord("a") + 13) % 26 + ord("a"))
            encrypted_text += encrypted_char
        elif char.isupper():
            encrypted_char = chr((ord(char) - ord("A") + 13) % 26 + ord("A"))
