def check_valid_parentheses(string: str) -> bool:
    """
    Checks if a given string containing parentheses is valid.
    """
    opening_parens = ['(', '[', '{']
    closing_parens = [')', ']', '}']
    parens_map = dict(zip(opening_parens, closing_parens))
    stack = []

    for char in string:
        if char in opening_parens:
            stack.append(char)
        elif char in closing_parens:
            if not stack or parens_map[stack.pop()] != char:
                return False
        else:
            return False

    return len(stack) == 0

