from decimal import Decimal

def solve_quadratic_equation(a, b, c):
    assert isinstance(a, (int, float)) and isinstance(b, (int, float)) and isinstance(c, (int, float)), "Input must be real numbers"
    assert not (a == b == c == 0), "Input cannot be all zero"
    a = Decimal(a)
    b = Decimal(b)
    c = Decimal(c)
    discriminant = b ** 2 - 4 * a * c
    if discriminant < 0:
        return None
    elif discriminant == 0:
        x = -b / (2 * a)
        return (x, x)
    else:
        x1 = (-b + discriminant ** 0.5) / (2 * a)
        x2 = (-b - discriminant ** 0.5) / (2 * a)
        return (round(x1, 3), round(x2, 3))

