def find_largest_multiple(num1, num2):
    def gcd(x, y):
        while y != 0:
            x, y = y, x % y
        return x

    def lcm(x, y):
        return x * y // gcd(x, y)
    lcm_val = lcm(num1, num2)
    max_val = max(num1, num2)
    while True:
        if max_val % lcm_val == 0:
            break
        max_val += 1
    min_val = min(num1, num2)
    while True:
        if min_val % num1 == 0 or min_val % num2 == 0:
            break
        min_val += 1
    return round(max(max_val, min_val), 2)

