def longest_non_decreasing_subsequence(nums):
    cache = {}

    def find_length(nums, start_index):
        if start_index == len(nums):
            return 0
        if start_index in cache:
            return cache[start_index]
        max_length = 1
        for i in range(start_index + 1, len(nums)):
            if nums[i] >= nums[start_index]:
                max_length = max(max_length, find_length(nums, i) + 1)
        cache[start_index] = max_length
        return max_length
    lengths = [find_length(nums, i) for i in range(len(nums) - 1, -1, -1)]
    return max(lengths)

