def flatten_dictionary(d):
    """
    Flattens a nested dictionary by combining keys with dots.
    For example, given {'a': 1, 'b': {'c': 2, 'd': 3}},
    the output should be {'a': 1, 'b.c': 2, 'b.d': 3}.
    """
    def _flatten(d, parent_key):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(_flatten(v, new_key))
            else:
                items.append((new_key, v))
        return items

    return dict(_flatten(d, None))

