def longest_unique_substr_len(s: str) -> int:
    if not s:
        return 0

    window = set()
    start = 0
    end = 0
    longest_len = 0

    while end < len(s):
        if s[end] in window:
            window.remove(s[start])
            start += 1
        else:
            window.add(s[end])
            end += 1
            longest_len = max(longest_len, end - start)

    return longest_len

