def find_connected_components(mapping):
    seen = set()
    connected_components = []

    for key, value in mapping.items():
        if (key, value) not in seen:
            component = set()
            stack = [(key, value)]
            while stack:
                curr_key, curr_value = stack.pop()
                if (curr_key, curr_value) not in seen:
                    seen.add((curr_key, curr_value))
                    component.add((curr_key, curr_value))
                    if curr_key in mapping:
                        stack.append((curr_key, mapping[curr_key]))
                    if curr_value in mapping:
                        stack.append((mapping[curr_value], curr_value))

            connected_components.append(component)

    return len(connected_components)

def tribonacci_sequence(n):
