        return 0
    elif n == 1 or n == 2:
        return 0
    elif n == 3:
        return 1
    else:
        a = 0
        b = 0
        c = 1
        for i in range(n - 3):
            temp = a + b + c
            a = b
            b = c
            c = temp
        return c

