def find_closest_corner_points(polygon1, polygon2):
    closest_points = []
    for point1 in polygon1:
        closest_distance = math.inf
        closest_point = None
        for point2 in polygon2:
            distance = math.sqrt((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2)
