def merge_sort(array, start, end):
    if end - start > 1:
        mid = (start + end) // 2
        merge_sort(array, start, mid)
        merge_sort(array, mid, end)
        temp = array[start:end]
        i, j = 0, mid - start
        for k in range(start, end):
            if j == end - start or (i < mid - start and temp[i] <= temp[j]):
                array[k] = temp[i]
                i += 1
            else:
                array[k] = temp[j]
                j += 1

