from datetime import datetime

def format_time_offset(dt: datetime) -> str:
    diff = datetime.now() - dt
    if diff.total_seconds() < 60:
        time_offset = "just now"
    elif diff.total_seconds() < 60 * 60:
        time_offset = f"{int(diff.total_seconds() / 60)} minute{(int(diff.total_seconds() / 60) > 1 and 's')} ago"
    elif diff.total_seconds() < 60 * 60 * 24:
        time_offset = f"{int(diff.total_seconds() / 3600)} hour{(int(diff.total_seconds() / 3600) > 1 and 's')} ago"
    else:
        time_offset = f"{int(diff.total_seconds() / 86400)} day{(int(diff.total_seconds() / 86400) > 1 and 's')} ago"
    if diff.total_seconds() < 0:
        time_offset = "just now" if diff.total_seconds() > -60 else "in the future"

    return time_offset

