import random

def generate_text_markov(strings, max_word_count=10, max_sentence_count=10):
    transition_matrix = {}
    longest_string = max(strings, key=len)
    words = longest_string.split()
    for i in range(len(words) - 1):
        curr_word = words[i]
        next_word = words[i + 1]
        if curr_word not in transition_matrix:
            transition_matrix[curr_word] = [next_word]
        else:
            transition_matrix[curr_word].append(next_word)
    current_word = words[0]
    generated_text = []

    while current_word in transition_matrix and len(generated_text) < max_sentence_count:
        next_words = transition_matrix[current_word]
        current_word = random.choice(next_words)

        if len(generated_text) + len(current_word.split()) > max_word_count:
            break

        generated_text.append(current_word)

    return " ".join(generated_text)

