def compute_ratio(numbers):
    ratio = {
        'sum': 0,
        'mean': 0,
        'median': 0,
    }
    ratio['sum'] = sum(numbers)
    ratio['mean'] = ratio['sum'] / len(numbers)
    if len(numbers) % 2 == 1:
        median_index = len(numbers) // 2
        ratio['median'] = numbers[median_index]
    else:
        median_index = len(numbers) // 2
        ratio['median'] = (numbers[median_index - 1] + numbers[median_index]) / 2

    return ratio

