import re

def center_string(string: str, width: int, padding_char: str) -> str:
    match = re.match(re.escape(string), string)
    if match is not None:
        match_length = len(match.group())
        padding_width = width - match_length
        if padding_width % 2 == 1:
            padding_width += 1
        padding_string = padding_char * (padding_width // 2)
        centered_string = padding_string + match.group() + padding_string
    else:
        raise ValueError("Could not match the string against the pattern")

    return centered_string

