def convert_and_translate(point, translation):
    x, y = point
    theta = x * 180 / math.pi  # Convert x radians to degrees
    phi = y * 180 / math.pi  # Convert y radians to degrees
    return (theta + translation[0], phi + translation[1])

def match_wildcard(pattern: str, text: str) -> bool:
    if not pattern:
        return not text

    if pattern[0] == "*":
        return any(match_wildcard(pattern[1:], text[i:]) for i in range(len(text) + 1))
    elif pattern[0] == "?":
        return match_wildcard(pattern[1:], text[1:]) if text else False
    else:
        return bool(text and pattern[0] == text[0] and match_wildcard(pattern[1:], text[1:]))

def is_valid(queens, row, col):
    """
    Check if a queen can be placed at a given position.
    """
    for r, c in enumerate(queens):
        if c == col or abs(row - r) == abs(col - c):
            return False
    return True

def solve_queens(n, queens=[]):
    """
    Use recursion to explore all possible configurations of the board.
    """
    if len(queens) == n:
        return [queens]
    return [solution for col in range(n) if is_valid(queens, len(queens), col)
            for solution in solve_queens(n, queens + [col])]
