def build_deep_structure(list_of_dicts):
    def build_level(level):
        next_level = {}
        for d in level:
            for key, value in d.items():
                if isinstance(value, dict):
                    next_level[key] = build_level([value])
                else:
                    next_level[key] = value
        return next_level

    return build_level(list_of_dicts)

