def gaussian_FWHM(mean, std, peak_value, energy_units='keV'):
    fwhm = 2.35482 * std
    if energy_units == 'keV':
        fwhm_keV = fwhm
    elif energy_units == 'eV':
        fwhm_keV = fwhm / 1000
    elif energy_units == 'J':
        fwhm_keV = fwhm / 1.60218e-16
    else:
        raise ValueError('Invalid energy units.')
    return fwhm_keV

def convert_milliseconds(milliseconds):
    seconds = milliseconds // 1000
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    days, hours = divmod(hours, 24)

    time_components = []
    if days > 0:
        time_components.append(f"{days} day{'s' if days > 1 else ''}")
    if hours > 0:
        time_components.append(f"{hours} hour{'s' if hours > 1 else ''}")
    if minutes > 0:
        time_components.append(f"{minutes} minute{'s' if minutes > 1 else ''}")
    if seconds > 0:
        time_components.append(f"{seconds} second{'s' if seconds > 1 else ''}")

    return ' '.join(time_components)

