def get_nested_attribute(data, path, default=None):
    attributes = path.split('.')
    def traverse_dictionary(data, attributes):
        if not attributes:
            return data
        attribute = attributes[0]
        value = data.get(attribute)
        if value is None:
            if default is not None:
                return default
            raise AttributeError(f"Attribute {attribute} is missing in the dictionary")
        return traverse_dictionary(value, attributes[1:])

    return traverse_dictionary(data, attributes)
