from pathlib import Path

def get_file_path_in_parent_dir(file_name, parent_dir):
    parent_dir_path = Path(parent_dir)
    file_path = parent_dir_path / file_name
    if file_path.exists():
        return str(file_path)
    else:
        grandparent_dir_path = parent_dir_path.parent
        grandparent_file_path = grandparent_dir_path / file_name
        if grandparent_file_path.exists():
            return str(grandparent_file_path)
        else:
            print(f"File {file_name} does not exist in any of the directories.")
            exit()

def find_largest_match_index(s1: str, s2: str) -> int:
    """
    Finds the index of the first occurrence of the largest match between two strings,
    where the first string is a substring of the second string. Returns -1 if no match is found.
    """
    m = len(s1)  # Length of the first string
    n = len(s2)  # Length of the second string

    if m > n:
        return -1  # No match possible
    start = 0
    end = m - 1

    largest_match = ""  # Largest match found so far

    while end < n:
        substring = s2[start:end + 1]  # Get the substring
        if substring == s1:
            if len(substring) > len(largest_match):
                largest_match = substring

        start += 1
        end += 1
    if largest_match:
        return s2.index(largest_match)
    else:
        return -1

