def construct_neural_network(layer_sizes):
    weights = []
    for i in range(len(layer_sizes) - 1):
        num_neurons_in_layer = layer_sizes[i]
        num_neurons_in_next_layer = layer_sizes[i + 1]
        weight_matrix = [[0 for j in range(num_neurons_in_next_layer)] for k in range(num_neurons_in_layer)]
        for j in range(num_neurons_in_layer):
            for k in range(num_neurons_in_next_layer):
                weight_matrix[j][k] = random.random()
        weights.append(weight_matrix)

    return weights

def traverse_tree(node, reverse_order):
    if len(node[1]) > 0:
        for child in node[1][::-1]:
            reverse_order = traverse_tree(child, reverse_order)
    reverse_order.append(node[0])
    return reverse_order

def reverse_tree(tree):
    reverse_order = []
    for node in tree:
        reverse_order = traverse_tree(node, reverse_order)
    return reverse_order

