import re

def apply_replacements(template: str, replacements: dict) -> str:
    """
    Applies replacements to a template string, replacing all instances of "{{}}" with the
    corresponding values from the replacement dictionary.
    """
    def replace_placeholders(match):
        placeholder = match.group(1)
        return replacements.get(placeholder, "")

    return re.sub(r"{{(.*?)}}", replace_placeholders, template)

