def truncate_stream(stream: bytes) -> str:
    output = ""
    for byte in stream:
        char = chr(byte)
        if char.isalnum():
            output += char.lower()
        else:
            break

    return output

def binary_to_byte_array(binary_string):
    if not binary_string.isnumeric() or len(binary_string) % 8 != 0:
        raise ValueError("Invalid binary string")

    byte_array = []
    for i in range(0, len(binary_string), 8):
        byte_string = binary_string[i:i+8]
        byte = int(byte_string, 2)
        byte_array.append(byte)

    return byte_array

