class Factory:
    def __init__(self, class_names):
        self.class_names = class_names
        self.register_classes()

    def register_classes(self):
        for class_name in self.class_names:
            setattr(self, class_name, eval(class_name))

    def create_instances(self):
        return {class_name: getattr(self, class_name)() for class_name in self.class_names}

def create_class_instances(class_names):
    factory = Factory(class_names)
    return factory.create_instances()

def swap_first_and_last_char(input_string):
    if not isinstance(input_string, str):
        raise TypeError("Input must be a string")

    if len(input_string) <= 1:
        return input_string

    first_char = input_string[0]
    last_char = input_string[-1]
    swapped_string = last_char + input_string[1:-1] + first_char
    return swapped_string

def serialize_to_yaml(dictionary: dict) -> str:
    if not dictionary:
        return ''

    if not all(isinstance(key, str) for key in dictionary):
        raise TypeError('Dictionary keys must be strings.')

    yaml = []
    for key, value in dictionary.items():
        if isinstance(value, str):
            value = f'"{value}"'
        elif isinstance(value, (int, float)):
            value = str(value)
        else:
            value = str(value)

        yaml.append(f'  {key}: {value}')

    return '\n'.join(yaml)

