import json

def walk_json(obj, path=None):
    if path is None:
        path = []

    results = []

    try:
        for key, value in obj.items():
            if isinstance(value, dict):
                results.extend(walk_json(value, path + [key]))
            else:
                results.append((path + [key], value))
    except Exception as e:
        print(f"Error: {e}")

    return results

