def pair_with_target_sum_difference(nums, target_difference):
    differences = {}
    for i, num in enumerate(nums):
        difference = num - target_difference
        if difference in differences:
            return differences[difference], i
        differences[num] = i
    raise ValueError("No pair of indices found")

def read_key_value_file(file_path: str) -> dict:
    """
    Reads a text file that contains key-value pairs (one pair per line) and stores them in a dictionary.
    """
    try:
        with open(file_path) as file_object:
            pairs = {}
            for line in file_object:
                key, value = line.strip().split(":")
                pairs[key] = value
            return pairs
    except (FileNotFoundError, PermissionError) as error:
        print(f"Error reading file: {error}")
        return {}

