def estimate_transition_probabilities(utterances):
    counts = {}
    for i in range(len(utterances) - 1):
        current_speaker = utterances[i][0]
        next_speaker = utterances[i+1][0]
        if current_speaker not in counts:
            counts[current_speaker] = {}
        counts[current_speaker][next_speaker] = counts[current_speaker].get(next_speaker, 0) + 1
    probabilities = {}
    for speaker, next_speaker_counts in counts.items():
        total_transitions = sum(next_speaker_counts.values())
        probabilities[speaker] = {next_speaker: count / total_transitions for next_speaker, count in next_speaker_counts.items()}

    return probabilities

def get_temperature_category(celsius_value: float) -> str:
    if not -273.15 <= celsius_value <= 100:
        raise ValueError('Invalid temperature')

    if celsius_value <= -10:
        return 'Cold'
    elif -10 < celsius_value < 0:
        return 'Chilly'
    elif 0 <= celsius_value < 20:
        return 'Comfortable'
    elif 20 <= celsius_value < 35:
        return 'Hot'
    else:
        return 'Extreme'

def dict_to_code(dictionary, indentation_level=0):
    code_lines = []
    for key, value in dictionary.items():
        indentation = "\t" * indentation_level
        if isinstance(value, dict):
            code_lines.append(f"{indentation}{key} = {{")
            code_lines.extend(dict_to_code(value, indentation_level + 1))
            code_lines.append(f"{indentation}}}")
        else:
            code_lines.append(f"{indentation}{key} = {value}")
    return code_lines

