def deepest_items(dictionary):
    def _deepest_items_helper(d, depth, max_depth, result):
        if not d:
            return None
        elif not isinstance(d, dict):
            return None
        for k, v in d.items():
            if not isinstance(v, dict):
                if depth == max_depth:
                    result.append((k, v))
                elif depth > max_depth:
                    result.clear()
                    result.append((k, v))
                    max_depth = depth
            else:
                _deepest_items_helper(v, depth + 1, max_depth, result)
        return result

    try:
        return _deepest_items_helper(dictionary, 0, 0, [])
    except:
        return None

