def check_sudoku(board):
    for i in range(9):
        seen_digits = set()
        for j in range(9):
            digit = board[i][j]
            if digit != 0:
                if digit in seen_digits:
                    return False
                seen_digits.add(digit)
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            seen_digits = set()
            for k in range(i, i+3):
                for l in range(j, j+3):
                    digit = board[k][l]
                    if digit != 0:
                        if digit in seen_digits:
                            return False
                        seen_digits.add(digit)

    return True

