def random_gaussian(mu: float, sigma: float) -> dict:
    """
    Generates a sequence of random variables with a Gaussian distribution and prints out the frequency distribution.
    """
    samples = {}

    for _ in range(1000):
        sample = np.random.normal(mu, sigma)
        samples[sample] = samples.get(sample, 0) + 1

