import base64

def base64url_encode(s):
    encoded_bytes = base64.b64encode(s.encode('utf-8'))
    encoded_string = encoded_bytes.decode('utf-8')
    encoded_urlsafe = encoded_string.replace('+', '-').replace('/', '_')
    return encoded_urlsafe.ljust(len(encoded_urlsafe) + len(encoded_urlsafe) % 4, '=')

