import numpy as np

def tensor_product(tensor_a, tensor_b):
    """
    Computes the element-wise product of two tensors of arbitrary dimensions.
    """
    if tensor_a.shape != tensor_b.shape:
        tensor_a, tensor_b = np.broadcast_arrays(tensor_a, tensor_b)

    return np.multiply(tensor_a, tensor_b)

import ast

def generate_docstring(filename):
    with open(filename, 'r') as file:
        source = file.read()
    tree = ast.parse(source)
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            docstring = generate_google_docstring(node)
            return docstring

def generate_google_docstring(node):
    docstring = f'"""{node.name.capitalize()} '
    if node.args.args:
        docstring += 'Args:\n    '
        docstring += '\n    '.join(f'{arg.arg}: Description of {arg.arg}' for arg in node.args.args)
    if node.returns:
        docstring += f'\n\nReturns:\n    {node.returns.id}'
    docstring += '\n"""'
    return docstring

