def distinct_count(arr):
    n = len(arr)
    distinct_count = 0
    last_distinct_index = 0

    for i in range(n):
        start, end = last_distinct_index, n - 1
        while start <= end:
            mid = (start + end) // 2
            if arr[mid] == arr[i]:
                start = mid + 1
            else:
                end = mid - 1

        if start > last_distinct_index:
            distinct_count += 1
            last_distinct_index = start

    return distinct_count

