def generate_key(tree: dict) -> str:
    key = ""

    def dfs(node: dict):
        nonlocal key
        if isinstance(node, int):
            key += str(node)
        elif isinstance(node, str):
            key += node
        else:
            for child in node.values():
                dfs(child)

    dfs(tree)

    return key

