def flatten_asts(ast_list):
    if not isinstance(ast_list, list):
        return []

    flattened = []

    def flatten(ast):
        if not isinstance(ast, list):
            return
        for item in ast:
            if isinstance(item, list):
                flatten(item)
            else:
                flattened.append(item)

    for ast in ast_list:
        flatten(ast)

    return flattened

def unique_values(data, key):
    unique_values = set()

    def flatten_dict(d, prefix):
        for k, v in d.items():
            if isinstance(v, dict):
                flatten_dict(v, prefix + '.' + k if prefix else k)
            else:
                unique_values.add(v)

    for d in data:
        flatten_dict(d, '')

    return list(unique_values)

from typing import List

def deduplicate_words(words: List[str]) -> List[str]:
    unique_words = {}
    deduplicated = []

    for index, word in enumerate(words):
        word = word.lower()
        if word not in unique_words:
            unique_words[word] = index
            deduplicated.append(word)

