def is_match(text, pattern):
    def match_pattern(text_idx, pattern_idx):
        if text_idx == len(text) and pattern_idx == len(pattern):
            return True
        if text_idx < len(text) and pattern_idx < len(pattern):
            curr_char = pattern[pattern_idx]
            if curr_char == '.':
                return match_pattern(text_idx + 1, pattern_idx + 1)
            elif curr_char == '*':
                for i in range(len(text) - text_idx + 1):
                    if match_pattern(text_idx + i, pattern_idx + 1):
                        return True
                return False
            else:
                return text[text_idx] == curr_char and match_pattern(text_idx + 1, pattern_idx + 1)
        if text_idx == len(text) and pattern_idx < len(pattern):
            return False
        if text_idx < len(text) and pattern_idx == len(pattern):
            return False

    return match_pattern(0, 0)

