import hashlib

def calculate_sha1_hash(file_path):
    try:
        with open(file_path, 'rb') as f:
            sha1 = hashlib.sha1()
            while True:
                chunk = f.read(4096)
                if not chunk:
                    break
                sha1.update(chunk)
            f.close()
            return sha1.hexdigest()
    except Exception as e:
        return f"Error calculating SHA1 hash: {e}"

