def check_expression(expr):
    if not expr:
        raise ValueError("Empty expression not allowed")

    stack = []
    mapping = {"(": ")", "[": "]", "{": "}"}

    for char in expr:
        if char in mapping:
            stack.append(mapping[char])
        elif char in mapping.values():
            if not stack or char != stack.pop():
                return False
        elif char not in mapping.keys() and char not in mapping.values():
            continue

    return not stack

