def calculate_max_grocery_spend(grocery_items, weights, price_per_day):
    total_cost = sum(grocery_items[i] * weights[i] for i in range(len(grocery_items)))
    total_weight = sum(weights)
    max_weight = price_per_day / total_cost * total_weight

    selected_items = []
    for i in range(len(grocery_items)):
        if weights[i] <= max_weight:
            selected_items.append(grocery_items[i])
            max_weight -= weights[i]

    return selected_items

