def spiral_pattern(arr):
    result = []
    row_start, row_end = 0, len(arr) - 1
    col_start, col_end = 0, len(arr[0]) - 1
    while row_start <= row_end and col_start <= col_end:
        for col in range(col_start, col_end + 1):
            result.append(arr[row_start][col])
        row_start += 1
        for row in range(row_start, row_end + 1):
            result.append(arr[row][col_end])
        col_end -= 1
        if row_start <= row_end:
            for col in range(col_end, col_start - 1, -1):
                result.append(arr[row_end][col])
            row_end -= 1
        if col_start <= col_end:
            for row in range(row_end, row_start - 1, -1):
                result.append(arr[row][col_start])
            col_start += 1
    return result

