def max_sum_sliding_window(arr, k):
    if not arr or k > len(arr):
        return 0
    if k == 1:
        return max(arr)

    max_sum = float('-inf')
    current_sum = sum(arr[:k]) # initialize current sum to the sum of the first k elements of the array
    for i in range(k, len(arr)):
        current_sum += arr[i] - arr[i-k] # add the next element and remove the previous element from the sliding window
        max_sum = max(max_sum, current_sum) # update the maximum sum
    return max_sum

