def hue_to_hex(hue: float) -> str:
    """
    Maps an HSV hue value to its corresponding closest colour.
    """
    spectrum = {
        'red': '#FF0000',
        'orange': '#FF7F00',
        'yellow': '#FFFF00',
        'green': '#00FF00',
        'blue': '#0000FF',
        'purple': '#800080',
    }

    if hue >= 0 and hue <= 30:
        return spectrum['red']
    elif hue > 30 and hue <= 90:
        return spectrum['orange']
    elif hue > 90 and hue <= 150:
        return spectrum['yellow']
    elif hue > 150 and hue <= 210:
        return spectrum['green']
    elif hue > 210 and hue <= 270:
        return spectrum['blue']
    elif hue > 270 and hue <= 330:
        return spectrum['purple']
    else:
        return spectrum['red']

