import os

def execute_command(command):
    commands = {
        "ls": list_files,
        "pwd": print_working_directory,
        "echo": print_arguments,
        "cd": change_directory,
        "exit": exit_program
    }

    command, *args = shlex.split(command)
    if command in commands:
        return commands[command](args)
    else:
        raise ValueError(f"Invalid command: {command}")

