def split(l):
    if len(l) <= 1:
        return l
    else:
        mid = len(l) // 2
        left = split(l[:mid])
        right = split(l[mid:])
        return merge(left, right)

def merge(left, right):
    result = []
    i, j = 0, 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result += left[i:]
    result += right[j:]
    return result

