import numpy as np

def broadcast_matrix_multiply(A, B):
    if A.shape[1] != B.shape[0]:
        raise ValueError("Matrices are not compatible for broadcast multiplication.")
    if A.shape[0] < B.shape[1]:
        A = np.tile(A, (B.shape[1], 1)).reshape(B.shape[1], A.shape[1])
    elif B.shape[0] < A.shape[1]:
        B = np.tile(B, (A.shape[1], 1)).reshape(A.shape[1], B.shape[1])
    result = np.zeros((A.shape[0], B.shape[1]))
    for i in range(A.shape[0]):
        for j in range(B.shape[1]):
            result[i, j] = np.sum(A[i, :] * B[:, j])

    return result

