def divide_without_operators(dividend: int, divisor: int) -> int:
    if not isinstance(dividend, int) or not isinstance(divisor, int):
        raise TypeError("Input arguments must be integers.")
    if divisor == 0:
        raise ValueError("Cannot divide by zero.")
    dividend = abs(dividend)
    quotient = 0
    while dividend >= abs(divisor):
        quotient += 1
        dividend -= divisor
    if dividend < 0:
        quotient *= -1

    return quotient

