def find_max_value(nested_list):
    """
    Finds the maximum value in a nested list of numbers.

    :param nested_list: The nested list to search
    :return: The maximum value found
    """
    max_value = float('-inf')

    def helper(list_item):
        nonlocal max_value
        if isinstance(list_item, list):
            for item in list_item:
                helper(item)
        else:
            max_value = max(max_value, list_item)

    helper(nested_list)
    return max_value

