def triangle_function(x, range):
    assert len(range) == 3, "Range must have three values"
    assert range[0] < range[1] < range[2], "Range must be strictly increasing"
    assert range[0] <= x <= range[2], "Value must be within the range"

    a, b, c = range

    if x <= b:
        membership = (x - a) / (b - a)
    else:
        membership = (c - x) / (c - b)

    return membership

def utf8_to_unicode(s: str) -> str:
    unicode_string = ""
    for c in s:
        unicode_string += f"\\u{ord(c):04x}"
    return unicode_string

def compute_concentration(isotope_masses, isotopic_abundances, normalized_concentrations):
    if len(isotope_masses) != len(isotopic_abundances) or len(isotope_masses) != len(normalized_concentrations):
        raise ValueError('All lists must have the same length.')
    compound_mass = 0
    for i, mass in enumerate(isotope_masses):
        compound_mass += mass * isotopic_abundances[i] * normalized_concentrations[i]
    concentration = 1 / compound_mass

    return concentration

import re

def is_ip_in_range(ip_address, ip_range):
    ip_pattern = r'^(\d{1,3}\.){3}\d{1,3}$'
    if not re.match(ip_pattern, ip_address):
        return False
    start_ip, end_ip = ip_range.split('-')
    if not re.match(ip_pattern, start_ip) or not re.match(ip_pattern, end_ip):
        return False
    def ip_to_long(ip):
        parts = ip.split('.')
        return int(parts[0]) * (256 ** 3) + int(parts[1]) * (256 ** 2) + int(parts[2]) * 256 + int(parts[3])

    start_ip_long = ip_to_long(start_ip)
    end_ip_long = ip_to_long(end_ip)
    ip_address_long = ip_to_long(ip_address)
    return start_ip_long <= ip_address_long <= end_ip_long

