from typing import List

def average_positive(items: List[any]) -> float:
    """
    Calculates the average of positive numbers in the input list `items`, rounded to two decimal places.
    If the input list is empty or contains only negative or non-numeric values, it returns `None`.
    Otherwise, it returns the average of the positive numbers, rounded to two decimal places.
    """

    try:
        numbers = [float(item) for item in items]
    except ValueError:
        return None
    positive_numbers = [number for number in numbers if number >= 0]

    if not positive_numbers:
        return None
    average = sum(positive_numbers) / len(positive_numbers)
    return round(average, 2)

