import pandas as pd
import urllib.parse

def parse_event_data(urls_and_event_data):
    parsed_data = []

    for url, event_data in urls_and_event_data:
        try:
            query_params = urllib.parse.urlparse(url).query
            query_params_dict = urllib.parse.parse_qs(query_params)
            topic = query_params_dict.get("topic", [None])[0]
            start = query_params_dict.get("start", [None])[0]
            end = query_params_dict.get("end", [None])[0]
            if not start:
                start_date = None
            else:
                start_date = pd.to_datetime(start)

            if not end:
                end_date = None
            else:
                end_date = pd.to_datetime(end)
            parsed_data.append([topic, start_date, end_date, event_data])
        except Exception as err:
            print(f"Error parsing URL: {url} - {err}")
            continue
    df = pd.DataFrame(parsed_data, columns=["topic", "start_date", "end_date", "event_data"])

    return df

