import torch

def convert_sparse_to_dense(sparse_tensor):
    num_words = max(word_index for word_index, _, _ in sparse_tensor) + 1
    num_docs = max(doc_index for _, doc_index, _ in sparse_tensor) + 1
    dense_tensor = [[0] * num_docs for _ in range(num_words)]
    for word_index, doc_index, count in sparse_tensor:
        dense_tensor[word_index][doc_index] = count
    return torch.tensor(dense_tensor, dtype=torch.float32)

