def dfs_traversal(graph, start_node):
    visited = set()
    traversal_order = []

    def explore(node):
        if node not in visited:
            visited.add(node)
            traversal_order.append(node)
            for neighbor in graph[node]:
                explore(neighbor)

    explore(start_node)
    return traversal_order

def bfs_traversal(graph, start_node):
    visited = set()
    traversal_order = []

    queue = [start_node]
    while queue:
        node = queue.pop(0)
        if node not in visited:
            visited.add(node)
            traversal_order.append(node)
            for neighbor in graph[node]:
                queue.append(neighbor)

    return traversal_order

