def linear_equation_solver(A, b, infeasible_value):
    try:
        x = np.linalg.solve(A, b)
        if np.any(x):
            return True, x
        else:
            return False, infeasible_value
    except np.linalg.LinAlgError as e:
        print(f"Error solving system: {e}")
        return False, infeasible_value

