def calculate_percentage_difference(a, b):
    difference = abs(a - b)
    larger_number = max(a, b)
    if a < b:
        return -(difference / larger_number) * 100
    elif a == b:
        return 0
    else:
        return (difference / larger_number) * 100

def process_packet_traces(packets):
    processed_packets = []
    for packet in packets:
        incoming_device = packet.get("from")
        outgoing_device = packet.get("to")
        current_trace = packet.get("trace")

        should_reverse = False
        if incoming_device == outgoing_device:
            should_reverse = True
        elif incoming_device in current_trace:
            should_reverse = True
        elif outgoing_device in current_trace:
            should_reverse = True
        elif current_trace.count(incoming_device) > 1:
            should_reverse = True
        elif current_trace.count(outgoing_device) > 1:
            should_reverse = True

        if should_reverse:
            current_trace = current_trace[::-1]
        elif incoming_device:
            current_trace.insert(0, incoming_device)
        elif outgoing_device:
            current_trace.append(outgoing_device)

        processed_packets.append(current_trace)

    return processed_packets

