import re

def transform_keys(obj):
    if isinstance(obj, dict):
        return {transform_key(key): transform_keys(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [transform_keys(item) for item in obj]
    else:
        return obj

def transform_key(key):
    patterns = [
        ("parentKey", "parent_key"),
        ("grandparentKey", "grandparent_key"),
        ("parent1Key", "parent_1_key"),
        ("grandparent1Key", "grandparent_1_key"),
    ]
    for pattern, replacement in patterns:
        match = re.search(pattern, key)
        if match:
            return key.replace(match.group(), replacement)
    return key

def parse_of_version(of_version: str) -> dict:
    parts = of_version.split(".")
    if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit():
        raise Exception("Invalid OpenFlow version string")
    major = int(parts[0])
    minor = int(parts[1])
    if major < 1:
        raise Exception("Invalid OpenFlow version string")
    return {
        "major": major,
        "minor": minor,
    }

def get_nested_attr(obj, attrs, default=None):
    if len(attrs) == 0:
        return default

    attr_name = attrs[0]
    if hasattr(obj, attr_name):
        if len(attrs) == 1:
            return getattr(obj, attr_name)
        else:
            return get_nested_attr(getattr(obj, attr_name), attrs[1:], default)
    else:
        return default

