import inspect

def find_priority_functions(module):
    members = inspect.getmembers(module)
    priority_functions = []

    for name, member in members:
        if inspect.isfunction(member):
            priority = getattr(member, "priority", None)
            if priority:
                priority_functions.append((name, priority))

    return priority_functions

from datetime import datetime
import re

def parse_and_convert_timestamp(timestamp_str, from_format, to_format):
    try:
        timestamp = datetime.strptime(timestamp_str, from_format)
    except ValueError:
        for fmt in ['%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S']:
            try:
                timestamp = datetime.strptime(timestamp_str, fmt)
                break
            except ValueError:
                continue
        else:
            raise ValueError('Invalid timestamp format')
    return timestamp.strftime(to_format)

