import sys

def retrieve_os_details():
    os_details = {}
    os_details["name"] = platform.system()
    os_details["version"] = platform.version()
    if os_details["name"] == "Linux":
        os_details["distribution"] = platform.linux_distribution()[0]
        os_details["distribution_version"] = platform.linux_distribution()[1]
    elif os_details["name"] == "Windows":
        os_details["release"] = platform.release()
        os_details["version"] = platform.version()
    elif os_details["name"] == "Darwin":
        os_details["build"] = platform.mac_ver()[0]
        os_details["version"] = platform.mac_ver()[2]

    return os_details

def scale_bounding_box(bounding_box, scaling_factor, image_size):
    top_left, bottom_right = bounding_box
    scaled_top_left = tuple(coord * scaling_factor for coord in top_left)
    scaled_bottom_right = tuple(coord * scaling_factor for coord in bottom_right)
    return (scaled_top_left, scaled_bottom_right)

def find_paths_to_all_nodes_with_sum(root, target_sum):
    paths = []

    def dfs(node, curr_sum, path):
        if not node.children:
            if curr_sum == target_sum:
                paths.append(path + [node.value])
            return
        for child in node.children:
            dfs(child, curr_sum + node.value, path + [node.value])
    dfs(root, 0, [])

    return paths

