from typing import Any

def store_and_retrieve_object(obj: Any, file_path: str) -> str:
    if not file_path.endswith('.pickle'):
        return 'Invalid file path. File path must end with ".pickle".'
    if not isinstance(obj, dict):
        obj = {file_path: obj}
    serialized_obj = pickle.dumps(obj)

    try:
        with open(file_path, 'wb') as f:
            f.write(serialized_obj)
        return 'Object stored successfully.'
    except Exception as e:
        return f'Error storing object: {e}'

