def calculate_capital_structure(stocks):
    capital_structure = {}
    total_capital = 0
    type_a_ratio = 0
    type_b_ratio = 0

    for stock, market_value in stocks.items():
        if stock[0] == 'A':
            capital_structure[stock] = market_value / 50
            type_a_ratio += 1
        else:
            capital_structure[stock] = market_value / 100
            type_b_ratio += 1
        total_capital += capital_structure[stock]

    type_a_ratio /= len(stocks)
    type_b_ratio /= len(stocks)

    return capital_structure, total_capital, type_a_ratio, type_b_ratio

import hashlib

def set_associative_cache(addresses, num_sets, num_ways, block_size):
    cache = {}
    for i in range(num_sets):
        cache[i] = [None] * num_ways
    cache_hits = 0
    cache_misses = 0
    for address in addresses:
        hash_obj = hashlib.md5(address.encode())
        hash_value = int(hash_obj.hexdigest(), 16)
        set_num = hash_value % num_sets
        way = hash_value % num_ways
        hit = False
        for i, cached_address in enumerate(cache[set_num]):
            if cached_address == address:
                cache_hits += 1
                hit = True
                cache[set_num].pop(i)
                cache[set_num].append(address)
                break

        if not hit:
            cache_misses += 1
            if None in cache[set_num]:
                cache[set_num][cache[set_num].index(None)] = address
            else:
                cache[set_num].pop(0)
                cache[set_num].append(address)
    return cache_hits, cache_misses

import re

def get_file_extension_re(file_path):
    file_path_pattern = (
        r"^(?P<file_name>(?P<dir_path>.*[/\\])?(?P<file_name_without_ext>[^/\\]+))\."
        r"(?P<file_extension>[^/\\]+)$"
    )
    match = re.search(file_path_pattern, file_path)
    if match:
        return match.group("file_extension")
    return ""

