def serialize(dictionary: dict) -> str:
    def escape_string(string):
        return string.replace("\\", "\\\\").replace("\"", "\\\"")

    def serialize_value(value):
        if isinstance(value, int) or isinstance(value, float):
            return str(value)
        elif isinstance(value, str):
            return f'"{escape_string(value)}"'
        elif isinstance(value, list) or isinstance(value, tuple):
            return "[" + ", ".join(serialize_value(item) for item in value) + "]"
        elif isinstance(value, dict):
            return "{" + ", ".join(f'"{k}": {serialize_value(v)}' for k, v in value.items()) + "}"
        else:
            return str(value)
    return "{" + ", ".join(f'"{k}": {serialize_value(v)}' for k, v in dictionary.items()) + "}"

